};

pub const IndexManager = struct {
    alloc: Allocator,
    base_path: []u8,
    byte_range: docstore_mod.ByteRange,
    relaxed_split_durability: bool,
    text_main_backend: persistent_mod.MainBackend,
    text_lsm_storage: ?lsm_backend_mod.Storage,
    text_main_lsm_options: lsm_backend_mod.Options,
    text_wal_lsm_options: lsm_backend_mod.Options,
    dense_storage_backend: hbc_mod.StorageBackend,
    dense_lsm_storage: ?lsm_backend_mod.Storage,
    dense_lsm_options: lsm_backend_mod.Options,
    sparse_backend: sparse_mod.SparseBackend,
    sparse_lsm_storage: ?lsm_backend_mod.Storage,
    sparse_lsm_options: lsm_backend_mod.Options,
    graph_reverse_backend: graph_mod.ReverseBackend,
    graph_lsm_storage: ?lsm_backend_mod.Storage,
    graph_reverse_lsm_options: lsm_backend_mod.Options,
    lsm_cache: ?*lsm_backend_mod.Cache,
    hbc_cache: ?*hbc_mod.Cache,
    lsm_root_generation: u64,
    io: ?std.Io,
    resource_manager: ?*resource_manager_mod.ResourceManager,
    owned_resource_manager: ?*resource_manager_mod.ResourceManager,
    bind_cache_resource_manager: bool,
    // Background lane used by algebraic indexes to run HLL cardinality
    // maintenance off the foreground write path. Attached after construction
    // via attachHllMaintenance(); when null, maintenance runs inline.
    hll_maintenance_lane: ?background_runtime_mod.DurableJobLane = null,
    hll_maintenance_owner_id: u64 = 0,
    primary_store: ?*docstore_mod.DocStore,
    applied_sequence_checkpoint_path: ?[]const u8,
    catalog_mutex: apply_rw_lock_mod.ApplyRwLock = .{},
    /// 0 = idle, 1 = queued/running, 2 = rerun requested while active.
    repair_cleanup_state: std.atomic.Value(u8) = .init(0),
    /// Durable generated-artifact cleanup uses the same single-flight shape,
    /// but runs in bounded pages so it cannot monopolize structural locks.
    artifact_cleanup_state: std.atomic.Value(u8) = .init(0),
    // Bulk text backfill performs its own policy compaction at durable batch
    // boundaries. Keep the asynchronous scheduler from competing with it (or
    // compacting an older schema generation) for CPU, mmap residency, and the
    // shared text-merge resource budget.
    text_backfill_active: std.atomic.Value(u32) = .init(0),
    next_text_index_instance_id: std.atomic.Value(u64) = .init(1),
    load_parallelism: ?usize = null,
    full_text_pending_bytes_accounted: u64 = 0,
    text_indexes: std.ArrayListUnmanaged(TextIndex),
    text_merge_scheduler: TextMergeScheduler,
    dense_indexes: std.ArrayListUnmanaged(DenseIndex),
    sparse_indexes: std.ArrayListUnmanaged(SparseIndex),
    graph_indexes: std.ArrayListUnmanaged(GraphIndex),
    algebraic_indexes: std.ArrayListUnmanaged(AlgebraicIndex),
    enrichments: std.ArrayListUnmanaged(enrichment_catalog.EnrichmentConfig),
    resolvers: std.ArrayListUnmanaged(resolver_catalog.ResolverConfig) = .empty,
    cached_has_generated_enrichment_targets: std.atomic.Value(bool),
    status_only_index_configs: []types.IndexConfig,
    // Indexes whose persisted artifacts failed to open (e.g. UnsupportedVersion).
    // Their configs are quarantined into status_only_index_configs so the
    // catalog, status reporting, and drop/recreate keep working while the
    // runtime index stays absent; this map carries the per-index load error
    // and retry/backoff state for self-healing (retryFailedIndexLoads).
    // Keys are duped index names; err_name values are static @errorName memory.
    failed_index_loads: std.StringHashMapUnmanaged(FailedIndexLoad) = .empty,
    // Durable repair intents gate service independently of load failures. A
    // replacement may load successfully after pointer activation while its
    // intent is still in activating/validating; queries must remain closed
    // until DB validation publishes a clean checkpoint.
    repair_unavailable_indexes: std.StringHashMapUnmanaged(void) = .empty,
    // Primary-store admission markers captured once before catalog open. The
    // immutable snapshot makes full-text backfill suppression O(1) per index
    // and lets every open mode install the same fail-closed service gate.
    managed_admission_mutex: std.atomic.Mutex = .unlocked,
    managed_admission_indexes: std.StringHashMapUnmanaged(void) = .empty,
    index_load_states: std.StringHashMapUnmanaged(IndexLoadState) = .empty,

    pub const FailedIndexLoad = struct {
        err_name: []const u8,
        retry_attempts: u32 = 0,
        // Monotonic deadline before which retryFailedIndexLoads skips this
        // index. 0 = due immediately (first retry happens on the next tick).
        next_retry_ns: u64 = 0,
    };

    const IndexLoadState = enum {
        loading,
        complete,
    };

    const TextMergeDeletionDelta = struct {
        bitmap: roaring.RoaringBitmap,
        count: usize = 0,

        fn init(alloc: Allocator) TextMergeDeletionDelta {
            return .{ .bitmap = roaring.RoaringBitmap.init(alloc) };
        }

        fn deinit(self: *TextMergeDeletionDelta) void {
            self.bitmap.deinit();
            self.* = undefined;
        }
    };

    /// Task-owned state published into exactly one TextIndex while the merge is
    /// active. Its stable heap address lets the merge worker and replay writers
    /// share the admitted allocator without borrowing scheduler-array storage.
    const TextMergeDeletionState = struct {
        backing_alloc: Allocator,
        budget: TextMergeBudgetAllocator,
        segment_ids: []u64 = &.{},
        deltas: []TextMergeDeletionDelta = &.{},
        valid: bool = true,

        fn create(
            backing_alloc: Allocator,
            reservation: *?resource_manager_mod.Reservation,
            segment_count: usize,
        ) !*TextMergeDeletionState {
            const state = try backing_alloc.create(TextMergeDeletionState);
            state.* = .{
                .backing_alloc = backing_alloc,
                .budget = TextMergeBudgetAllocator.init(backing_alloc, reservation.*),
            };
            reservation.* = null;
            errdefer state.destroy();

            const alloc = state.budget.allocator();
            state.segment_ids = alloc.alloc(u64, segment_count) catch |err| return state.allocationError(err);
            state.deltas = alloc.alloc(TextMergeDeletionDelta, segment_count) catch |err| return state.allocationError(err);
            for (0..segment_count) |i| {
                state.segment_ids[i] = 0;
                state.deltas[i] = TextMergeDeletionDelta.init(alloc);
            }
            return state;
        }

        fn destroy(self: *TextMergeDeletionState) void {
            const backing_alloc = self.backing_alloc;
            const alloc = self.budget.allocator();
            for (self.deltas) |*delta| delta.deinit();
            if (self.deltas.len > 0) alloc.free(self.deltas);
            if (self.segment_ids.len > 0) alloc.free(self.segment_ids);
            self.budget.deinit();
            self.* = undefined;
            backing_alloc.destroy(self);
        }

        fn allocationError(self: *const TextMergeDeletionState, err: anyerror) anyerror {
            if (self.budget.denied()) return error.ResourceBudgetExceeded;
            return err;
        }

        fn allocator(self: *TextMergeDeletionState) Allocator {
            return self.budget.allocator();
        }

        fn recordCommittedDeletes(self: *TextMergeDeletionState, delete_infos: []const index_mod.IndexWriter.DeleteInfo) void {
            if (!self.valid) return;
            record_state: {
                for (delete_infos) |delete_info| {
                    for (self.segment_ids, 0..) |segment_id, segment_idx| {
                        if (segment_id != delete_info.seg_id) continue;
                        std.debug.assert(delete_info.applied_count <= delete_info.local_ids.len);
                        const committed_ids = delete_info.local_ids[0..delete_info.applied_count];
                        self.deltas[segment_idx].bitmap.addSortedAscending(committed_ids) catch {
                            self.valid = false;
                            break :record_state;
                        };
                        self.deltas[segment_idx].count += committed_ids.len;
                        break;
                    }
                }
            }
        }
    };

    pub const TextIndex = struct {
        /// Monotonic catalog identity. Admission planning may release the
        /// catalog lock while it waits, then reject a delete/recreate ABA
        /// before publishing a plan derived from the old schema.
        instance_id: u64 = 0,
        /// Protected by analysis_mutex. Planning captures this revision so a
        /// runtime schema or analyzer configuration refresh cannot invalidate
        /// producer admission estimates while the caller waits for a permit.
        projection_revision: u64 = 1,
        apply_mutex: *std.atomic.Mutex,
        merge_delta_mutex: std.atomic.Mutex = .unlocked,
        merge_deletion_states: std.ArrayListUnmanaged(*TextMergeDeletionState) = .empty,
        analysis_mutex: apply_rw_lock_mod.ApplyRwLock = .{},
        config: types.IndexConfig,
        chunk_name: ?[]u8,
        text_analysis: introducer_mod.TextAnalysisConfig,
        observed_field_analyzers: []mapper.ObservedFieldAnalyzer = &.{},
        runtime_schema: ?schema_mod.TableSchema,
        rebuild_root_path: []u8,
        persistent: persistent_mod.PersistentIndex,
        // Per-index derived workers can publish independently. Stats and
        // producer admission sample this bit without taking every index's
        // apply mutex, so it must not be a plain concurrently-mutated bool.
        compaction_pending: std.atomic.Value(bool) = .init(false),

        pub fn lockAnalysisShared(self: *TextIndex) void {
            self.analysis_mutex.lockShared();
        }

        pub fn unlockAnalysisShared(self: *TextIndex) void {
            self.analysis_mutex.unlockShared();
        }

        fn attachMergeDeletionState(self: *TextIndex, alloc: Allocator, state: *TextMergeDeletionState) !void {
            lockAtomicMutex(&self.merge_delta_mutex);
            defer self.merge_delta_mutex.unlock();
            try self.merge_deletion_states.append(alloc, state);
        }

        fn detachMergeDeletionState(self: *TextIndex, state: *const TextMergeDeletionState) void {
            lockAtomicMutex(&self.merge_delta_mutex);
            defer self.merge_delta_mutex.unlock();
            for (self.merge_deletion_states.items, 0..) |candidate, i| {
                if (candidate != state) continue;
                _ = self.merge_deletion_states.orderedRemove(i);
                return;
            }
        }

        fn detachAllMergeDeletionStates(self: *TextIndex) void {
            lockAtomicMutex(&self.merge_delta_mutex);
            defer self.merge_delta_mutex.unlock();
            self.merge_deletion_states.clearRetainingCapacity();
        }

        fn mergeDeletionStateCurrent(self: *TextIndex, state: *const TextMergeDeletionState) bool {
            lockAtomicMutex(&self.merge_delta_mutex);
            defer self.merge_delta_mutex.unlock();
            for (self.merge_deletion_states.items) |candidate| {
                if (candidate == state) return candidate.valid;
            }
            return false;
        }

        /// Return with merge_delta_mutex held only when this state is still the
        /// attached, valid publication source. The caller must unlock it. This
        /// makes the lower-level public batch helpers safe even when a caller
        /// omits the customary per-index apply lease.
        fn lockMergeDeletionStateCurrent(self: *TextIndex, state: *const TextMergeDeletionState) bool {
            lockAtomicMutex(&self.merge_delta_mutex);
            for (self.merge_deletion_states.items) |candidate| {
                if (candidate == state and candidate.valid) return true;
            }
            self.merge_delta_mutex.unlock();
            return false;
        }

        fn recordCommittedDeletes(self: *TextIndex, delete_infos: []const index_mod.IndexWriter.DeleteInfo) void {
            lockAtomicMutex(&self.merge_delta_mutex);
            defer self.merge_delta_mutex.unlock();
            for (self.merge_deletion_states.items) |state| state.recordCommittedDeletes(delete_infos);
        }
    };

    pub const OwnedFieldAnalyzer = struct {
        field: []u8,
        analyzer: analysis_mod.Analyzer,
        char_filters: []analysis_mod.CharFilter,
        filters: []analysis_mod.TokenFilter,

        fn init(alloc: Allocator, field: []const u8, analyzer: *const analysis_mod.Analyzer) !OwnedFieldAnalyzer {
            const owned_field = try alloc.dupe(u8, field);
            errdefer alloc.free(owned_field);
            const char_filters = try alloc.dupe(analysis_mod.CharFilter, analyzer.char_filters);
            errdefer alloc.free(char_filters);
            const filters = try alloc.dupe(analysis_mod.TokenFilter, analyzer.filters);
            errdefer alloc.free(filters);
            return .{
                .field = owned_field,
                .analyzer = .{
                    .char_filters = char_filters,
                    .tokenizer = analyzer.tokenizer,
                    .filters = filters,
                },
                .char_filters = char_filters,
                .filters = filters,
            };
        }

        fn deinit(self: *OwnedFieldAnalyzer, alloc: Allocator) void {
            alloc.free(self.field);
            alloc.free(self.char_filters);
            alloc.free(self.filters);
            self.* = undefined;
        }
    };

    /// Immutable resources needed by text-query work that outlives the DB's
    /// catalog/apply lease. The persistent snapshot pins segment storage while
    /// owned analyzer pipelines avoid borrowing schema-generation memory.
    pub const TextQueryLease = struct {
        alloc: Allocator,
        snapshot: *index_mod.IndexSnapshot,
        analyzers: []OwnedFieldAnalyzer,

        pub fn analyzerForField(self: *const TextQueryLease, field: []const u8) ?*const analysis_mod.Analyzer {
            for (self.analyzers) |*item| {
                if (std.mem.eql(u8, item.field, field)) return &item.analyzer;
            }
            return null;
        }

        pub fn deinit(self: *TextQueryLease) void {
            self.snapshot.release();
            for (self.analyzers) |*item| item.deinit(self.alloc);
            self.alloc.free(self.analyzers);
            self.* = undefined;
        }
    };

    pub const ObservedDynamicFieldCapabilitySet = dynamic_field_capability.ObservedDynamicFieldCapabilitySet;
    pub const DynamicFieldObservationQuery = dynamic_field_capability.ObservationQuery;

    pub const AlgebraicIndex = struct {
        apply_mutex: *std.atomic.Mutex,
        config: types.IndexConfig,
        // Heap-stable because background HLL jobs retain `*Index` while the
        // manager's AlgebraicIndex array is free to grow and relocate entries.
        index: *algebraic_mod.index.Index,
    };

    pub const TextMergeSourceSegment = struct {
        id: u64,
        deleted: ?roaring.RoaringBitmap = null,
        deleted_count: u32 = 0,

        fn deinit(self: *TextMergeSourceSegment, alloc: Allocator) void {
            _ = alloc;
            if (self.deleted) |*deleted| deleted.deinit();
            self.* = undefined;
        }
    };

    pub const TextMergeTask = struct {
        index_name: []u8,
        persistent: *persistent_mod.PersistentIndex,
        source: []TextMergeSourceSegment,
        merge_indices: []usize,
        snapshot: *index_mod.IndexSnapshot,
        deletion_state: *TextMergeDeletionState,

        pub fn deinit(self: *TextMergeTask, alloc: Allocator) void {
            const task_alloc = self.mergeAllocator();
            self.snapshot.release();
            task_alloc.free(self.merge_indices);
            for (self.source) |*source| source.deinit(task_alloc);
            task_alloc.free(self.source);
            self.deletion_state.destroy();
            alloc.free(self.index_name);
            self.* = undefined;
        }

        fn mergeAllocator(self: *const TextMergeTask) Allocator {
            return self.deletion_state.budget.allocator();
        }

        fn bufferReservationBytes(self: *const TextMergeTask) ?u64 {
            return if (self.deletion_state.budget.reservation) |reservation| reservation.bytes else null;
        }

        fn discardSourceCleanPages(self: *const TextMergeTask) void {
            for (self.merge_indices) |seg_idx| {
                if (seg_idx >= self.snapshot.segments.len) continue;
                self.snapshot.segments[seg_idx].data.madviseDiscardCleanPages();
            }
        }
    };

    pub const TextMergeResult = struct {
        const OutputLocation = struct {
            segment: u32,
            doc: u32,
        };

        const OrdinalSlot = struct {
            identity: u32,
            location: OutputLocation,
            occupied: bool = false,
        };

        const IdSlot = struct {
            hash: u64,
            identity: []const u8,
            location: OutputLocation,
            occupied: bool = false,
        };

        segments: [][]u8 = &.{},
        prepared_segments: []persistent_mod.PreparedMergeSegment = &.{},
        prepared_owner: ?*persistent_mod.PersistentIndex = null,
        output_ordinals: []OrdinalSlot = &.{},
        output_ids: []IdSlot = &.{},
        /// Stable allocator behind the build-scoped tracking wrapper. Result
        /// storage must be released before the owning merge task is destroyed.
        owned_alloc: ?Allocator = null,
        elapsed_ns: u64 = 0,
        /// Peak bytes allocated through the merge task allocator. File-backed
        /// and heap-backed builders both run through this allocator.
        peak_task_alloc_bytes: u64 = 0,

        // Lookup storage is allocated through the task's tracking wrapper.
        // That wrapper delegates raw allocations unchanged to the backing
        // allocator, so detached result ownership is released through `alloc`
        // in deinit after the stack-scoped tracker has recorded its peak.
        fn buildPublicationLookup(self: *TextMergeResult, alloc: Allocator) !void {
            const output_count = if (self.prepared_segments.len > 0) self.prepared_segments.len else self.segments.len;
            var ordinal_count: usize = 0;
            var id_count: usize = 0;
            for (0..output_count) |output_idx| {
                const bytes = if (self.prepared_segments.len > 0)
                    self.prepared_segments[output_idx].data.bytes()
                else
                    self.segments[output_idx];
                var reader = try segment_mod.SegmentReader.init(alloc, bytes);
                defer reader.deinit();
                for (0..reader.doc_count) |doc_idx| {
                    const doc_id: u32 = @intCast(doc_idx);
                    if (try reader.docOrdinal(doc_id)) |ordinal| {
                        _ = ordinal;
                        ordinal_count += 1;
                    } else if (try reader.storedDoc(doc_id)) |stored| {
                        _ = stored;
                        id_count += 1;
                    } else {
                        return error.MissingMergeDocumentIdentity;
                    }
                }
            }

            const ordinal_capacity = try publicationLookupCapacity(ordinal_count);
            const id_capacity = try publicationLookupCapacity(id_count);
            const ordinals = try alloc.alloc(OrdinalSlot, ordinal_capacity);
            errdefer if (ordinals.len > 0) alloc.free(ordinals);
            for (ordinals) |*slot| slot.occupied = false;
            const ids = try alloc.alloc(IdSlot, id_capacity);
            errdefer if (ids.len > 0) alloc.free(ids);
            for (ids) |*slot| slot.occupied = false;

            for (0..output_count) |output_idx| {
                const bytes = if (self.prepared_segments.len > 0)
                    self.prepared_segments[output_idx].data.bytes()
                else
                    self.segments[output_idx];
                var reader = try segment_mod.SegmentReader.init(alloc, bytes);
                defer reader.deinit();
                for (0..reader.doc_count) |doc_idx| {
                    const doc_id: u32 = @intCast(doc_idx);
                    const location: OutputLocation = .{ .segment = @intCast(output_idx), .doc = doc_id };
                    if (try reader.docOrdinal(doc_id)) |ordinal| {
                        try insertOrdinal(ordinals, ordinal, location);
                    } else if (try reader.storedDoc(doc_id)) |stored| {
                        try insertId(ids, stored.id, location);
                    } else unreachable;
                }
            }
            self.output_ordinals = ordinals;
            self.output_ids = ids;
        }

        fn outputForOrdinal(self: *const TextMergeResult, identity: u32) ?OutputLocation {
            if (self.output_ordinals.len == 0) return null;
            var index = ordinalHash(identity) & (self.output_ordinals.len - 1);
            for (0..self.output_ordinals.len) |_| {
                const slot = self.output_ordinals[index];
                if (!slot.occupied) return null;
                if (slot.identity == identity) return slot.location;
                index = (index + 1) & (self.output_ordinals.len - 1);
            }
            return null;
        }

        fn outputForId(self: *const TextMergeResult, identity: []const u8) ?OutputLocation {
            if (self.output_ids.len == 0) return null;
            const hash = std.hash.Wyhash.hash(0, identity);
            var index: usize = @intCast(hash & @as(u64, @intCast(self.output_ids.len - 1)));
            for (0..self.output_ids.len) |_| {
                const slot = self.output_ids[index];
                if (!slot.occupied) return null;
                if (slot.hash == hash and std.mem.eql(u8, slot.identity, identity)) return slot.location;
                index = (index + 1) & (self.output_ids.len - 1);
            }
            return null;
        }

        fn publicationLookupCapacity(entry_count: usize) !usize {
            if (entry_count == 0) return 0;
            const doubled = try std.math.mul(usize, entry_count, 2);
            return try std.math.ceilPowerOfTwo(usize, @max(@as(usize, 2), doubled));
        }

        fn ordinalHash(identity: u32) usize {
            var value: u64 = identity;
            value ^= value >> 16;
            value *%= 0x7feb352d;
            value ^= value >> 15;
            value *%= 0x846ca68b;
            value ^= value >> 16;
            return @intCast(value);
        }

        fn insertOrdinal(slots: []OrdinalSlot, identity: u32, location: OutputLocation) !void {
            var index = ordinalHash(identity) & (slots.len - 1);
            for (0..slots.len) |_| {
                const slot = &slots[index];
                if (!slot.occupied) {
                    slot.* = .{ .identity = identity, .location = location, .occupied = true };
                    return;
                }
                if (slot.identity == identity) return error.DuplicateMergeDocumentIdentity;
                index = (index + 1) & (slots.len - 1);
            }
            return error.MergePublicationLookupFull;
        }

        fn insertId(slots: []IdSlot, identity: []const u8, location: OutputLocation) !void {
            const hash = std.hash.Wyhash.hash(0, identity);
            var index: usize = @intCast(hash & @as(u64, @intCast(slots.len - 1)));
            for (0..slots.len) |_| {
                const slot = &slots[index];
                if (!slot.occupied) {
                    slot.* = .{ .hash = hash, .identity = identity, .location = location, .occupied = true };
                    return;
                }
                if (slot.hash == hash and std.mem.eql(u8, slot.identity, identity)) return error.DuplicateMergeDocumentIdentity;
                index = (index + 1) & (slots.len - 1);
            }
            return error.MergePublicationLookupFull;
        }

        pub fn deinit(self: *TextMergeResult, alloc: Allocator) void {
            const result_alloc = self.owned_alloc orelse alloc;
            if (self.output_ordinals.len > 0) result_alloc.free(self.output_ordinals);
            if (self.output_ids.len > 0) result_alloc.free(self.output_ids);
            merger_mod.freeMergedSegments(result_alloc, self.segments);
            if (self.prepared_segments.len > 0) {
                if (self.prepared_owner) |owner| {
                    owner.discardPreparedMergeSegments(self.prepared_segments);
                } else {
                    const staging_alloc = self.prepared_segments[0].staging_alloc;
                    for (self.prepared_segments) |*segment| {
                        segment.deinit(result_alloc);
                    }
                    staging_alloc.free(self.prepared_segments);
                }
            }
            self.* = undefined;
        }
    };

    const TextMergePublicationDeletes = struct {
        source_current: bool,
        bitmaps: []?roaring.RoaringBitmap,

        fn deinit(self: *TextMergePublicationDeletes, alloc: Allocator) void {
            for (self.bitmaps) |*maybe_deleted| {
                if (maybe_deleted.*) |*deleted| deleted.deinit();
            }
            alloc.free(self.bitmaps);
            self.* = undefined;
        }
    };

    const TextMergeResultOutputStats = struct {
        segments: u64 = 0,
        bytes: u64 = 0,
    };

    pub const DenseIndex = struct {
        apply_mutex: *std.atomic.Mutex,
        config: types.IndexConfig,
        field_name: []u8,
        dims: u32,
        metric: vector_mod.DistanceMetric,
        external: bool,
        managed_direct_field: bool = false,
        chunk_name: ?[]u8,
        embedding_name: ?[]u8,
        index: hbc_mod.HBCIndex,
        vector_loader_context: ?*DenseVectorLoadContext = null,
        ordinal_vector_ids: std.AutoHashMapUnmanaged(doc_identity.DocOrdinal, u64) = .empty,
        vector_ordinals: std.AutoHashMapUnmanaged(u64, doc_identity.DocOrdinal) = .empty,
    };

    const DenseVectorLoadContext = struct {
        manager: *IndexManager,
        index_name: []u8,

        fn deinit(self: *DenseVectorLoadContext, alloc: Allocator) void {
            alloc.free(self.index_name);
            alloc.destroy(self);
        }
    };

    const DenseVectorLoadSession = struct {
        const ReadTxnKind = enum {
            probe,
            snapshot,
        };

        context: *DenseVectorLoadContext,
        read_txn: ?docstore_mod.DocStore.Txn = null,
        read_txn_kind: ReadTxnKind = .probe,
        txn_override: ?docstore_mod.DocStore.Batch.BatchTxn = null,
        raw_cache: std.StringHashMapUnmanaged([]const u8) = .empty,
        vector_cache: std.AutoHashMapUnmanaged(u64, []f32) = .empty,
        raw_cache_hits: u64 = 0,
        raw_cache_misses: u64 = 0,
        raw_batch_reads: u64 = 0,
        raw_scalar_reads: u64 = 0,
        raw_cache_key_bytes: u64 = 0,
        raw_read_value_bytes: u64 = 0,
        vector_cache_hits: u64 = 0,
        vector_cache_misses: u64 = 0,
        vector_cache_bytes: u64 = 0,
        working_bytes_current: u64 = 0,
        working_slice: resource_manager_mod.Slice = .dense_apply_working_set,
        recycle_raw_reads: bool = true,
        cache_raw_values: bool = true,
        cache_vectors: bool = true,
        block_cache_admission: backend_types.Namespace.BlockCacheAdmission = .retain,

        const DefaultRawReadLimitBytes: u64 = 32 * 1024 * 1024;
        const MaxRawReadLimitBytes: u64 = 64 * 1024 * 1024;

        fn deinit(self: *@This()) void {
            self.context.manager.observeDenseWorkingBytes(self.working_slice, &self.working_bytes_current, 0);
            if (getenv("ANTFLY_DEBUG_DENSE_VECTOR_LOAD_SESSION") != null and self.raw_cache_hits + self.raw_cache_misses + self.vector_cache_hits + self.vector_cache_misses >= 128) {
                std.log.debug(
                    "dense vector load session raw_hits={} raw_misses={} vector_hits={} vector_misses={} cached_keys={} cached_vectors={} raw_key_bytes={} raw_value_bytes={} cached_vector_bytes={} index={s}",
                    .{
                        self.raw_cache_hits,
                        self.raw_cache_misses,
                        self.vector_cache_hits,
                        self.vector_cache_misses,
                        self.raw_cache.count(),
                        self.vector_cache.count(),
                        self.raw_cache_key_bytes,
                        self.raw_read_value_bytes,
                        self.vector_cache_bytes,
                        self.context.index_name,
                    },
                );
            }
            self.clearRawCacheKeys();
            self.raw_cache.deinit(self.context.manager.alloc);
            var vector_it = self.vector_cache.iterator();
            while (vector_it.next()) |entry| self.context.manager.alloc.free(entry.value_ptr.*);
            self.vector_cache.deinit(self.context.manager.alloc);
            if (self.read_txn) |*txn| txn.abort();
            self.* = undefined;
        }

        fn rawReadLimitBytes(self: *const @This()) u64 {
            const manager = self.context.manager.resource_manager orelse return DefaultRawReadLimitBytes;
            const stats = manager.sliceStats(self.working_slice);
            if (stats.hard_limit_bytes == 0) return DefaultRawReadLimitBytes;
            return @min(MaxRawReadLimitBytes, @max(@as(u64, 1), stats.hard_limit_bytes / 4));
        }

        fn rawWorkingBytes(self: *const @This()) u64 {
            return self.vector_cache_bytes +| self.raw_cache_key_bytes +| self.raw_read_value_bytes;
        }

        fn observeWorkingBytes(self: *@This()) void {
            self.context.manager.observeDenseWorkingBytes(self.working_slice, &self.working_bytes_current, self.rawWorkingBytes());
        }

        fn clearRawCacheKeys(self: *@This()) void {
            var it = self.raw_cache.keyIterator();
            while (it.next()) |key| self.context.manager.alloc.free(key.*);
            self.raw_cache.clearRetainingCapacity();
            self.raw_cache_key_bytes = 0;
        }

        fn recycleRawReadState(self: *@This()) void {
            self.clearRawCacheKeys();
            if (self.read_txn) |*txn| {
                txn.abort();
                self.read_txn = null;
            }
            self.raw_read_value_bytes = 0;
            self.observeWorkingBytes();
        }

        fn recycleRawReadStateIfNeeded(self: *@This()) void {
            if (!self.recycle_raw_reads) return;
            if (self.raw_cache_key_bytes +| self.raw_read_value_bytes >= self.rawReadLimitBytes()) {
                self.recycleRawReadState();
            }
        }

        fn getTxn(self: *@This(), store: *docstore_mod.DocStore) !*docstore_mod.DocStore.Txn {
            if (self.read_txn == null) {
                self.read_txn = switch (self.read_txn_kind) {
                    .probe => try store.beginProbeTxnWithBlockCacheAdmission(self.block_cache_admission),
                    .snapshot => try store.beginReadTxnWithBlockCacheAdmission(self.block_cache_admission),
                };
            }
            return &self.read_txn.?;
        }

        fn noteRawValuesLoaded(self: *@This(), values: []const ?[]const u8) void {
            if (self.txn_override != null) return;
            var bytes: u64 = 0;
            for (values) |maybe_value| {
                const value = maybe_value orelse continue;
                bytes +|= @intCast(value.len);
            }
            self.raw_read_value_bytes +|= bytes;
            // A getMany is one bounded working set. Account its retained
            // transaction pages once, rather than performing an atomic
            // ResourceManager update for every returned vector.
            self.observeWorkingBytes();
        }

        fn maybeCacheRawValue(self: *@This(), key: []const u8, value: []const u8) !void {
            if (!self.cache_raw_values) return;
            if (self.raw_cache.contains(key)) return;
            const next_key_bytes = self.raw_cache_key_bytes +| @as(u64, @intCast(key.len));
            if (next_key_bytes +| self.raw_read_value_bytes > self.rawReadLimitBytes()) return;
            const owned_key = try self.context.manager.alloc.dupe(u8, key);
            errdefer self.context.manager.alloc.free(owned_key);
            try self.raw_cache.put(self.context.manager.alloc, owned_key, value);
            self.raw_cache_key_bytes = next_key_bytes;
            self.observeWorkingBytes();
        }

        fn get(self: *@This(), store: *docstore_mod.DocStore, key: []const u8) ![]const u8 {
            self.recycleRawReadStateIfNeeded();
            if (self.cache_raw_values) {
                if (self.raw_cache.get(key)) |cached| {
                    self.raw_cache_hits += 1;
                    return cached;
                }
            }
            self.raw_cache_misses += 1;
            self.raw_scalar_reads += 1;
            const value = if (self.txn_override) |txn|
                try txn.get(key)
            else
                try (try self.getTxn(store)).get(key);
            self.noteRawValuesLoaded(&.{@as(?[]const u8, value)});
            try self.maybeCacheRawValue(key, value);
            return value;
        }

        fn getManySorted(self: *@This(), store: *docstore_mod.DocStore, keys: []const []const u8, values: []?[]const u8) !void {
            if (keys.len != values.len) return error.InvalidArgument;
            @memset(values, null);
            if (keys.len == 0) return;
            self.recycleRawReadStateIfNeeded();

            const miss_keys = try self.context.manager.alloc.alloc([]const u8, keys.len);
            defer self.context.manager.alloc.free(miss_keys);
            const miss_indexes = try self.context.manager.alloc.alloc(usize, keys.len);
            defer self.context.manager.alloc.free(miss_indexes);

            var miss_count: usize = 0;
            for (keys, 0..) |key, i| {
                if (self.cache_raw_values) {
                    if (self.raw_cache.get(key)) |cached| {
                        self.raw_cache_hits += 1;
                        values[i] = cached;
                        continue;
                    }
                }
                self.raw_cache_misses += 1;
                miss_keys[miss_count] = key;
                miss_indexes[miss_count] = i;
                values[i] = null;
                miss_count += 1;
            }
            if (miss_count == 0) return;
            self.raw_batch_reads += 1;

            const miss_values = try self.context.manager.alloc.alloc(?[]const u8, miss_count);
            defer self.context.manager.alloc.free(miss_values);
            @memset(miss_values, null);
            const debug_timing = getenv("ANTFLY_DEBUG_DENSE_VECTOR_LOAD_SESSION") != null;
            const txn_start_ns = if (debug_timing) platform_time.monotonicNs() else 0;
            var txn_opened = false;
            if (self.txn_override) |txn| {
                if (debug_timing) txn_opened = false;
                const read_start_ns = if (debug_timing) platform_time.monotonicNs() else 0;
                try txn.getManySorted(miss_keys[0..miss_count], miss_values);
                if (debug_timing and miss_count >= 32) {
                    std.log.debug(
                        "dense vector load batch index={s} keys={} txn_opened={} txn_us={} read_us={} kind=batch",
                        .{ self.context.index_name, miss_count, txn_opened, (read_start_ns - txn_start_ns) / 1000, (platform_time.monotonicNs() - read_start_ns) / 1000 },
                    );
                }
            } else {
                const had_txn = self.read_txn != null;
                const txn = try self.getTxn(store);
                txn_opened = !had_txn;
                const read_start_ns = if (debug_timing) platform_time.monotonicNs() else 0;
                try txn.getManySorted(miss_keys[0..miss_count], miss_values);
                if (debug_timing and miss_count >= 32) {
                    std.log.debug(
                        "dense vector load batch index={s} keys={} txn_opened={} txn_us={} read_us={} kind={s}",
                        .{
                            self.context.index_name,
                            miss_count,
                            txn_opened,
                            (read_start_ns - txn_start_ns) / 1000,
                            (platform_time.monotonicNs() - read_start_ns) / 1000,
                            switch (self.read_txn_kind) {
                                .probe => "probe",
                                .snapshot => "snapshot",
                            },
                        },
                    );
                }
            }
            self.noteRawValuesLoaded(miss_values[0..miss_count]);
            for (miss_values[0..miss_count], 0..) |maybe_value, i| {
                const out_index = miss_indexes[i];
                values[out_index] = maybe_value;
                const value = maybe_value orelse continue;
                try self.maybeCacheRawValue(miss_keys[i], value);
            }
        }

        fn getVector(self: *@This(), vector_id: u64) ?[]const f32 {
            if (self.vector_cache.get(vector_id)) |cached| {
                self.vector_cache_hits += 1;
                return cached;
            }
            self.vector_cache_misses += 1;
            return null;
        }

        fn cacheVector(self: *@This(), vector_id: u64, vector: []const f32) !void {
            if (self.vector_cache.contains(vector_id)) return;
            if (!self.cache_vectors) return;
            const byte_len: u64 = @intCast(vector.len * @sizeOf(f32));
            const next_bytes = std.math.add(u64, self.vector_cache_bytes, byte_len) catch return;
            const next_working_bytes = next_bytes +| self.raw_cache_key_bytes +| self.raw_read_value_bytes;
            if (!self.context.manager.tryObserveDenseWorkingBytes(self.working_slice, &self.working_bytes_current, next_working_bytes)) return;
            errdefer self.observeWorkingBytes();

            const owned = try self.context.manager.alloc.dupe(f32, vector);
            errdefer self.context.manager.alloc.free(owned);
            try self.vector_cache.put(self.context.manager.alloc, vector_id, owned);
            self.vector_cache_bytes = next_bytes;
        }
    };

    const DenseVectorMetadataPresenceMemo = struct {
        values: std.AutoHashMapUnmanaged(u64, bool) = .empty,
        metadata: std.AutoHashMapUnmanaged(u64, []const u8) = .empty,

        fn deinit(self: *@This(), alloc: Allocator) void {
            var it = self.metadata.valueIterator();
            while (it.next()) |value| alloc.free(value.*);
            self.values.deinit(alloc);
            self.metadata.deinit(alloc);
            self.* = undefined;
        }

        fn get(self: *const @This(), vector_id: u64) ?bool {
            return self.values.get(vector_id);
        }

        fn put(self: *@This(), alloc: Allocator, vector_id: u64, present: bool) !void {
            try self.values.put(alloc, vector_id, present);
        }

        fn getMetadata(self: *const @This(), vector_id: u64) ?[]const u8 {
            return self.metadata.get(vector_id);
        }

        fn notePresent(self: *@This(), alloc: Allocator, vector_id: u64, metadata: []const u8) !void {
            const owned = try alloc.alloc(u8, metadata.len);
            std.mem.copyForwards(u8, owned, metadata);
            errdefer alloc.free(owned);
            try self.values.put(alloc, vector_id, true);
            if (try self.metadata.fetchPut(alloc, vector_id, owned)) |existing| {
                if (existing.value.ptr != owned.ptr or existing.value.len != owned.len) {
                    alloc.free(existing.value);
                }
            }
        }

        fn noteAbsent(self: *@This(), alloc: Allocator, vector_id: u64) !void {
            try self.values.put(alloc, vector_id, false);
            if (self.metadata.fetchRemove(vector_id)) |existing| {
                alloc.free(existing.value);
            }
        }
    };

    threadlocal var active_dense_vector_load_session: ?*DenseVectorLoadSession = null;

