    // Provide the background lane that algebraic indexes use for HLL cardinality
    // maintenance. Call before loading indexes so newly opened algebraic indexes
    // pick up the lane; already-open indexes are (re)attached here too.
    pub fn attachHllMaintenance(self: *IndexManager, lane: background_runtime_mod.DurableJobLane, owner_id: u64) void {
        self.hll_maintenance_lane = lane;
        self.hll_maintenance_owner_id = owner_id;
        for (self.algebraic_indexes.items) |*entry| {
            entry.index.attachHllMaintenanceLane(lane, owner_id);
            if (self.primary_store) |store| {
                entry.index.loadAdaptiveHllCardinalities(store) catch |err| {
                    std.log.warn("adaptive HLL registry recovery failed index={s} err={s}", .{ entry.config.name, @errorName(err) });
                };
                entry.index.resumeHllMaintenance(store);
            }
        }
    }

    fn bindPrimaryStore(self: *IndexManager, store: anytype) void {
        const Store = @TypeOf(store);
        if (comptime Store == *docstore_mod.DocStore) {
            self.primary_store = store;
        }
    }

    fn freeTextIndexEntry(self: *IndexManager, entry: *TextIndex) void {
        self.deinitTextIndexEntry(entry, false);
    }

    fn abandonTextIndexEntryAfterCrash(self: *IndexManager, entry: *TextIndex) void {
        self.deinitTextIndexEntry(entry, true);
    }

    fn deinitTextIndexEntry(self: *IndexManager, entry: *TextIndex, abandon_after_crash: bool) void {
        entry.detachAllMergeDeletionStates();
        entry.merge_deletion_states.deinit(self.alloc);
        entry.analysis_mutex.lockExclusive();
        defer entry.analysis_mutex.unlockExclusive();
        if (abandon_after_crash) {
            entry.persistent.abandonAfterCrash();
        } else {
            entry.persistent.close();
        }
        self.destroyIndexApplyMutex(entry.apply_mutex);
        if (entry.chunk_name) |chunk_name| self.alloc.free(chunk_name);
        introducer_mod.freeTextAnalysisConfig(self.alloc, entry.text_analysis);
        for (entry.observed_field_analyzers) |item| {
            self.alloc.free(item.field_name);
            self.alloc.free(item.analyzer_name);
        }
        if (entry.observed_field_analyzers.len > 0) self.alloc.free(entry.observed_field_analyzers);
        if (entry.runtime_schema) |schema| schema_mod.freeSchema(self.alloc, schema);
        self.alloc.free(entry.rebuild_root_path);
        entry.config.deinit(self.alloc);
    }

    /// Regenerate every algebraic index's schema-derived config from `schema_json`
    /// and apply it in place when the schema-derived capability actually changed.
    /// Carries forward user-tunable runtime knobs, gates dynamic-only changes at
    /// field resolution, and gates static type/layout changes at the whole
    /// planner. A generation-local projection completion marker releases either
    /// gate after rebuild. No-op when there are no algebraic indexes, no schema,
    /// or the capability fingerprint is unchanged.
    pub fn reloadAlgebraicSchemaConfigs(self: *IndexManager, schema_json: []const u8) !void {
        if (schema_json.len == 0) return;
        for (self.algebraic_indexes.items) |*entry| {
            const cur = entry.index.config();
            const new_config_json = try algebraic_mod.schema_capability.configJsonFromSchemaJsonAlloc(self.alloc, cur.table, schema_json);
            defer self.alloc.free(new_config_json);

            var new_parsed = try std.json.parseFromSlice(algebraic_mod.index.Config, self.alloc, new_config_json, .{ .allocate = .alloc_always });
            defer new_parsed.deinit();

            // Skip when the schema-derived capability is unchanged. Compare the
            // capability fingerprint (which encodes schema_version, fields, and
            // dynamic-template rules) rather than raw bytes: the live and durable
            // serializations differ in shape and tunable knobs, so a byte compare
            // would never short-circuit and every reconcile would churn the
            // live config.
            if (cur.capability_fingerprint.len > 0 and
                std.mem.eql(u8, new_parsed.value.capability_fingerprint, cur.capability_fingerprint)) continue;

            const delta = algebraic_mod.index.schemaCapabilityDelta(cur, new_parsed.value);
            const projection_ready = entry.index.projectionConfigReady();

            // Carry forward user-tunable runtime knobs (the durable regeneration
            // in api/tables.zig preserves the same set) so a schema/template
            // change does not silently reset planner/adaptive tuning in place.
            new_parsed.value.adaptive = cur.adaptive;
            new_parsed.value.pathfact_policy = cur.pathfact_policy;
            new_parsed.value.max_result_buckets = cur.max_result_buckets;
            new_parsed.value.max_planner_scan_rows = cur.max_planner_scan_rows;
            new_parsed.value.max_batch_accumulator_entries = cur.max_batch_accumulator_entries;
            new_parsed.value.max_cardinality_cache_bytes = cur.max_cardinality_cache_bytes;
            new_parsed.value.max_hll_contributions_per_document = cur.max_hll_contributions_per_document;
            new_parsed.value.max_hll_contribution_bytes_per_document = cur.max_hll_contribution_bytes_per_document;
            new_parsed.value.max_distributed_hll_partial_bytes = cur.max_distributed_hll_partial_bytes;
            new_parsed.value.max_hll_maintenance_rows_per_tick = cur.max_hll_maintenance_rows_per_tick;
            new_parsed.value.max_pending_hll_observation_entries = cur.max_pending_hll_observation_entries;
            new_parsed.value.max_pending_hll_observation_bytes = cur.max_pending_hll_observation_bytes;
            new_parsed.value.hll_cardinalities = cur.hll_cardinalities;
            new_parsed.value.min_max_candidate_cache_size = cur.min_max_candidate_cache_size;
            new_parsed.value.enable_temporal_range_pruning = cur.enable_temporal_range_pruning;

            // Static type/layout changes can make old docfacts incompatible with
            // the regenerated config, so gate the whole planner until a shadow
            // rebuild proves complete coverage. Preserve an older non-ready
            // lifecycle unless this generation already has such a proof.
            if (delta.static_fields_changed) {
                new_parsed.value.capability_lifecycle_status = "rebuild_required";
            } else if (!projection_ready and !algebraic_mod.index.capabilityLifecycleStatusReady(cur.capability_lifecycle_status)) {
                new_parsed.value.capability_lifecycle_status = cur.capability_lifecycle_status;
            }

            // Dynamic-only changes use the narrower gate so unchanged static
            // fields keep accelerating. A completed matching generation may
            // clear a conservative catalog flag in runtime; otherwise preserve
            // pending state until repair publishes a fully rebuilt generation.
            new_parsed.value.dynamic_rules_backfill_pending =
                new_parsed.value.dynamic_field_rules.len > 0 and
                (delta.dynamic_rules_changed or (cur.dynamic_rules_backfill_pending and !projection_ready));

            const merged_json = try std.json.Stringify.valueAlloc(self.alloc, new_parsed.value, .{ .emit_null_optional_fields = false });
            defer self.alloc.free(merged_json);

            const owned = try self.alloc.dupe(u8, merged_json);
            errdefer self.alloc.free(owned);
            try entry.index.reloadConfigJson(merged_json);
            self.alloc.free(entry.config.config_json);
            entry.config.config_json = owned;
        }
    }

    fn freeAlgebraicIndexEntry(self: *IndexManager, entry: *AlgebraicIndex) void {
        entry.index.destroy();
        self.destroyIndexApplyMutex(entry.apply_mutex);
        entry.config.deinit(self.alloc);
        entry.* = undefined;
    }

    fn freeDenseIndexEntry(self: *IndexManager, entry: *DenseIndex) void {
        self.deinitDenseIndexEntry(entry, false);
    }

    fn abandonDenseIndexEntryAfterCrash(self: *IndexManager, entry: *DenseIndex) void {
        self.deinitDenseIndexEntry(entry, true);
    }

    fn deinitDenseIndexEntry(self: *IndexManager, entry: *DenseIndex, abandon_after_crash: bool) void {
        if (abandon_after_crash) {
            entry.index.abandonAfterCrash();
        } else {
            entry.index.close();
        }
        self.destroyIndexApplyMutex(entry.apply_mutex);
        if (entry.vector_loader_context) |ctx| ctx.deinit(self.alloc);
        entry.ordinal_vector_ids.deinit(self.alloc);
        entry.vector_ordinals.deinit(self.alloc);
        self.alloc.free(entry.field_name);
        if (entry.chunk_name) |chunk_name| self.alloc.free(chunk_name);
        if (entry.embedding_name) |embedding_name| self.alloc.free(embedding_name);
        entry.config.deinit(self.alloc);
    }

    fn reopenDenseIndexStorage(self: *IndexManager, entry: *DenseIndex, path: []const u8) !void {
        const zpath = try self.alloc.dupeZ(u8, path);
        defer self.alloc.free(zpath);

        const dense_cfg = try parseDenseConfig(self.alloc, entry.config.config_json);
        defer dense_cfg.deinit(self.alloc);
        const cache_limits = self.resource_manager.?.hbcCacheLimits(dense_cfg.dims, self.hbc_cache != null);

        var index = try hbc_mod.HBCIndex.openWithLsmOptions(self.alloc, zpath, .{
            .storage_backend = self.dense_storage_backend,
            .dims = dense_cfg.dims,
            .metric = dense_cfg.metric,
            .split_algo = dense_cfg.split_algo,
            .search_width = dense_cfg.search_width,
            .epsilon = dense_cfg.epsilon,
            .branching_factor = dense_cfg.branching_factor,
            .leaf_size = dense_cfg.leaf_size,
            .bulk_build_algo = dense_cfg.bulk_build_algo,
            .kmeans_backend = dense_cfg.kmeans_backend,
            .kmeans_update_strategy = dense_cfg.kmeans_update_strategy,
            .use_quantization = dense_cfg.use_quantization,
            .rerank_policy = dense_cfg.rerank_policy,
            .quantizer_seed = dense_cfg.quantizer_seed,
            .use_random_ortho_trans = dense_cfg.use_random_ortho_trans,
            .max_cached_nodes = cache_limits.max_cached_nodes,
            .max_cached_vectors = cache_limits.max_cached_vectors,
            .max_cached_metadata = cache_limits.max_cached_metadata,
            .lazy_posting_maintenance = dense_cfg.lazy_posting_maintenance,
            .auto_posting_maintenance_max_postings = dense_cfg.auto_posting_maintenance_max_postings,
            .centroid_directory_mode = dense_cfg.centroid_directory_mode,
            .flat_centroid_block_size = dense_cfg.flat_centroid_block_size,
            .flat_centroid_probe_count = dense_cfg.flat_centroid_probe_count,
            .no_sync = self.relaxed_split_durability,
            .no_meta_sync = self.relaxed_split_durability,
        }, .{
            .backend_options = self.dense_lsm_options,
            .storage = self.dense_lsm_storage,
            .cache = self.lsm_cache,
            .root_generation = self.lsm_root_generation,
        });
        errdefer index.close();

        if (self.hbc_cache) |cache| index.attachSharedCache(cache);
        if (self.resource_manager) |manager| {
            index.attachResourceManagerWithSharedCacheBinding(manager, self.bind_cache_resource_manager);
        }

        const vector_loader_context = try self.alloc.create(DenseVectorLoadContext);
        errdefer self.alloc.destroy(vector_loader_context);
        vector_loader_context.* = .{
            .manager = self,
            .index_name = try self.alloc.dupe(u8, entry.config.name),
        };
        errdefer {
            self.alloc.free(vector_loader_context.index_name);
            self.alloc.destroy(vector_loader_context);
        }
        index.setExternalVectorLoader(vector_loader_context, loadDenseVectorForHbc);
        index.setExternalVectorScratchLoader(vector_loader_context, loadDenseVectorForHbcIntoScratch);
        index.setExternalVectorBatchScratchLoader(vector_loader_context, loadDenseVectorsForHbcBatch);
        index.setExternalVectorBatchTransformedMatrixLoader(vector_loader_context, loadDenseVectorsForHbcBatchIntoTransformedMatrix);
        index.setExternalVectorBatchDistanceLoader(vector_loader_context, scoreDenseVectorsForHbcBatch);

        entry.index = index;
        entry.vector_loader_context = vector_loader_context;
    }

    pub fn resetDenseIndexForArtifactRebuild(self: *IndexManager, index_name: []const u8) !void {
        const entry = self.denseIndex(index_name) orelse return error.IndexNotFound;
        const path = try self.activeIndexPath(index_name);
        defer self.alloc.free(path);

        entry.index.close();
        if (entry.vector_loader_context) |ctx| {
            ctx.deinit(self.alloc);
            entry.vector_loader_context = null;
        }

        deleteIndexDirIfPresent(path);
        entry.ordinal_vector_ids.clearRetainingCapacity();
        entry.vector_ordinals.clearRetainingCapacity();
        try self.reopenDenseIndexStorage(entry, path);
    }

    pub fn resetSparseIndexForArtifactRebuild(self: *IndexManager, index_name: []const u8) !void {
        const entry = self.sparseIndex(index_name) orelse return error.IndexNotFound;
        const path = try self.activeIndexPath(index_name);
        defer self.alloc.free(path);

        entry.index.close();
        deleteIndexDirIfPresent(path);

        const zpath = try self.alloc.dupeZ(u8, path);
        defer self.alloc.free(zpath);
        entry.index = try sparse_mod.SparseIndex.open(self.alloc, zpath, .{
            .no_sync = self.relaxed_split_durability,
            .no_meta_sync = self.relaxed_split_durability,
            .backend = self.sparse_backend,
            .lsm_storage = self.sparse_lsm_storage,
            .lsm_cache = self.lsm_cache,
            .lsm_options = self.sparse_lsm_options,
            .lsm_root_generation = self.lsm_root_generation,
        });
    }

    pub fn resetGraphIndexForArtifactRebuild(self: *IndexManager, index_name: []const u8) !void {
        const entry = self.graphIndex(index_name) orelse return error.IndexNotFound;
        const path = try self.activeIndexPath(index_name);
        defer self.alloc.free(path);

        var graph_cfg = try parseGraphConfig(self.alloc, entry.config.config_json);
        defer graph_cfg.deinit(self.alloc);

        const forward_path = try std.fmt.allocPrint(self.alloc, "{s}/forward", .{path});
        defer self.alloc.free(forward_path);
        const reverse_path = try std.fmt.allocPrint(self.alloc, "{s}/reverse", .{path});
        defer self.alloc.free(reverse_path);
        const zforward = try self.alloc.dupeZ(u8, forward_path);
        defer self.alloc.free(zforward);
        const zreverse = try self.alloc.dupeZ(u8, reverse_path);
        defer self.alloc.free(zreverse);

        entry.index.close();
        deleteIndexDirIfPresent(path);

        entry.index = try graph_mod.GraphIndex.openWithPrivateStores(self.alloc, zforward, zreverse, entry.config.name, .{
            .no_sync = self.relaxed_split_durability,
            .no_meta_sync = self.relaxed_split_durability,
            .reverse_backend = self.graph_reverse_backend,
            .reverse_lsm_storage = self.graph_lsm_storage,
            .reverse_lsm_cache = self.lsm_cache,
            .reverse_lsm_options = self.graph_reverse_lsm_options,
            .reverse_lsm_root_generation = self.lsm_root_generation,
            .edge_type_configs = entry.edge_type_configs,
            .rebuild_root_path = path,
            .rebuild_owner_generation = coverageGenerationForConfig(entry.config),
            .algebraic_semiring_traversal = graph_cfg.algebraic_semiring_traversal,
        });
    }

    pub fn resetFullTextIndexForArtifactRebuild(self: *IndexManager, store: *docstore_mod.DocStore, index_name: []const u8) !u64 {
        const entry = self.textIndexEntry(index_name) orelse return error.IndexNotFound;
        const rebuild_state = self.rebuildState(.full_text, entry.rebuild_root_path, entry.config);

        try entry.persistent.resetAllForRebuild();
        try rebuild_state.updateWithIo(self.checkpointIo(), "");
        try self.backfillTextIndex(store, entry, null);
        try entry.persistent.sync(true);
        try self.saveBackfilledAppliedSequence(store, entry.config);
        var checkpoint = try apply_state.loadProjectionCheckpointWithSidecar(
            self.alloc,
            self.checkpointIo(),
            store,
            self.applied_sequence_checkpoint_path,
            entry.config.name,
        );
        checkpoint.status = .clean;
        checkpoint.config_hash = types.indexConfigHash(entry.config);
        try apply_state.saveProjectionCheckpointWithSidecar(
            self.alloc,
            self.checkpointIo(),
            store,
            self.applied_sequence_checkpoint_path,
            entry.config.name,
            checkpoint,
        );

        const rebuilt = entry.persistent.snapshot().liveDocCount();
        const compaction_pending = try self.textIndexNeedsMerge(&entry.persistent, activeTextMergePolicy());
        entry.compaction_pending.store(compaction_pending, .release);
        if (compaction_pending) {
            TextMergeScheduler.schedule(entry);
        } else {
            TextMergeScheduler.noteComplete(entry);
        }
        return rebuilt;
    }

    pub fn resetFullTextIndexForArtifactRebuildFromReadTxn(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        read_txn: *docstore_mod.DocStore.Txn,
        index_name: []const u8,
        cancel_check: ?types.RepairCancelCheck,
        capacity_check: ?types.RepairCapacityCheck,
    ) !u64 {
        const entry = self.textIndexEntry(index_name) orelse return error.IndexNotFound;
        const rebuild_state = self.rebuildState(.full_text, entry.rebuild_root_path, entry.config);

        try checkRepairCancelled(cancel_check);
        try entry.persistent.resetAllForRebuild();
        try rebuild_state.updateWithIo(self.checkpointIo(), "");
        try self.backfillTextIndexFromReadTxn(store, read_txn, entry, null, cancel_check, capacity_check);
        try checkRepairCancelled(cancel_check);
        try entry.persistent.sync(true);

        return entry.persistent.snapshot().liveDocCount();
    }

    pub fn clearDenseHbcCaches(self: *IndexManager) void {
        for (self.dense_indexes.items) |*entry| entry.index.clearAllCaches();
    }

    fn freeSparseIndexEntry(self: *IndexManager, entry: *SparseIndex) void {
        self.deinitSparseIndexEntry(entry, false);
    }

    fn abandonSparseIndexEntryAfterCrash(self: *IndexManager, entry: *SparseIndex) void {
        self.deinitSparseIndexEntry(entry, true);
    }

    fn deinitSparseIndexEntry(self: *IndexManager, entry: *SparseIndex, abandon_after_crash: bool) void {
        if (abandon_after_crash) {
            entry.index.abandonAfterCrash();
        } else {
            entry.index.close();
        }
        self.destroyIndexApplyMutex(entry.apply_mutex);
        self.alloc.free(entry.field_name);
        if (entry.chunk_name) |chunk_name| self.alloc.free(chunk_name);
        if (entry.embedding_name) |embedding_name| self.alloc.free(embedding_name);
        self.alloc.free(entry.rebuild_root_path);
        entry.config.deinit(self.alloc);
    }

    fn freeGraphIndexEntry(self: *IndexManager, entry: *GraphIndex) void {
        self.deinitGraphIndexEntry(entry, false);
    }

    fn abandonGraphIndexEntryAfterCrash(self: *IndexManager, entry: *GraphIndex) void {
        self.deinitGraphIndexEntry(entry, true);
    }

    fn deinitGraphIndexEntry(self: *IndexManager, entry: *GraphIndex, abandon_after_crash: bool) void {
        if (abandon_after_crash) {
            entry.index.abandonAfterCrash();
        } else {
            entry.index.close();
        }
        self.destroyIndexApplyMutex(entry.apply_mutex);
        for (entry.edge_type_configs) |cfg| {
            self.alloc.free(cfg.name);
            if (cfg.field_name) |field_name| self.alloc.free(field_name);
        }
        self.alloc.free(entry.edge_type_configs);
        if (entry.artifact_source) |*source| source.deinit(self.alloc);
        self.alloc.free(entry.rebuild_root_path);
        entry.config.deinit(self.alloc);
    }

    pub fn deinit(self: *IndexManager) void {
        self.deinitWithBackendDisposition(false);
    }

    /// Releases a pre-crash generation without executing backend finalizers.
    /// This is for storage simulators and fault injection after the modeled
    /// device has already rolled back volatile state. Call
    /// prepareForCrashRollback() before performing that rollback.
    pub fn abandonAfterCrash(self: *IndexManager) void {
        self.deinitWithBackendDisposition(true);
    }

    /// Quiesce delayed full-text file reclamation before a modeled storage
    /// rollback. This fence must precede device.crash(); abandonAfterCrash()
    /// may then safely release the stale in-memory generation.
    pub fn prepareForCrashRollback(self: *IndexManager) void {
        for (self.text_indexes.items) |*entry| {
            entry.persistent.prepareForCrashRollback();
        }
    }

    fn deinitWithBackendDisposition(self: *IndexManager, abandon_after_crash: bool) void {
        self.releaseFullTextPendingBytes();
        self.text_merge_scheduler.deinit(self.alloc);
        for (self.text_indexes.items) |*entry| {
            if (abandon_after_crash) self.abandonTextIndexEntryAfterCrash(entry) else self.freeTextIndexEntry(entry);
        }
        for (self.dense_indexes.items) |*entry| {
            if (abandon_after_crash) self.abandonDenseIndexEntryAfterCrash(entry) else self.freeDenseIndexEntry(entry);
        }
        for (self.sparse_indexes.items) |*entry| {
            if (abandon_after_crash) self.abandonSparseIndexEntryAfterCrash(entry) else self.freeSparseIndexEntry(entry);
        }
        for (self.graph_indexes.items) |*entry| {
            if (abandon_after_crash) self.abandonGraphIndexEntryAfterCrash(entry) else self.freeGraphIndexEntry(entry);
        }
        for (self.algebraic_indexes.items) |*entry| {
            self.freeAlgebraicIndexEntry(entry);
        }
        self.clearStatusOnlyIndexConfigs();
        self.clearFailedIndexLoads();
        self.failed_index_loads.deinit(self.alloc);
        self.clearRepairUnavailableIndexes();
        self.repair_unavailable_indexes.deinit(self.alloc);
        self.clearManagedAdmissionSnapshot();
        self.managed_admission_indexes.deinit(self.alloc);
        self.clearIndexLoadStates();
        self.index_load_states.deinit(self.alloc);
        for (self.enrichments.items) |*entry| entry.deinit(self.alloc);
        for (self.resolvers.items) |*entry| entry.deinit(self.alloc);
        self.text_indexes.deinit(self.alloc);
        self.dense_indexes.deinit(self.alloc);
        self.sparse_indexes.deinit(self.alloc);
        self.graph_indexes.deinit(self.alloc);
        self.algebraic_indexes.deinit(self.alloc);
        self.enrichments.deinit(self.alloc);
        self.resolvers.deinit(self.alloc);
        self.alloc.free(self.base_path);
        if (self.owned_resource_manager) |manager| {
            manager.deinit(self.alloc);
            self.alloc.destroy(manager);
        }
        self.* = undefined;
    }

    fn clearStatusOnlyIndexConfigs(self: *IndexManager) void {
        for (self.status_only_index_configs) |*cfg| cfg.deinit(self.alloc);
        if (self.status_only_index_configs.len > 0) self.alloc.free(self.status_only_index_configs);
        self.status_only_index_configs = &.{};
    }

    /// Load error recorded for `name` during the last catalog load, or null
    /// if the index loaded normally (or is not configured).
    pub fn loadFailure(self: *const IndexManager, name: []const u8) ?[]const u8 {
        return (self.failed_index_loads.get(name) orelse return null).err_name;
    }

    pub const IndexLoadRecoveryAction = enum {
        retry_open,
        rebuild_from_artifacts,
        manual_intervention,
    };

    /// Classifies policy, not corruption severity. Keep the destructive
    /// automatic-rebuild allowlist deliberately narrow: an unknown load error
    /// must never become permission to delete or replace an index root.
    pub fn loadFailureRecoveryAction(err_name: []const u8) IndexLoadRecoveryAction {
        if (std.mem.eql(u8, err_name, "IncompleteBulkPublish")) {
            return .rebuild_from_artifacts;
        }
        if (std.mem.eql(u8, err_name, "TableReadChurn")) {
            return .retry_open;
        }
        return .manual_intervention;
    }

    pub fn recoveryActionForIndex(self: *const IndexManager, name: []const u8) ?IndexLoadRecoveryAction {
        const err_name = self.loadFailure(name) orelse return null;
        return loadFailureRecoveryAction(err_name);
    }

    pub fn hasLoadFailures(self: *const IndexManager) bool {
        return self.failed_index_loads.count() > 0;
    }

    /// Refresh schema-derived mapping state for text indexes that have not
    /// published any documents yet. Table creation can provision the default
    /// full-text index before its schema metadata is committed locally; without
    /// this refresh, early writes are projected with dynamic mappings and become
    /// unreachable through the declared field after a clean restart.
    ///
    /// Non-empty generations are deliberately immutable here. Schema migration
    /// serves those through their versioned runtime until a new generation is
    /// built and promoted.
    pub fn refreshEmptyTextIndexSchemas(self: *IndexManager, store: anytype) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();

        for (self.text_indexes.items) |*entry| {
            lockAtomicWithBackoff(entry.apply_mutex);
            defer entry.apply_mutex.unlock();
            entry.analysis_mutex.lockExclusive();
            defer entry.analysis_mutex.unlockExclusive();

            if (entry.persistent.hasPhysicalSegments()) continue;

            const runtime_schema = try loadRuntimeSchemaForTextIndex(self.alloc, store, entry.config.name);
            var runtime_schema_owned = runtime_schema;
            errdefer if (runtime_schema_owned) |schema| schema_mod.freeSchema(self.alloc, schema);

            var text_analysis = try parseTextAnalysisForIndexConfig(self.alloc, entry.config.config_json, runtime_schema_owned);
            var text_analysis_owned = true;
            errdefer if (text_analysis_owned) introducer_mod.freeTextAnalysisConfig(self.alloc, text_analysis);
            try appendObservedFieldAnalyzers(self.alloc, &text_analysis, entry.observed_field_analyzers);
            const provenance = try TextProjectionProvenance.fromRuntimeSchema(
                self.alloc,
                entry.config,
                runtime_schema_owned,
            );

            // Registry claims may be safely ahead of an empty generation, but
            // the generation witness must never be ahead of its live runtime.
            // Persist claims first, then the witness, then swap infallibly.
            try publishFullTextDictionaryRegistry(store, self.alloc, entry.config.name, text_analysis);
            try saveTextProjectionProvenance(&entry.persistent, self.alloc, provenance);

            const previous_schema = entry.runtime_schema;
            const previous_analysis = entry.text_analysis;
            entry.runtime_schema = runtime_schema_owned;
            entry.text_analysis = text_analysis;
            advanceTextProjectionRevisionAssumeAnalysisLocked(entry);
            runtime_schema_owned = null;
            text_analysis_owned = false;

            if (previous_schema) |schema| schema_mod.freeSchema(self.alloc, schema);
            introducer_mod.freeTextAnalysisConfig(self.alloc, previous_analysis);
        }
    }

    pub fn markRepairUnavailable(self: *IndexManager, name: []const u8) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        if (self.repair_unavailable_indexes.contains(name)) return;
        const owned = try self.alloc.dupe(u8, name);
        errdefer self.alloc.free(owned);
        try self.repair_unavailable_indexes.put(self.alloc, owned, {});
    }

    pub fn clearRepairUnavailable(self: *IndexManager, name: []const u8) void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        if (self.repair_unavailable_indexes.fetchRemove(name)) |entry| self.alloc.free(entry.key);
    }

    pub fn repairUnavailable(self: *IndexManager, name: []const u8) bool {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();
        return self.repair_unavailable_indexes.contains(name);
    }

    pub fn hasRepairUnavailableIndexes(self: *IndexManager) bool {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();
        return self.repair_unavailable_indexes.count() != 0;
    }

    fn clearRepairUnavailableIndexes(self: *IndexManager) void {
        var it = self.repair_unavailable_indexes.keyIterator();
        while (it.next()) |key| self.alloc.free(key.*);
        self.repair_unavailable_indexes.clearRetainingCapacity();
    }

    fn clearManagedAdmissionSnapshot(self: *IndexManager) void {
        var it = self.managed_admission_indexes.keyIterator();
        while (it.next()) |key| self.alloc.free(key.*);
        self.managed_admission_indexes.clearRetainingCapacity();
    }

    pub fn replaceManagedAdmissionSnapshot(
        self: *IndexManager,
        admissions: []const docstore_mod.OwnedKVPair,
    ) !void {
        lockAtomicWithBackoff(&self.managed_admission_mutex);
        defer self.managed_admission_mutex.unlock();
        self.clearManagedAdmissionSnapshot();
        try self.managed_admission_indexes.ensureTotalCapacity(self.alloc, @intCast(admissions.len));
        for (admissions) |admission| {
            const name = try internal_keys.managedIndexAdmissionNameAlloc(self.alloc, admission.key);
            errdefer self.alloc.free(name);
            const gop = self.managed_admission_indexes.getOrPutAssumeCapacity(name);
            if (gop.found_existing) {
                self.alloc.free(name);
                return error.InvalidManagedIndexAdmission;
            }
        }
    }

    pub fn clearManagedAdmissionSnapshotForIndex(self: *IndexManager, name: []const u8) void {
        lockAtomicWithBackoff(&self.managed_admission_mutex);
        defer self.managed_admission_mutex.unlock();
        if (self.managed_admission_indexes.fetchRemove(name)) |entry| self.alloc.free(entry.key);
    }

    pub fn markManagedAdmissionsUnavailable(self: *IndexManager) !void {
        var names = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (names.items) |name| self.alloc.free(name);
            names.deinit(self.alloc);
        }
        {
            lockAtomicWithBackoff(&self.managed_admission_mutex);
            defer self.managed_admission_mutex.unlock();
            try names.ensureTotalCapacity(self.alloc, self.managed_admission_indexes.count());
            var it = self.managed_admission_indexes.keyIterator();
            while (it.next()) |name| names.appendAssumeCapacity(try self.alloc.dupe(u8, name.*));
        }
        for (names.items) |name| try self.markRepairUnavailable(name);
    }

    fn managedAdmissionPending(self: *IndexManager, name: []const u8) bool {
        lockAtomicWithBackoff(&self.managed_admission_mutex);
        defer self.managed_admission_mutex.unlock();
        return self.managed_admission_indexes.contains(name);
    }

    fn clearFailedIndexLoads(self: *IndexManager) void {
        var it = self.failed_index_loads.keyIterator();
        while (it.next()) |key| self.alloc.free(key.*);
        self.failed_index_loads.clearRetainingCapacity();
    }

    fn dropFailedIndexLoad(self: *IndexManager, name: []const u8) void {
        if (self.failed_index_loads.fetchRemove(name)) |entry| self.alloc.free(entry.key);
    }

    fn clearIndexLoadStates(self: *IndexManager) void {
        var it = self.index_load_states.keyIterator();
        while (it.next()) |key| self.alloc.free(key.*);
        self.index_load_states.clearRetainingCapacity();
    }

    fn beginIndexLoadNoLock(self: *IndexManager, name: []const u8) !void {
        const owned_name = try self.alloc.dupe(u8, name);
        errdefer self.alloc.free(owned_name);
        const gop = try self.index_load_states.getOrPut(self.alloc, owned_name);
        if (!gop.found_existing) {
            gop.key_ptr.* = owned_name;
        } else {
            self.alloc.free(owned_name);
        }
        gop.value_ptr.* = .loading;
    }

    fn completeIndexLoadNoLock(self: *IndexManager, name: []const u8) void {
        if (self.index_load_states.getPtr(name)) |state| state.* = .complete;
    }

    fn dropIndexLoadStateNoLock(self: *IndexManager, name: []const u8) void {
        if (self.index_load_states.fetchRemove(name)) |entry| self.alloc.free(entry.key);
    }

    pub fn indexLoadComplete(self: *IndexManager, name: []const u8) bool {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();
        return (self.index_load_states.get(name) orelse .complete) == .complete;
    }

    fn appendStatusOnlyConfig(self: *IndexManager, cfg: types.IndexConfig) !void {
        const old = self.status_only_index_configs;
        const replacement = try self.alloc.alloc(types.IndexConfig, old.len + 1);
        @memcpy(replacement[0..old.len], old);
        replacement[old.len] = cfg;
        if (old.len > 0) self.alloc.free(old);
        self.status_only_index_configs = replacement;
    }

    /// Quarantine an index whose persisted artifacts could not be opened:
    /// keep its config visible (catalog persistence, status, drop/recreate)
    /// while the runtime index stays absent, and record the load error.
    /// Errors from an index open that indicate a transient read race rather
    /// than persistent artifact damage: a read-only replica open can race
    /// the writer's obsolete-run reclaim (FileNotFound after the manifest
    /// load), or table churn can invalidate the open mid-flight. On
    /// read-only opens these must propagate instead of quarantining — the
    /// query layer reopens against a fresh manifest and retries
    /// (queryWithTransientReadRetry), whereas a quarantined replica would
    /// serve IndexUnavailable until the read cache next invalidates it: the
    /// quarantine retry worker only runs on the writer. Writer opens keep
    /// quarantining everything — the writer cannot race its own (not yet
    /// started) reclaim, so FileNotFound there is persistent damage, and
    /// the writer's self-heal worker covers the unlikely transient case.
    /// Only meaningful now that the LSM run-table loader classifies
    /// FileNotFound separately from UnsupportedVersion.
    fn indexOpenErrorIsTransientRead(err: anyerror) bool {
        return switch (err) {
            error.FileNotFound, error.EndOfStream, error.TableReadChurn => true,
            else => false,
        };
    }

    fn recordFailedIndexLoad(self: *IndexManager, cfg: types.IndexConfig, err: anyerror) !void {
        if (self.loadFailure(cfg.name) != null) return;
        var cloned = try types.IndexConfig.clone(self.alloc, cfg);
        errdefer cloned.deinit(self.alloc);
        try self.appendStatusOnlyConfig(cloned);
        // The clone is owned by status_only_index_configs from here on.
        const name_key = try self.alloc.dupe(u8, cfg.name);
        errdefer self.alloc.free(name_key);
        try self.failed_index_loads.put(self.alloc, name_key, .{ .err_name = @errorName(err) });
    }

    const quarantine_retry_base_backoff_ns: u64 = 30 * std.time.ns_per_s;
    const quarantine_retry_max_backoff_ns: u64 = 10 * std.time.ns_per_min;

    fn quarantineRetryBackoffNs(attempts: u32) u64 {
        const shift: u6 = @intCast(@min(attempts, 5));
        return @min(quarantine_retry_base_backoff_ns << shift, quarantine_retry_max_backoff_ns);
    }

    pub const QuarantineRetryResult = struct {
        recovered: usize = 0,
        remaining: usize = 0,
    };

    /// DB-owned service fence for publishing a newly opened quarantined
    /// index. Opening and backfill happen outside this fence; only the final
    /// catalog commit excludes readers that borrow pointers into inline index
    /// arrays.
    pub const CatalogPublicationFence = struct {
        ptr: *anyopaque,
        lock_fn: *const fn (*anyopaque) void,
        unlock_fn: *const fn (*anyopaque) void,

        fn lock(self: @This()) void {
            self.lock_fn(self.ptr);
        }

        fn unlock(self: @This()) void {
            self.unlock_fn(self.ptr);
        }
    };

    /// Re-attempts opening quarantined indexes whose backoff deadline has
    /// passed (all of them when `force` is set). A successful open registers
    /// the runtime index, removes the quarantined config from the
    /// status-only list, and clears the recorded load error — the same end
    /// state as a clean open-time load. A failed attempt updates the
    /// recorded error and pushes the next attempt out exponentially
    /// (30s..10min). `remaining` is the quarantine count after this pass,
    /// read under the catalog lock so callers can stop polling at zero.
    pub fn retryFailedIndexLoads(
        self: *IndexManager,
        store: anytype,
        now_ns: u64,
        force: bool,
        publication_fence: CatalogPublicationFence,
    ) !QuarantineRetryResult {
        const RetryTask = struct {
            name: []u8,
            cfg: types.IndexConfig,

            fn deinit(task: *@This(), alloc: Allocator) void {
                alloc.free(task.name);
                task.cfg.deinit(alloc);
                task.* = undefined;
            }
        };

        var tasks = std.ArrayListUnmanaged(RetryTask).empty;
        defer {
            for (tasks.items) |*task| task.deinit(self.alloc);
            tasks.deinit(self.alloc);
        }
        var stale_failed_names = std.ArrayListUnmanaged([]const u8).empty;
        defer stale_failed_names.deinit(self.alloc);

        {
            self.catalog_mutex.lockExclusive();
            defer self.catalog_mutex.unlockExclusive();
            if (self.failed_index_loads.count() == 0) return .{};

            var it = self.failed_index_loads.iterator();
            while (it.next()) |entry| {
                if (!force and now_ns < entry.value_ptr.next_retry_ns) continue;
                const cfg = blk: {
                    for (self.status_only_index_configs) |*candidate| {
                        if (std.mem.eql(u8, candidate.name, entry.key_ptr.*)) break :blk candidate.*;
                    }
                    try stale_failed_names.append(self.alloc, entry.key_ptr.*);
                    continue;
                };
                var task = RetryTask{
                    .name = try self.alloc.dupe(u8, entry.key_ptr.*),
                    .cfg = undefined,
                };
                var task_name_owned = true;
                errdefer if (task_name_owned) self.alloc.free(task.name);
                task.cfg = try types.IndexConfig.clone(self.alloc, cfg);
                var task_cfg_owned = true;
                errdefer if (task_cfg_owned) task.cfg.deinit(self.alloc);
                try tasks.append(self.alloc, task);
                task_name_owned = false;
                task_cfg_owned = false;
            }
            for (stale_failed_names.items) |name| self.dropFailedIndexLoad(name);
        }

        var recovered: usize = 0;
        for (tasks.items) |*task| {
            self.catalog_mutex.lockExclusive();
            if (self.failed_index_loads.get(task.name) == null) {
                self.catalog_mutex.unlockExclusive();
                continue;
            }
            self.beginIndexLoadNoLock(task.name) catch |err| {
                self.catalog_mutex.unlockExclusive();
                return err;
            };
            self.catalog_mutex.unlockExclusive();

            var opened = self.openConfiguredIndexDetached(store, task.cfg, true, false) catch |err| {
                self.catalog_mutex.lockExclusive();
                defer self.catalog_mutex.unlockExclusive();
                self.completeIndexLoadNoLock(task.name);
                const record = self.failed_index_loads.getPtr(task.name) orelse continue;
                record.err_name = @errorName(err);
                record.retry_attempts +|= 1;
                record.next_retry_ns = now_ns + quarantineRetryBackoffNs(record.retry_attempts);
                std.log.warn("quarantined index retry failed name={s} attempt={d} err={s}", .{
                    task.name,
                    record.retry_attempts,
                    @errorName(err),
                });
                continue;
            };

            {
                // Lock order is structural/service fence -> catalog. The DB
                // fence drains maintenance and takes apply exclusive, matching
                // every other live index publication. Keep slow open/backfill
                // work above this scope so recovery does not stall queries.
                publication_fence.lock();
                defer publication_fence.unlock();

                self.catalog_mutex.lockExclusive();
                if (self.failed_index_loads.get(task.name) == null) {
                    self.completeIndexLoadNoLock(task.name);
                    self.catalog_mutex.unlockExclusive();
                    opened.deinit(self);
                    continue;
                }
                var remove_idx: ?usize = null;
                for (self.status_only_index_configs, 0..) |old_cfg, i| {
                    if (std.mem.eql(u8, old_cfg.name, task.name)) {
                        remove_idx = i;
                        break;
                    }
                }
                if (remove_idx == null) {
                    self.completeIndexLoadNoLock(task.name);
                    self.dropFailedIndexLoad(task.name);
                    self.catalog_mutex.unlockExclusive();
                    opened.deinit(self);
                    continue;
                }
                // Pre-allocate the shrunken status-only list so registration
                // and de-quarantine commit together once the open succeeded.
                const old = self.status_only_index_configs;
                const replacement: []types.IndexConfig = if (old.len <= 1)
                    &.{}
                else
                    self.alloc.alloc(types.IndexConfig, old.len - 1) catch |err| {
                        self.completeIndexLoadNoLock(task.name);
                        self.catalog_mutex.unlockExclusive();
                        opened.deinit(self);
                        return err;
                    };
                self.appendOpenedIndex(opened) catch |err| {
                    if (replacement.len > 0) self.alloc.free(replacement);
                    self.completeIndexLoadNoLock(task.name);
                    self.catalog_mutex.unlockExclusive();
                    opened.deinit(self);
                    return err;
                };
                self.completeIndexLoadNoLock(task.name);
                var wi: usize = 0;
                for (old, 0..) |old_cfg, i| {
                    if (i == remove_idx.?) {
                        var removed = old_cfg;
                        removed.deinit(self.alloc);
                        continue;
                    }
                    replacement[wi] = old_cfg;
                    wi += 1;
                }
                if (old.len > 0) self.alloc.free(old);
                self.status_only_index_configs = replacement;
                // Log before dropFailedIndexLoad frees the `name` key buffer.
                std.log.info("quarantined index recovered name={s} kind={s}", .{ task.name, @tagName(task.cfg.kind) });
                self.dropFailedIndexLoad(task.name);
                self.catalog_mutex.unlockExclusive();
                recovered += 1;
            }
        }

        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        return .{ .recovered = recovered, .remaining = self.failed_index_loads.count() };
    }

    fn accountFullTextPendingBytes(self: *IndexManager, pending_bytes: u64) !void {
        const manager = self.resource_manager orelse return;
        try manager.adjustUsage(.full_text_pending_segments, &self.full_text_pending_bytes_accounted, pending_bytes);
    }

    fn releaseFullTextPendingBytes(self: *IndexManager) void {
        if (self.full_text_pending_bytes_accounted == 0) return;
        if (self.resource_manager) |manager| {
            manager.adjustUsage(
                .full_text_pending_segments,
                &self.full_text_pending_bytes_accounted,
                0,
            ) catch {};
        }
        self.full_text_pending_bytes_accounted = 0;
    }

    fn observeDenseWorkingBytes(self: *IndexManager, slice: resource_manager_mod.Slice, current: *u64, next: u64) void {
        if (self.resource_manager) |manager| {
            manager.observeUsage(slice, current, next);
        } else {
            current.* = next;
        }
    }

    fn tryObserveDenseWorkingBytes(self: *IndexManager, slice: resource_manager_mod.Slice, current: *u64, next: u64) bool {
        if (self.resource_manager) |manager| {
            manager.adjustUsage(slice, current, next) catch return false;
        } else {
            current.* = next;
        }
        return true;
    }

    fn observeDenseApplyWorkingBytes(self: *IndexManager, current: *u64, next: u64) void {
        self.observeDenseWorkingBytes(.dense_apply_working_set, current, next);
    }

    pub fn updateRange(self: *IndexManager, byte_range: docstore_mod.ByteRange) void {
        self.byte_range = byte_range;
    }

    pub fn syncAll(self: *IndexManager, force: bool) !void {
        for (self.text_indexes.items) |*entry| try entry.persistent.sync(force);
        for (self.dense_indexes.items) |*entry| try entry.index.sync(force);
        for (self.sparse_indexes.items) |*entry| try entry.index.sync(force);
        for (self.graph_indexes.items) |*entry| try entry.index.sync(force);
        for (self.algebraic_indexes.items) |*entry| try entry.index.sync(force);
    }

    pub fn syncIndexByName(self: *IndexManager, name: []const u8, force: bool) !void {
        for (self.text_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.persistent.sync(force);
                return;
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.index.sync(force);
                return;
            }
        }
        for (self.sparse_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.index.sync(force);
                return;
            }
        }
        for (self.graph_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.index.sync(force);
                return;
            }
        }
        for (self.algebraic_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.index.sync(force);
                return;
            }
        }
        return error.IndexNotFound;
    }

    pub fn syncReplayStateByName(self: *IndexManager, store: *docstore_mod.DocStore, name: []const u8) !void {
        for (self.text_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.persistent.checkpointLsmWalAfterDurableBoundary();
                return;
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.index.syncReplayState();
                try entry.index.checkpointLsmWalAfterDurableBoundary();
                return;
            }
        }
        for (self.sparse_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.index.syncReplayState();
                try entry.index.checkpointLsmWalAfterDurableBoundary();
                return;
            }
        }
        for (self.graph_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try store.syncReplayState();
                try entry.index.syncReplayState();
                try entry.index.checkpointLsmWalAfterDurableBoundary();
                return;
            }
        }
        for (self.algebraic_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                try entry.index.sync(false);
                return;
            }
        }
        return error.IndexNotFound;
    }

    fn lsmMaintenanceScoreUnlocked(self: *const IndexManager) u64 {
        var score: u64 = 0;
        for (self.text_indexes.items) |*entry| {
            score = @max(score, entry.persistent.lsmMaintenanceScore());
        }
        for (self.dense_indexes.items) |*entry| {
            score = @max(score, entry.index.lsmMaintenanceScore());
        }
        return score;
    }

    pub fn lsmMaintenanceScore(self: *const IndexManager) u64 {
        const mutable: *IndexManager = @constCast(self);
        mutable.catalog_mutex.lockShared();
        defer mutable.catalog_mutex.unlockShared();
        return self.lsmMaintenanceScoreUnlocked();
    }

    fn lsmMaintenanceDebtHintUnlocked(self: *const IndexManager) u64 {
        var score: u64 = 0;
        for (self.text_indexes.items) |*entry| {
            score = @max(score, entry.persistent.lsmMaintenanceDebtHint());
        }
        for (self.dense_indexes.items) |*entry| {
            score = @max(score, entry.index.lsmMaintenanceDebtHint());
        }
        return score;
    }

    pub fn lsmMaintenanceDebtHint(self: *IndexManager) u64 {
        if (!self.catalog_mutex.tryLockShared()) return 1;
        defer self.catalog_mutex.unlockShared();
        return self.lsmMaintenanceDebtHintUnlocked();
    }

    pub fn nextLsmMaintenanceWakeDelayNsBestEffort(self: *IndexManager) ?u64 {
        if (!self.catalog_mutex.tryLockShared()) return null;
        defer self.catalog_mutex.unlockShared();

        var delay_ns: ?u64 = null;
        for (self.text_indexes.items) |*entry| {
            if (entry.persistent.nextLsmMaintenanceWakeDelayNsBestEffort()) |candidate| {
                delay_ns = if (delay_ns) |current| @min(current, candidate) else candidate;
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (entry.index.nextLsmMaintenanceWakeDelayNsBestEffort()) |candidate| {
                delay_ns = if (delay_ns) |current| @min(current, candidate) else candidate;
            }
        }
        return delay_ns;
    }

    pub fn refreshLsmMaintenanceDebtHint(self: *IndexManager) void {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();
        for (self.text_indexes.items) |*entry| {
            entry.persistent.refreshLsmMaintenanceDebtHint();
        }
        for (self.dense_indexes.items) |*entry| {
            entry.index.refreshLsmMaintenanceDebtHint();
        }
    }

    pub fn snapshotLsmMaintenanceStats(self: *const IndexManager) lsm_backend_mod.Backend.MaintenanceStats {
        var stats = lsm_backend_mod.Backend.MaintenanceStats{};
        for (self.text_indexes.items) |*entry| {
            if (entry.persistent.snapshotLsmMaintenanceStats()) |entry_stats| {
                lsm_backend_mod.Backend.accumulateMaintenanceStats(&stats, entry_stats);
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (entry.index.snapshotLsmMaintenanceStats()) |entry_stats| {
                lsm_backend_mod.Backend.accumulateMaintenanceStats(&stats, entry_stats);
            }
        }
        return stats;
    }

    pub fn snapshotLsmWriteStats(self: *const IndexManager) lsm_backend_mod.Backend.WriteStats {
        var stats = lsm_backend_mod.Backend.WriteStats{};
        for (self.text_indexes.items) |*entry| {
            if (entry.persistent.snapshotLsmWriteStats()) |entry_stats| {
                lsm_backend_mod.Backend.accumulateWriteStats(&stats, entry_stats);
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (entry.index.snapshotLsmWriteStats()) |entry_stats| {
                lsm_backend_mod.Backend.accumulateWriteStats(&stats, entry_stats);
            }
        }
        return stats;
    }

    pub fn snapshotLsmOpenStats(self: *const IndexManager) lsm_backend_mod.Backend.OpenStats {
        var stats = lsm_backend_mod.Backend.OpenStats{};
        for (self.text_indexes.items) |*entry| {
            if (entry.persistent.snapshotLsmOpenStats()) |entry_stats| {
                lsm_backend_mod.Backend.accumulateOpenStats(&stats, entry_stats);
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (entry.index.snapshotLsmOpenStats()) |entry_stats| {
                lsm_backend_mod.Backend.accumulateOpenStats(&stats, entry_stats);
            }
        }
        return stats;
    }

    pub fn checkpointLsmWalForManagedIndex(self: *IndexManager, index_ref: ManagedIndexRef) !void {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();

        switch (index_ref.kind) {
            .full_text => {
                const entry = self.textIndex(index_ref.name) orelse return error.IndexNotFound;
                try entry.checkpointLsmWalAfterDurableBoundary();
            },
            .dense_vector => {
                const entry = self.denseIndex(index_ref.name) orelse return error.IndexNotFound;
                try entry.index.checkpointLsmWalAfterDurableBoundary();
            },
            .sparse_vector => {
                const entry = self.sparseIndex(index_ref.name) orelse return error.IndexNotFound;
                try entry.index.checkpointLsmWalAfterDurableBoundary();
            },
            .graph => {
                const entry = self.graphIndex(index_ref.name) orelse return error.IndexNotFound;
                try entry.index.checkpointLsmWalAfterDurableBoundary();
            },
            else => {},
        }
    }

    pub fn saveDenseProjectionCheckpointMetadata(
        self: *IndexManager,
        index_name: []const u8,
        checkpoint: apply_state.ProjectionCheckpoint,
    ) !void {
        var apply_guard = try self.lockManagedIndexApply(.{
            .name = index_name,
            .kind = .dense_vector,
        });
        defer apply_guard.unlock();
        const entry = self.denseIndex(index_name) orelse return error.IndexNotFound;
        try entry.index.saveProjectionCheckpointMetadata(.{
            .applied_sequence = checkpoint.applied_sequence,
            .status = @intFromEnum(checkpoint.status),
            .generation = checkpoint.generation,
            .config_hash = checkpoint.config_hash,
        });
    }

    pub fn denseProjectionCheckpointMetadata(
        self: *const IndexManager,
        index_name: []const u8,
    ) ?apply_state.ProjectionCheckpoint {
        const entry = for (self.dense_indexes.items) |*candidate| {
            if (std.mem.eql(u8, candidate.config.name, index_name)) break candidate;
        } else return null;
        const checkpoint = entry.index.projectionCheckpointMetadata();
        return .{
            .applied_sequence = checkpoint.applied_sequence,
            .status = switch (checkpoint.status) {
                @intFromEnum(apply_state.ProjectionStatus.clean) => .clean,
                @intFromEnum(apply_state.ProjectionStatus.rebuilding) => .rebuilding,
                @intFromEnum(apply_state.ProjectionStatus.degraded) => .degraded,
                @intFromEnum(apply_state.ProjectionStatus.repair_required) => .repair_required,
                else => .repair_required,
            },
            .generation = checkpoint.generation,
            .config_hash = checkpoint.config_hash,
        };
    }

    pub fn snapshotLsmNativeStorageStats(self: *const IndexManager) lsm_backend_mod.NativeStorageStats {
        var stats = lsm_backend_mod.NativeStorageStats{};
        for (self.text_indexes.items) |*entry| {
            if (entry.persistent.snapshotLsmNativeStorageStats()) |entry_stats| {
                accumulateNativeStorageStats(&stats, entry_stats);
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (entry.index.snapshotLsmNativeStorageStats()) |entry_stats| {
                accumulateNativeStorageStats(&stats, entry_stats);
            }
        }
        return stats;
    }

    fn accumulateNativeStorageStats(stats: *lsm_backend_mod.NativeStorageStats, entry: lsm_backend_mod.NativeStorageStats) void {
        stats.fd_cache_entries = @max(stats.fd_cache_entries, entry.fd_cache_entries);
        stats.fd_admitted_descriptors = @max(stats.fd_admitted_descriptors, entry.fd_admitted_descriptors);
        stats.fd_persistent_descriptors = @max(stats.fd_persistent_descriptors, entry.fd_persistent_descriptors);
        stats.fd_admission_capacity = @max(stats.fd_admission_capacity, entry.fd_admission_capacity);
        stats.fd_persistent_reserve = @max(stats.fd_persistent_reserve, entry.fd_persistent_reserve);
        stats.fd_admission_waiters = @max(stats.fd_admission_waiters, entry.fd_admission_waiters);
        stats.fd_admission_waits = @max(stats.fd_admission_waits, entry.fd_admission_waits);
        stats.fd_persistent_admission_failures = @max(stats.fd_persistent_admission_failures, entry.fd_persistent_admission_failures);
    }

    pub fn snapshotTextMemoryAttribution(self: *IndexManager) TextMemoryAttributionStats {
        return self.snapshotTextMemoryAttributionWithDetail(false);
    }

    /// Detailed inverted-layout attribution walks every term and posting in
    /// every segment. Keep it off the periodic health-metrics path: on a
    /// corpus-sized index that turns observability into a recurring full-index
    /// scan and faults clean mmaps into RSS. Explicit benchmark diagnostics can
    /// opt in at a controlled sampling cadence.
    fn snapshotTextMemoryAttributionWithDetail(
        self: *IndexManager,
        detailed_inverted_layout: bool,
    ) TextMemoryAttributionStats {
        var stats = TextMemoryAttributionStats{};
        stats.text_indexes = @intCast(self.text_indexes.items.len);
        for (self.text_indexes.items) |*entry| {
            const persistent_memory = entry.persistent.memoryStatsSnapshot();
            stats.configured_lmdb_main_map_bytes +|= persistent_memory.configured_lmdb_main_map_bytes;
            stats.configured_lmdb_wal_map_bytes +|= persistent_memory.configured_lmdb_wal_map_bytes;
            stats.text_segment_estimated_resident_bytes +|= persistent_memory.segment_estimated_resident_bytes;
            stats.text_segment_recently_touched_bytes +|= persistent_memory.segment_recently_touched_bytes;
            stats.text_segment_cold_mapped_bytes +|= persistent_memory.segment_cold_mapped_bytes;
            stats.text_segment_residency_evictions +|= persistent_memory.segment_residency_evictions;

            const snap = entry.persistent.acquireSnapshot();
            defer snap.release();
            stats.text_segments +|= @intCast(snap.segments.len);
            for (snap.segments) |seg| {
                const bytes: u64 = @intCast(seg.data.bytes().len);
                stats.text_segment_bytes +|= bytes;
                stats.text_max_segment_bytes = @max(stats.text_max_segment_bytes, bytes);
                switch (seg.data) {
                    .mmap => stats.text_mmap_segment_bytes +|= bytes,
                    .heap => stats.text_heap_segment_bytes +|= bytes,
                }
                const layout = seg.layoutStats(detailed_inverted_layout);
                if (detailed_inverted_layout) seg.data.madviseDiscardCleanPages();
                stats.stored_fields_bytes +|= layout.stored_fields_bytes;
                stats.inverted_text_bytes +|= layout.inverted_text_bytes;
                stats.inverted_header_bytes +|= layout.inverted_header_bytes;
                stats.inverted_norm_bytes +|= layout.inverted_norm_bytes;
                stats.inverted_term_dict_bytes +|= layout.inverted_term_dict_bytes;
                stats.inverted_term_block_bytes +|= layout.inverted_term_block_bytes;
                stats.inverted_term_index_bytes +|= layout.inverted_term_index_bytes;
                stats.inverted_fst_bytes +|= layout.inverted_fst_bytes;
                stats.inverted_bloom_bytes +|= layout.inverted_bloom_bytes;
                stats.inverted_postings_bytes +|= layout.inverted_postings_bytes;
                stats.inverted_postings_header_bytes +|= layout.inverted_postings_header_bytes;
                stats.inverted_block_max_bytes +|= layout.inverted_block_max_bytes;
                stats.inverted_chunk_meta_bytes +|= layout.inverted_chunk_meta_bytes;
                stats.inverted_postings_payload_bytes +|= layout.inverted_postings_payload_bytes;
                stats.inverted_positions_bytes +|= layout.inverted_positions_bytes;
                stats.inverted_skip_bytes +|= layout.inverted_skip_bytes;
                stats.inverted_one_hit_terms +|= layout.inverted_one_hit_terms;
                stats.inverted_single_doc_postings_terms +|= layout.inverted_single_doc_postings_terms;
                stats.inverted_postings_terms +|= layout.inverted_postings_terms;
                stats.inverted_postings_doc_frequency_total +|= layout.inverted_postings_doc_frequency_total;
                stats.inverted_projected_posting_count_blocks_64 +|= layout.inverted_projected_posting_count_blocks_64;
                stats.inverted_projected_posting_count_blocks_128 +|= layout.inverted_projected_posting_count_blocks_128;
                stats.inverted_projected_posting_count_blocks_256 +|= layout.inverted_projected_posting_count_blocks_256;
                stats.typed_doc_values_bytes +|= layout.typed_doc_values_bytes;
                stats.doc_ordinals_bytes +|= layout.doc_ordinals_bytes;
                stats.section_index_bytes +|= layout.section_index_bytes;
            }
        }
        return stats;
    }

    fn logMemoryAttribution(
        self: *IndexManager,
        label: []const u8,
        source_docs: usize,
        projection_docs: usize,
        batch_segments: usize,
    ) void {
        if (!memoryAttributionSampleDue()) return;

        const memory = process_memory.snapshot();
        const text_stats = self.snapshotTextMemoryAttributionWithDetail(memoryLayoutDetailEnabled());
        const text_merge_stats = self.textMergeStatsSnapshot();
        const lsm_stats = self.snapshotLsmMaintenanceStats();
        const lsm_cache_stats: lsm_backend_mod.cache.Stats = if (self.lsm_cache) |cache| cache.snapshotStats() else .{};
        var ft_pending_used: u64 = 0;
        var ft_pending_peak: u64 = 0;
        var ft_build_used: u64 = 0;
        var ft_build_peak: u64 = 0;
        var ft_residency_used: u64 = 0;
        var ft_residency_peak: u64 = 0;
        var text_merge_used: u64 = 0;
        var text_merge_peak: u64 = 0;
        var lsm_cache_used: u64 = 0;
        var lsm_cache_peak: u64 = 0;
        var lsm_compaction_used: u64 = 0;
        var lsm_compaction_peak: u64 = 0;
        var lsm_table_builder_used: u64 = 0;
        var lsm_table_builder_peak: u64 = 0;
        var lsm_state_used: u64 = 0;
        var lsm_state_peak: u64 = 0;
        var lsm_wal_write_used: u64 = 0;
        var lsm_wal_write_peak: u64 = 0;
        var lsm_wal_retention_used: u64 = 0;
        var lsm_wal_retention_peak: u64 = 0;
        var lsm_recovery_used: u64 = 0;
        var lsm_recovery_peak: u64 = 0;
        var derived_backlog_used: u64 = 0;
        var derived_backlog_peak: u64 = 0;
        var cache_reclaim_requests: u64 = 0;
        var cache_reclaimed_bytes: u64 = 0;
        if (self.resource_manager) |manager| {
            const resource_stats = manager.snapshot();
            cache_reclaim_requests = resource_stats.reclaim_requests;
            cache_reclaimed_bytes = resource_stats.reclaimed_bytes;
            const ft_pending = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.full_text_pending_segments)];
            const ft_build = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.full_text_build_working_set)];
            const ft_residency = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.full_text_segment_residency)];
            const text_merge = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.text_merge_buffers)];
            const lsm_cache = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_block_table_cache)];
            const lsm_compaction = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_compaction_work)];
            const lsm_table_builder = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_table_builder_working_set)];
            const lsm_state = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_in_memory_state)];
            const lsm_wal_write = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_wal_write_working_set)];
            const lsm_wal_retention = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_wal_retention)];
            const lsm_recovery = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_recovery_working_set)];
            const derived_backlog = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.derived_backlog)];
            ft_pending_used = ft_pending.used_bytes;
            ft_pending_peak = ft_pending.peak_bytes;
            ft_build_used = ft_build.used_bytes;
            ft_build_peak = ft_build.peak_bytes;
            ft_residency_used = ft_residency.used_bytes;
            ft_residency_peak = ft_residency.peak_bytes;
            text_merge_used = text_merge.used_bytes;
            text_merge_peak = text_merge.peak_bytes;
            lsm_cache_used = lsm_cache.used_bytes;
            lsm_cache_peak = lsm_cache.peak_bytes;
            lsm_compaction_used = lsm_compaction.used_bytes;
            lsm_compaction_peak = lsm_compaction.peak_bytes;
            lsm_table_builder_used = lsm_table_builder.used_bytes;
            lsm_table_builder_peak = lsm_table_builder.peak_bytes;
            lsm_state_used = lsm_state.used_bytes;
            lsm_state_peak = lsm_state.peak_bytes;
            lsm_wal_write_used = lsm_wal_write.used_bytes;
            lsm_wal_write_peak = lsm_wal_write.peak_bytes;
            lsm_wal_retention_used = lsm_wal_retention.used_bytes;
            lsm_wal_retention_peak = lsm_wal_retention.peak_bytes;
            lsm_recovery_used = lsm_recovery.used_bytes;
            lsm_recovery_peak = lsm_recovery.peak_bytes;
            derived_backlog_used = derived_backlog.used_bytes;
            derived_backlog_peak = derived_backlog.peak_bytes;
        }
        // WAL retention is physical log-file size, not resident memory. Keep it
        // visible as its own disk-pressure signal, but do not subtract it from
        // RSS/footprint attribution.
        const lsm_resource_used = lsm_cache_used +| lsm_compaction_used +| lsm_table_builder_used +| lsm_state_used +| lsm_wal_write_used +| lsm_recovery_used;
        const lsm_resource_peak = lsm_cache_peak +| lsm_compaction_peak +| lsm_table_builder_peak +| lsm_state_peak +| lsm_wal_write_peak +| lsm_recovery_peak;
        const rss_after_lsm_resource_gap = memory.resident_bytes -| lsm_resource_used;
        const footprint_after_lsm_resource_gap = memory.footprint_bytes -| lsm_resource_used;

        std.log.info(
            "antfly_bench_memory_attribution label={s} source_docs={d} projection_docs={d} batch_segments={d} rss_bytes={d} footprint_bytes={d} peak_footprint_bytes={d} malloc_available={any} malloc_allocated_bytes={d} malloc_zone_bytes={d} text_indexes={d} text_segments={d} text_segment_bytes={d} mapped_segment_bytes={d} text_mmap_segment_bytes={d} text_heap_segment_bytes={d} text_max_segment_bytes={d} text_segment_estimated_resident_bytes={d} text_segment_recently_touched_bytes={d} text_segment_cold_mapped_bytes={d} text_segment_residency_evictions={d} configured_lmdb_main_map_bytes={d} configured_lmdb_wal_map_bytes={d}",
            .{
                label,
                source_docs,
                projection_docs,
                batch_segments,
                memory.resident_bytes,
                memory.footprint_bytes,
                memory.peak_footprint_bytes,
                memory.malloc_available,
                memory.malloc_allocated_bytes,
                memory.malloc_zone_bytes,
                text_stats.text_indexes,
                text_stats.text_segments,
                text_stats.text_segment_bytes,
                text_stats.text_mmap_segment_bytes,
                text_stats.text_mmap_segment_bytes,
                text_stats.text_heap_segment_bytes,
                text_stats.text_max_segment_bytes,
                text_stats.text_segment_estimated_resident_bytes,
                text_stats.text_segment_recently_touched_bytes,
                text_stats.text_segment_cold_mapped_bytes,
                text_stats.text_segment_residency_evictions,
                text_stats.configured_lmdb_main_map_bytes,
                text_stats.configured_lmdb_wal_map_bytes,
            },
        );
        std.log.info(
            "antfly_bench_memory_segment_layout label={s} stored_fields_bytes={d} inverted_text_bytes={d} inverted_header_bytes={d} inverted_norm_bytes={d} inverted_term_dict_bytes={d} inverted_term_block_bytes={d} inverted_term_index_bytes={d} inverted_fst_bytes={d} inverted_bloom_bytes={d} inverted_postings_bytes={d} inverted_postings_header_bytes={d} inverted_block_max_bytes={d} inverted_chunk_meta_bytes={d} inverted_postings_payload_bytes={d} inverted_positions_bytes={d} inverted_skip_bytes={d} inverted_one_hit_terms={d} inverted_postings_terms={d} typed_doc_values_bytes={d} doc_ordinals_bytes={d} section_index_bytes={d}",
            .{
                label,
                text_stats.stored_fields_bytes,
                text_stats.inverted_text_bytes,
                text_stats.inverted_header_bytes,
                text_stats.inverted_norm_bytes,
                text_stats.inverted_term_dict_bytes,
                text_stats.inverted_term_block_bytes,
                text_stats.inverted_term_index_bytes,
                text_stats.inverted_fst_bytes,
                text_stats.inverted_bloom_bytes,
                text_stats.inverted_postings_bytes,
                text_stats.inverted_postings_header_bytes,
                text_stats.inverted_block_max_bytes,
                text_stats.inverted_chunk_meta_bytes,
                text_stats.inverted_postings_payload_bytes,
                text_stats.inverted_positions_bytes,
                text_stats.inverted_skip_bytes,
                text_stats.inverted_one_hit_terms,
                text_stats.inverted_postings_terms,
                text_stats.typed_doc_values_bytes,
                text_stats.doc_ordinals_bytes,
                text_stats.section_index_bytes,
            },
        );
        std.log.info(
            "antfly_bench_memory_resources label={s} full_text_pending_used_bytes={d} full_text_pending_peak_bytes={d} full_text_build_used_bytes={d} full_text_build_peak_bytes={d} full_text_residency_used_bytes={d} full_text_residency_peak_bytes={d} text_merge_used_bytes={d} text_merge_peak_bytes={d} derived_backlog_used_bytes={d} derived_backlog_peak_bytes={d} lsm_cache_used_bytes={d} lsm_cache_peak_bytes={d} lsm_compaction_used_bytes={d} lsm_compaction_peak_bytes={d} lsm_table_builder_used_bytes={d} lsm_table_builder_peak_bytes={d} lsm_state_used_bytes={d} lsm_state_peak_bytes={d} lsm_wal_write_used_bytes={d} lsm_wal_write_peak_bytes={d} lsm_wal_retention_disk_bytes={d} lsm_wal_retention_peak_disk_bytes={d} lsm_recovery_used_bytes={d} lsm_recovery_peak_bytes={d} lsm_resource_used_bytes={d} lsm_resource_peak_bytes={d} cache_reclaim_requests={d} cache_reclaimed_bytes={d} rss_after_lsm_resource_gap_bytes={d} footprint_after_lsm_resource_gap_bytes={d}",
            .{
                label,
                ft_pending_used,
                ft_pending_peak,
                ft_build_used,
                ft_build_peak,
                ft_residency_used,
                ft_residency_peak,
                text_merge_used,
                text_merge_peak,
                derived_backlog_used,
                derived_backlog_peak,
                lsm_cache_used,
                lsm_cache_peak,
                lsm_compaction_used,
                lsm_compaction_peak,
                lsm_table_builder_used,
                lsm_table_builder_peak,
                lsm_state_used,
                lsm_state_peak,
                lsm_wal_write_used,
                lsm_wal_write_peak,
                lsm_wal_retention_used,
                lsm_wal_retention_peak,
                lsm_recovery_used,
                lsm_recovery_peak,
                lsm_resource_used,
                lsm_resource_peak,
                cache_reclaim_requests,
                cache_reclaimed_bytes,
                rss_after_lsm_resource_gap,
                footprint_after_lsm_resource_gap,
            },
        );
        std.log.info(
            "antfly_bench_memory_lsm_tables label={s} lsm_mutable_bytes={d} lsm_immutable_bytes={d} lsm_immutable_memtables={d} lsm_total_run_bytes={d} lsm_total_runs={d} lsm_cache_entries={d} lsm_cache_transient_serves={d} lsm_cache_state_bytes={d} lsm_cache_raw_table_bytes={d} lsm_cache_table_index_bytes={d} lsm_cache_block_bytes={d} lsm_cache_physical_block_bytes={d}",
            .{
                label,
                lsm_stats.mutable_bytes,
                lsm_stats.immutable_bytes,
                lsm_stats.immutable_memtables,
                lsm_stats.total_run_bytes,
                lsm_stats.total_runs,
                lsm_cache_stats.entry_count,
                lsm_cache_stats.run_state.transient_serves +|
                    lsm_cache_stats.run_table_raw.transient_serves +|
                    lsm_cache_stats.run_table_index.transient_serves +|
                    lsm_cache_stats.run_table_block.transient_serves +|
                    lsm_cache_stats.run_table_physical_block.transient_serves,
                lsm_cache_stats.run_state.used_bytes,
                lsm_cache_stats.run_table_raw.used_bytes,
                lsm_cache_stats.run_table_index.used_bytes,
                lsm_cache_stats.run_table_block.used_bytes,
                lsm_cache_stats.run_table_physical_block.used_bytes,
            },
        );
        std.log.info(
            "antfly_bench_lsm_snapshot_resources label={s} lsm_mutable_snapshot_clone_calls={d} lsm_mutable_snapshot_clone_bytes_total={d} lsm_mutable_snapshot_clone_peak_bytes={d} lsm_read_snapshot_mutable_rotations={d} lsm_read_snapshot_mutable_rotation_bytes_total={d} lsm_read_snapshot_mutable_rotation_peak_bytes={d} lsm_mutable_snapshot_clone_bound_read_txn_calls={d} lsm_mutable_snapshot_clone_bound_read_txn_bytes_total={d} lsm_mutable_snapshot_clone_namespace_read_txn_calls={d} lsm_mutable_snapshot_clone_namespace_read_txn_bytes_total={d} lsm_mutable_snapshot_clone_other_calls={d} lsm_mutable_snapshot_clone_other_bytes_total={d}",
            .{
