                text_merge_stats.deferred_for_pressure,
                text_merge_stats.backpressure_events,
                text_merge_stats.backpressure_ns,
            },
        );
    }

    fn runLsmObsoleteReclaimDueUnlocked(self: *IndexManager, comptime best_effort: bool) !bool {
        for (self.text_indexes.items) |*entry| {
            if (entry.persistent.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| {
                if (delay_ns == 0) {
                    const progressed = if (best_effort)
                        try entry.persistent.runLsmMaintenanceStepBestEffort()
                    else
                        try entry.persistent.runLsmMaintenanceStep();
                    if (progressed) return true;
                }
            }
        }
        for (self.dense_indexes.items) |*entry| {
            if (entry.index.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| {
                if (delay_ns == 0) {
                    const progressed = if (best_effort)
                        try entry.index.runLsmMaintenanceStepBestEffort()
                    else
                        try entry.index.runLsmMaintenanceStep();
                    if (progressed) return true;
                }
            }
        }
        return false;
    }

    pub fn runLsmObsoleteReclaimDue(self: *IndexManager) !bool {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();
        return try self.runLsmObsoleteReclaimDueUnlocked(false);
    }

    pub fn runLsmObsoleteReclaimDueBestEffort(self: *IndexManager) !bool {
        if (!self.catalog_mutex.tryLockShared()) return false;
        defer self.catalog_mutex.unlockShared();
        return try self.runLsmObsoleteReclaimDueUnlocked(true);
    }

    pub fn runLsmMaintenanceStep(self: *IndexManager) !bool {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();

        var best_kind: enum { none, text, dense } = .none;
        var best_index: usize = 0;
        var best_score: u64 = 0;

        for (self.text_indexes.items, 0..) |*entry, i| {
            const score = entry.persistent.lsmMaintenanceScore();
            if (score > best_score) {
                best_score = score;
                best_kind = .text;
                best_index = i;
            }
        }
        for (self.dense_indexes.items, 0..) |*entry, i| {
            const score = entry.index.lsmMaintenanceScore();
            if (score > best_score) {
                best_score = score;
                best_kind = .dense;
                best_index = i;
            }
        }

        if (best_score == 0) return false;
        return switch (best_kind) {
            .none => false,
            .text => try self.text_indexes.items[best_index].persistent.runLsmMaintenanceStep(),
            .dense => try self.dense_indexes.items[best_index].index.runLsmMaintenanceStep(),
        };
    }

    pub fn runLsmMaintenanceStepBestEffort(self: *IndexManager) !bool {
        if (!self.catalog_mutex.tryLockShared()) return false;
        defer self.catalog_mutex.unlockShared();

        var best_kind: enum { none, text, dense } = .none;
        var best_index: usize = 0;
        var best_score: u64 = 0;

        for (self.text_indexes.items, 0..) |*entry, i| {
            const raw_score = entry.persistent.lsmMaintenanceDebtHint();
            const score = if (raw_score != 0) raw_score else if (entry.persistent.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| if (delay_ns == 0) @as(u64, 1) else @as(u64, 0) else @as(u64, 0);
            if (score > best_score) {
                best_score = score;
                best_kind = .text;
                best_index = i;
            }
        }
        for (self.dense_indexes.items, 0..) |*entry, i| {
            const raw_score = entry.index.lsmMaintenanceDebtHint();
            const score = if (raw_score != 0) raw_score else if (entry.index.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| if (delay_ns == 0) @as(u64, 1) else @as(u64, 0) else @as(u64, 0);
            if (score > best_score) {
                best_score = score;
                best_kind = .dense;
                best_index = i;
            }
        }

        if (best_score == 0) return false;
        return switch (best_kind) {
            .none => false,
            .text => try self.text_indexes.items[best_index].persistent.runLsmMaintenanceStepBestEffort(),
            .dense => try self.dense_indexes.items[best_index].index.runLsmMaintenanceStepBestEffort(),
        };
    }

    pub fn runDenseLsmMaintenanceByName(self: *IndexManager, name: []const u8, max_steps: usize) !usize {
        const entry = self.denseIndex(name) orelse return error.IndexNotFound;
        var steps: usize = 0;
        while (steps < max_steps) {
            if (!try entry.index.runLsmMaintenanceStep()) break;
            steps += 1;
        }
        return steps;
    }

    pub const DensePostingMaintenanceOptions = struct {
        max_postings_per_index: usize = 64,
        max_layout_changes_per_index: usize = 8,
        max_boundary_reassignments_per_index: usize = 64,
        boundary_reassignment_min_improvement: f32 = 0.0,
    };

    // Node budget per tree-link repair sweep run from the dense maintenance
    // lane. Repairs persist as the sweep goes, so an exhausted budget simply
    // resumes on the next maintenance pass.
    const dense_link_repair_max_nodes: usize = 4096;

    pub fn runDensePostingMaintenance(self: *IndexManager, options: DensePostingMaintenanceOptions) !usize {
        var total_steps: usize = 0;
        for (self.dense_indexes.items) |*entry| {
            // A write path observed a tree-link inconsistency (stale parent
            // pointer / dangling node reference): run a bounded repair sweep
            // before posting maintenance so traversals stop tripping on it.
            if (try entry.index.maybeRepairTreeLinks(dense_link_repair_max_nodes)) |link_repair| {
                total_steps += @intCast(link_repair.repaired());
            }
            const backlog = try entry.index.postingBacklogStats();
            if (!backlog.needsRepair()) continue;

            const result = try entry.index.repairDirtyPostingsWithOptions(.{
                .max_postings = options.max_postings_per_index,
                .rebalance_layout = true,
                .max_layout_changes = options.max_layout_changes_per_index,
                .max_boundary_reassignments = options.max_boundary_reassignments_per_index,
                .boundary_reassignment_min_improvement = options.boundary_reassignment_min_improvement,
            });
            total_steps += @intCast(result.repaired_postings + result.split_postings + result.merged_postings + result.boundary_reassigned_vectors);
        }
        return total_steps;
    }

    pub fn denseLsmMaintenanceScoreByName(self: *IndexManager, name: []const u8) !u64 {
        const entry = self.denseIndex(name) orelse return error.IndexNotFound;
        return entry.index.lsmMaintenanceScore();
    }

    pub fn syncAllProfiled(self: *IndexManager, force: bool) !SyncProfile {
        var profile = SyncProfile{};

        const text_started = nowNs();
        for (self.text_indexes.items) |*entry| try entry.persistent.sync(force);
        profile.text_ns = elapsedSince(text_started);

        const dense_started = nowNs();
        for (self.dense_indexes.items) |*entry| try entry.index.sync(force);
        profile.dense_ns = elapsedSince(dense_started);

        const sparse_started = nowNs();
        for (self.sparse_indexes.items) |*entry| try entry.index.sync(force);
        profile.sparse_ns = elapsedSince(sparse_started);

        const graph_started = nowNs();
        for (self.graph_indexes.items) |*entry| try entry.index.sync(force);
        profile.graph_ns = elapsedSince(graph_started);

        return profile;
    }

    pub fn load(self: *IndexManager, store: anytype) !void {
        try self.loadWithBackfill(store, true, false);
    }

    pub fn loadNoBackfill(self: *IndexManager, store: anytype) !void {
        try self.loadWithBackfill(store, false, true);
    }

    fn loadWithBackfill(self: *IndexManager, store: anytype, allow_backfill: bool, read_only: bool) !void {
        const load_started_ns = nowNs();
        self.bindPrimaryStore(store);
        self.clearStatusOnlyIndexConfigs();
        self.clearFailedIndexLoads();
        try self.loadEnrichmentCatalog(store);
        try self.loadResolverCatalog(store);

        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginProbe();
        defer txn.abort();
        const data = txn.get(index_catalog_key) catch |err| switch (err) {
            error.NotFound => {
                self.storeGeneratedEnrichmentTargetCache(try self.computeGeneratedEnrichmentTargetCache());
                return;
            },
            else => return err,
        };

        const configs = try deserializeCatalog(self.alloc, data);
        defer {
            for (configs) |*cfg| cfg.deinit(self.alloc);
            self.alloc.free(configs);
        }

        var parallelism: usize = 1;
        if (comptime builtin.single_threaded or builtin.os.tag == .freestanding) {
            for (configs) |cfg| {
                self.openConfiguredIndex(store, cfg, allow_backfill, read_only) catch |err| {
                    if (read_only and indexOpenErrorIsTransientRead(err)) return err;
                    std.log.warn("load configured index failed name={s} kind={s} err={s}", .{
                        cfg.name,
                        @tagName(cfg.kind),
                        @errorName(err),
                    });
                    try self.recordFailedIndexLoad(cfg, err);
                };
            }
        } else {
            parallelism = self.resolvedLoadParallelism(configs.len, allow_backfill, read_only);
            if (parallelism <= 1) {
                for (configs) |cfg| {
                    self.openConfiguredIndex(store, cfg, allow_backfill, read_only) catch |err| {
                        if (read_only and indexOpenErrorIsTransientRead(err)) return err;
                        std.log.warn("load configured index failed name={s} kind={s} err={s}", .{
                            cfg.name,
                            @tagName(cfg.kind),
                            @errorName(err),
                        });
                        try self.recordFailedIndexLoad(cfg, err);
                    };
                }
            } else {
                for (configs) |cfg| {
                    try self.ensureConfiguredIndexDir(cfg);
                }
                try self.loadConfiguredIndexesParallel(store, configs, parallelism);
            }
        }
        try self.refreshGeneratedEnrichmentTargetCache();
        if (openProfileEnabled()) {
            std.log.info("index_manager_load_profile index_count={} parallelism={} total_ns={}", .{
                configs.len,
                parallelism,
                elapsedSince(load_started_ns),
            });
        }
    }

    pub fn loadCatalogOnly(self: *IndexManager, store: anytype) !void {
        self.bindPrimaryStore(store);
        self.clearFailedIndexLoads();
        try self.loadEnrichmentCatalog(store);
        try self.loadResolverCatalog(store);

        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginProbe();
        defer txn.abort();
        const data = txn.get(index_catalog_key) catch |err| switch (err) {
            error.NotFound => {
                self.clearStatusOnlyIndexConfigs();
                return;
            },
            else => return err,
        };

        const configs = try deserializeCatalog(self.alloc, data);
        errdefer {
            for (configs) |*cfg| cfg.deinit(self.alloc);
            self.alloc.free(configs);
        }
        self.clearStatusOnlyIndexConfigs();
        self.status_only_index_configs = configs;
    }

    fn resolvedLoadParallelism(
        self: *const IndexManager,
        config_count: usize,
        allow_backfill: bool,
        read_only: bool,
    ) usize {
        // Detached index construction is only parallel-safe when it cannot
        // mutate the shared primary store. Writable opens can publish lexical
        // registry entries and backfills persist checkpoints, so serialize
        // them even when no backfill is ultimately needed.
        if (config_count <= 1 or builtin.single_threaded or allow_backfill or !read_only) return 1;
        if (self.load_parallelism) |value| return @min(@max(value, 1), config_count);

        var parallelism = std.Thread.getCpuCount() catch 1;
        parallelism /= 2;
        if (parallelism == 0) parallelism = 1;
        parallelism = @min(parallelism, 4);
        return @min(parallelism, config_count);
    }

    fn loadConfiguredIndexesParallel(
        self: *IndexManager,
        store: anytype,
        configs: []const types.IndexConfig,
        parallelism: usize,
    ) !void {
        var marked_loading: usize = 0;
        errdefer {
            for (configs[0..marked_loading]) |cfg| self.completeIndexLoadNoLock(cfg.name);
        }
        for (configs) |cfg| {
            try self.beginIndexLoadNoLock(cfg.name);
            marked_loading += 1;
        }
        defer {
            for (configs) |cfg| self.completeIndexLoadNoLock(cfg.name);
        }

        const Store = @TypeOf(store);
        const WorkerState = struct {
            manager: *IndexManager,
            store: Store,
            configs: []const types.IndexConfig,
            results: []OpenResult,
            next_index: std.atomic.Value(usize) = .init(0),

            fn run(state: *@This()) void {
                while (true) {
                    const index = state.next_index.fetchAdd(1, .monotonic);
                    if (index >= state.configs.len) return;
                    const opened = state.manager.openConfiguredIndexDetached(state.store, state.configs[index], false, true) catch |err| {
                        std.log.warn("load configured index failed name={s} kind={s} err={s}", .{
                            state.configs[index].name,
                            @tagName(state.configs[index].kind),
                            @errorName(err),
                        });
                        state.results[index] = .{ .err = err };
                        continue;
                    };
                    state.results[index] = .{ .opened = opened };
                }
            }
        };

        const results = try self.alloc.alloc(OpenResult, configs.len);
        defer {
            for (results) |*result| result.deinit(self);
            self.alloc.free(results);
        }
        for (results) |*result| result.* = .{};

        var state = WorkerState{
            .manager = self,
            .store = store,
            .configs = configs,
            .results = results,
        };

        const spawned_count = parallelism - 1;
        var threads = try self.alloc.alloc(std.Thread, spawned_count);
        defer self.alloc.free(threads);

        var spawned: usize = 0;
        var threads_joined = false;
        errdefer {
            if (!threads_joined) {
                for (threads[0..spawned]) |*thread| thread.join();
            }
        }
        for (threads) |*thread| {
            thread.* = try std.Thread.spawn(.{}, WorkerState.run, .{&state});
            spawned += 1;
        }

        WorkerState.run(&state);

        for (threads[0..spawned]) |*thread| thread.join();
        threads_joined = true;

        // A failed index load quarantines that index instead of failing the
        // whole table open; the other indexes stay usable and the failure is
        // reported via loadFailure()/status so clients can drop+recreate.
        // Transient read races on read-only opens propagate instead (the
        // deferred results cleanup releases any other opened indexes).
        for (results, 0..) |*result, i| {
            if (result.err) |err| {
                if (indexOpenErrorIsTransientRead(err)) return err;
                try self.recordFailedIndexLoad(configs[i], err);
            }
        }

        for (results) |*result| {
            if (result.opened) |*opened| {
                try self.appendOpenedIndex(opened.*);
                result.opened = null;
            }
        }
    }

    pub const AtomicCatalogMutation = union(enum) {
        put: struct {
            key: []const u8,
            value: []const u8,
        },
        delete: []const u8,
        put_delete: struct {
            put: struct {
                key: []const u8,
                value: []const u8,
            },
            delete: []const u8,
        },
    };

    const generated_artifact_cleanup_magic: u64 = 0x32504e4c43414641; // "AFACLNP2"
    const generated_artifact_cleanup_null_len = std.math.maxInt(u32);
    const generated_artifact_cleanup_header_len = @sizeOf(u64) + 4 * @sizeOf(u32);
    const generated_artifact_cleanup_scan_limit: usize = 512;

    const GeneratedArtifactCleanupPhase = enum(u32) {
        generated_artifacts = 1,
        dense_metadata = 2,
        derived_coverage = 3,
        finalization = 4,
        algebraic_canonical_facts = 5,
        algebraic_canonical_tuples = 6,
        algebraic_canonical_dictionary = 7,
        algebraic_canonical_registry = 8,
        algebraic_active_facts = 9,
        algebraic_active_tuples = 10,
        algebraic_active_dictionary = 11,
        algebraic_active_registry = 12,
    };

    const AlgebraicCleanupGeneration = enum { canonical, active };
    const AlgebraicCleanupFamily = enum { facts, tuples, dictionary, registry };

    const GeneratedArtifactCleanupRecord = struct {
        phase: GeneratedArtifactCleanupPhase,
        chunk_name: ?[]const u8,
        embedding_name: ?[]const u8,
        cursor: ?[]const u8,
    };

    pub const GeneratedArtifactCleanupDrainResult = struct {
        alloc: ?Allocator = null,
        found: bool = false,
        completed: bool = false,
        key: []u8 = &.{},
        index_name: []u8 = &.{},

        pub fn deinit(self: *@This()) void {
            const alloc = self.alloc orelse {
                self.* = .{};
                return;
            };
            if (self.key.len != 0) alloc.free(self.key);
            if (self.index_name.len != 0) alloc.free(self.index_name);
            self.* = .{};
        }
    };

    pub fn setIo(self: *IndexManager, io: ?std.Io) void {
        self.io = io;
    }

    pub fn checkpointIo(self: *const IndexManager) std.Io {
        return self.io orelse std.Io.Threaded.global_single_threaded.io();
    }

    /// Binds rebuild cursors to the same storage backend as their index kind.
    /// Callers must use this instead of assuming the logical root is a host
    /// filesystem path; Lite and other external roots may be single files.
    pub fn rebuildState(
        self: *const IndexManager,
        kind: types.IndexKind,
        root_path: []const u8,
        cfg: types.IndexConfig,
    ) backfill_state_mod.RebuildState {
        const storage = switch (kind) {
            .full_text => self.text_lsm_storage,
            .dense_vector => self.dense_lsm_storage,
            .sparse_vector => self.sparse_lsm_storage,
            .graph => self.graph_lsm_storage,
            .algebraic => null,
        };
        return backfill_state_mod.RebuildState.initOwned(
            root_path,
            storage,
            coverageGenerationForConfig(cfg),
        );
    }

    const GeneratedArtifactCleanupPlan = struct {
        alloc: Allocator,
        key: ?[]u8 = null,
        value: ?[]u8 = null,

        fn deinit(self: *@This()) void {
            if (self.key) |key| self.alloc.free(key);
            if (self.value) |value| self.alloc.free(value);
            self.* = undefined;
        }
    };

    pub fn add(self: *IndexManager, store: anytype, cfg: types.IndexConfig) !void {
        try self.addWithOptions(store, cfg, true, null);
    }

    pub fn addWithAtomicMutation(
        self: *IndexManager,
        store: anytype,
        cfg: types.IndexConfig,
        admission: ?AtomicCatalogMutation,
    ) !void {
        try self.addWithOptions(store, cfg, true, admission);
    }

    /// Managed admission deliberately leaves corpus reconstruction to the
    /// bounded owner-side repair scheduler. The supplied outbox row commits in
    /// the same primary-store transaction as the catalog, so a process crash
    /// cannot publish an index generation without durable rebuild debt.
    pub fn addManaged(
        self: *IndexManager,
        store: anytype,
        cfg: types.IndexConfig,
        admission: ?AtomicCatalogMutation,
    ) !void {
        try self.addWithOptions(store, cfg, false, admission);
    }

    fn addWithOptions(
        self: *IndexManager,
        store: anytype,
        cfg: types.IndexConfig,
        allow_backfill: bool,
        admission: ?AtomicCatalogMutation,
    ) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        self.bindPrimaryStore(store);
        if (self.has(cfg.name)) return error.IndexAlreadyExists;

        var stored_cfg = try indexConfigWithCoverageGeneration(self.alloc, self.io, cfg);
        defer stored_cfg.deinit(self.alloc);

        // Catalog absence is the generation boundary. Reject any
        // crash-surviving artifact cleanup before the new config can bind the
        // same public artifact names, then discard name-scoped index state.
        try self.prepareStorageForFreshCatalogEntry(store, stored_cfg);
        try self.provisionConfiguredIndexDirDurable(stored_cfg);

        const enrichment_checkpoint = self.enrichments.items.len;
        var enrichment_catalog_committed = false;
        errdefer if (!enrichment_catalog_committed) self.truncateEnrichments(enrichment_checkpoint);

        const enrichments_changed = try self.ensureShorthandEnrichments(stored_cfg);
        const has_generated_after_enrichments = if (enrichments_changed)
            try self.computeGeneratedEnrichmentTargetCache()
        else
            false;

        try self.openConfiguredIndex(store, stored_cfg, allow_backfill, false);
        errdefer {
            self.removeInMemory(stored_cfg.name);
        }
        const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCache();
        if (enrichments_changed) {
            try self.persistEnrichmentCatalog(store);
            enrichment_catalog_committed = true;
        }
        self.persistCatalogWithAtomicMutation(store, admission) catch |err| {
            self.removeInMemory(stored_cfg.name);
            if (enrichment_catalog_committed) {
                self.storeGeneratedEnrichmentTargetCache(has_generated_after_enrichments);
            }
            return err;
        };
        self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
    }

    pub fn addAllNoBackfill(self: *IndexManager, store: anytype, configs: []const types.IndexConfig) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        self.bindPrimaryStore(store);
        if (configs.len == 0) return;

        var stored_configs = try self.alloc.alloc(types.IndexConfig, configs.len);
        var stored_initialized: usize = 0;
        defer {
            for (stored_configs[0..stored_initialized]) |*stored_cfg| stored_cfg.deinit(self.alloc);
            self.alloc.free(stored_configs);
        }
        for (configs, 0..) |cfg, i| {
            stored_configs[i] = try indexConfigWithCoverageGeneration(self.alloc, self.io, cfg);
            stored_initialized += 1;
        }

        var opened = std.ArrayListUnmanaged([]const u8).empty;
        defer opened.deinit(self.alloc);
        errdefer {
            for (opened.items) |name| self.removeInMemory(name);
        }

        const enrichment_checkpoint = self.enrichments.items.len;
        var enrichment_catalog_committed = false;
        errdefer if (!enrichment_catalog_committed) self.truncateEnrichments(enrichment_checkpoint);

        var enrichments_changed = false;
        for (stored_configs, 0..) |cfg, i| {
            if (self.has(cfg.name)) return error.IndexAlreadyExists;
            for (stored_configs[0..i]) |prior| {
                if (std.mem.eql(u8, prior.name, cfg.name)) return error.IndexAlreadyExists;
            }
            enrichments_changed = (try self.ensureShorthandEnrichments(cfg)) or enrichments_changed;
        }
        const has_generated_after_enrichments = if (enrichments_changed)
            try self.computeGeneratedEnrichmentTargetCache()
        else
            false;

        for (stored_configs) |cfg| {
            try self.provisionConfiguredIndexDirDurable(cfg);
            try self.openConfiguredIndex(store, cfg, false, false);
            try opened.append(self.alloc, cfg.name);
        }

        const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCache();
        if (enrichments_changed) {
            try self.persistEnrichmentCatalog(store);
            enrichment_catalog_committed = true;
        }
        self.persistCatalog(store) catch |err| {
            for (opened.items) |name| self.removeInMemory(name);
            if (enrichment_catalog_committed) {
                self.storeGeneratedEnrichmentTargetCache(has_generated_after_enrichments);
            }
            return err;
        };
        self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
    }

    pub fn registerShadowIndex(self: *IndexManager, store: anytype, cfg: types.IndexConfig) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        if (self.has(cfg.name)) return error.IndexAlreadyExists;
        var stored_cfg = try indexConfigWithCoverageGeneration(self.alloc, self.io, cfg);
        defer stored_cfg.deinit(self.alloc);
        try self.openConfiguredIndex(store, stored_cfg, true, false);
        errdefer {
            self.removeInMemory(stored_cfg.name);
        }
        try self.refreshGeneratedEnrichmentTargetCache();
    }

    pub fn registerReplacementIndex(self: *IndexManager, store: anytype, cfg: types.IndexConfig) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        self.bindPrimaryStore(store);
        if (self.has(cfg.name)) return error.IndexAlreadyExists;
        try self.openConfiguredIndex(store, cfg, false, false);
        errdefer self.removeInMemory(cfg.name);
        try self.refreshGeneratedEnrichmentTargetCache();
    }

    pub fn addEnrichment(self: *IndexManager, store: anytype, cfg: types.EnrichmentConfig) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        var internal = try enrichmentFromPublic(self.alloc, cfg);
        defer internal.deinit(self.alloc);

        try validateEnrichmentConfig(self, internal);
        if (self.getEnrichmentByName(internal.name) != null) return error.EnrichmentAlreadyExists;

        const enrichment_checkpoint = self.enrichments.items.len;
        errdefer self.truncateEnrichments(enrichment_checkpoint);

        try self.enrichments.append(self.alloc, try enrichment_catalog.EnrichmentConfig.clone(self.alloc, internal));
        try self.validateEnrichmentCatalogGraph();
        const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCache();
        try self.persistEnrichmentCatalog(store);
        self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
    }

    pub const EnrichmentUpsertResult = enum {
        added,
        updated,
        unchanged,
    };

    pub fn upsertEnrichment(self: *IndexManager, store: anytype, cfg: types.EnrichmentConfig) !EnrichmentUpsertResult {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        var internal = try enrichmentFromPublic(self.alloc, cfg);
        defer internal.deinit(self.alloc);

        try validateEnrichmentConfig(self, internal);

        for (self.enrichments.items) |*entry| {
            if (!std.mem.eql(u8, entry.name, internal.name)) continue;
            if (internalEnrichmentConfigsEqual(entry.*, internal)) return .unchanged;

            var replacement = try enrichment_catalog.EnrichmentConfig.clone(self.alloc, internal);
            var previous = entry.*;
            entry.* = replacement;
            self.validateEnrichmentCatalogGraph() catch |err| {
                entry.* = previous;
                replacement.deinit(self.alloc);
                return err;
            };
            const has_generated_enrichment_targets = self.computeGeneratedEnrichmentTargetCache() catch |err| {
                entry.* = previous;
                replacement.deinit(self.alloc);
                return err;
            };
            self.persistEnrichmentCatalog(store) catch |err| {
                entry.* = previous;
                replacement.deinit(self.alloc);
                return err;
            };
            previous.deinit(self.alloc);
            self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
            return .updated;
        }

        const enrichment_checkpoint = self.enrichments.items.len;
        errdefer self.truncateEnrichments(enrichment_checkpoint);

        try self.enrichments.append(self.alloc, try enrichment_catalog.EnrichmentConfig.clone(self.alloc, internal));
        try self.validateEnrichmentCatalogGraph();
        const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCache();
        try self.persistEnrichmentCatalog(store);
        self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
        return .added;
    }

    pub fn removeEnrichment(self: *IndexManager, store: anytype, kind: types.EnrichmentKind, name: []const u8) !bool {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        const internal_kind = publicEnrichmentKindToInternal(kind);
        if (enrichmentInUse(self, internal_kind, name)) return error.EnrichmentInUse;

        for (self.enrichments.items, 0..) |*entry, i| {
            if (entry.kind != internal_kind) continue;
            if (!std.mem.eql(u8, entry.name, name)) continue;
            const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCacheExcluding(
                null,
                .{ .kind = internal_kind, .name = name },
            );
            entry.deinit(self.alloc);
            _ = self.enrichments.orderedRemove(i);
            try self.persistEnrichmentCatalog(store);
            self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
            return true;
        }
        return false;
    }

    pub fn getResolver(self: *const IndexManager, name: []const u8) ?*const resolver_catalog.ResolverConfig {
        for (self.resolvers.items) |*entry| {
            if (std.mem.eql(u8, entry.name, name)) return entry;
        }
        return null;
    }

    fn resolverResolutionArtifactInUse(self: *const IndexManager, resolution_artifact: []const u8, except_name: ?[]const u8) bool {
        for (self.resolvers.items) |entry| {
            if (except_name) |name| {
                if (std.mem.eql(u8, entry.name, name)) continue;
            }
            if (std.mem.eql(u8, entry.resolution_artifact, resolution_artifact)) return true;
        }
        return false;
    }

    pub const ResolverUpsertResult = enum {
        inserted,
        updated_backfill_required,
        updated_no_backfill,
    };

    fn resolverMaterialConfigChanged(existing: resolver_catalog.ResolverConfig, next: resolver_catalog.ResolverConfig) bool {
        return !std.mem.eql(u8, existing.table, next.table) or
            !std.mem.eql(u8, existing.key_template, next.key_template) or
            existing.type_must_match != next.type_must_match or
            !std.mem.eql(u8, existing.scorer_json, next.scorer_json) or
            !std.mem.eql(u8, existing.candidate_search, next.candidate_search) or
            !std.mem.eql(u8, existing.candidate_ann_index, next.candidate_ann_index) or
            existing.candidate_limit != next.candidate_limit or
            !std.mem.eql(u8, existing.name_embedding, next.name_embedding) or
            existing.name_embedding_dims != next.name_embedding_dims or
            !std.mem.eql(u8, existing.fusion_combine, next.fusion_combine) or
            existing.fusion_trust != next.fusion_trust or
            existing.fusion_prior != next.fusion_prior or
            existing.fusion_prior_weight != next.fusion_prior_weight or
            existing.config_generation != next.config_generation;
    }

    pub fn addResolver(self: *IndexManager, store: anytype, cfg: resolver_catalog.ResolverConfig) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        if (self.getResolver(cfg.name) != null) return error.ResolverAlreadyExists;
        if (self.resolverResolutionArtifactInUse(cfg.resolution_artifact, null)) return error.ResolverArtifactAlreadyExists;

        const checkpoint = self.resolvers.items.len;
        errdefer self.truncateResolvers(checkpoint);
        try self.resolvers.append(self.alloc, try resolver_catalog.ResolverConfig.clone(self.alloc, cfg));
        try self.persistResolverCatalog(store, .mark_reresolve_dirty);
    }

    /// Add or replace a resolver by name. Source/output artifact stream bindings
    /// are immutable for an existing resolver; material resolver/scorer config
    /// changes ask the caller to re-resolve existing extraction artifacts because
    /// their incremental replay hints will not fire on their own.
    pub fn upsertResolver(self: *IndexManager, store: anytype, cfg: resolver_catalog.ResolverConfig) !ResolverUpsertResult {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        for (self.resolvers.items) |*entry| {
            if (!std.mem.eql(u8, entry.name, cfg.name)) continue;
            if (!std.mem.eql(u8, entry.source_artifact, cfg.source_artifact)) return error.ResolverSourceArtifactImmutable;
            if (entry.source_artifact_kind != cfg.source_artifact_kind) return error.ResolverSourceArtifactImmutable;
            if (!std.mem.eql(u8, entry.resolution_artifact, cfg.resolution_artifact)) return error.ResolverArtifactImmutable;
            if (self.resolverResolutionArtifactInUse(cfg.resolution_artifact, cfg.name)) return error.ResolverArtifactAlreadyExists;
            const material_changed = resolverMaterialConfigChanged(entry.*, cfg);
            var replacement = try resolver_catalog.ResolverConfig.clone(self.alloc, cfg);
            errdefer replacement.deinit(self.alloc);
            entry.deinit(self.alloc);
            entry.* = replacement;
            try self.persistResolverCatalog(store, if (material_changed) .mark_reresolve_dirty else .catalog_only);
            return if (material_changed) .updated_backfill_required else .updated_no_backfill;
        }
        if (self.resolverResolutionArtifactInUse(cfg.resolution_artifact, null)) return error.ResolverArtifactAlreadyExists;
        const checkpoint = self.resolvers.items.len;
        errdefer self.truncateResolvers(checkpoint);
        try self.resolvers.append(self.alloc, try resolver_catalog.ResolverConfig.clone(self.alloc, cfg));
        try self.persistResolverCatalog(store, .mark_reresolve_dirty);
        return .inserted;
    }

    pub fn removeResolver(self: *IndexManager, store: anytype, name: []const u8) !bool {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        for (self.resolvers.items, 0..) |*entry, i| {
            if (!std.mem.eql(u8, entry.name, name)) continue;
            entry.deinit(self.alloc);
            _ = self.resolvers.orderedRemove(i);
            try self.persistResolverCatalog(store, .catalog_only);
            return true;
        }
        return false;
    }

    pub fn listResolvers(self: *const IndexManager, alloc: Allocator) ![]resolver_catalog.ResolverConfig {
        const out = try alloc.alloc(resolver_catalog.ResolverConfig, self.resolvers.items.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |*cfg| cfg.deinit(alloc);
            alloc.free(out);
        }
        for (self.resolvers.items, 0..) |cfg, i| {
            out[i] = try resolver_catalog.ResolverConfig.clone(alloc, cfg);
            initialized += 1;
        }
        return out;
    }

    fn truncateResolvers(self: *IndexManager, len: usize) void {
        while (self.resolvers.items.len > len) {
            self.resolvers.items[self.resolvers.items.len - 1].deinit(self.alloc);
            _ = self.resolvers.pop();
        }
    }

    pub fn remove(self: *IndexManager, store: anytype, name: []const u8) !bool {
        return try self.removeWithAtomicMutation(store, name, null);
    }

    pub fn removeManaged(self: *IndexManager, store: anytype, name: []const u8, admission_key: []const u8) !bool {
        return try self.removeWithAtomicMutation(store, name, .{ .delete = admission_key });
    }

    fn clearAppliedSequenceAfterCatalogRemoval(self: *IndexManager, store: anytype, name: []const u8) void {
        if (builtin.is_test) {
            if (test_inject_index_removal_cleanup_error) |err| {
                std.log.warn("index removal committed with injected stale applied-sequence metadata name={s} err={s}", .{ name, @errorName(err) });
                return;
            }
        }
        apply_state.clearAppliedSequenceWithCheckpoint(self.alloc, self.checkpointIo(), store, self.applied_sequence_checkpoint_path, name) catch |err| {
            std.log.warn("index removal committed with stale applied-sequence metadata name={s} err={s}", .{ name, @errorName(err) });
        };
    }

    fn encodeGeneratedArtifactCleanupRecord(
        self: *IndexManager,
        phase: GeneratedArtifactCleanupPhase,
        chunk_name: ?[]const u8,
        embedding_name: ?[]const u8,
        cursor: ?[]const u8,
    ) ![]u8 {
        const chunk_len = if (chunk_name) |value|
            std.math.cast(u32, value.len) orelse return error.NameTooLong
        else
            generated_artifact_cleanup_null_len;
        const embedding_len = if (embedding_name) |value|
            std.math.cast(u32, value.len) orelse return error.NameTooLong
        else
            generated_artifact_cleanup_null_len;
        const cursor_len = if (cursor) |value|
            std.math.cast(u32, value.len) orelse return error.KeyTooLong
        else
            generated_artifact_cleanup_null_len;
        const payload_len = (if (chunk_name) |value| value.len else 0) +
            (if (embedding_name) |value| value.len else 0) +
            (if (cursor) |value| value.len else 0);
        const out = try self.alloc.alloc(u8, generated_artifact_cleanup_header_len + payload_len);
        std.mem.writeInt(u64, out[0..8], generated_artifact_cleanup_magic, .little);
        std.mem.writeInt(u32, out[8..12], @intFromEnum(phase), .little);
        std.mem.writeInt(u32, out[12..16], chunk_len, .little);
        std.mem.writeInt(u32, out[16..20], embedding_len, .little);
        std.mem.writeInt(u32, out[20..24], cursor_len, .little);
        var offset: usize = generated_artifact_cleanup_header_len;
        if (chunk_name) |value| {
            @memcpy(out[offset .. offset + value.len], value);
            offset += value.len;
        }
        if (embedding_name) |value| {
            @memcpy(out[offset .. offset + value.len], value);
            offset += value.len;
        }
        if (cursor) |value| {
            @memcpy(out[offset .. offset + value.len], value);
        }
        return out;
    }

    fn decodeGeneratedArtifactCleanupRecord(raw: []const u8) !GeneratedArtifactCleanupRecord {
        if (raw.len < generated_artifact_cleanup_header_len) return error.InvalidGeneratedArtifactCleanup;
        if (std.mem.readInt(u64, raw[0..8], .little) != generated_artifact_cleanup_magic)
            return error.InvalidGeneratedArtifactCleanup;
        const phase = std.enums.fromInt(GeneratedArtifactCleanupPhase, std.mem.readInt(u32, raw[8..12], .little)) orelse
            return error.InvalidGeneratedArtifactCleanup;
        const chunk_len_raw = std.mem.readInt(u32, raw[12..16], .little);
        const embedding_len_raw = std.mem.readInt(u32, raw[16..20], .little);
        const cursor_len_raw = std.mem.readInt(u32, raw[20..24], .little);
        const chunk_len: usize = if (chunk_len_raw == generated_artifact_cleanup_null_len) 0 else chunk_len_raw;
        const embedding_len: usize = if (embedding_len_raw == generated_artifact_cleanup_null_len) 0 else embedding_len_raw;
        const cursor_len: usize = if (cursor_len_raw == generated_artifact_cleanup_null_len) 0 else cursor_len_raw;
        const expected_len = generated_artifact_cleanup_header_len + chunk_len + embedding_len + cursor_len;
        if (raw.len != expected_len) return error.InvalidGeneratedArtifactCleanup;
        var offset: usize = generated_artifact_cleanup_header_len;
        const chunk_name: ?[]const u8 = if (chunk_len_raw == generated_artifact_cleanup_null_len)
            null
        else blk: {
            const value = raw[offset .. offset + chunk_len];
            offset += chunk_len;
            break :blk value;
        };
        const embedding_name: ?[]const u8 = if (embedding_len_raw == generated_artifact_cleanup_null_len)
            null
        else blk: {
            const value = raw[offset .. offset + embedding_len];
            offset += embedding_len;
            break :blk value;
        };
        const cursor: ?[]const u8 = if (cursor_len_raw == generated_artifact_cleanup_null_len)
            null
        else
            raw[offset .. offset + cursor_len];
        return .{ .phase = phase, .chunk_name = chunk_name, .embedding_name = embedding_name, .cursor = cursor };
    }

    fn prepareGeneratedArtifactCleanupPlan(
        self: *IndexManager,
        name: []const u8,
        kind: types.IndexKind,
        coverage_generation: u64,
        owned_chunk_name: ?[]const u8,
        owned_embedding_name: ?[]const u8,
    ) !GeneratedArtifactCleanupPlan {
        var plan = GeneratedArtifactCleanupPlan{ .alloc = self.alloc };
        errdefer plan.deinit();
        plan.key = try internal_keys.indexArtifactCleanupKeyAlloc(self.alloc, name, coverage_generation);
        const initial_phase: GeneratedArtifactCleanupPhase = if (kind == .algebraic)
            .algebraic_canonical_facts
        else
            .generated_artifacts;
        plan.value = try self.encodeGeneratedArtifactCleanupRecord(initial_phase, owned_chunk_name, owned_embedding_name, null);
        return plan;
    }

    fn combineRemovalCatalogMutation(
        base: ?AtomicCatalogMutation,
        cleanup: *const GeneratedArtifactCleanupPlan,
    ) !?AtomicCatalogMutation {
        const cleanup_key = cleanup.key orelse return base;
        const cleanup_value = cleanup.value.?;
        return if (base) |mutation| switch (mutation) {
            .delete => |key| .{ .put_delete = .{
                .put = .{ .key = cleanup_key, .value = cleanup_value },
                .delete = key,
            } },
            .put, .put_delete => error.InvalidArgument,
        } else .{ .put = .{ .key = cleanup_key, .value = cleanup_value } };
    }

    fn drainGeneratedArtifactCleanupRecordPage(
        self: *IndexManager,
        store: anytype,
        key: []const u8,
        raw: []const u8,
    ) !GeneratedArtifactCleanupDrainResult {
        const record = try decodeGeneratedArtifactCleanupRecord(raw);
        if (builtin.is_test) {
            if (test_inject_generated_artifact_cleanup_error) |err| return err;
            var remaining = test_generated_artifact_cleanup_failures_remaining.load(.acquire);
            while (remaining != 0) {
                if (test_generated_artifact_cleanup_failures_remaining.cmpxchgWeak(
                    remaining,
                    remaining - 1,
                    .acq_rel,
                    .acquire,
                )) |actual| {
                    remaining = actual;
                    continue;
                }
                return error.TestTransientGeneratedArtifactCleanup;
            }
        }
        switch (record.phase) {
            .dense_metadata => {
                const index_name = try internal_keys.indexArtifactCleanupNameAlloc(self.alloc, key);
                defer self.alloc.free(index_name);
                const prefix = try denseIndexMetadataPrefixAlloc(self.alloc, index_name);
                defer self.alloc.free(prefix);
                return try self.drainGeneratedArtifactCleanupMetadataPage(store, key, record, prefix, .derived_coverage);
            },
            .derived_coverage => {
                const index_name = try internal_keys.indexArtifactCleanupNameAlloc(self.alloc, key);
                defer self.alloc.free(index_name);
                const prefix = try internal_keys.derivedCoverageOutcomePrefixAlloc(self.alloc, index_name);
                defer self.alloc.free(prefix);
                return try self.drainGeneratedArtifactCleanupMetadataPage(store, key, record, prefix, .finalization);
            },
            .algebraic_canonical_facts => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .canonical, .facts, .algebraic_canonical_tuples),
            .algebraic_canonical_tuples => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .canonical, .tuples, .algebraic_canonical_dictionary),
            .algebraic_canonical_dictionary => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .canonical, .dictionary, .algebraic_canonical_registry),
            .algebraic_canonical_registry => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .canonical, .registry, .algebraic_active_facts),
            .algebraic_active_facts => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .active, .facts, .algebraic_active_tuples),
            .algebraic_active_tuples => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .active, .tuples, .algebraic_active_dictionary),
            .algebraic_active_dictionary => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .active, .dictionary, .algebraic_active_registry),
            .algebraic_active_registry => return try self.drainGeneratedArtifactCleanupAlgebraicPage(store, key, record, .active, .registry, .finalization),
            .finalization => return .{ .found = true, .completed = true },
            .generated_artifacts => {},
        }

        if (record.chunk_name == null and record.embedding_name == null) {
            const next_value = try self.encodeGeneratedArtifactCleanupRecord(.dense_metadata, null, null, null);
            defer self.alloc.free(next_value);
            try store.put(key, next_value);
            return .{ .found = true, .completed = false };
        }
        const lower = try internal_keys.documentRangeLowerAlloc(self.alloc, "");
        defer self.alloc.free(lower);
        const upper_owned = try internal_keys.documentRangeUpperAlloc(self.alloc, "");
        defer if (upper_owned) |upper| self.alloc.free(upper);

        const ScanState = struct {
            manager: *IndexManager,
            chunk_name: ?[]const u8,
            embedding_name: ?[]const u8,
            deletes: std.ArrayListUnmanaged([]u8) = .empty,
            last_key: ?[]u8 = null,
            scanned: usize = 0,
            stopped: bool = false,

            fn deinit(state: *@This()) void {
                for (state.deletes.items) |delete_key| state.manager.alloc.free(delete_key);
                state.deletes.deinit(state.manager.alloc);
                if (state.last_key) |last_key| state.manager.alloc.free(last_key);
            }

            fn scanEntry(ctx: ?*anyopaque, candidate: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                state.scanned += 1;

                var should_delete = false;
                if (state.chunk_name) |chunk_name| {
                    should_delete = (internal_keys.isChunkArtifactRecordKey(candidate) and internal_keys.matchesChunkArtifactName(candidate, chunk_name)) or
                        (internal_keys.isDerivedEmbeddingArtifactKey(candidate) and try state.manager.derivedEmbeddingBaseMatchesChunk(candidate, chunk_name));
                }
                if (!should_delete) if (state.embedding_name) |embedding_name| {
                    should_delete = (internal_keys.isEmbeddingArtifactKey(candidate) and internal_keys.matchesEmbeddingArtifactName(candidate, embedding_name)) or
                        (internal_keys.isDerivedEmbeddingArtifactKey(candidate) and internal_keys.matchesDerivedEmbeddingArtifactName(candidate, embedding_name));
                };
                if (should_delete) try state.deletes.append(state.manager.alloc, try state.manager.alloc.dupe(u8, candidate));

                if (state.scanned >= generated_artifact_cleanup_scan_limit) {
                    state.last_key = try state.manager.alloc.dupe(u8, candidate);
                    state.stopped = true;
                    return .stop;
                }
                return .@"continue";
            }
        };

        var state = ScanState{
            .manager = self,
            .chunk_name = record.chunk_name,
            .embedding_name = record.embedding_name,
        };
        defer state.deinit();
        try store.scanWithContext(
            record.cursor orelse lower,
            if (upper_owned) |upper| upper else "",
            .{ .lower_exclusive = record.cursor != null },
            &state,
            ScanState.scanEntry,
        );

        var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer delete_keys.deinit(self.alloc);
        try delete_keys.ensureTotalCapacity(self.alloc, state.deletes.items.len + 1);
        for (state.deletes.items) |delete_key| delete_keys.appendAssumeCapacity(delete_key);

        if (state.stopped) {
            const next_value = try self.encodeGeneratedArtifactCleanupRecord(.generated_artifacts, record.chunk_name, record.embedding_name, state.last_key.?);
            defer self.alloc.free(next_value);
            const writes = [_]docstore_mod.KVPair{.{ .key = key, .value = next_value }};
            try store.putBatch(&writes, delete_keys.items);
            return .{ .found = true, .completed = false };
        }

        const next_value = try self.encodeGeneratedArtifactCleanupRecord(.dense_metadata, record.chunk_name, record.embedding_name, null);
        defer self.alloc.free(next_value);
        const writes = [_]docstore_mod.KVPair{.{ .key = key, .value = next_value }};
        try store.putBatch(&writes, delete_keys.items);
        return .{ .found = true, .completed = false };
    }

    fn drainGeneratedArtifactCleanupMetadataPage(
        self: *IndexManager,
        store: anytype,
        key: []const u8,
        record: GeneratedArtifactCleanupRecord,
        prefix: []const u8,
        next_phase: GeneratedArtifactCleanupPhase,
    ) !GeneratedArtifactCleanupDrainResult {
        const rows = try store.scanPrefixPage(
            self.alloc,
            prefix,
            record.cursor,
            generated_artifact_cleanup_scan_limit,
        );
        defer docstore_mod.DocStore.freeResults(self.alloc, rows);

        const delete_keys = try self.alloc.alloc([]const u8, rows.len);
        defer self.alloc.free(delete_keys);
        for (rows, 0..) |row, i| delete_keys[i] = row.key;

        if (rows.len == generated_artifact_cleanup_scan_limit) {
            const next_value = try self.encodeGeneratedArtifactCleanupRecord(
                record.phase,
                record.chunk_name,
                record.embedding_name,
                rows[rows.len - 1].key,
            );
            defer self.alloc.free(next_value);
            const writes = [_]docstore_mod.KVPair{.{ .key = key, .value = next_value }};
            try store.putBatch(&writes, delete_keys);
            return .{ .found = true, .completed = false };
        }

        if (next_phase == .finalization) {
            if (delete_keys.len != 0) try store.putBatch(&.{}, delete_keys);
            return .{ .found = true, .completed = true };
        }
        const next_value = try self.encodeGeneratedArtifactCleanupRecord(
            next_phase,
            record.chunk_name,
            record.embedding_name,
            null,
        );
        defer self.alloc.free(next_value);
        const writes = [_]docstore_mod.KVPair{.{ .key = key, .value = next_value }};
        try store.putBatch(&writes, delete_keys);
        return .{ .found = true, .completed = false };
    }

    fn algebraicCleanupStorageNamespaceAlloc(
        self: *IndexManager,
        index_name: []const u8,
        generation: AlgebraicCleanupGeneration,
    ) ![]u8 {
        if (generation == .canonical) {
            return try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ canonical_algebraic_generation, index_name });
        }
        const canonical_path = try self.indexPath(index_name);
        defer self.alloc.free(canonical_path);
        const active_path = try self.activeIndexPath(index_name);
        defer self.alloc.free(active_path);
        if (std.mem.eql(u8, active_path, canonical_path)) {
            return try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ canonical_algebraic_generation, index_name });
        }
        const indexes_dir = std.fs.path.dirname(active_path) orelse return error.InvalidIndexRootPointer;
        const repair_root = std.fs.path.dirname(indexes_dir) orelse return error.InvalidIndexRootPointer;
        return try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ std.fs.path.basename(repair_root), index_name });
    }

    fn algebraicCleanupPrefixAlloc(
        self: *IndexManager,
        storage_namespace: []const u8,
        family: AlgebraicCleanupFamily,
    ) ![]u8 {
        return switch (family) {
            .facts => try algebraic_mod.index.storagePrefixAlloc(self.alloc, storage_namespace),
            .tuples => try algebraic_mod.index.tupleStoragePrefixAlloc(self.alloc, storage_namespace),
            .dictionary => try algebraic_mod.index.dictionaryStoragePrefixAlloc(self.alloc, storage_namespace),
            .registry => try algebraic_mod.index.dictionaryRegistryPrefixAlloc(self.alloc, storage_namespace),
        };
    }

    fn drainGeneratedArtifactCleanupAlgebraicPage(
        self: *IndexManager,
        store: anytype,
        key: []const u8,
        record: GeneratedArtifactCleanupRecord,
        generation: AlgebraicCleanupGeneration,
        family: AlgebraicCleanupFamily,
        next_phase: GeneratedArtifactCleanupPhase,
    ) !GeneratedArtifactCleanupDrainResult {
        const index_name = try internal_keys.indexArtifactCleanupNameAlloc(self.alloc, key);
        defer self.alloc.free(index_name);
        const storage_namespace = try self.algebraicCleanupStorageNamespaceAlloc(index_name, generation);
        defer self.alloc.free(storage_namespace);
        const prefix = try self.algebraicCleanupPrefixAlloc(storage_namespace, family);
        defer self.alloc.free(prefix);
        return try self.drainGeneratedArtifactCleanupMetadataPage(store, key, record, prefix, next_phase);
    }

    pub fn drainGeneratedArtifactCleanupOutboxPage(self: *IndexManager, store: anytype) !GeneratedArtifactCleanupDrainResult {
        const prefix = try internal_keys.indexArtifactCleanupRootPrefixAlloc(self.alloc);
        defer self.alloc.free(prefix);
        const page_limit: usize = 32;
        var after_key: ?[]u8 = null;
        defer if (after_key) |key| self.alloc.free(key);
        var first_err: ?anyerror = null;

        // A malformed or temporarily unavailable tombstone must fail its own
        // namespace closed without starving cleanup for unrelated indexes.
        while (true) {
            const rows = try store.scanPrefixPage(self.alloc, prefix, after_key, page_limit);
            defer docstore_mod.DocStore.freeResults(self.alloc, rows);
            if (rows.len == 0) {
                if (first_err) |err| return err;
                return .{};
            }
            for (rows) |row| {
                const index_name = internal_keys.indexArtifactCleanupNameAlloc(self.alloc, row.key) catch |err| {
                    if (first_err == null) first_err = err;
                    continue;
                };
                var result = self.drainGeneratedArtifactCleanupRecordPage(store, row.key, row.value) catch |err| {
                    self.alloc.free(index_name);
                    if (first_err == null) first_err = err;
                    continue;
                };
                result.alloc = self.alloc;
                result.index_name = index_name;
                errdefer result.deinit();
                result.key = try self.alloc.dupe(u8, row.key);
                return result;
            }
            if (rows.len < page_limit) {
                if (first_err) |err| return err;
                return .{};
            }
            const next = try self.alloc.dupe(u8, rows[rows.len - 1].key);
            if (after_key) |key| self.alloc.free(key);
            after_key = next;
        }
    }

    pub fn drainGeneratedArtifactCleanupForIndexPage(
        self: *IndexManager,
        store: anytype,
        index_name: []const u8,
    ) !GeneratedArtifactCleanupDrainResult {
        const prefix = try internal_keys.indexArtifactCleanupIndexPrefixAlloc(self.alloc, index_name);
        defer self.alloc.free(prefix);
        return try self.drainGeneratedArtifactCleanupPrefixPage(store, prefix);
    }

    fn drainGeneratedArtifactCleanupPrefixPage(
        self: *IndexManager,
        store: anytype,
        prefix: []const u8,
    ) !GeneratedArtifactCleanupDrainResult {
        const rows = try store.scanPrefixPage(self.alloc, prefix, null, 1);
        defer docstore_mod.DocStore.freeResults(self.alloc, rows);
        if (rows.len == 0) return .{};
        var result = try self.drainGeneratedArtifactCleanupRecordPage(store, rows[0].key, rows[0].value);
        result.alloc = self.alloc;
        errdefer result.deinit();
        result.key = try self.alloc.dupe(u8, rows[0].key);
        result.index_name = try internal_keys.indexArtifactCleanupNameAlloc(self.alloc, rows[0].key);
        return result;
    }

    /// Return the retired index whose cleanup owns a namespace needed by cfg.
    /// Cleanup rows are structural metadata, so this scan is proportional to
    /// outstanding deletion debt rather than document count and is paged to
    /// keep temporary memory bounded.
    pub fn pendingGeneratedArtifactCleanupIndexForConfigAlloc(
        self: *IndexManager,
        store: anytype,
        cfg: types.IndexConfig,
    ) !?[]u8 {
        var refs = try self.artifactRefsFromConfig(cfg);
        defer refs.deinit(self.alloc);
        const prefix = try internal_keys.indexArtifactCleanupRootPrefixAlloc(self.alloc);
        defer self.alloc.free(prefix);

        const page_limit: usize = 128;
        var after_key: ?[]u8 = null;
        defer if (after_key) |key| self.alloc.free(key);
        while (true) {
            const rows = try store.scanPrefixPage(self.alloc, prefix, after_key, page_limit);
            defer docstore_mod.DocStore.freeResults(self.alloc, rows);
            if (rows.len == 0) return null;
            for (rows) |row| {
                const retired_name = try internal_keys.indexArtifactCleanupNameAlloc(self.alloc, row.key);
                errdefer self.alloc.free(retired_name);
                const record = try decodeGeneratedArtifactCleanupRecord(row.value);
                const conflicts = std.mem.eql(u8, retired_name, cfg.name) or
                    (refs.chunk_name != null and record.chunk_name != null and std.mem.eql(u8, refs.chunk_name.?, record.chunk_name.?)) or
                    (refs.embedding_name != null and record.embedding_name != null and std.mem.eql(u8, refs.embedding_name.?, record.embedding_name.?));
                if (conflicts) return retired_name;
                self.alloc.free(retired_name);
            }
            if (rows.len < page_limit) return null;
            const next = try self.alloc.dupe(u8, rows[rows.len - 1].key);
            if (after_key) |key| self.alloc.free(key);
            after_key = next;
        }
    }

    pub fn finalizeRetiredIndexStorage(self: *IndexManager, store: anytype, name: []const u8) !void {
        const canonical_path = try self.indexPath(name);
        defer self.alloc.free(canonical_path);
        const active_path = try self.activeIndexPath(name);
        defer self.alloc.free(active_path);

        self.catalog_mutex.lockExclusive();
        if (self.get(name) != null) {
            self.catalog_mutex.unlockExclusive();
            return error.IndexGenerationStillActive;
        }
        self.invalidateIndexPathCaches(active_path);
        self.invalidateIndexPathCaches(canonical_path);
        self.catalog_mutex.unlockExclusive();

        // The durable cleanup tombstone prevents same-name admission until
        // finalization succeeds, so checkpoint and filesystem I/O need not hold
        // the catalog lock used by unrelated indexes.
        try apply_state.clearAppliedSequenceWithCheckpoint(
            self.alloc,
            self.checkpointIo(),
            store,
            self.applied_sequence_checkpoint_path,
            name,
        );
        // Algebraic keyspaces are drained in bounded, cursor-backed outbox
        // phases before finalization reaches this filesystem-only tail.
        if (!std.mem.eql(u8, active_path, canonical_path)) try self.deleteIndexDirUsingIoIfPresentFallible(active_path);
        try self.deleteIndexDirUsingIoIfPresentFallible(canonical_path);
    }

    fn removeWithAtomicMutation(
        self: *IndexManager,
        store: anytype,
        name: []const u8,
        atomic_mutation: ?AtomicCatalogMutation,
    ) !bool {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        if (self.get(name) == null) return false;

        if (try self.removeStatusOnlyConfig(store, name, atomic_mutation)) {
            // Quarantined (failed-to-load) indexes live in the status-only
            // list; removing one must also clear its recorded load error so a
            // subsequent recreate starts clean.
            self.dropFailedIndexLoad(name);
            self.dropIndexLoadStateNoLock(name);
            return true;
        }
        for (self.text_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                const index_path = try self.indexPath(name);
                defer self.alloc.free(index_path);
                const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCacheExcluding(name, null);
                var cleanup = try self.prepareGeneratedArtifactCleanupPlan(name, entry.config.kind, coverageGenerationForConfig(entry.config), null, null);
                defer cleanup.deinit();
                try self.persistCatalogExcludingWithAtomicMutation(
                    store,
                    name,
                    try combineRemovalCatalogMutation(atomic_mutation, &cleanup),
                );
                self.text_merge_scheduler.removeIndex(self.alloc, name);
                entry.detachAllMergeDeletionStates();
                self.freeTextIndexEntry(entry);
                _ = self.text_indexes.orderedRemove(i);
                defer self.dropIndexLoadStateNoLock(name);
                self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
                self.clearAppliedSequenceAfterCatalogRemoval(store, name);
                self.invalidateIndexRootForName(name, index_path);
                return true;
            }
        }
        for (self.dense_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                const index_path = try self.indexPath(name);
                defer self.alloc.free(index_path);
                const owned_chunk_name = if (entry.chunk_name) |chunk_name|
                    if (self.ownsGeneratedChunkArtifacts(name, chunk_name)) try self.alloc.dupe(u8, chunk_name) else null
                else
                    null;
                defer if (owned_chunk_name) |chunk_name| self.alloc.free(chunk_name);
                const owned_embedding_name = if (entry.embedding_name) |embedding_name|
                    if (self.ownsGeneratedEmbeddingArtifacts(name, embedding_name)) try self.alloc.dupe(u8, embedding_name) else null
                else
                    null;
                defer if (owned_embedding_name) |embedding_name| self.alloc.free(embedding_name);
                const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCacheExcluding(name, null);
                var artifact_cleanup = try self.prepareGeneratedArtifactCleanupPlan(
                    name,
                    entry.config.kind,
                    coverageGenerationForConfig(entry.config),
                    owned_chunk_name,
                    owned_embedding_name,
                );
                defer artifact_cleanup.deinit();
                const commit_mutation = try combineRemovalCatalogMutation(atomic_mutation, &artifact_cleanup);
                try self.persistCatalogExcludingWithAtomicMutation(store, name, commit_mutation);
                self.freeDenseIndexEntry(entry);
                _ = self.dense_indexes.orderedRemove(i);
                defer self.dropIndexLoadStateNoLock(name);
                self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
                self.clearAppliedSequenceAfterCatalogRemoval(store, name);
                self.invalidateIndexRootForName(name, index_path);
                return true;
            }
        }
        for (self.sparse_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                const index_path = try self.indexPath(name);
                defer self.alloc.free(index_path);
                const owned_chunk_name = if (entry.chunk_name) |chunk_name|
                    if (self.ownsGeneratedChunkArtifacts(name, chunk_name)) try self.alloc.dupe(u8, chunk_name) else null
                else
                    null;
                defer if (owned_chunk_name) |chunk_name| self.alloc.free(chunk_name);
                const owned_embedding_name = if (entry.embedding_name) |embedding_name|
                    if (self.ownsGeneratedEmbeddingArtifacts(name, embedding_name)) try self.alloc.dupe(u8, embedding_name) else null
                else
                    null;
                defer if (owned_embedding_name) |embedding_name| self.alloc.free(embedding_name);
                const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCacheExcluding(name, null);
                var artifact_cleanup = try self.prepareGeneratedArtifactCleanupPlan(
                    name,
                    entry.config.kind,
                    coverageGenerationForConfig(entry.config),
                    owned_chunk_name,
                    owned_embedding_name,
                );
                defer artifact_cleanup.deinit();
                const commit_mutation = try combineRemovalCatalogMutation(atomic_mutation, &artifact_cleanup);
                try self.persistCatalogExcludingWithAtomicMutation(store, name, commit_mutation);
                self.freeSparseIndexEntry(entry);
                _ = self.sparse_indexes.orderedRemove(i);
                defer self.dropIndexLoadStateNoLock(name);
                self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
                self.clearAppliedSequenceAfterCatalogRemoval(store, name);
                self.invalidateIndexRootForName(name, index_path);
                return true;
            }
        }
        for (self.graph_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                const index_path = try self.indexPath(name);
                defer self.alloc.free(index_path);
                const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCacheExcluding(name, null);
                var cleanup = try self.prepareGeneratedArtifactCleanupPlan(name, entry.config.kind, coverageGenerationForConfig(entry.config), null, null);
                defer cleanup.deinit();
                try self.persistCatalogExcludingWithAtomicMutation(
                    store,
                    name,
                    try combineRemovalCatalogMutation(atomic_mutation, &cleanup),
                );
                self.freeGraphIndexEntry(entry);
                _ = self.graph_indexes.orderedRemove(i);
                defer self.dropIndexLoadStateNoLock(name);
                self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
                self.clearAppliedSequenceAfterCatalogRemoval(store, name);
                self.invalidateIndexRootForName(name, index_path);
                return true;
            }
        }
        for (self.algebraic_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                const index_path = try self.indexPath(name);
                defer self.alloc.free(index_path);
                const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCacheExcluding(name, null);
                var cleanup = try self.prepareGeneratedArtifactCleanupPlan(name, entry.config.kind, coverageGenerationForConfig(entry.config), null, null);
                defer cleanup.deinit();
                try self.persistCatalogExcludingWithAtomicMutation(
                    store,
                    name,
                    try combineRemovalCatalogMutation(atomic_mutation, &cleanup),
                );
                self.freeAlgebraicIndexEntry(entry);
                _ = self.algebraic_indexes.orderedRemove(i);
                defer self.dropIndexLoadStateNoLock(name);
                self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
                self.clearAppliedSequenceAfterCatalogRemoval(store, name);
                self.invalidateIndexRootForName(name, index_path);
                return true;
            }
        }
        return false;
    }

    pub fn reopenQuarantinedIndexForArtifactRebuild(self: *IndexManager, store: anytype, name: []const u8) !types.IndexKind {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();

        for (self.status_only_index_configs, 0..) |cfg, i| {
            if (!std.mem.eql(u8, cfg.name, name)) continue;

            var rebuild_cfg = try types.IndexConfig.clone(self.alloc, cfg);
            errdefer rebuild_cfg.deinit(self.alloc);
            const index_path = try self.indexPath(name);
            defer self.alloc.free(index_path);

            self.deleteIndexRootForName(name, index_path);
            try self.openConfiguredIndex(store, rebuild_cfg, false, false);
            errdefer self.removeInMemory(name);

            const replacement: []types.IndexConfig = if (self.status_only_index_configs.len > 1)
                try self.alloc.alloc(types.IndexConfig, self.status_only_index_configs.len - 1)
            else
                &.{};
            errdefer if (replacement.len > 0) self.alloc.free(replacement);

            var out: usize = 0;
            var removed = cfg;
            for (self.status_only_index_configs, 0..) |existing, existing_i| {
                if (existing_i == i) continue;
                replacement[out] = existing;
                out += 1;
            }
            self.alloc.free(self.status_only_index_configs);
            self.status_only_index_configs = replacement;

            self.dropFailedIndexLoad(name);
            self.dropIndexLoadStateNoLock(name);
            try self.refreshGeneratedEnrichmentTargetCache();

            const kind = rebuild_cfg.kind;
            removed.deinit(self.alloc);
            rebuild_cfg.deinit(self.alloc);
            return kind;
        }

        return error.IndexNotFound;
    }

    pub fn detachReplacementIndex(self: *IndexManager, name: []const u8) !DetachedIndex {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        return self.detachInMemoryNoLock(name) orelse error.IndexNotFound;
    }

    pub fn destroyDetachedReplacementIndex(self: *IndexManager, entry: *DetachedIndex) void {
        entry.deinit(self);
    }

    /// Publishes any already-open replacement generation without a
    /// size-dependent close/reopen tail. All allocations and validation happen
    /// before the durable pointer commit; the detached predecessor is returned
    /// to the caller for retirement after service fences are released.
    pub fn installAdoptedReplacementIndex(
        self: *IndexManager,
        store: anytype,
        cfg: types.IndexConfig,
        replacement_index_path: []const u8,
        expected_previous_pointer: ?[]const u8,
        replacement: *DetachedIndex,
    ) !?DetachedIndex {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        self.bindPrimaryStore(store);

        if (std.meta.activeTag(replacement.*) != cfg.kind or
            types.indexConfigHash(detachedIndexConfig(replacement).*) != types.indexConfigHash(cfg))
        {
            return error.IndexReplacementConfigurationMismatch;
        }
        const target_path = try self.indexPath(cfg.name);
        defer self.alloc.free(target_path);
        const previous_pointer = try self.readActiveIndexRootPointer(target_path, cfg.name);
        defer if (previous_pointer) |value| self.alloc.free(value);
        if (!optionalBytesEqual(previous_pointer, expected_previous_pointer)) return error.IndexRootPointerChanged;
        const replacement_relative_path = try self.relativeRepairIndexRootForActivePath(cfg.name, replacement_index_path);
        defer self.alloc.free(replacement_relative_path);
        _ = try index_generation_manifest.validateReady(
            self.alloc,
            replacement_index_path,
            null,
            cfg.name,
            types.indexConfigHash(cfg),
        );

        var status_only_index: ?usize = null;
        for (self.status_only_index_configs, 0..) |status_cfg, i| {
            if (std.mem.eql(u8, status_cfg.name, cfg.name)) {
                status_only_index = i;
                break;
            }
        }
        const status_replacement: ?[]types.IndexConfig = if (status_only_index) |remove_i| blk: {
            const next: []types.IndexConfig = if (self.status_only_index_configs.len > 1)
                try self.alloc.alloc(types.IndexConfig, self.status_only_index_configs.len - 1)
            else
                &.{};
            var out: usize = 0;
            for (self.status_only_index_configs, 0..) |status_cfg, i| {
                if (i == remove_i) continue;
                next[out] = status_cfg;
                out += 1;
            }
            break :blk next;
        } else null;
        var status_replacement_committed = false;
        defer if (!status_replacement_committed) if (status_replacement) |next| {
            if (next.len > 0) self.alloc.free(next);
        };

        try self.ensureDetachedIndexCapacity(replacement.*);
        const replacement_generates = try self.configRequiresEnrichmentReplay(detachedIndexConfig(replacement).*);
        const generated_targets = replacement_generates or
            try self.computeGeneratedEnrichmentTargetCacheExcluding(cfg.name, null);

        try self.writeActiveIndexRootPointer(target_path, replacement_relative_path);
        const retired = self.detachInMemoryNoLock(cfg.name);
        self.appendDetachedIndexAssumeCapacity(replacement);
        if (status_only_index) |remove_i| {
            var removed = self.status_only_index_configs[remove_i];
            if (self.status_only_index_configs.len > 0) self.alloc.free(self.status_only_index_configs);
            self.status_only_index_configs = status_replacement.?;
            status_replacement_committed = true;
            removed.deinit(self.alloc);
        }
        self.dropFailedIndexLoad(cfg.name);
        self.storeGeneratedEnrichmentTargetCache(generated_targets);
        return retired;
    }

    /// Captures the durable pointer selected immediately before activation.
    /// Null denotes the canonical root and is distinct from an uncaptured
    /// rollback anchor in the durable repair intent.
    pub fn captureActiveIndexRootPointer(self: *const IndexManager, name: []const u8) !?[]u8 {
        const target_path = try self.indexPath(name);
        defer self.alloc.free(target_path);
        return try self.readActiveIndexRootPointer(target_path, name);
    }

    /// Restores the exact generation captured before replacement activation.
    /// The candidate is retained for postmortem/retry cleanup; this method
    /// changes only the durable pointer and in-memory runtime selection.
    pub fn restoreActiveIndexRootPointer(
        self: *IndexManager,
        name: []const u8,
        expected_candidate_relative_path: []const u8,
        previous_pointer: ?[]const u8,
    ) !void {
        self.catalog_mutex.lockExclusive();
        defer self.catalog_mutex.unlockExclusive();
        const target_path = try self.indexPath(name);
        defer self.alloc.free(target_path);
        const current_pointer = try self.readActiveIndexRootPointer(target_path, name);
        defer if (current_pointer) |value| self.alloc.free(value);
        if (!optionalBytesEqual(current_pointer, expected_candidate_relative_path)) {
            return error.IndexRootPointerChanged;
        }
        self.removeInMemory(name);
        if (previous_pointer) |value| {
            try self.writeActiveIndexRootPointer(target_path, value);
        } else {
            try self.clearActiveIndexRootPointer(target_path);
        }
    }

    /// Returns whether the durable active-root pointer for `name` selects the
    /// exact repair candidate recorded by a replica-local repair intent.  This
    /// is used during restart reconciliation to distinguish a crash before
    /// pointer activation from a crash after activation but before validation
    /// and intent cleanup.
    pub fn isRepairCandidateActive(
        self: *const IndexManager,
        name: []const u8,
        candidate_relative_path: []const u8,
    ) !bool {
        const active_path = try self.activeIndexPath(name);
        defer self.alloc.free(active_path);
        const candidate_path = try std.fmt.allocPrint(
            self.alloc,
            "{s}/{s}",
            .{ self.base_path, candidate_relative_path },
        );
        defer self.alloc.free(candidate_path);
        return std.mem.eql(u8, active_path, candidate_path);
    }

    /// Advance at most one bounded algebraic key-deletion batch while also
    /// collecting filesystem-only generations. Deleted keys are the durable
    /// cursor for orphan generations: restart discovery resumes at the first
    /// remaining family without retaining an in-memory scan result.
    pub fn cleanupInactiveRepairShadowRootsPage(self: *IndexManager) !bool {
        if (builtin.os.tag == .freestanding) return false;
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();

        // Once no durable repair intent protects rollback, canonical roots
        // selected through a pointer contain only stale generation data plus
        // the pointer file. Prune that stale data before collecting orphaned
        // shadow roots.
        for (self.text_indexes.items) |entry| self.cleanupCanonicalRootAfterPointer(entry.config.name);
        for (self.dense_indexes.items) |entry| self.cleanupCanonicalRootAfterPointer(entry.config.name);
        for (self.sparse_indexes.items) |entry| self.cleanupCanonicalRootAfterPointer(entry.config.name);
        for (self.graph_indexes.items) |entry| self.cleanupCanonicalRootAfterPointer(entry.config.name);
        for (self.algebraic_indexes.items) |entry| {
            if (try self.cleanupCanonicalAlgebraicGenerationAfterPointerPage(entry.config.name)) return true;
        }
        for (self.status_only_index_configs) |cfg| switch (cfg.kind) {
            .algebraic => if (try self.cleanupCanonicalAlgebraicGenerationAfterPointerPage(cfg.name)) return true,
            else => self.cleanupCanonicalRootAfterPointer(cfg.name),
        };

        var active_roots = std.StringHashMapUnmanaged(void).empty;
        defer {
            var it = active_roots.iterator();
            while (it.next()) |entry| self.alloc.free(entry.key_ptr.*);
            active_roots.deinit(self.alloc);
        }
        try self.collectActiveRepairShadowRoots(&active_roots);

        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        var dir = std.Io.Dir.cwd().openDir(io, self.base_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
        defer dir.close(io);

        var iter = dir.iterate();
        while (try iter.next(io)) |entry| {
            if (entry.kind != .directory) continue;
            if (!std.mem.startsWith(u8, entry.name, repair_shadow_root_prefix)) continue;
            if (active_roots.contains(entry.name)) continue;
            const path = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ self.base_path, entry.name });
            defer self.alloc.free(path);
            if (repairShadowRootInProgress(path)) continue;
            if (try self.cleanupAlgebraicNamespacesInRepairRootPage(io, path, entry.name)) return true;
            deleteIndexDirIfPresent(path);
        }
        return false;
    }

    fn cleanupAlgebraicNamespacesInRepairRootPage(
        self: *IndexManager,
        io: std.Io,
        shadow_path: []const u8,
        generation: []const u8,
    ) !bool {
        const indexes_path = try std.fmt.allocPrint(self.alloc, "{s}/indexes", .{shadow_path});
        defer self.alloc.free(indexes_path);
        var indexes_dir = std.Io.Dir.cwd().openDir(io, indexes_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
        defer indexes_dir.close(io);
        var iter = indexes_dir.iterate();
        while (try iter.next(io)) |entry| {
            const storage_namespace = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ generation, entry.name });
            defer self.alloc.free(storage_namespace);
            if (!try self.deleteAlgebraicStorageNamespacePage(storage_namespace)) return true;
        }
        return false;
    }

    fn cleanupCanonicalAlgebraicGenerationAfterPointerPage(self: *IndexManager, name: []const u8) !bool {
        const target_path = try self.indexPath(name);
        defer self.alloc.free(target_path);
        const pointer = try self.readActiveIndexRootPointer(target_path, name);
        if (pointer) |value| {
            self.alloc.free(value);
            const storage_namespace = try std.fmt.allocPrint(
                self.alloc,
                "{s}/{s}",
                .{ canonical_algebraic_generation, name },
            );
            defer self.alloc.free(storage_namespace);
            if (!try self.deleteAlgebraicStorageNamespacePage(storage_namespace)) return true;
            try pruneCanonicalIndexRootAfterPointerInstall(target_path);
        }
        return false;
    }

    fn cleanupCanonicalRootAfterPointer(self: *const IndexManager, name: []const u8) void {
        const target_path = self.indexPath(name) catch return;
        defer self.alloc.free(target_path);
        const pointer = self.readActiveIndexRootPointer(target_path, name) catch return;
        if (pointer) |value| {
            self.alloc.free(value);
            pruneCanonicalIndexRootAfterPointerInstall(target_path) catch |err| {
                std.log.warn("failed to prune previous canonical index root name={s} err={s}", .{ name, @errorName(err) });
            };
        }
    }

    fn removeStatusOnlyConfig(
        self: *IndexManager,
        store: anytype,
        name: []const u8,
        atomic_mutation: ?AtomicCatalogMutation,
    ) !bool {
        for (self.status_only_index_configs, 0..) |cfg, i| {
            if (!std.mem.eql(u8, cfg.name, name)) continue;

            const index_path = try self.indexPath(name);
            defer self.alloc.free(index_path);
            var artifact_refs = self.bestEffortArtifactRefsFromConfig(cfg);
            defer artifact_refs.deinit(self.alloc);
            const cleanup_artifacts = cfg.kind == .dense_vector or cfg.kind == .sparse_vector;
            const owned_chunk_name = if (cleanup_artifacts) blk: {
                const chunk_name = artifact_refs.chunk_name orelse break :blk null;
                if (try self.chunkArtifactsReferencedElsewhereIncludingStatusOnly(name, chunk_name)) break :blk null;
                break :blk try self.alloc.dupe(u8, chunk_name);
            } else null;
            defer if (owned_chunk_name) |chunk_name| self.alloc.free(chunk_name);
            const owned_embedding_name = if (cleanup_artifacts) blk: {
                const embedding_name = artifact_refs.embedding_name orelse break :blk null;
                if (try self.embeddingArtifactsReferencedElsewhereIncludingStatusOnly(name, embedding_name)) break :blk null;
                break :blk try self.alloc.dupe(u8, embedding_name);
            } else null;
            defer if (owned_embedding_name) |embedding_name| self.alloc.free(embedding_name);
            const replacement: []types.IndexConfig = if (self.status_only_index_configs.len > 1)
                try self.alloc.alloc(types.IndexConfig, self.status_only_index_configs.len - 1)
            else
                &.{};
            var replacement_owned = replacement.len > 0;
            errdefer if (replacement_owned) self.alloc.free(replacement);
            var out: usize = 0;
            var removed = cfg;
            var removed_owned = false;
            defer if (removed_owned) removed.deinit(self.alloc);
            for (self.status_only_index_configs, 0..) |existing, existing_i| {
                if (existing_i == i) continue;
                replacement[out] = existing;
                out += 1;
            }
            // Status-only configs are deliberately excluded from the runtime
            // generated-target cache, so this value is unchanged by removal.
            // Compute it before the catalog commit to keep the commit boundary
            // free of fallible planning.
            const has_generated_enrichment_targets = try self.computeGeneratedEnrichmentTargetCache();
            var artifact_cleanup = try self.prepareGeneratedArtifactCleanupPlan(
                name,
                cfg.kind,
                coverageGenerationForConfig(cfg),
                owned_chunk_name,
                owned_embedding_name,
            );
            defer artifact_cleanup.deinit();
            const commit_mutation = try combineRemovalCatalogMutation(atomic_mutation, &artifact_cleanup);
            // All fallible cleanup planning is complete. Catalog absence and
            // marker deletion now commit immediately before runtime removal.
            try self.persistCatalogExcludingWithAtomicMutation(store, name, commit_mutation);
            self.alloc.free(self.status_only_index_configs);
            self.status_only_index_configs = replacement;
            replacement_owned = false;
            removed_owned = true;
            defer self.dropIndexLoadStateNoLock(name);

            self.storeGeneratedEnrichmentTargetCache(has_generated_enrichment_targets);
            self.clearAppliedSequenceAfterCatalogRemoval(store, name);
            self.invalidateIndexRootForName(name, index_path);
            return true;
        }
        return false;
    }

    pub fn requiresEnrichmentReplay(self: *const IndexManager, name: []const u8) !bool {
        for (self.dense_indexes.items) |entry| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            return try self.configRequiresEnrichmentReplay(entry.config);
        }
        for (self.sparse_indexes.items) |entry| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            return try self.configRequiresEnrichmentReplay(entry.config);
        }
        return false;
    }

    const ExcludedEnrichment = struct {
        kind: enrichment_catalog.EnrichmentType,
        name: []const u8,
    };

    fn computeGeneratedEnrichmentTargetCache(self: *const IndexManager) !bool {
        return try self.computeGeneratedEnrichmentTargetCacheExcluding(null, null);
    }

    fn computeGeneratedEnrichmentTargetCacheExcluding(
        self: *const IndexManager,
        excluded_index_name: ?[]const u8,
        excluded_enrichment: ?ExcludedEnrichment,
    ) !bool {
        for (self.dense_indexes.items) |entry| {
            if (excluded_index_name) |index_name| {
                if (std.mem.eql(u8, entry.config.name, index_name)) continue;
            }
            if (try parseDenseGeneratorConfig(self.alloc, entry.config.config_json)) |generator| {
                generator.deinit(self.alloc);
                return true;
            }
            if (entry.embedding_name) |embedding_name| {
                if (self.getEnrichmentExcluding(.embedding, embedding_name, excluded_enrichment) != null) return true;
            }
        }
        for (self.sparse_indexes.items) |entry| {
            if (excluded_index_name) |index_name| {
                if (std.mem.eql(u8, entry.config.name, index_name)) continue;
            }
            if (try parseSparseGeneratorConfig(self.alloc, entry.config.config_json)) |generator| {
                generator.deinit(self.alloc);
                return true;
            }
        }
        for (self.text_indexes.items) |entry| {
            if (excluded_index_name) |index_name| {
                if (std.mem.eql(u8, entry.config.name, index_name)) continue;
            }
            const chunk_name = entry.chunk_name orelse continue;
            const chunk_cfg = self.getEnrichmentExcluding(.chunk, chunk_name, excluded_enrichment) orelse continue;
            if (chunk_cfg.source_artifact_name.len == 0) return true;
        }
        for (self.enrichments.items) |entry| {
            if (excluded_enrichment) |skip| {
                if (entry.kind == skip.kind and std.mem.eql(u8, entry.name, skip.name)) continue;
            }
            if (entry.kind == .asset) return true;
        }
        return false;
    }

    fn refreshGeneratedEnrichmentTargetCache(self: *IndexManager) !void {
        self.storeGeneratedEnrichmentTargetCache(try self.computeGeneratedEnrichmentTargetCache());
    }

    fn storeGeneratedEnrichmentTargetCache(self: *IndexManager, value: bool) void {
        self.cached_has_generated_enrichment_targets.store(value, .release);
    }

    pub fn hasGeneratedEnrichmentTargets(self: *const IndexManager) bool {
        return self.cached_has_generated_enrichment_targets.load(.acquire);
    }

    pub fn has(self: *const IndexManager, name: []const u8) bool {
        return self.get(name) != null;
    }

    pub fn get(self: *const IndexManager, name: []const u8) ?*const types.IndexConfig {
        for (self.text_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return &entry.config;
        }
        for (self.dense_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return &entry.config;
        }
        for (self.sparse_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return &entry.config;
        }
        for (self.graph_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return &entry.config;
        }
        for (self.algebraic_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return &entry.config;
        }
        for (self.status_only_index_configs) |*cfg| {
            if (std.mem.eql(u8, cfg.name, name)) return cfg;
        }
        return null;
    }

    pub fn count(self: *const IndexManager) u32 {
        return @intCast(self.text_indexes.items.len + self.dense_indexes.items.len + self.sparse_indexes.items.len + self.graph_indexes.items.len + self.algebraic_indexes.items.len + self.status_only_index_configs.len);
    }

    pub fn listIndexesPublic(self: *const IndexManager, alloc: Allocator) ![]types.IndexConfig {
        const total = self.text_indexes.items.len + self.dense_indexes.items.len + self.sparse_indexes.items.len + self.graph_indexes.items.len + self.algebraic_indexes.items.len + self.status_only_index_configs.len;
        const out = try alloc.alloc(types.IndexConfig, total);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |*cfg| cfg.deinit(alloc);
            alloc.free(out);
        }

        for (self.text_indexes.items) |entry| {
            out[initialized] = try types.IndexConfig.clone(alloc, entry.config);
            initialized += 1;
        }
        for (self.dense_indexes.items) |entry| {
            out[initialized] = try types.IndexConfig.clone(alloc, entry.config);
            initialized += 1;
        }
        for (self.sparse_indexes.items) |entry| {
            out[initialized] = try types.IndexConfig.clone(alloc, entry.config);
            initialized += 1;
        }
        for (self.graph_indexes.items) |entry| {
            out[initialized] = try types.IndexConfig.clone(alloc, entry.config);
            initialized += 1;
        }
        for (self.algebraic_indexes.items) |entry| {
            out[initialized] = try types.IndexConfig.clone(alloc, entry.config);
            initialized += 1;
        }
        for (self.status_only_index_configs) |cfg| {
            out[initialized] = try types.IndexConfig.clone(alloc, cfg);
            initialized += 1;
        }

        return out;
    }

    pub fn hasManagedIndexes(self: *const IndexManager) bool {
        return self.text_indexes.items.len > 0 or self.dense_indexes.items.len > 0 or self.sparse_indexes.items.len > 0 or self.graph_indexes.items.len > 0 or self.algebraic_indexes.items.len > 0 or self.status_only_index_configs.len > 0;
    }

    pub fn managedIndexNames(self: *const IndexManager, alloc: Allocator) ![][]u8 {
        const total = self.text_indexes.items.len + self.dense_indexes.items.len + self.sparse_indexes.items.len + self.graph_indexes.items.len + self.algebraic_indexes.items.len + self.status_only_index_configs.len;
        var names = try alloc.alloc([]u8, total);
        var initialized: usize = 0;
        errdefer {
            for (names[0..initialized]) |name| alloc.free(name);
            alloc.free(names);
        }

        for (self.text_indexes.items) |entry| {
            names[initialized] = try alloc.dupe(u8, entry.config.name);
            initialized += 1;
        }
        for (self.dense_indexes.items) |entry| {
            names[initialized] = try alloc.dupe(u8, entry.config.name);
            initialized += 1;
        }
        for (self.sparse_indexes.items) |entry| {
            names[initialized] = try alloc.dupe(u8, entry.config.name);
            initialized += 1;
        }
        for (self.graph_indexes.items) |entry| {
            names[initialized] = try alloc.dupe(u8, entry.config.name);
            initialized += 1;
        }
        for (self.algebraic_indexes.items) |entry| {
            names[initialized] = try alloc.dupe(u8, entry.config.name);
            initialized += 1;
        }
        for (self.status_only_index_configs) |cfg| {
            names[initialized] = try alloc.dupe(u8, cfg.name);
            initialized += 1;
        }

        return names;
    }

    pub fn managedIndexes(self: *const IndexManager, alloc: Allocator) ![]ManagedIndexRef {
        var status_only_count: usize = 0;
        for (self.status_only_index_configs) |cfg| {
            if (self.loadFailure(cfg.name) == null) status_only_count += 1;
        }
        const total = self.text_indexes.items.len + self.dense_indexes.items.len + self.sparse_indexes.items.len + self.graph_indexes.items.len + self.algebraic_indexes.items.len + status_only_count;
        var refs = try alloc.alloc(ManagedIndexRef, total);
        var initialized: usize = 0;
        errdefer {
            for (refs[0..initialized]) |ref| alloc.free(@constCast(ref.name));
            alloc.free(refs);
        }

        for (self.text_indexes.items) |entry| {
            refs[initialized] = .{
                .name = try alloc.dupe(u8, entry.config.name),
                .kind = .full_text,
            };
            initialized += 1;
        }
        for (self.dense_indexes.items) |entry| {
            refs[initialized] = .{
                .name = try alloc.dupe(u8, entry.config.name),
                .kind = .dense_vector,
                .estimated_dense_vector_bytes = @as(u64, entry.dims) * @sizeOf(f32),
            };
            initialized += 1;
        }
        for (self.sparse_indexes.items) |entry| {
            refs[initialized] = .{
                .name = try alloc.dupe(u8, entry.config.name),
                .kind = .sparse_vector,
            };
            initialized += 1;
        }
        for (self.graph_indexes.items) |entry| {
            refs[initialized] = .{
                .name = try alloc.dupe(u8, entry.config.name),
                .kind = .graph,
            };
            initialized += 1;
        }
        for (self.algebraic_indexes.items) |entry| {
            refs[initialized] = .{
                .name = try alloc.dupe(u8, entry.config.name),
                .kind = .algebraic,
            };
            initialized += 1;
        }
        for (self.status_only_index_configs) |cfg| {
            // Quarantined indexes (config retained after a load failure) have
            // no runtime; replay/apply/maintenance work driven off this list
            // must skip them or it would fail with IndexNotFound.
            if (self.loadFailure(cfg.name) != null) continue;
            refs[initialized] = .{
                .name = try alloc.dupe(u8, cfg.name),
                .kind = cfg.kind,
            };
            initialized += 1;
        }

        return refs;
    }

    pub fn getEnrichment(self: *const IndexManager, kind: enrichment_catalog.EnrichmentType, name: []const u8) ?*const enrichment_catalog.EnrichmentConfig {
        return self.getEnrichmentExcluding(kind, name, null);
    }

    fn getEnrichmentByName(self: *const IndexManager, name: []const u8) ?*const enrichment_catalog.EnrichmentConfig {
        for (self.enrichments.items) |*entry| {
            if (std.mem.eql(u8, entry.name, name)) return entry;
        }
        return null;
    }

    fn getEnrichmentExcluding(
        self: *const IndexManager,
        kind: enrichment_catalog.EnrichmentType,
        name: []const u8,
        excluded: ?ExcludedEnrichment,
    ) ?*const enrichment_catalog.EnrichmentConfig {
        for (self.enrichments.items) |*entry| {
            if (excluded) |skip| {
                if (entry.kind == skip.kind and std.mem.eql(u8, entry.name, skip.name)) continue;
            }
            if (entry.kind == kind and std.mem.eql(u8, entry.name, name)) return entry;
        }
        return null;
    }

    pub fn getEnrichmentPublic(self: *const IndexManager, alloc: Allocator, kind: types.EnrichmentKind, name: []const u8) !?types.EnrichmentConfig {
        const internal_kind = publicEnrichmentKindToInternal(kind);
        const cfg = self.getEnrichment(internal_kind, name) orelse return null;
        return try enrichmentToPublic(alloc, cfg.*);
    }

    pub fn listEnrichmentsPublic(self: *const IndexManager, alloc: Allocator) ![]types.EnrichmentConfig {
        const out = try alloc.alloc(types.EnrichmentConfig, self.enrichments.items.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |*cfg| cfg.deinit(alloc);
            if (out.len > 0) alloc.free(out);
        }

        for (self.enrichments.items, 0..) |cfg, i| {
            out[i] = try enrichmentToPublic(alloc, cfg);
            initialized += 1;
        }
        return out;
    }

    pub fn planGeneratedEnrichments(
        self: *const IndexManager,
        alloc: Allocator,
        doc_key: []const u8,
        doc_value: []const u8,
        explicit_dense: []const mapper.DenseEmbeddingWrite,
        explicit_sparse: []const mapper.SparseEmbeddingWrite,
    ) ![]enrichment_types.GeneratedEnrichmentRequest {
        var requests = std.ArrayListUnmanaged(enrichment_types.GeneratedEnrichmentRequest).empty;
        errdefer {
            for (requests.items) |request| enrichment_types.freeGeneratedRequest(alloc, request);
            requests.deinit(alloc);
        }

        for (self.enrichments.items) |entry| {
            if (entry.kind != .asset) continue;
            try requests.append(alloc, .{
                .kind = .asset,
                .index_name = try alloc.dupe(u8, entry.name),
                .artifact_name = try alloc.dupe(u8, entry.name),
                .doc_key = try alloc.dupe(u8, doc_key),
                .source_field = try alloc.dupe(u8, entry.source_field),
                .source_template = if (entry.source_template.len > 0) try alloc.dupe(u8, entry.source_template) else "",
                .full_text_index = entry.full_text_index,
                .content_type = if (entry.content_type.len > 0) try alloc.dupe(u8, entry.content_type) else "",
                .producer_json = if (entry.producer_json.len > 0) try alloc.dupe(u8, entry.producer_json) else "",
                .execution_json = if (entry.execution_json.len > 0) try alloc.dupe(u8, entry.execution_json) else "",
            });
        }

        for (self.text_indexes.items) |entry| {
            const chunk_name = entry.chunk_name orelse continue;
            const chunk_cfg = self.getEnrichment(.chunk, chunk_name) orelse continue;
            if (chunk_cfg.source_artifact_name.len > 0) continue;
            if (!hasGeneratedChunkRequest(requests.items, doc_key, chunk_cfg.source_field, chunk_cfg.source_template, chunk_cfg.name)) {
                try requests.append(alloc, .{
                    .kind = .chunk_text,
                    .index_name = try alloc.dupe(u8, entry.config.name),
                    .artifact_name = try alloc.dupe(u8, chunk_cfg.name),
                    .doc_key = try alloc.dupe(u8, doc_key),
                    .source_field = try alloc.dupe(u8, chunk_cfg.source_field),
                    .source_template = if (chunk_cfg.source_template.len > 0) try alloc.dupe(u8, chunk_cfg.source_template) else "",
                    .chunk_size = chunk_cfg.chunk_size,
                    .chunk_overlap = chunk_cfg.chunk_overlap,
                    .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                    .full_text_index = true,
                    .execution_json = if (chunk_cfg.execution_json.len > 0) try alloc.dupe(u8, chunk_cfg.execution_json) else "",
                });
            }
        }

        for (self.dense_indexes.items) |entry| {
            if (hasExplicitDenseEmbedding(explicit_dense, entry.config.name)) continue;
            if (try mapper.extractDenseVectorField(alloc, doc_value, entry.field_name, entry.dims)) |vector| {
                alloc.free(vector);
                continue;
            }

            if (try parseDenseGeneratorConfig(alloc, entry.config.config_json)) |generator| {
                defer generator.deinit(alloc);
                const chunk_cfg = resolveChunkGenerator(self, generator);
                const embedding_name = entry.embedding_name orelse entry.config.name;
                if (generatorHasChunking(chunk_cfg) and !hasGeneratedChunkRequest(requests.items, doc_key, chunk_cfg.source_field, chunk_cfg.source_template, chunk_cfg.artifact_name)) {
                    try requests.append(alloc, .{
                        .kind = .chunk_text,
                        .index_name = try alloc.dupe(u8, entry.config.name),
                        .artifact_name = try alloc.dupe(u8, chunk_cfg.artifact_name),
                        .doc_key = try alloc.dupe(u8, doc_key),
                        .source_field = try alloc.dupe(u8, chunk_cfg.source_field),
                        .source_template = if (chunk_cfg.source_template.len > 0) try alloc.dupe(u8, chunk_cfg.source_template) else "",
                        .chunk_size = chunk_cfg.chunk_size,
                        .chunk_overlap = chunk_cfg.chunk_overlap,
                        .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                        .full_text_index = chunk_cfg.full_text_index,
                        .execution_json = if (chunk_cfg.chunking_execution_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunking_execution_json) else "",
                    });
                }
                if (!hasGeneratedDenseEmbeddingRequest(requests.items, doc_key, chunk_cfg.source_field, chunk_cfg.source_template, chunk_cfg.artifact_name, embedding_name)) {
                    try requests.append(alloc, .{
                        .kind = .dense_embedding,
                        .index_name = try alloc.dupe(u8, entry.config.name),
                        .artifact_name = try alloc.dupe(u8, chunk_cfg.artifact_name),
                        .embedding_name = try alloc.dupe(u8, embedding_name),
                        .doc_key = try alloc.dupe(u8, doc_key),
                        .source_field = try alloc.dupe(u8, chunk_cfg.source_field),
                        .source_template = if (chunk_cfg.source_template.len > 0) try alloc.dupe(u8, chunk_cfg.source_template) else "",
                        .expected_dims = entry.dims,
                        .chunk_size = chunk_cfg.chunk_size,
                        .chunk_overlap = chunk_cfg.chunk_overlap,
                        .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                        .full_text_index = chunk_cfg.full_text_index,
                        .execution_json = if (chunk_cfg.embedding_execution_json.len > 0) try alloc.dupe(u8, chunk_cfg.embedding_execution_json) else "",
                    });
                }
            } else if (entry.embedding_name) |embedding_name| {
                const embedding_cfg = self.getEnrichment(.embedding, embedding_name) orelse continue;
                if (embedding_cfg.expected_dims > 0 and embedding_cfg.expected_dims != entry.dims) continue;
                if (embedding_cfg.source_artifact_name.len > 0) {
                    const chunk_cfg = self.getEnrichment(.chunk, embedding_cfg.source_artifact_name) orelse return error.InvalidIndexConfig;
                    if (chunk_cfg.source_artifact_name.len == 0 and !hasGeneratedChunkRequest(requests.items, doc_key, chunk_cfg.source_field, chunk_cfg.source_template, chunk_cfg.name)) {
                        try requests.append(alloc, .{
                            .kind = .chunk_text,
                            .index_name = try alloc.dupe(u8, entry.config.name),
                            .artifact_name = try alloc.dupe(u8, chunk_cfg.name),
                            .doc_key = try alloc.dupe(u8, doc_key),
                            .source_field = try alloc.dupe(u8, chunk_cfg.source_field),
                            .source_template = if (chunk_cfg.source_template.len > 0) try alloc.dupe(u8, chunk_cfg.source_template) else "",
                            .chunk_size = chunk_cfg.chunk_size,
                            .chunk_overlap = chunk_cfg.chunk_overlap,
                            .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                            .full_text_index = chunk_cfg.full_text_index,
                            .execution_json = if (chunk_cfg.execution_json.len > 0) try alloc.dupe(u8, chunk_cfg.execution_json) else "",
                        });
                    }
                    if (!hasGeneratedDenseEmbeddingRequest(requests.items, doc_key, embedding_cfg.source_field, embedding_cfg.source_template, chunk_cfg.name, embedding_name)) {
                        try requests.append(alloc, .{
                            .kind = .dense_embedding,
                            .index_name = try alloc.dupe(u8, entry.config.name),
                            .artifact_name = try alloc.dupe(u8, chunk_cfg.name),
                            .embedding_name = try alloc.dupe(u8, embedding_name),
                            .doc_key = try alloc.dupe(u8, doc_key),
                            .source_field = try alloc.dupe(u8, embedding_cfg.source_field),
                            .source_template = if (embedding_cfg.source_template.len > 0) try alloc.dupe(u8, embedding_cfg.source_template) else "",
                            .expected_dims = entry.dims,
                            .chunk_size = chunk_cfg.chunk_size,
                            .chunk_overlap = chunk_cfg.chunk_overlap,
                            .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                            .full_text_index = chunk_cfg.full_text_index,
                            .execution_json = if (embedding_cfg.execution_json.len > 0) try alloc.dupe(u8, embedding_cfg.execution_json) else "",
                        });
                    }
                } else {
                    if (!hasGeneratedDenseEmbeddingRequest(requests.items, doc_key, embedding_cfg.source_field, embedding_cfg.source_template, "", embedding_name)) {
                        try requests.append(alloc, .{
                            .kind = .dense_embedding,
                            .index_name = try alloc.dupe(u8, entry.config.name),
                            .artifact_name = "",
                            .embedding_name = try alloc.dupe(u8, embedding_name),
                            .doc_key = try alloc.dupe(u8, doc_key),
                            .source_field = try alloc.dupe(u8, embedding_cfg.source_field),
                            .source_template = if (embedding_cfg.source_template.len > 0) try alloc.dupe(u8, embedding_cfg.source_template) else "",
                            .expected_dims = entry.dims,
                            .execution_json = if (embedding_cfg.execution_json.len > 0) try alloc.dupe(u8, embedding_cfg.execution_json) else "",
                        });
                    }
                }
            }
        }

        for (self.sparse_indexes.items) |entry| {
            if (hasExplicitSparseEmbedding(explicit_sparse, entry.config.name)) continue;
            if (try mapper.extractSparseVectorField(alloc, doc_value, entry.field_name)) |sparse_vec| {
                var vec = sparse_vec;
                vec.deinit(alloc);
                continue;
            }

            if (try parseSparseGeneratorConfig(alloc, entry.config.config_json)) |generator| {
                defer generator.deinit(alloc);
                const chunk_cfg = resolveChunkGenerator(self, generator);
                if (generatorHasChunking(chunk_cfg) and !hasGeneratedChunkRequest(requests.items, doc_key, chunk_cfg.source_field, chunk_cfg.source_template, chunk_cfg.artifact_name)) {
                    try requests.append(alloc, .{
                        .kind = .chunk_text,
                        .index_name = try alloc.dupe(u8, entry.config.name),
                        .artifact_name = try alloc.dupe(u8, chunk_cfg.artifact_name),
                        .doc_key = try alloc.dupe(u8, doc_key),
                        .source_field = try alloc.dupe(u8, chunk_cfg.source_field),
                        .source_template = if (chunk_cfg.source_template.len > 0) try alloc.dupe(u8, chunk_cfg.source_template) else "",
                        .chunk_size = chunk_cfg.chunk_size,
                        .chunk_overlap = chunk_cfg.chunk_overlap,
                        .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                        .full_text_index = chunk_cfg.full_text_index,
                        .execution_json = if (chunk_cfg.chunking_execution_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunking_execution_json) else "",
                    });
                }
                try requests.append(alloc, .{
                    .kind = .sparse_embedding,
                    .index_name = try alloc.dupe(u8, entry.config.name),
                    .artifact_name = try alloc.dupe(u8, chunk_cfg.artifact_name),
                    .embedding_name = if (chunk_cfg.embedding_name) |embedding_name| try alloc.dupe(u8, embedding_name) else try alloc.dupe(u8, entry.config.name),
                    .doc_key = try alloc.dupe(u8, doc_key),
                    .source_field = try alloc.dupe(u8, chunk_cfg.source_field),
                    .source_template = if (chunk_cfg.source_template.len > 0) try alloc.dupe(u8, chunk_cfg.source_template) else "",
                    .chunk_size = chunk_cfg.chunk_size,
                    .chunk_overlap = chunk_cfg.chunk_overlap,
                    .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                    .full_text_index = chunk_cfg.full_text_index,
                    .execution_json = if (chunk_cfg.embedding_execution_json.len > 0) try alloc.dupe(u8, chunk_cfg.embedding_execution_json) else "",
                });
            } else if (entry.embedding_name) |embedding_name| {
                const embedding_cfg = self.getEnrichment(.embedding, embedding_name) orelse continue;
                if (embedding_cfg.expected_dims != 0) continue;
                if (embedding_cfg.source_artifact_name.len > 0) {
                    const chunk_cfg = self.getEnrichment(.chunk, embedding_cfg.source_artifact_name) orelse return error.InvalidIndexConfig;
                    if (chunk_cfg.source_artifact_name.len == 0 and !hasGeneratedChunkRequest(requests.items, doc_key, chunk_cfg.source_field, chunk_cfg.source_template, chunk_cfg.name)) {
                        try requests.append(alloc, .{
                            .kind = .chunk_text,
                            .index_name = try alloc.dupe(u8, entry.config.name),
                            .artifact_name = try alloc.dupe(u8, chunk_cfg.name),
                            .doc_key = try alloc.dupe(u8, doc_key),
                            .source_field = try alloc.dupe(u8, chunk_cfg.source_field),
                            .source_template = if (chunk_cfg.source_template.len > 0) try alloc.dupe(u8, chunk_cfg.source_template) else "",
                            .chunk_size = chunk_cfg.chunk_size,
                            .chunk_overlap = chunk_cfg.chunk_overlap,
                            .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                            .full_text_index = chunk_cfg.full_text_index,
                            .execution_json = if (chunk_cfg.execution_json.len > 0) try alloc.dupe(u8, chunk_cfg.execution_json) else "",
                        });
                    }
                    if (!hasGeneratedSparseEmbeddingRequest(requests.items, doc_key, embedding_cfg.source_field, embedding_cfg.source_template, chunk_cfg.name, embedding_name)) {
                        try requests.append(alloc, .{
                            .kind = .sparse_embedding,
                            .index_name = try alloc.dupe(u8, entry.config.name),
                            .artifact_name = try alloc.dupe(u8, chunk_cfg.name),
                            .embedding_name = try alloc.dupe(u8, embedding_name),
                            .doc_key = try alloc.dupe(u8, doc_key),
                            .source_field = try alloc.dupe(u8, embedding_cfg.source_field),
                            .source_template = if (embedding_cfg.source_template.len > 0) try alloc.dupe(u8, embedding_cfg.source_template) else "",
                            .chunk_size = chunk_cfg.chunk_size,
                            .chunk_overlap = chunk_cfg.chunk_overlap,
                            .chunker_json = if (chunk_cfg.chunker_json.len > 0) try alloc.dupe(u8, chunk_cfg.chunker_json) else "",
                            .full_text_index = chunk_cfg.full_text_index,
                            .execution_json = if (embedding_cfg.execution_json.len > 0) try alloc.dupe(u8, embedding_cfg.execution_json) else "",
                        });
                    }
                } else if (!hasGeneratedSparseEmbeddingRequest(requests.items, doc_key, embedding_cfg.source_field, embedding_cfg.source_template, "", embedding_name)) {
                    try requests.append(alloc, .{
                        .kind = .sparse_embedding,
                        .index_name = try alloc.dupe(u8, entry.config.name),
                        .artifact_name = "",
                        .embedding_name = try alloc.dupe(u8, embedding_name),
                        .doc_key = try alloc.dupe(u8, doc_key),
                        .source_field = try alloc.dupe(u8, embedding_cfg.source_field),
                        .source_template = if (embedding_cfg.source_template.len > 0) try alloc.dupe(u8, embedding_cfg.source_template) else "",
                        .execution_json = if (embedding_cfg.execution_json.len > 0) try alloc.dupe(u8, embedding_cfg.execution_json) else "",
                    });
                }
            }
        }

        return try requests.toOwnedSlice(alloc);
    }

    pub fn appendIndexFieldEmbeddingsToExtractedWrite(
        self: *const IndexManager,
        alloc: Allocator,
        doc_key: []const u8,
        doc_value: []const u8,
        extracted: *mapper.ExtractedWrite,
    ) !void {
        for (self.dense_indexes.items) |entry| {
            if (hasExplicitDenseEmbedding(extracted.dense_embeddings, entry.config.name)) continue;
            const vector = (try mapper.extractDenseVectorField(alloc, doc_value, entry.field_name, entry.dims)) orelse continue;
            var vector_owned = true;
            errdefer if (vector_owned) alloc.free(vector);
            var index_name = try alloc.dupe(u8, entry.config.name);
            errdefer if (index_name.len > 0) alloc.free(index_name);
            var owned_doc_key = try alloc.dupe(u8, doc_key);
            errdefer if (owned_doc_key.len > 0) alloc.free(owned_doc_key);
            try appendDenseEmbeddingToExtractedWrite(alloc, extracted, .{
                .index_name = index_name,
                .doc_key = owned_doc_key,
                .vector = vector,
            });
            index_name = &.{};
            owned_doc_key = &.{};
            vector_owned = false;
        }

        for (self.sparse_indexes.items) |entry| {
            if (hasExplicitSparseEmbedding(extracted.sparse_embeddings, entry.config.name)) continue;
            var sparse_vec = (try mapper.extractSparseVectorField(alloc, doc_value, entry.field_name)) orelse continue;
            errdefer sparse_vec.deinit(alloc);
            var index_name = try alloc.dupe(u8, entry.config.name);
            errdefer if (index_name.len > 0) alloc.free(index_name);
            var owned_doc_key = try alloc.dupe(u8, doc_key);
            errdefer if (owned_doc_key.len > 0) alloc.free(owned_doc_key);
            try appendSparseEmbeddingToExtractedWrite(alloc, extracted, .{
                .index_name = index_name,
                .doc_key = owned_doc_key,
                .indices = sparse_vec.indices,
                .values = sparse_vec.values,
            });
            index_name = &.{};
            owned_doc_key = &.{};
            sparse_vec.indices = &.{};
            sparse_vec.values = &.{};
        }
    }

    pub fn vectorStoreFieldNamesAlloc(self: *const IndexManager, alloc: Allocator) ![][]u8 {
        var fields = std.ArrayListUnmanaged([]u8).empty;
        errdefer {
            for (fields.items) |field| alloc.free(field);
            fields.deinit(alloc);
        }

        for (self.dense_indexes.items) |entry| {
            if (entry.external or entry.chunk_name != null or entry.embedding_name != null) continue;
            if (containsOwnedString(fields.items, entry.field_name)) continue;
            try fields.append(alloc, try alloc.dupe(u8, entry.field_name));
        }
        for (self.sparse_indexes.items) |entry| {
            if (try parseSparseGeneratorConfig(alloc, entry.config.config_json)) |generator| {
                generator.deinit(alloc);
                continue;
            }
            if (containsOwnedString(fields.items, entry.field_name)) continue;
            try fields.append(alloc, try alloc.dupe(u8, entry.field_name));
        }
        return try fields.toOwnedSlice(alloc);
    }

    pub fn textIndex(self: *IndexManager, name: ?[]const u8) ?*persistent_mod.PersistentIndex {
        if (name) |index_name| {
            for (self.text_indexes.items) |*entry| {
                if (std.mem.eql(u8, entry.config.name, index_name)) return &entry.persistent;
            }
            return null;
        }

        if (self.text_indexes.items.len == 1) return &self.text_indexes.items[0].persistent;
        return null;
    }

    pub fn textIndexEntry(self: *IndexManager, name: ?[]const u8) ?*TextIndex {
        if (name) |index_name| {
            for (self.text_indexes.items) |*entry| {
                if (std.mem.eql(u8, entry.config.name, index_name)) return entry;
            }
            return null;
        }

        if (self.text_indexes.items.len == 1) return &self.text_indexes.items[0];
        return null;
    }

    pub fn acquireTextQueryLease(
        self: *IndexManager,
        alloc: Allocator,
        name: ?[]const u8,
        fields: []const []const u8,
    ) !?TextQueryLease {
        self.catalog_mutex.lockShared();
        defer self.catalog_mutex.unlockShared();

        const entry = self.textIndexEntry(name) orelse return null;
        entry.analysis_mutex.lockShared();
        defer entry.analysis_mutex.unlockShared();
        const snapshot = entry.persistent.acquireSnapshot();
        errdefer snapshot.release();

        const analyzers = try alloc.alloc(OwnedFieldAnalyzer, fields.len);
        var initialized: usize = 0;
        errdefer {
            for (analyzers[0..initialized]) |*item| item.deinit(alloc);
            alloc.free(analyzers);
        }
        for (fields, 0..) |field, i| {
            const analyzer_name = textFieldAnalyzerName(entry, field) orelse return error.InvalidIndexConfig;
            const analyzer = introducer_mod.resolveAnalyzerName(analyzer_name, entry.text_analysis) orelse
                return error.InvalidIndexConfig;
            analyzers[i] = try OwnedFieldAnalyzer.init(alloc, field, analyzer);
            initialized += 1;
        }
        return .{
            .alloc = alloc,
            .snapshot = snapshot,
            .analyzers = analyzers,
        };
    }

    pub fn observedDynamicFieldCapabilitiesAlloc(
        self: *IndexManager,
        alloc: Allocator,
        name: ?[]const u8,
    ) ![]schema_mod.FieldCapability {
        const entry = self.textIndexEntry(name) orelse return &.{};
        entry.analysis_mutex.lockShared();
        defer entry.analysis_mutex.unlockShared();
        return try self.observedDynamicFieldCapabilitiesLockedAlloc(alloc, entry, .{
            .index_name = name,
            .coverage_read_mode = .validate,
        });
    }

    fn observedDynamicFieldCapabilitiesLockedAlloc(
        self: *IndexManager,
        alloc: Allocator,
        entry: *IndexManager.TextIndex,
        observation: dynamic_field_capability.ObservationQuery,
    ) ![]schema_mod.FieldCapability {
        _ = self;
        const capability_count = observedDynamicFieldCapabilityCount(entry, observation);
        if (capability_count == 0) return &.{};

        const capabilities = try alloc.alloc(schema_mod.FieldCapability, capability_count);
        var initialized: usize = 0;
        errdefer {
            for (capabilities[0..initialized]) |item| schema_mod.freeOwnedFieldCapability(alloc, item);
            alloc.free(capabilities);
        }
        for (entry.observed_field_analyzers) |item| {
            if (!observation.includesField(item.field_name)) continue;
            var capability = schema_mod.observedDynamicFieldCapability(entry.runtime_schema, item.field_name, item.mapping());
            if (schema_mod.mappingHasNativeDocValues(item.mapping())) {
                if (try observedDynamicFieldTypedDocValueCoverageStatus(entry, item.field_name, item.mapping(), observation)) |coverage| {
                    if (coverage == .covered) {
                        capability.doc_value_coverage = "covered";
                        capability.queryability_state = "queryable";
                    } else {
                        capability.doc_value_coverage = typed_dv_coverage.statusName(coverage);
                        capability.queryability_state = "missing_doc_values";
                    }
                }
            }
            schema_mod.refreshSortLifecycleState(&capability);
            capabilities[initialized] = try schema_mod.cloneFieldCapabilityAlloc(
                alloc,
                capability,
            );
            initialized += 1;
        }
        if (entry.runtime_schema) |schema| {
            for (schema.exact_fields) |field| {
                if (!schema_mod.mappingHasNativeDocValues(field.mapping)) continue;
                if (!observation.includesField(field.field)) continue;
                var capability = schema_mod.exactFieldCapability(schema, field);
                if (try observedDynamicFieldTypedDocValueCoverageStatus(entry, field.field, field.mapping, observation)) |coverage| {
                    if (coverage == .covered) {
                        capability.doc_value_coverage = "covered";
                        capability.queryability_state = "queryable";
                    } else {
                        capability.doc_value_coverage = typed_dv_coverage.statusName(coverage);
                        capability.queryability_state = "missing_doc_values";
                    }
                }
                schema_mod.refreshSortLifecycleState(&capability);
                capabilities[initialized] = try schema_mod.cloneFieldCapabilityAlloc(alloc, capability);
                initialized += 1;
            }
            for (schema.dynamic_templates) |template| {
                const field = schema_mod.exactDynamicTemplatePath(template) orelse continue;
                if (!schema_mod.mappingHasNativeDocValues(template.mapping)) continue;
                if (!observation.includesField(field)) continue;
                var capability = schema_mod.dynamicTemplateFieldCapability(schema, template);
                if (try observedDynamicFieldTypedDocValueCoverageStatus(entry, field, template.mapping, observation)) |coverage| {
                    if (coverage == .covered) {
                        capability.doc_value_coverage = "covered";
                        capability.queryability_state = "queryable";
                    } else {
                        capability.doc_value_coverage = typed_dv_coverage.statusName(coverage);
                        capability.queryability_state = "missing_doc_values";
                    }
                }
                schema_mod.refreshSortLifecycleState(&capability);
                capabilities[initialized] = try schema_mod.cloneFieldCapabilityAlloc(alloc, capability);
                initialized += 1;
            }
        }
        std.debug.assert(initialized == capability_count);
        return capabilities;
    }

    fn observedDynamicFieldCapabilityCount(
        entry: *TextIndex,
        observation: dynamic_field_capability.ObservationQuery,
    ) usize {
        var capability_count: usize = 0;
        for (entry.observed_field_analyzers) |item| {
            if (observation.includesField(item.field_name)) capability_count += 1;
        }
        const schema = entry.runtime_schema orelse return capability_count;
        for (schema.exact_fields) |field| {
            if (!schema_mod.mappingHasNativeDocValues(field.mapping)) continue;
            if (!observation.includesField(field.field)) continue;
            capability_count += 1;
        }
        for (schema.dynamic_templates) |template| {
            const field = schema_mod.exactDynamicTemplatePath(template) orelse continue;
            if (!schema_mod.mappingHasNativeDocValues(template.mapping)) continue;
            if (!observation.includesField(field)) continue;
            capability_count += 1;
        }
        return capability_count;
    }

    fn observedDynamicFieldTypedDocValueCoverageStatus(
        entry: *IndexManager.TextIndex,
        field: []const u8,
        mapping: schema_mod.FieldMapping,
        observation: dynamic_field_capability.ObservationQuery,
    ) !?typed_dv_coverage.Status {
        try observation.checkActive();
        if (!schema_mod.mappingHasNativeDocValues(mapping)) return .missing_doc_values_section;
        const snapshot = entry.persistent.snapshot();
        if (snapshot.liveDocCount() == 0) return .covered;

        var has_uninitialized_coverage = false;
        for (snapshot.segments) |*segment| {
            if (segment.liveDocCount() == 0) continue;
            const coverage = switch (observation.coverage_read_mode) {
                .validate => (try segment.typedDocValuesCoverageWithValidation(field, .{
                    .execution_deadline_ns = observation.execution_deadline_ns,
                    .cancellation = observation.cancellation,
                })) orelse return .missing_doc_values_section,
                .cached_only => switch (segment.cachedTypedDocValuesCoverage(field)) {
                    .missing => return .missing_doc_values_section,
                    .uninitialized => {
                        has_uninitialized_coverage = true;
                        continue;
                    },
                    .initialized => |coverage| coverage,
                },
            };
            const value_type = coverage.value_type orelse return coverage.status;
            if (!typedDocValueReaderMatchesMapping(value_type, mapping)) return .doc_values_kind_mismatch;
            if (coverage.status != .covered) return coverage.status;
        }
        return if (has_uninitialized_coverage) null else .covered;
    }

    fn typedDocValueReaderMatchesMapping(value_type: typed_dv.ValueType, mapping: schema_mod.FieldMapping) bool {
        return switch (mapping.field_type) {
            .datetime => value_type == .u64_val,
            .numeric => switch (value_type) {
                .u64_val, .i64_val, .f64_val, .numeric_val => true,
                else => false,
            },
            .boolean => value_type == .bool_val,
            .keyword, .link => value_type == .bytes_val,
            .geopoint => value_type == .geo_point,
            else => false,
        };
    }

    pub fn observedDynamicFieldCapabilitySetsAlloc(
        self: *IndexManager,
        alloc: Allocator,
        observation: dynamic_field_capability.ObservationQuery,
    ) ![]ObservedDynamicFieldCapabilitySet {
        try observation.checkActive();
        const locked_entries = try alloc.alloc(*TextIndex, self.text_indexes.items.len);
        defer alloc.free(locked_entries);
        var locked_count: usize = 0;
        var cleanup_partial_locks = true;
        errdefer if (cleanup_partial_locks) {
            while (locked_count > 0) {
                locked_count -= 1;
                locked_entries[locked_count].analysis_mutex.unlockShared();
            }
        };
        for (self.text_indexes.items) |*entry| {
            if (observation.index_name) |name| {
                if (!std.mem.eql(u8, entry.config.name, name)) continue;
            }
            if (observation.execution_deadline_ns != null or observation.cancellation != null) {
                if (!entry.analysis_mutex.tryLockShared()) return error.StorageReadTemporarilyUnavailable;
            } else {
                entry.analysis_mutex.lockShared();
            }
            locked_entries[locked_count] = entry;
            locked_count += 1;
        }
        cleanup_partial_locks = false;
        defer {
            while (locked_count > 0) {
                locked_count -= 1;
                locked_entries[locked_count].analysis_mutex.unlockShared();
            }
        }
        try observation.checkActive();
        var set_count: usize = 0;
        for (self.text_indexes.items) |*entry| {
            try observation.checkActive();
            if (observation.index_name) |name| {
                if (!std.mem.eql(u8, entry.config.name, name)) continue;
            }
            if (observedDynamicFieldCapabilityCount(entry, observation) > 0) set_count += 1;
        }
        if (set_count == 0) return &.{};

        const sets = try alloc.alloc(ObservedDynamicFieldCapabilitySet, set_count);
        var initialized: usize = 0;
        errdefer {
            for (sets[0..initialized]) |*set| set.deinit(alloc);
            alloc.free(sets);
        }

        for (self.text_indexes.items) |*entry| {
            if (observation.index_name) |name| {
                if (!std.mem.eql(u8, entry.config.name, name)) continue;
            }
            if (observedDynamicFieldCapabilityCount(entry, observation) == 0) continue;
            sets[initialized] = blk: {
                const index_name = try alloc.dupe(u8, entry.config.name);
                errdefer alloc.free(index_name);
                const field_capabilities = try self.observedDynamicFieldCapabilitiesLockedAlloc(alloc, entry, observation);
                break :blk .{
                    .index_name = index_name,
                    .field_capabilities = field_capabilities,
                };
            };
            initialized += 1;
        }
        return sets;
    }

    pub fn fullTextLexicalAccessPath(self: *IndexManager, name: ?[]const u8, field: []const u8, analyzer: []const u8) ?algebraic_mod.ir.PhysicalAccessPath {
        const entry = self.textIndexEntry(name) orelse return null;
        entry.analysis_mutex.lockShared();
        defer entry.analysis_mutex.unlockShared();
        if (!textFieldAnalyzerMatches(entry, field, analyzer)) return null;
        const identity = algebraic_mod.lexical.DictionaryIdentity.analyzedText(entry.config.name, field, analyzer);
        return algebraic_mod.ir.lexicalAccessPath(entry.config.name, .full_text_postings, identity, true);
    }

    pub fn planFullTextLexicalAccessPathAlloc(
        self: *IndexManager,
        alloc: Allocator,
        name: ?[]const u8,
        field: []const u8,
        analyzer: ?[]const u8,
        fragment: algebraic_mod.ir.TensorFragment,
    ) !?algebraic_mod.ir.AccessPathPlan {
        const entry = self.textIndexEntry(name) orelse return null;
        entry.analysis_mutex.lockShared();
        defer entry.analysis_mutex.unlockShared();
        const resolved_analyzer = if (analyzer) |explicit| blk: {
            if (!textFieldAnalyzerMatches(entry, field, explicit)) return null;
            break :blk explicit;
        } else textFieldAnalyzerName(entry, field) orelse return null;
        return try self.planTypedAccessPathAlloc(alloc, .{
            .fragment = fragment,
            .layout = .full_text_postings,
            .output_dims = &.{.doc},
            .owner = entry.config.name,
            .dictionary = algebraic_mod.lexical.DictionaryIdentity.analyzedText(entry.config.name, field, resolved_analyzer),
        });
    }

    fn textFieldAnalyzerName(entry: *const TextIndex, field: []const u8) ?[]const u8 {
        var resolved: ?[]const u8 = null;
        for (entry.text_analysis.field_analyzers) |item| {
            if (!std.mem.eql(u8, item.field_name, field)) continue;
            if (resolved == null) {
                resolved = item.analyzer_name;
            } else if (!std.mem.eql(u8, resolved.?, item.analyzer_name)) {
                return null;
            }
        }
        return resolved orelse "standard";
    }

    fn textFieldAnalyzerMatches(entry: *const TextIndex, field: []const u8, analyzer: []const u8) bool {
        var saw_field = false;
        for (entry.text_analysis.field_analyzers) |item| {
            if (!std.mem.eql(u8, item.field_name, field)) continue;
            saw_field = true;
            if (std.mem.eql(u8, item.analyzer_name, analyzer)) return true;
        }
        return !saw_field and std.mem.eql(u8, analyzer, "standard");
    }

    pub fn handoffRightOnlyTextSegmentsFrom(self: *IndexManager, src: *IndexManager, split_key: []const u8, collect_skip_doc_keys: bool) ![]TextSplitHandoff {
        var handoffs = try self.alloc.alloc(TextSplitHandoff, self.text_indexes.items.len);
        errdefer {
            for (handoffs) |*handoff| {
                if (handoff.index_name.len > 0) handoff.deinit(self.alloc);
            }
            self.alloc.free(handoffs);
        }
        for (handoffs) |*handoff| {
            handoff.* = .{
                .index_name = &.{},
                .skip_doc_keys = .empty,
                .transferred_segments = 0,
            };
        }

        for (self.text_indexes.items, 0..) |*dest_entry, i| {
            handoffs[i].index_name = try self.alloc.dupe(u8, dest_entry.config.name);
            const src_entry = src.findTextIndexEntry(dest_entry.config.name) orelse continue;
            const result = try src_entry.persistent.handoffRightOnlySegmentsToChildDetailed(&dest_entry.persistent, split_key, self.alloc, collect_skip_doc_keys);
            defer self.alloc.free(result.doc_keys);

            handoffs[i].transferred_segments += result.transferred_segments;
            if (collect_skip_doc_keys) {
                try mergeHandoffDocKeys(self.alloc, &handoffs[i], result.doc_keys);
            }

            const plan = try src_entry.persistent.classifyActiveSegmentsForSplit(self.alloc, split_key);
            defer {
                for (plan) |*entry| entry.deinit(self.alloc);
                self.alloc.free(plan);
            }

            for (plan) |entry| {
                if (entry.class != .mixed) continue;

                var stored_segment = try src_entry.persistent.readStoredSegment(self.alloc, entry.seg_id);
                defer stored_segment.deinit(self.alloc);

                var rebuilt = try buildSplitSegment(
                    self.alloc,
                    stored_segment.segment_bytes,
                    stored_segment.deletion_bitmap_bytes,
                    split_key,
                    .right,
                    dest_entry.config.config_json,
                    collect_skip_doc_keys,
                );
                defer if (rebuilt.segment_bytes) |segment_bytes| self.alloc.free(segment_bytes);
                defer self.alloc.free(rebuilt.doc_keys);
                if (rebuilt.segment_bytes) |segment_bytes| {
                    rebuilt.segment_bytes = null;
                    try dest_entry.persistent.indexSegmentOwned(segment_bytes);
                    handoffs[i].transferred_segments += 1;
                    if (collect_skip_doc_keys) {
                        try mergeHandoffDocKeys(self.alloc, &handoffs[i], rebuilt.doc_keys);
                    }
                }
            }
        }

        return handoffs;
    }

    pub fn handoffSparseFrom(self: *IndexManager, src: *IndexManager, lower: []const u8, upper: []const u8, collect_skip_doc_keys: bool) ![]SparseSplitHandoff {
        var handoffs = try self.alloc.alloc(SparseSplitHandoff, self.sparse_indexes.items.len);
        errdefer {
            for (handoffs) |*handoff| {
                if (handoff.index_name.len > 0) handoff.deinit(self.alloc);
            }
            self.alloc.free(handoffs);
        }
        for (handoffs) |*handoff| {
            handoff.* = .{
                .index_name = &.{},
                .skip_doc_keys = .empty,
                .transferred_docs = 0,
            };
        }

        for (self.sparse_indexes.items, 0..) |*dest_entry, i| {
            handoffs[i].index_name = try self.alloc.dupe(u8, dest_entry.config.name);
            const src_entry = src.findSparseIndexEntry(dest_entry.config.name) orelse continue;
            const rebuilt = try src_entry.index.handoffRangeInto(&dest_entry.index, self.alloc, lower, upper, collect_skip_doc_keys);
            defer self.alloc.free(rebuilt.doc_ids);

            handoffs[i].transferred_docs += rebuilt.doc_ids.len;
            handoffs[i].select_docs_ns += rebuilt.select_docs_ns;
            handoffs[i].terms_ns += rebuilt.terms_ns;
            handoffs[i].commit_ns += rebuilt.commit_ns;
            if (collect_skip_doc_keys) {
                try mergeSkipDocKeys(self.alloc, &handoffs[i].skip_doc_keys, rebuilt.doc_ids);
            }
        }

        return handoffs;
    }

    pub fn handoffSparseFromPreparedDocIds(self: *IndexManager, src: *IndexManager, doc_ids: []const []const u8, lower: []const u8, upper: []const u8, collect_skip_doc_keys: bool) ![]SparseSplitHandoff {
        var handoffs = try self.alloc.alloc(SparseSplitHandoff, self.sparse_indexes.items.len);
        errdefer {
            for (handoffs) |*handoff| {
                if (handoff.index_name.len > 0) handoff.deinit(self.alloc);
            }
            self.alloc.free(handoffs);
        }
        for (handoffs) |*handoff| {
            handoff.* = .{
                .index_name = &.{},
                .skip_doc_keys = .empty,
                .transferred_docs = 0,
            };
        }

        for (self.sparse_indexes.items, 0..) |*dest_entry, i| {
            handoffs[i].index_name = try self.alloc.dupe(u8, dest_entry.config.name);
            const src_entry = src.findSparseIndexEntry(dest_entry.config.name) orelse continue;
            const rebuilt = try src_entry.index.handoffPreparedDocIdsInto(&dest_entry.index, self.alloc, doc_ids, lower, upper, collect_skip_doc_keys);
            defer self.alloc.free(rebuilt.doc_ids);

            handoffs[i].transferred_docs += rebuilt.doc_ids.len;
            handoffs[i].select_docs_ns += rebuilt.select_docs_ns;
            handoffs[i].terms_ns += rebuilt.terms_ns;
            handoffs[i].commit_ns += rebuilt.commit_ns;
            if (collect_skip_doc_keys) {
                try mergeSkipDocKeys(self.alloc, &handoffs[i].skip_doc_keys, rebuilt.doc_ids);
            }
        }

        return handoffs;
    }

    pub fn handoffDenseFrom(self: *IndexManager, src: *IndexManager, dest_store: *docstore_mod.DocStore, split_key: []const u8, collect_skip_doc_keys: bool) ![]DenseSplitHandoff {
        const dense_split_batch_size = 1024;
        var handoffs = try self.alloc.alloc(DenseSplitHandoff, self.dense_indexes.items.len);
        errdefer {
            for (handoffs) |*handoff| {
                if (handoff.index_name.len > 0) handoff.deinit(self.alloc);
            }
            self.alloc.free(handoffs);
        }
        for (handoffs) |*handoff| {
            handoff.* = .{
                .index_name = &.{},
                .skip_doc_keys = .empty,
                .transferred_docs = 0,
            };
        }

        for (self.dense_indexes.items, 0..) |*dest_entry, i| {
            const src_entry = src.denseIndex(dest_entry.config.name) orelse continue;
            const split_work = src_entry.index.estimateSplitRebuildWork(split_key) catch |err| switch (err) {
                error.MissingSplitRange => continue,
                else => return err,
            };
            handoffs[i].index_name = try self.alloc.dupe(u8, dest_entry.config.name);
            const total_members = split_work.totalRightMembers();
            var dest_txn = try dest_entry.index.beginWriteTxn();
            errdefer dest_txn.abort();
            var store_batch = try dest_store.beginWriteBatch();
            errdefer store_batch.abort();
            const store_txn = store_batch.asTxn();
            const Context = struct {
                alloc: Allocator,
                handoff: *DenseSplitHandoff,
                collect_skip_doc_keys: bool,
                collected: []hbc_mod.PreparedBulkBuildInput,
                vectors_storage: []f32,
                transformed_storage: []f32,
                collected_count: usize = 0,
                max_vector_id: u64 = 0,

                fn consume(ctx: *@This(), items: []const hbc_mod.BatchInsertItem) !void {
                    for (items) |item| {
                        const slot = ctx.collected_count;
                        const dims = item.vector.len;
                        const vector_slot = ctx.vectors_storage[slot * dims ..][0..dims];
                        @memcpy(vector_slot, item.vector);
                        const transformed_slot = ctx.transformed_storage[slot * dims ..][0..dims];
                        @memcpy(transformed_slot, item.transformed orelse unreachable);
                        const owned_metadata = try ctx.alloc.dupe(u8, item.metadata);
                        errdefer ctx.alloc.free(owned_metadata);

                        ctx.collected[slot] = .{
                            .vector_id = item.vector_id,
                            .vector = vector_slot,
                            .transformed = transformed_slot,
                            .metadata = owned_metadata,
                        };
                        ctx.collected_count += 1;

                        if (ctx.collect_skip_doc_keys) {
                            const owned_key = try ctx.alloc.dupe(u8, owned_metadata);
                            errdefer ctx.alloc.free(owned_key);
                            const gop = try ctx.handoff.skip_doc_keys.getOrPut(ctx.alloc, owned_key);
                            if (gop.found_existing) {
                                ctx.alloc.free(owned_key);
                            } else {
                                gop.value_ptr.* = {};
                            }
                        }
                        ctx.handoff.transferred_docs += 1;
                        ctx.max_vector_id = @max(ctx.max_vector_id, item.vector_id);
                    }
                }
            };

            const dims: usize = @intCast(dest_entry.index.config.dims);
            const collected = try self.alloc.alloc(hbc_mod.PreparedBulkBuildInput, total_members);
            defer self.alloc.free(collected);
            const vectors_storage = try self.alloc.alloc(f32, total_members * dims);
            defer self.alloc.free(vectors_storage);
            const transformed_storage = try self.alloc.alloc(f32, total_members * dims);
            defer self.alloc.free(transformed_storage);
            var ctx = Context{
                .alloc = self.alloc,
                .handoff = &handoffs[i],
                .collect_skip_doc_keys = collect_skip_doc_keys,
                .collected = collected,
                .vectors_storage = vectors_storage,
                .transformed_storage = transformed_storage,
            };
            defer {
                for (ctx.collected[0..ctx.collected_count]) |item| {
                    self.alloc.free(@constCast(item.metadata));
                }
            }
            const stream_started = nowNs();
            _ = try src_entry.index.streamSplitMembers(split_key, dense_split_batch_size, &ctx, Context.consume);
            handoffs[i].stream_ns += elapsedSince(stream_started);

            const before_insert = dest_entry.index.getWriteProfile();
            const insert_started = nowNs();
            try dest_entry.index.bulkBuildPreparedInputsTxn(&dest_txn, ctx.collected[0..ctx.collected_count]);
            handoffs[i].insert_ns += elapsedSince(insert_started);
            const after_insert = dest_entry.index.getWriteProfile();
            handoffs[i].insert_store_ns += after_insert.bulk_build_store_ns - before_insert.bulk_build_store_ns;
            handoffs[i].insert_tree_ns += after_insert.bulk_build_tree_ns - before_insert.bulk_build_tree_ns;

            const mapping_started = nowNs();
            try self.writeDenseVectorMappingsForItemsTxn(dest_store, store_txn, dest_entry.config.name, ctx.collected[0..ctx.collected_count]);
            handoffs[i].mapping_ns += elapsedSince(mapping_started);

            const before_finalize = dest_entry.index.getWriteProfile();
            const finalize_started = nowNs();
            try dest_entry.index.finishWriteTxn(&dest_txn);
            handoffs[i].finalize_ns += elapsedSince(finalize_started);
            const after_finalize = dest_entry.index.getWriteProfile();
            handoffs[i].finalize_quantized_ns += after_finalize.refresh_quantized_ns - before_finalize.refresh_quantized_ns;
            handoffs[i].finalize_flush_ns += after_finalize.insert_flush_metadata_ns - before_finalize.insert_flush_metadata_ns;
            handoffs[i].finalize_commit_ns += after_finalize.insert_commit_ns - before_finalize.insert_commit_ns;

            if (ctx.max_vector_id > 0) {
                try self.setDenseNextIdAtLeastTxn(store_txn, dest_entry.config.name, ctx.max_vector_id + 1);
            }
            try store_batch.commit();
        }

        return handoffs;
    }

    fn writeDenseVectorMappingsForItemsTxn(
        self: *IndexManager,
        _: *docstore_mod.DocStore,
        txn: anytype,
        index_name: []const u8,
        items: []const hbc_mod.PreparedBulkBuildInput,
    ) !void {
        if (items.len == 0) return;

        for (items) |item| {
            const doc_map_key = try denseDocMappingKey(self.alloc, index_name, item.metadata);
            defer self.alloc.free(doc_map_key);

            var buf: [8]u8 = undefined;
            std.mem.writeInt(u64, &buf, item.vector_id, .little);
            try txn.put(doc_map_key, &buf);
        }
    }

    pub fn splitDestinationNeedsDocumentIndexing(
        self: *const IndexManager,
        dense_handoffs: []const DenseSplitHandoff,
        text_handoffs: []const TextSplitHandoff,
        sparse_handoffs: []const SparseSplitHandoff,
    ) bool {
        if (self.dense_indexes.items.len != dense_handoffs.len) return true;
        for (self.dense_indexes.items) |entry| {
            _ = findDenseSplitHandoff(dense_handoffs, entry.config.name) orelse return true;
        }
        if (self.text_indexes.items.len > 0) {
            if (text_handoffs.len != self.text_indexes.items.len) return true;
            for (self.text_indexes.items) |entry| {
                _ = findTextSplitHandoff(text_handoffs, entry.config.name) orelse return true;
            }
        }

        if (self.sparse_indexes.items.len != sparse_handoffs.len) return true;
        for (self.sparse_indexes.items) |entry| {
            _ = findSparseSplitHandoff(sparse_handoffs, entry.config.name) orelse return true;
        }

        // When the destination only has text indexes, the split handoff path
        // already transferred or rebuilt the full child-side text coverage.
        // Sparse indexes hand off their child-side forward/reverse coverage and
        // rebuild postings directly from source chunks.
        // Graph indexes are handled separately from edge keys.
        return false;
    }

    fn ownsGeneratedChunkArtifacts(self: *const IndexManager, exclude_index_name: []const u8, chunk_name: []const u8) bool {
        // Chunk artifacts can still be valid reusable inputs for retained
        // embedding enrichment config, so chunk ownership intentionally keeps
        // following enrichment references in addition to live indexes.
        return !self.chunkArtifactsReferencedElsewhere(exclude_index_name, chunk_name);
    }

    fn ownsGeneratedEmbeddingArtifacts(self: *const IndexManager, exclude_index_name: []const u8, embedding_name: []const u8) bool {
        // Embedding artifact lifetime follows the live index graph for the same
        // reason as generated chunk artifacts: shorthand enrichment catalog
        // entries are retained config, not proof that stale artifacts are still
        // query-visible.
        return !self.embeddingArtifactsReferencedElsewhere(exclude_index_name, embedding_name);
    }

    fn chunkArtifactsReferencedElsewhere(self: *const IndexManager, exclude_index_name: []const u8, chunk_name: []const u8) bool {
        for (self.text_indexes.items) |entry| {
            if (std.mem.eql(u8, entry.config.name, exclude_index_name)) continue;
            if (entry.chunk_name) |configured| {
                if (std.mem.eql(u8, configured, chunk_name)) return true;
            }
        }
        for (self.dense_indexes.items) |entry| {
            if (std.mem.eql(u8, entry.config.name, exclude_index_name)) continue;
            if (entry.chunk_name) |configured| {
                if (std.mem.eql(u8, configured, chunk_name)) return true;
            }
        }
        for (self.sparse_indexes.items) |entry| {
            if (std.mem.eql(u8, entry.config.name, exclude_index_name)) continue;
            if (entry.chunk_name) |configured| {
                if (std.mem.eql(u8, configured, chunk_name)) return true;
            }
        }
        for (self.enrichments.items) |entry| {
            if (entry.kind == .embedding and std.mem.eql(u8, entry.source_artifact_name, chunk_name)) return true;
        }
        return false;
    }

    fn embeddingArtifactsReferencedElsewhere(self: *const IndexManager, exclude_index_name: []const u8, embedding_name: []const u8) bool {
        for (self.dense_indexes.items) |entry| {
            if (std.mem.eql(u8, entry.config.name, exclude_index_name)) continue;
            if (entry.embedding_name) |configured| {
                if (std.mem.eql(u8, configured, embedding_name)) return true;
            }
        }
        for (self.sparse_indexes.items) |entry| {
            if (std.mem.eql(u8, entry.config.name, exclude_index_name)) continue;
            if (entry.embedding_name) |configured| {
                if (std.mem.eql(u8, configured, embedding_name)) return true;
            }
        }
        return false;
    }

    const ArtifactRefs = struct {
        chunk_name: ?[]u8 = null,
        embedding_name: ?[]u8 = null,
        asset_name: ?[]u8 = null,

        fn deinit(self: *@This(), alloc: Allocator) void {
            if (self.chunk_name) |value| alloc.free(value);
            if (self.embedding_name) |value| alloc.free(value);
            if (self.asset_name) |value| alloc.free(value);
            self.* = undefined;
        }
    };

    fn artifactRefsFromConfig(self: *IndexManager, cfg: types.IndexConfig) !ArtifactRefs {
        switch (cfg.kind) {
            .full_text => {
                const text_cfg = try parseTextConfig(self.alloc, cfg.config_json);
                defer text_cfg.deinit(self.alloc);
                return .{
                    .chunk_name = if (text_cfg.source_artifact_name) |name| try self.alloc.dupe(u8, name) else null,
                };
            },
            .dense_vector => {
                const dense_cfg = try parseDenseConfig(self.alloc, cfg.config_json);
                defer dense_cfg.deinit(self.alloc);
                const dense_generator = try parseDenseGeneratorConfig(self.alloc, cfg.config_json);
                defer if (dense_generator) |generator| generator.deinit(self.alloc);
                const referenced_embedding = if (dense_generator == null and dense_cfg.embedding_name != null and !dense_cfg.external)
                    self.getEnrichment(.embedding, dense_cfg.embedding_name.?)
                else
                    null;
                return .{
                    .chunk_name = if (dense_generator) |generator|
                        if (generatorHasChunking(generator)) try self.alloc.dupe(u8, generator.artifact_name) else null
                    else if (referenced_embedding) |embedding_cfg|
                        if (embedding_cfg.source_artifact_name.len > 0) try self.alloc.dupe(u8, embedding_cfg.source_artifact_name) else null
                    else
                        null,
                    .embedding_name = if (dense_generator) |generator|
                        if (generator.embedding_name) |embedding_name| try self.alloc.dupe(u8, embedding_name) else try self.alloc.dupe(u8, cfg.name)
                    else if (dense_cfg.embedding_name) |embedding_name|
                        try self.alloc.dupe(u8, embedding_name)
                    else
                        null,
                };
            },
            .sparse_vector => {
                const sparse_generator = try parseSparseGeneratorConfig(self.alloc, cfg.config_json);
                defer if (sparse_generator) |generator| generator.deinit(self.alloc);
                const referenced_embedding = if (sparse_generator == null)
                    self.getEnrichment(.embedding, cfg.name)
                else
                    null;
                return .{
                    .chunk_name = if (sparse_generator) |generator| blk: {
                        const chunk_cfg = resolveChunkGenerator(self, generator);
                        break :blk if (generatorHasChunking(chunk_cfg)) try self.alloc.dupe(u8, chunk_cfg.artifact_name) else null;
                    } else if (referenced_embedding) |embedding_cfg|
                        if (embedding_cfg.source_artifact_name.len > 0) try self.alloc.dupe(u8, embedding_cfg.source_artifact_name) else null
                    else
                        null,
                    .embedding_name = if (sparse_generator) |generator|
                        if (generator.embedding_name) |embedding_name| try self.alloc.dupe(u8, embedding_name) else try self.alloc.dupe(u8, cfg.name)
                    else
                        try self.alloc.dupe(u8, cfg.name),
                };
            },
            .graph => {
                var graph_cfg = try parseGraphConfig(self.alloc, cfg.config_json);
                defer graph_cfg.deinit(self.alloc);
                return .{
                    .asset_name = if (graph_cfg.artifact_source) |source| try self.alloc.dupe(u8, source.artifact_name) else null,
                };
            },
            .algebraic => return .{},
        }
    }

    fn bestEffortArtifactRefsFromConfig(self: *IndexManager, cfg: types.IndexConfig) ArtifactRefs {
        return self.artifactRefsFromConfig(cfg) catch |err| {
            std.log.warn("status-only index artifact refs unavailable name={s} kind={s} err={s}", .{
                cfg.name,
                @tagName(cfg.kind),
                @errorName(err),
            });
            return .{};
        };
    }

    fn chunkArtifactsReferencedElsewhereIncludingStatusOnly(self: *IndexManager, exclude_index_name: []const u8, chunk_name: []const u8) !bool {
        if (self.chunkArtifactsReferencedElsewhere(exclude_index_name, chunk_name)) return true;
        for (self.status_only_index_configs) |cfg| {
            if (std.mem.eql(u8, cfg.name, exclude_index_name)) continue;
            var refs = self.artifactRefsFromConfig(cfg) catch |err| {
                std.log.warn("status-only chunk artifact reference check skipped name={s} kind={s} err={s}", .{
                    cfg.name,
                    @tagName(cfg.kind),
                    @errorName(err),
                });
                return true;
            };
            defer refs.deinit(self.alloc);
            if (refs.chunk_name) |configured| {
                if (std.mem.eql(u8, configured, chunk_name)) return true;
            }
        }
        return false;
    }

    fn embeddingArtifactsReferencedElsewhereIncludingStatusOnly(self: *IndexManager, exclude_index_name: []const u8, embedding_name: []const u8) !bool {
        if (self.embeddingArtifactsReferencedElsewhere(exclude_index_name, embedding_name)) return true;
        for (self.status_only_index_configs) |cfg| {
            if (std.mem.eql(u8, cfg.name, exclude_index_name)) continue;
            var refs = self.artifactRefsFromConfig(cfg) catch |err| {
                std.log.warn("status-only embedding artifact reference check skipped name={s} kind={s} err={s}", .{
                    cfg.name,
                    @tagName(cfg.kind),
                    @errorName(err),
                });
                return true;
            };
            defer refs.deinit(self.alloc);
            if (refs.embedding_name) |configured| {
                if (std.mem.eql(u8, configured, embedding_name)) return true;
            }
        }
        return false;
    }

    fn deleteDenseIndexMetadata(self: *IndexManager, store: anytype, index_name: []const u8) !void {
        const prefix = try denseIndexMetadataPrefixAlloc(self.alloc, index_name);
        defer self.alloc.free(prefix);
        try self.deleteKeysWithPrefix(store, prefix);
        const legacy_prefix = try legacyDenseIndexMetadataPrefixAlloc(self.alloc, index_name);
        defer self.alloc.free(legacy_prefix);
        try self.deleteKeysWithPrefix(store, legacy_prefix);
    }

    fn derivedEmbeddingBaseMatchesChunk(self: *IndexManager, key: []const u8, chunk_name: []const u8) !bool {
        const base_key = (try internal_keys.derivedEmbeddingBaseKeyAlloc(self.alloc, key)) orelse return false;
        defer self.alloc.free(base_key);
        return internal_keys.matchesChunkArtifactName(base_key, chunk_name);
    }

    fn deleteKeysWithPrefix(self: *IndexManager, store: anytype, prefix: []const u8) !void {
        const entries = try store.scanPrefix(self.alloc, prefix);
        defer docstore_mod.DocStore.freeResults(self.alloc, entries);
        if (entries.len == 0) return;

        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(self.alloc);
        for (entries) |entry| {
            try deletes.append(self.alloc, entry.key);
        }
        try store.putBatch(&.{}, deletes.items);
    }

    fn deleteKeysWithPrefixPage(self: *IndexManager, store: anytype, prefix: []const u8) !bool {
        const entries = try store.scanPrefixPage(self.alloc, prefix, null, generated_artifact_cleanup_scan_limit);
        defer docstore_mod.DocStore.freeResults(self.alloc, entries);
        if (entries.len == 0) return true;

        const deletes = try self.alloc.alloc([]const u8, entries.len);
        defer self.alloc.free(deletes);
        for (entries, 0..) |entry, i| deletes[i] = entry.key;
        try store.putBatch(&.{}, deletes);
        // A following page verifies exhaustion. This keeps one call bounded to
        // one storage batch even when a family contains exactly one short page.
        return false;
    }

    pub fn deleteAlgebraicStorageNamespacePage(self: *IndexManager, storage_namespace: []const u8) !bool {
        const store = self.primary_store orelse return error.PrimaryStoreUnavailable;
        const fact_prefix = try algebraic_mod.index.storagePrefixAlloc(self.alloc, storage_namespace);
        defer self.alloc.free(fact_prefix);
        if (!try self.deleteKeysWithPrefixPage(store, fact_prefix)) return false;
        const tuple_prefix = try algebraic_mod.index.tupleStoragePrefixAlloc(self.alloc, storage_namespace);
        defer self.alloc.free(tuple_prefix);
        if (!try self.deleteKeysWithPrefixPage(store, tuple_prefix)) return false;
        const dictionary_prefix = try algebraic_mod.index.dictionaryStoragePrefixAlloc(self.alloc, storage_namespace);
        defer self.alloc.free(dictionary_prefix);
        if (!try self.deleteKeysWithPrefixPage(store, dictionary_prefix)) return false;

        const registry_prefix = try algebraic_mod.index.dictionaryRegistryPrefixAlloc(self.alloc, storage_namespace);
        defer self.alloc.free(registry_prefix);
        return try self.deleteKeysWithPrefixPage(store, registry_prefix);
    }

    pub fn rebuildGraphSplitDestination(self: *IndexManager, lower: []const u8, upper: []const u8) !usize {
        var rebuilt: usize = 0;
        for (self.graph_indexes.items) |*entry| {
            rebuilt += try entry.index.rebuildReverseFromOwnedOutgoingEdges(self.alloc, lower, upper);
        }
        return rebuilt;
    }

    pub fn copyGraphSplitDestinationFrom(self: *IndexManager, src: *IndexManager, lower: []const u8, upper: []const u8) !usize {
        var copied: usize = 0;
        for (src.graph_indexes.items) |*src_entry| {
            const dest_entry = self.graphIndex(src_entry.config.name) orelse return error.IndexNotFound;
            copied += try src_entry.index.copyOwnedOutgoingEdgesTo(&dest_entry.index, self.alloc, lower, upper);
        }
        return copied;
    }

    pub fn pruneTextSplitRange(self: *IndexManager, split_key: []const u8) !void {
        for (self.text_indexes.items) |*entry| {
            const plan = try entry.persistent.classifyActiveSegmentsForSplit(self.alloc, split_key);
            defer {
                for (plan) |*plan_entry| plan_entry.deinit(self.alloc);
                self.alloc.free(plan);
            }

            var remove_ids = std.ArrayListUnmanaged(u64).empty;
            defer remove_ids.deinit(self.alloc);

            for (plan) |plan_entry| {
                switch (plan_entry.class) {
                    .left_only => {},
                    .right_only => try remove_ids.append(self.alloc, plan_entry.seg_id),
                    .mixed => {
                        var stored_segment = try entry.persistent.readStoredSegment(self.alloc, plan_entry.seg_id);
                        defer stored_segment.deinit(self.alloc);

                        var rebuilt = try buildSplitSegment(
                            self.alloc,
                            stored_segment.segment_bytes,
                            stored_segment.deletion_bitmap_bytes,
                            split_key,
                            .left,
                            entry.config.config_json,
                            false,
                        );
                        defer if (rebuilt.segment_bytes) |segment_bytes| self.alloc.free(segment_bytes);
                        defer {
                            for (rebuilt.doc_keys) |key| self.alloc.free(key);
                            self.alloc.free(rebuilt.doc_keys);
                        }

                        if (rebuilt.segment_bytes) |segment_bytes| {
                            try entry.persistent.replaceSegmentsOwned(&.{plan_entry.seg_id}, segment_bytes);
                            rebuilt.segment_bytes = null;
                        } else {
                            try remove_ids.append(self.alloc, plan_entry.seg_id);
                        }
                    },
                }
            }

            try entry.persistent.removeSegments(remove_ids.items);
        }
    }

    pub fn pruneDenseSplitRange(self: *IndexManager, store: *docstore_mod.DocStore, split_key: []const u8) !void {
        for (self.dense_indexes.items) |*entry| {
            var members = try entry.index.collectSplitMembers(split_key);
            defer members.deinit(self.alloc);

            for ([_][]const u64{ members.right_only_members, members.mixed_right_members }) |member_ids| {
                for (member_ids) |member_id| {
                    const metadata = (try entry.index.getMetadata(member_id)) orelse continue;
                    defer self.alloc.free(metadata);

                    entry.index.delete(member_id) catch |err| switch (err) {
                        error.NotFound => {},
                        else => return err,
                    };
                    try self.clearDenseVectorMapping(store, entry.config.name, metadata, member_id);
                }
            }
        }
    }

    pub fn pruneSparseSplitRange(self: *IndexManager, split_key: []const u8, original_range_end: []const u8) !void {
        for (self.sparse_indexes.items) |*entry| {
            try entry.index.pruneRange(self.alloc, split_key, original_range_end);
        }
    }

    pub fn pruneGraphSplitRange(self: *IndexManager, split_key: []const u8, original_range_end: []const u8) !void {
        for (self.graph_indexes.items) |*entry| {
            _ = try entry.index.pruneOwnedRange(self.alloc, split_key, original_range_end);
        }
    }

    pub fn textChunkName(self: *const IndexManager, name: []const u8) ?[]const u8 {
        for (self.text_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return entry.chunk_name;
        }
        return null;
    }

    pub fn selectedTextChunkName(self: *const IndexManager, name: ?[]const u8) ?[]const u8 {
        if (name) |index_name| return self.textChunkName(index_name);
        if (self.text_indexes.items.len == 1) return self.text_indexes.items[0].chunk_name;
        return null;
    }

    pub fn textIndexIsChunkBacked(self: *const IndexManager, alloc: Allocator, name: ?[]const u8) !bool {
        const entry = if (name) |index_name| blk: {
            for (self.text_indexes.items) |*text_entry| {
                if (std.mem.eql(u8, text_entry.config.name, index_name)) break :blk text_entry;
            }
            break :blk null;
        } else if (self.text_indexes.items.len == 1)
            &self.text_indexes.items[0]
        else
            null;
        const resolved = entry orelse return false;
        if (resolved.chunk_name != null) return true;

        for (self.enrichments.items) |cfg| {
            if (cfg.kind == .asset and cfg.full_text_index) return true;
            if (cfg.kind != .chunk) continue;
            if (cfg.full_text_index) return true;
            if (cfg.chunker_json.len == 0) continue;
            if (try chunking_types.parseHasFullTextIndexFromSlice(alloc, cfg.chunker_json)) return true;
        }
        return false;
    }

    pub fn denseIndex(self: *IndexManager, name: ?[]const u8) ?*DenseIndex {
        if (name) |index_name| {
            for (self.dense_indexes.items) |*entry| {
                if (std.mem.eql(u8, entry.config.name, index_name)) return entry;
            }
            return null;
        }
        if (self.dense_indexes.items.len == 1) return &self.dense_indexes.items[0];
        return null;
    }

    pub fn denseVectorAccessPath(self: *IndexManager, name: ?[]const u8) ?algebraic_mod.ir.PhysicalAccessPath {
        const entry = self.denseIndex(name) orelse return null;
        return algebraic_mod.ir.vectorAccessPath(entry.config.name, .dense_vector);
    }

