    pub fn exactScoreDenseEntryWithRequest(
        self: *IndexManager,
        entry: *DenseIndex,
        req: hbc_mod.SearchRequest,
    ) !dense_exact.SearchOutcome {
        try checkDenseSearchCancelled(req);
        const previous_load_session = active_dense_vector_load_session;
        var vector_load_session: ?DenseVectorLoadSession = null;
        defer {
            if (vector_load_session != null) active_dense_vector_load_session = previous_load_session;
            if (vector_load_session) |*session| session.deinit();
        }

        if (active_dense_vector_load_session == null and self.primary_store != null and entry.vector_loader_context != null) {
            vector_load_session = .{
                .context = entry.vector_loader_context.?,
                .working_slice = .dense_search_working_set,
                .recycle_raw_reads = false,
                .cache_raw_values = false,
                .cache_vectors = false,
                .block_cache_admission = if (entry.index.prefersDecodedVectorResidency()) .transient else .retain,
            };
            active_dense_vector_load_session = &vector_load_session.?;
        }

        // Admit the candidate-normalization and per-candidate metadata arrays
        // before any of them allocate. The include length is a conservative
        // upper bound after sort/unique/subtraction; charging the exclusion
        // copy unconditionally preserves fail-closed accounting without first
        // scanning a large request merely to discover whether it is sorted.
        const requested_candidates: u64 = @intCast(req.filter_ids.len);
        const fixed_candidate_bytes = requested_candidates *|
            (@as(u64, @sizeOf(u64)) + @sizeOf(?[]const u8) + @sizeOf(?[]u8));
        const exclusion_bytes = @as(u64, @intCast(req.exclude_ids.len)) *| @sizeOf(u64);
        const result_capacity_bytes = @as(u64, @intCast(req.k)) *| 64;
        const vector_scratch_bytes = @as(u64, entry.dims) *| @sizeOf(f32);
        const preflight_workspace_bytes = fixed_candidate_bytes +| exclusion_bytes +|
            result_capacity_bytes +| vector_scratch_bytes +| 4096;
        var workspace_accounted: u64 = 0;
        if (!self.tryObserveDenseWorkingBytes(
            .dense_search_working_set,
            &workspace_accounted,
            preflight_workspace_bytes,
        )) return error.ResourceBudgetExceeded;
        defer self.observeDenseWorkingBytes(.dense_search_working_set, &workspace_accounted, 0);

        const prepare_start_ns = platform_time.monotonicNs();
        var candidates = try dense_exact.CandidateDifference.init(self.alloc, req.filter_ids, req.exclude_ids);
        defer candidates.deinit();
        const unique_candidate_ids = candidates.values;
        var exact_profile: dense_exact.SearchOutcome.Profile = .{
            .candidate_count = @intCast(unique_candidate_ids.len),
            .workspace_bytes = preflight_workspace_bytes,
            .candidate_prepare_ns = platform_time.monotonicNs() - prepare_start_ns,
        };
        try checkDenseSearchCancelled(req);

        // Exact scoring is single-pass. Retaining every decoded vector in a
        // request-local cache doubles residency without creating a reuse
        // opportunity, so force it off even when a caller supplied a session.
        const exact_load_session = blk: {
            const session = active_dense_vector_load_session orelse break :blk null;
            if (entry.vector_loader_context == null or session.context != entry.vector_loader_context.?) break :blk null;
            break :blk session;
        };
        const previous_cache_vectors = if (exact_load_session) |session| session.cache_vectors else false;
        if (exact_load_session) |session| session.cache_vectors = false;
        defer {
            if (exact_load_session) |session| session.cache_vectors = previous_cache_vectors;
        }

        var results = try hbc_mod.SearchResults.initCapacity(
            self.alloc,
            req.k,
            req.k,
            @min(req.k, unique_candidate_ids.len),
        );
        errdefer results.deinit();

        var txn = try entry.index.beginReadTxn();
        defer txn.abort();

        // Candidate IDs are sorted, so resolve metadata and vectors with the
        // backend's ordered batch/cursor APIs. The old loop performed one
        // metadata probe and could open one primary-store transaction per
        // candidate, which dominated highly selective filtered searches.
        const candidate_metadata = try self.alloc.alloc(?[]const u8, unique_candidate_ids.len);
        defer self.alloc.free(candidate_metadata);
        @memset(candidate_metadata, null);
        const metadata_lookup_start_ns = platform_time.monotonicNs();
        var metadata_start: usize = 0;
        while (metadata_start < unique_candidate_ids.len) {
            try checkDenseSearchCancelled(req);
            const metadata_end = @min(
                metadata_start + exact_dense_metadata_batch_size,
                unique_candidate_ids.len,
            );
            try entry.index.getMetadataManySortedInTxn(
                &txn,
                unique_candidate_ids[metadata_start..metadata_end],
                candidate_metadata[metadata_start..metadata_end],
            );
            metadata_start = metadata_end;
        }
        exact_profile.metadata_lookup_ns = platform_time.monotonicNs() - metadata_lookup_start_ns;
        try checkDenseSearchCancelled(req);

        const fallback_doc_keys = try self.alloc.alloc(?[]u8, unique_candidate_ids.len);
        defer {
            for (fallback_doc_keys) |maybe_doc_key| {
                if (maybe_doc_key) |doc_key| self.alloc.free(doc_key);
            }
            self.alloc.free(fallback_doc_keys);
        }
        @memset(fallback_doc_keys, null);

        var needs_primary_metadata = false;
        for (candidate_metadata) |maybe_metadata| {
            if (maybe_metadata == null) {
                needs_primary_metadata = true;
                break;
            }
        }
        if (needs_primary_metadata) {
            if (self.primary_store) |store| {
                var legacy_vector_ordinals = std.AutoHashMapUnmanaged(u64, doc_identity.DocOrdinal).empty;
                defer legacy_vector_ordinals.deinit(self.alloc);
                var needs_legacy_reverse = false;
                for (unique_candidate_ids, candidate_metadata, 0..) |vector_id, maybe_metadata, i| {
                    if (i % exact_dense_cancellation_stride == 0) try checkDenseSearchCancelled(req);
                    if (maybe_metadata == null and !entry.vector_ordinals.contains(vector_id)) {
                        needs_legacy_reverse = true;
                        break;
                    }
                }
                if (needs_legacy_reverse) {
                    try legacy_vector_ordinals.ensureTotalCapacity(self.alloc, entry.ordinal_vector_ids.count());
                    var reverse_it = entry.ordinal_vector_ids.iterator();
                    var reverse_count: usize = 0;
                    while (reverse_it.next()) |item| : (reverse_count += 1) {
                        if (reverse_count % exact_dense_cancellation_stride == 0) try checkDenseSearchCancelled(req);
                        legacy_vector_ordinals.putAssumeCapacity(item.value_ptr.*, item.key_ptr.*);
                    }
                }

                var identity_txn = try store.beginProbeTxn();
                defer identity_txn.abort();
                for (unique_candidate_ids, candidate_metadata, 0..) |vector_id, maybe_metadata, i| {
                    if (i % exact_dense_cancellation_stride == 0) try checkDenseSearchCancelled(req);
                    if (maybe_metadata != null) continue;
                    const ordinal = entry.vector_ordinals.get(vector_id) orelse legacy_vector_ordinals.get(vector_id) orelse continue;
                    fallback_doc_keys[i] = try doc_identity.lookupDocIdTxn(self.alloc, &identity_txn, ordinal);
                }
            }
        }

        const query_measure = vector_mod.norm(req.query);
        var vectors_scored: u64 = 0;
        const vectors_stored_externally = entry.vector_loader_context != null and
            self.primary_store != null and
            entry.index.hasExternalVectorLoader();
        if (vectors_stored_externally) {
            // Production indexes intentionally keep full vectors outside HBC.
            // Do not issue the guaranteed `.vecs` miss: compact eligible IDs
            // into bounded sorted batches and read their artifacts together.
            const batch_capacity = @min(exact_dense_score_batch_size, unique_candidate_ids.len);
            const artifact_name = entry.embedding_name orelse entry.config.name;
            var max_batch_key_bytes: u64 = 0;
            var key_scan_start: usize = 0;
            while (key_scan_start < unique_candidate_ids.len) {
                const key_scan_end = @min(key_scan_start + exact_dense_score_batch_size, unique_candidate_ids.len);
                var batch_key_bytes: u64 = 0;
                for (candidate_metadata[key_scan_start..key_scan_end], fallback_doc_keys[key_scan_start..key_scan_end]) |maybe_metadata, fallback_doc_key| {
                    const doc_key = maybe_metadata orelse fallback_doc_key orelse continue;
                    if (req.filter_prefix.len > 0 and !std.mem.startsWith(u8, doc_key, req.filter_prefix)) continue;
                    // Internal tuple encoding can escape every byte. Include
                    // fixed namespace/components plus arena alignment slack.
                    batch_key_bytes +|= @as(u64, @intCast(doc_key.len)) *| 2 +| @as(u64, @intCast(artifact_name.len)) +| 64;
                    // A direct-field index created by backfill may predate
                    // materialized vector artifacts. Its compatibility path
                    // retains the artifact key and the primary-document key
                    // in the same per-batch arena before scoring.
                    if (!entry.external and entry.embedding_name == null) {
                        batch_key_bytes +|= @as(u64, @intCast(doc_key.len)) *| 2 +| 32;
                    }
                }
                max_batch_key_bytes = @max(max_batch_key_bytes, batch_key_bytes);
                key_scan_start = key_scan_end;
            }
            const per_candidate_workspace = @sizeOf(u64) + @sizeOf(?[]const u8) + @sizeOf(f32) +
                @sizeOf([]const u8) + @sizeOf(?[]const u8) + @sizeOf(DenseArtifactReadKey) +
                @sizeOf([]const u8) + @sizeOf(usize) + @sizeOf(?[]const u8);
            const batch_workspace_bytes = @as(u64, @intCast(batch_capacity)) *| per_candidate_workspace +|
                @as(u64, entry.dims) *| @sizeOf(f32) +| max_batch_key_bytes +| 4096;
            const total_workspace_bytes = preflight_workspace_bytes +| batch_workspace_bytes;
            exact_profile.workspace_bytes = total_workspace_bytes;
            if (!self.tryObserveDenseWorkingBytes(.dense_search_working_set, &workspace_accounted, total_workspace_bytes)) {
                return error.ResourceBudgetExceeded;
            }

            const batch_ids = try self.alloc.alloc(u64, batch_capacity);
            defer self.alloc.free(batch_ids);
            const batch_metadata = try self.alloc.alloc(?[]const u8, batch_capacity);
            defer self.alloc.free(batch_metadata);
            const batch_distances = try self.alloc.alloc(f32, batch_capacity);
            defer self.alloc.free(batch_distances);
            const artifact_keys = try self.alloc.alloc([]const u8, batch_capacity);
            defer self.alloc.free(artifact_keys);
            const raw_values = try self.alloc.alloc(?[]const u8, batch_capacity);
            defer self.alloc.free(raw_values);
            const vector_scratch = try self.alloc.alloc(f32, entry.dims);
            defer self.alloc.free(vector_scratch);

            var hbc_profile: hbc_mod.SearchProfile = .{};
            var candidate_start: usize = 0;
            while (candidate_start < unique_candidate_ids.len) {
                try checkDenseSearchCancelled(req);
                const candidate_end = @min(candidate_start + exact_dense_score_batch_size, unique_candidate_ids.len);
                var batch_len: usize = 0;
                for (unique_candidate_ids[candidate_start..candidate_end], candidate_metadata[candidate_start..candidate_end], fallback_doc_keys[candidate_start..candidate_end]) |vector_id, maybe_metadata, fallback_doc_key| {
                    const doc_key = maybe_metadata orelse fallback_doc_key orelse continue;
                    if (req.filter_prefix.len > 0 and !std.mem.startsWith(u8, doc_key, req.filter_prefix)) continue;
                    batch_ids[batch_len] = vector_id;
                    batch_metadata[batch_len] = doc_key;
                    batch_distances[batch_len] = std.math.inf(f32);
                    batch_len += 1;
                }
                if (batch_len > 0) {
                    exact_profile.batch_count += 1;
                    exact_profile.max_batch_size = @max(exact_profile.max_batch_size, batch_len);
                    try scoreDenseVectorsForHbcBatch(
                        entry.vector_loader_context.?,
                        batch_ids[0..batch_len],
                        batch_metadata[0..batch_len],
                        req.query,
                        query_measure,
                        entry.metric,
                        batch_distances[0..batch_len],
                        vector_scratch,
                        entry.dims,
                        .{ .artifact_keys = artifact_keys, .raw_values = raw_values },
                        &hbc_profile,
                    );
                    for (batch_ids[0..batch_len], batch_metadata[0..batch_len], batch_distances[0..batch_len]) |vector_id, maybe_doc_key, distance| {
                        if (!std.math.isFinite(distance)) {
                            exact_profile.missing_vectors += 1;
                            continue;
                        }
                        vectors_scored += 1;
                        if (req.distance_over) |threshold| if (distance <= threshold) continue;
                        if (req.distance_under) |threshold| if (distance >= threshold) continue;
                        const owned_metadata = if (maybe_doc_key) |doc_key| try self.alloc.dupe(u8, doc_key) else null;
                        results.addResultWithOwnedMetadata(vector_id, distance, 0, owned_metadata);
                    }
                }
                candidate_start = candidate_end;
            }
            exact_profile.artifact_key_ns = hbc_profile.rerank_artifact_key_ns;
            exact_profile.artifact_read_ns = hbc_profile.rerank_artifact_read_ns;
            exact_profile.artifact_decode_ns = hbc_profile.rerank_artifact_decode_ns;
            exact_profile.distance_ns = hbc_profile.rerank_artifact_distance_ns;
            exact_profile.lsm_cache_hits = hbc_profile.rerank_lsm_cache_hits;
            exact_profile.lsm_cache_misses = hbc_profile.rerank_lsm_cache_misses;
        } else {
            var vector_cursor = entry.index.openNamespacedCursor(self.alloc, &txn, .vecs) catch |err| switch (err) {
                error.Unsupported => null,
                else => return err,
            };
            defer if (vector_cursor) |*cursor| cursor.close();
            const vector_scratch = try self.alloc.alloc(f32, entry.dims);
            defer self.alloc.free(vector_scratch);
            for (unique_candidate_ids, candidate_metadata, fallback_doc_keys, 0..) |vector_id, maybe_metadata, fallback_doc_key, i| {
                if (i % exact_dense_cancellation_stride == 0) try checkDenseSearchCancelled(req);
                const doc_key = maybe_metadata orelse fallback_doc_key;
                if (req.filter_prefix.len > 0) {
                    const resolved_doc_key = doc_key orelse continue;
                    if (!std.mem.startsWith(u8, resolved_doc_key, req.filter_prefix)) continue;
                }
                const distance_start_ns = platform_time.monotonicNs();
                const vector = (if (vector_cursor) |*cursor|
                    entry.index.getVectorViewOrScratchWithCursor(cursor, vector_id, vector_scratch)
                else
                    entry.index.getVectorViewOrScratch(&txn, vector_id, vector_scratch)) catch |err| switch (err) {
                    error.NotFound => {
                        exact_profile.missing_vectors += 1;
                        continue;
                    },
                    else => return err,
                };
                if (vector.len != req.query.len) return error.DimensionMismatch;
                vectors_scored += 1;
                const distance = vector_mod.distanceToQuery(req.query, query_measure, vector, entry.metric);
                exact_profile.distance_ns += platform_time.monotonicNs() - distance_start_ns;
                if (!std.math.isFinite(distance)) continue;
                if (req.distance_over) |threshold| if (distance <= threshold) continue;
                if (req.distance_under) |threshold| if (distance >= threshold) continue;
                const owned_metadata = if (doc_key) |resolved_doc_key| try self.alloc.dupe(u8, resolved_doc_key) else null;
                results.addResultWithOwnedMetadata(vector_id, distance, 0, owned_metadata);
            }
        }
        if (exact_load_session) |session| {
            exact_profile.request_vector_cache_entries = session.vector_cache.count();
            exact_profile.raw_batch_reads = session.raw_batch_reads;
            exact_profile.raw_scalar_reads = session.raw_scalar_reads;
        }
        results.sort();
        if (getenv("ANTFLY_BENCH_QUERY_PROFILE") != null) {
            std.log.info("antfly_bench_dense_exact_filter index={s} candidates={d} hits={d} batches={d} batch_reads={d} scalar_reads={d} missing={d}", .{
                entry.config.name,
                unique_candidate_ids.len,
                results.getHits().len,
                exact_profile.batch_count,
                exact_profile.raw_batch_reads,
                exact_profile.raw_scalar_reads,
                exact_profile.missing_vectors,
            });
        }
        return .{
            .results = results,
            .vectors_scored = vectors_scored,
            .profile = exact_profile,
        };
    }

    pub fn textIndexesForChunk(
        self: *const IndexManager,
        alloc: Allocator,
        chunk_name: []const u8,
        include_default_full_text: bool,
    ) ![][]u8 {
        var names = std.ArrayListUnmanaged([]u8).empty;
        errdefer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }
        for (self.text_indexes.items) |entry| {
            if (entry.chunk_name) |configured| {
                if (std.mem.eql(u8, configured, chunk_name)) {
                    try names.append(alloc, try alloc.dupe(u8, entry.config.name));
                }
            } else if (include_default_full_text) {
                try names.append(alloc, try alloc.dupe(u8, entry.config.name));
            }
        }
        return try names.toOwnedSlice(alloc);
    }

    pub fn denseChunkName(self: *const IndexManager, name: []const u8) ?[]const u8 {
        for (self.dense_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return entry.chunk_name;
        }
        return null;
    }

    pub fn selectedDenseChunkName(self: *const IndexManager, name: ?[]const u8) ?[]const u8 {
        if (name) |index_name| return self.denseChunkName(index_name);
        if (self.dense_indexes.items.len == 1) return self.dense_indexes.items[0].chunk_name;
        return null;
    }

    pub fn denseEmbeddingName(self: *const IndexManager, name: []const u8) ?[]const u8 {
        for (self.dense_indexes.items) |*entry| {
            if (std.mem.eql(u8, entry.config.name, name)) return entry.embedding_name;
        }
        return null;
    }

    pub fn selectedDenseEmbeddingName(self: *const IndexManager, name: ?[]const u8) ?[]const u8 {
        if (name) |index_name| return self.denseEmbeddingName(index_name);
        if (self.dense_indexes.items.len == 1) return self.dense_indexes.items[0].embedding_name;
        return null;
    }

    pub fn denseIndexesForEmbedding(self: *const IndexManager, alloc: Allocator, embedding_name: []const u8, dims: u32) ![][]u8 {
        var names = std.ArrayListUnmanaged([]u8).empty;
        errdefer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }
        for (self.dense_indexes.items) |entry| {
            const configured = entry.embedding_name orelse if (entry.external) entry.config.name else continue;
            if (!std.mem.eql(u8, configured, embedding_name)) continue;
            if (entry.dims != dims) return error.ConflictingEnrichmentConfig;
            try names.append(alloc, try alloc.dupe(u8, entry.config.name));
        }
        return try names.toOwnedSlice(alloc);
    }

    pub fn vectorIndexesForChunk(self: *const IndexManager, alloc: Allocator, chunk_name: []const u8) ![][]u8 {
        return self.vectorIndexesDependingOnArtifact(alloc, chunk_name);
    }

    pub fn vectorIndexesDependingOnArtifact(self: *const IndexManager, alloc: Allocator, artifact_name: []const u8) ![][]u8 {
        return self.indexesDependingOnArtifactInternal(alloc, artifact_name, false);
    }

    /// Resolve every projection transitively affected by an artifact producer.
    /// This runs only on failure/repair paths, where complete fanout is more
    /// important than maintaining separate, eventually-divergent consumers for
    /// vector, full-text, and graph indexes.
    pub fn indexesDependingOnArtifact(self: *const IndexManager, alloc: Allocator, artifact_name: []const u8) ![][]u8 {
        return self.indexesDependingOnArtifactInternal(alloc, artifact_name, true);
    }

    fn indexesDependingOnArtifactInternal(
        self: *const IndexManager,
        alloc: Allocator,
        artifact_name: []const u8,
        include_non_vector: bool,
    ) ![][]u8 {
        var dependent_artifacts = std.StringHashMapUnmanaged(void).empty;
        defer dependent_artifacts.deinit(alloc);
        try dependent_artifacts.put(alloc, artifact_name, {});
        var changed = true;
        while (changed) {
            changed = false;
            for (self.enrichments.items) |enrichment| {
                if (enrichment.source_artifact_name.len == 0 or !dependent_artifacts.contains(enrichment.source_artifact_name)) continue;
                if (dependent_artifacts.contains(enrichment.name)) continue;
                try dependent_artifacts.put(alloc, enrichment.name, {});
                changed = true;
            }
        }

        var names = std.ArrayListUnmanaged([]u8).empty;
        errdefer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }
        for (self.dense_indexes.items) |entry| {
            const depends = (if (entry.chunk_name) |name| dependent_artifacts.contains(name) else false) or
                (if (entry.embedding_name) |name| dependent_artifacts.contains(name) else false);
            if (!depends) continue;
            try names.append(alloc, try alloc.dupe(u8, entry.config.name));
        }
        for (self.sparse_indexes.items) |entry| {
            const depends = (if (entry.chunk_name) |name| dependent_artifacts.contains(name) else false) or
                (if (entry.embedding_name) |name| dependent_artifacts.contains(name) else false);
            if (!depends) continue;
            if (containsOwnedString(names.items, entry.config.name)) continue;
            try names.append(alloc, try alloc.dupe(u8, entry.config.name));
        }
        if (include_non_vector) {
            var include_default_full_text = false;
            for (self.enrichments.items) |enrichment| {
                if (dependent_artifacts.contains(enrichment.name) and enrichment.full_text_index) {
                    include_default_full_text = true;
                    break;
                }
            }
            for (self.text_indexes.items) |entry| {
                const depends = if (entry.chunk_name) |name|
                    dependent_artifacts.contains(name)
                else
                    include_default_full_text;
                if (!depends or containsOwnedString(names.items, entry.config.name)) continue;
                try names.append(alloc, try alloc.dupe(u8, entry.config.name));
            }
            for (self.graph_indexes.items) |entry| {
                const source = entry.artifact_source orelse continue;
                if (!dependent_artifacts.contains(source.artifact_name) or
                    containsOwnedString(names.items, entry.config.name)) continue;
                try names.append(alloc, try alloc.dupe(u8, entry.config.name));
            }
        }
        return try names.toOwnedSlice(alloc);
    }

    pub fn coverageGenerationForIndex(self: *const IndexManager, index_name: []const u8) ?u64 {
        const cfg = self.get(index_name) orelse return null;
        if (cfg.kind != .dense_vector and cfg.kind != .sparse_vector) return null;
        return coverageGenerationForConfig(cfg.*);
    }

    pub const CoverageIdentity = struct {
        generation: u64,
        config_fingerprint: ?u64,
    };

    pub fn coverageIdentityMapAlloc(self: *const IndexManager, alloc: Allocator) !std.StringHashMapUnmanaged(CoverageIdentity) {
        var identities = std.StringHashMapUnmanaged(CoverageIdentity).empty;
        errdefer identities.deinit(alloc);
        const vector_count = self.dense_indexes.items.len + self.sparse_indexes.items.len + self.status_only_index_configs.len;
        try identities.ensureTotalCapacity(alloc, @intCast(vector_count));
        for (self.dense_indexes.items) |entry| {
            identities.putAssumeCapacity(entry.config.name, coverageIdentityForConfig(entry.config));
        }
        for (self.sparse_indexes.items) |entry| {
            identities.putAssumeCapacity(entry.config.name, coverageIdentityForConfig(entry.config));
        }
        for (self.status_only_index_configs) |cfg| {
            if (cfg.kind != .dense_vector and cfg.kind != .sparse_vector) continue;
            identities.putAssumeCapacity(cfg.name, coverageIdentityForConfig(cfg));
        }
        return identities;
    }

    pub fn denseIndexUsesManagedDirectField(self: *const IndexManager, index_name: []const u8) bool {
        for (self.dense_indexes.items) |entry| {
            if (!std.mem.eql(u8, entry.config.name, index_name)) continue;
            return entry.managed_direct_field;
        }
        return false;
    }

    pub fn denseIndexUsesExternalCoverage(self: *const IndexManager, index_name: []const u8) bool {
