    pub fn validateSparseEmbeddingArtifactsByName(self: *IndexManager, store: *docstore_mod.DocStore, index_name: []const u8, writes: []const mapper.SparseEmbeddingWrite) !void {
        if (writes.len == 0) return;

        const PendingSparseArtifactValidationLoad = struct {
            doc_key: []const u8,
            artifact_key: []const u8,
        };
        var pending_artifact_loads = std.ArrayListUnmanaged(PendingSparseArtifactValidationLoad).empty;
        defer pending_artifact_loads.deinit(self.alloc);
        for (writes) |write| {
            if (!std.mem.eql(u8, write.index_name, index_name)) continue;
            if (write.artifact_key != null and write.indices.len == 0) {
                try pending_artifact_loads.append(self.alloc, .{
                    .doc_key = write.doc_key,
                    .artifact_key = write.artifact_key.?,
                });
            }
        }
        if (pending_artifact_loads.items.len == 0) return;

        std.mem.sort(PendingSparseArtifactValidationLoad, pending_artifact_loads.items, {}, struct {
            fn lessThan(_: void, a: PendingSparseArtifactValidationLoad, b: PendingSparseArtifactValidationLoad) bool {
                return std.mem.order(u8, a.artifact_key, b.artifact_key) == .lt;
            }
        }.lessThan);

        const read_keys = try self.alloc.alloc([]const u8, pending_artifact_loads.items.len);
        defer self.alloc.free(read_keys);
        const read_values = try self.alloc.alloc(?[]const u8, pending_artifact_loads.items.len);
        defer self.alloc.free(read_values);
        for (pending_artifact_loads.items, 0..) |item, i| read_keys[i] = item.artifact_key;

        var artifact_read_txn = try store.beginProbeTxn();
        defer artifact_read_txn.abort();
        try artifact_read_txn.getManySorted(read_keys, read_values);

        for (read_values) |maybe_raw| {
            const raw = maybe_raw orelse return error.ArtifactRepairRequired;
            const maybe_view = enrichment_artifact_codec.sparseEmbeddingVectorView(raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return error.ArtifactRepairRequired;
                return err;
            };
            if (maybe_view != null) continue;

            var decoded = enrichment_artifact_codec.decodeSparseEmbeddingAlloc(self.alloc, raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return error.ArtifactRepairRequired;
                return err;
            };
            decoded.deinit(self.alloc);
        }
    }

    fn beginTextBackfill(self: *IndexManager) void {
        const prior = self.text_backfill_active.fetchAdd(1, .acq_rel);
        if (prior != 0) return;

        // A schema-generation rebuild supersedes useful merge work on the
        // currently opened generation. Invalidate already-dispatched work so
        // it cannot publish after the bulk builder has started, and leave the
        // pending bit intact so a still-live index can resume afterwards.
        for (self.text_indexes.items) |*existing| {
            self.text_merge_scheduler.supersedeInFlightForIndex(self.alloc, existing.config.name);
            existing.detachAllMergeDeletionStates();
        }
    }

    fn endTextBackfill(self: *IndexManager) void {
        const prior = self.text_backfill_active.fetchSub(1, .acq_rel);
        std.debug.assert(prior > 0);
    }

    fn backfillTextIndex(self: *IndexManager, store: *docstore_mod.DocStore, entry: *TextIndex, resume_from: ?[]const u8) !void {
        if (builtin.is_test) test_text_backfill_invocations += 1;
        self.beginTextBackfill();
        defer self.endTextBackfill();
        const rebuild_state = self.rebuildState(.full_text, entry.rebuild_root_path, entry.config);
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();

        const lower = try internal_keys.documentRangeLowerAlloc(self.alloc, self.byte_range.start);
        defer self.alloc.free(lower);
        const upper = try internal_keys.documentRangeUpperAlloc(self.alloc, if (self.byte_range.end.len > 0) self.byte_range.end else "");
        defer if (upper) |buf| self.alloc.free(buf);

        var mapped_docs = std.ArrayListUnmanaged(mapper.MapperDoc).empty;
        defer {
            for (mapped_docs.items) |doc| {
                self.alloc.free(@constCast(doc.key));
                self.alloc.free(@constCast(doc.value));
            }
            mapped_docs.deinit(self.alloc);
        }

        var flushed_batches: usize = 0;
        var saw_visible_doc = false;
        var batch_last_doc_key: ?[]const u8 = null;
        defer if (batch_last_doc_key) |buf| self.alloc.free(buf);

        const flush_batch = struct {
            fn run(
                manager: *IndexManager,
                doc_store: *docstore_mod.DocStore,
                text_entry: *TextIndex,
                rebuild: backfill_state_mod.RebuildState,
                docs_buf: *std.ArrayListUnmanaged(mapper.MapperDoc),
                last_doc_key: []const u8,
                flush_count: *usize,
            ) !void {
                const stats = try manager.indexTextProjectionDocsMaybeChunked(doc_store, text_entry, docs_buf.items);
                // Bound fanout without forcing a merge-policy walk after every
                // page. Larger policy batches reduce incremental merge/write
                // amplification while the target generation is unpublished.
                try manager.finalizeTextBatchMutations(text_entry, .{
                    .compact_text = false,
                    .compact_text_segment_threshold = text_backfill_compact_segment_threshold,
                }, stats);
                try rebuild.updateWithIo(manager.checkpointIo(), last_doc_key);
                for (docs_buf.items) |doc| {
                    manager.alloc.free(@constCast(doc.key));
                    manager.alloc.free(@constCast(doc.value));
                }
                docs_buf.clearRetainingCapacity();
                flush_count.* += 1;
                if (@import("builtin").is_test) {
                    if (test_abort_text_backfill_after_batches) |limit| {
                        if (flush_count.* >= limit) return error.TestInjectedBackfillFailure;
                    }
                }
            }
        }.run;

        var scan_lower_buf: ?[]u8 = if (resume_from) |buf| try self.alloc.dupe(u8, buf) else null;
        defer if (scan_lower_buf) |buf| self.alloc.free(buf);
        const backfill_doc_limit = if (@import("builtin").is_test) test_text_backfill_batch_size orelse text_backfill_batch_size else text_backfill_batch_size;
        const backfill_source_target_bytes = textProjectionSourceBuildTargetBytes();
        const scan_budget_per_page = @max(backfill_doc_limit * 2, 256);
        var reached_end = false;

        while (!reached_end) {
            var page_last_seen_key: ?[]u8 = null;
            defer if (page_last_seen_key) |buf| self.alloc.free(buf);

            const ScanState = struct {
                manager: *IndexManager,
                text_entry: *TextIndex,
                lower_exclusive: ?[]const u8,
                mapped_docs: *std.ArrayListUnmanaged(mapper.MapperDoc),
                batch_last_doc_key: *?[]const u8,
                page_last_seen_key: *?[]u8,
                saw_visible_doc: *bool,
                scan_budget: usize,
                doc_limit: usize,
                source_target_bytes: usize,
                source_bytes: usize = 0,
                scanned: usize = 0,
                stopped_early: bool = false,

                fn rememberKey(state: *@This(), key: []const u8) !void {
                    if (state.page_last_seen_key.*) |old| state.manager.alloc.free(old);
                    state.page_last_seen_key.* = try state.manager.alloc.dupe(u8, key);
                }

                fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!backend_scan.ScanAction {
                    const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
                    if (state.lower_exclusive) |exclusive| {
                        if (std.mem.order(u8, key, exclusive) != .gt) return .@"continue";
                    }
                    state.scanned += 1;
                    if (isMetadataKey(key) or !state.manager.keyInRange(key) or !try textIndexShouldConsumeDoc(state.manager, state.text_entry, key)) {
                        try state.rememberKey(key);
                        if (state.scanned >= state.scan_budget) {
                            state.stopped_early = true;
                            return .stop;
                        }
                        return .@"continue";
                    }

                    state.saw_visible_doc.* = true;
                    const doc_id = if (internal_keys.isPrimaryDocumentKey(key))
                        (try internal_keys.decodePrimaryDocumentKeyAlloc(state.manager.alloc, key)) orelse return .@"continue"
                    else
                        try state.manager.alloc.dupe(u8, key);
                    var doc_id_owned = true;
                    errdefer if (doc_id_owned) state.manager.alloc.free(doc_id);
                    const doc_value = try state.manager.alloc.dupe(u8, value);
                    var doc_value_owned = true;
                    errdefer if (doc_value_owned) state.manager.alloc.free(doc_value);

                    const doc_bytes = @sizeOf(mapper.MapperDoc) + doc_id.len + doc_value.len;
                    if (state.mapped_docs.items.len > 0 and state.source_bytes +| doc_bytes > state.source_target_bytes) {
                        // Do not consume this key. The next page resumes after
                        // page_last_seen_key and visits it again. Including the
                        // crossing document here created a one-document tail
                        // segment for almost every rebuild page.
                        state.manager.alloc.free(doc_id);
                        state.manager.alloc.free(doc_value);
                        doc_id_owned = false;
                        doc_value_owned = false;
                        state.stopped_early = true;
                        return .stop;
                    }

                    try state.mapped_docs.append(state.manager.alloc, .{
                        .key = doc_id,
                        .value = doc_value,
                        // Resolve ordinals as one sorted batch in
                        // textProjectionSourceDocsWithOrdinals. A point lookup
                        // here turns a full rebuild into millions of sparse LSM
                        // reads and repeatedly reacquires the backend lock.
                        .doc_ordinal = null,
                    });
                    doc_id_owned = false;
                    doc_value_owned = false;
                    state.source_bytes +|= doc_bytes;
                    try state.rememberKey(key);

                    if (state.batch_last_doc_key.*) |old| state.manager.alloc.free(old);
                    state.batch_last_doc_key.* = try state.manager.alloc.dupe(u8, key);

                    if (state.mapped_docs.items.len >= state.doc_limit or
                        state.source_bytes >= state.source_target_bytes or
                        state.scanned >= state.scan_budget)
                    {
                        state.stopped_early = true;
                        return .stop;
                    }
                    return .@"continue";
                }
            };

            var scan_state = ScanState{
                .manager = self,
                .text_entry = entry,
                .lower_exclusive = scan_lower_buf,
                .mapped_docs = &mapped_docs,
                .batch_last_doc_key = &batch_last_doc_key,
                .page_last_seen_key = &page_last_seen_key,
                .saw_visible_doc = &saw_visible_doc,
                .scan_budget = scan_budget_per_page,
                .doc_limit = backfill_doc_limit,
                .source_target_bytes = backfill_source_target_bytes,
            };
            try backend_scan.scanWithContext(&runtime_store.store, if (scan_lower_buf) |buf| buf else lower, if (upper) |buf| buf else "", .{}, &scan_state, ScanState.scanEntry);
            reached_end = !scan_state.stopped_early or page_last_seen_key == null;

            if (page_last_seen_key) |seen| {
                if (scan_lower_buf) |old| self.alloc.free(old);
                scan_lower_buf = try self.alloc.dupe(u8, seen);
            }

            if (mapped_docs.items.len > 0) {
                try flush_batch(self, store, entry, rebuild_state, &mapped_docs, batch_last_doc_key.?, &flushed_batches);
                if (batch_last_doc_key) |old| self.alloc.free(old);
                batch_last_doc_key = null;
            }
        }

        if (flushed_batches > 0) try self.compactTextIndex(&entry.persistent, activeTextMergePolicy());
        if (!saw_visible_doc or flushed_batches > 0) try rebuild_state.clearWithIo(self.checkpointIo());
        if (flushed_batches > 0) try entry.persistent.checkpointLsmWalAfterDurableBoundary();
    }

    fn backfillTextIndexFromReadTxn(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        read_txn: *docstore_mod.DocStore.Txn,
        entry: *TextIndex,
        resume_from: ?[]const u8,
        cancel_check: ?types.RepairCancelCheck,
        capacity_check: ?types.RepairCapacityCheck,
    ) !void {
        self.beginTextBackfill();
        defer self.endTextBackfill();
        const rebuild_state = self.rebuildState(.full_text, entry.rebuild_root_path, entry.config);

        const lower = try internal_keys.documentRangeLowerAlloc(self.alloc, self.byte_range.start);
        defer self.alloc.free(lower);
        const upper = try internal_keys.documentRangeUpperAlloc(self.alloc, if (self.byte_range.end.len > 0) self.byte_range.end else "");
        defer if (upper) |buf| self.alloc.free(buf);

        var mapped_docs = std.ArrayListUnmanaged(mapper.MapperDoc).empty;
        defer {
            for (mapped_docs.items) |doc| {
                self.alloc.free(@constCast(doc.key));
                self.alloc.free(@constCast(doc.value));
            }
            mapped_docs.deinit(self.alloc);
        }

        var flushed_batches: usize = 0;
        var saw_visible_doc = false;
        var batch_last_doc_key: ?[]const u8 = null;
        defer if (batch_last_doc_key) |buf| self.alloc.free(buf);

        const flush_batch = struct {
            fn run(
                manager: *IndexManager,
                doc_store: *docstore_mod.DocStore,
                text_entry: *TextIndex,
                rebuild: backfill_state_mod.RebuildState,
                docs_buf: *std.ArrayListUnmanaged(mapper.MapperDoc),
                last_doc_key: []const u8,
                flush_count: *usize,
                identity_txn: *docstore_mod.DocStore.Txn,
                check: ?types.RepairCancelCheck,
                capacity: ?types.RepairCapacityCheck,
            ) !void {
                try checkRepairCancelled(check);
                if (capacity) |admission| try admission.boundary();

                // Keep repair/backfill generation consistency while replacing
                // per-document point reads with one sorted LSM batch lookup.
                const doc_ids = try manager.alloc.alloc([]const u8, docs_buf.items.len);
                defer manager.alloc.free(doc_ids);
                for (docs_buf.items, 0..) |doc, i| doc_ids[i] = doc.key;
                const ordinals = try doc_identity.lookupOrdinalsTxnAlloc(manager.alloc, identity_txn, doc_ids);
                defer manager.alloc.free(ordinals);
                for (docs_buf.items, ordinals) |*doc, ordinal| doc.doc_ordinal = ordinal;

                const stats = try manager.indexTextProjectionDocsMaybeChunked(doc_store, text_entry, docs_buf.items);
                try manager.finalizeTextBatchMutations(text_entry, .{
                    .compact_text = false,
                    .compact_text_segment_threshold = text_backfill_compact_segment_threshold,
                }, stats);
                try rebuild.updateWithIo(manager.checkpointIo(), last_doc_key);
                for (docs_buf.items) |doc| {
                    manager.alloc.free(@constCast(doc.key));
                    manager.alloc.free(@constCast(doc.value));
                }
                docs_buf.clearRetainingCapacity();
                flush_count.* += 1;
                if (@import("builtin").is_test) {
                    if (test_abort_text_backfill_after_batches) |limit| {
                        if (flush_count.* >= limit) return error.TestInjectedBackfillFailure;
                    }
                }
            }
        }.run;

        var scan_lower_buf: ?[]u8 = if (resume_from) |buf| try self.alloc.dupe(u8, buf) else null;
        defer if (scan_lower_buf) |buf| self.alloc.free(buf);
        const backfill_doc_limit = if (@import("builtin").is_test) test_text_backfill_batch_size orelse text_backfill_batch_size else text_backfill_batch_size;
        const backfill_source_target_bytes = textProjectionSourceBuildTargetBytes();
        const scan_budget_per_page = @max(backfill_doc_limit * 2, 256);
        var reached_end = false;

        while (!reached_end) {
            try checkRepairCancelled(cancel_check);
            var page_last_seen_key: ?[]u8 = null;
            defer if (page_last_seen_key) |buf| self.alloc.free(buf);

            const ScanState = struct {
                manager: *IndexManager,
                text_entry: *TextIndex,
                lower_exclusive: ?[]const u8,
                mapped_docs: *std.ArrayListUnmanaged(mapper.MapperDoc),
                batch_last_doc_key: *?[]const u8,
                page_last_seen_key: *?[]u8,
                saw_visible_doc: *bool,
                scan_budget: usize,
                doc_limit: usize,
                source_target_bytes: usize,
                source_bytes: usize = 0,
                scanned: usize = 0,
                stopped_early: bool = false,

                fn rememberKey(state: *@This(), key: []const u8) !void {
                    if (state.page_last_seen_key.*) |old| state.manager.alloc.free(old);
                    state.page_last_seen_key.* = try state.manager.alloc.dupe(u8, key);
                }

                fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                    const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
                    if (state.lower_exclusive) |exclusive| {
                        if (std.mem.order(u8, key, exclusive) != .gt) return .@"continue";
                    }
                    state.scanned += 1;
                    if (isMetadataKey(key) or !state.manager.keyInRange(key) or !try textIndexShouldConsumeDoc(state.manager, state.text_entry, key)) {
                        try state.rememberKey(key);
                        if (state.scanned >= state.scan_budget) {
                            state.stopped_early = true;
                            return .stop;
                        }
                        return .@"continue";
                    }

                    state.saw_visible_doc.* = true;
                    const doc_id = if (internal_keys.isPrimaryDocumentKey(key))
                        (try internal_keys.decodePrimaryDocumentKeyAlloc(state.manager.alloc, key)) orelse return .@"continue"
                    else
                        try state.manager.alloc.dupe(u8, key);
                    var doc_id_owned = true;
                    errdefer if (doc_id_owned) state.manager.alloc.free(doc_id);
                    const doc_value = try state.manager.alloc.dupe(u8, value);
                    var doc_value_owned = true;
                    errdefer if (doc_value_owned) state.manager.alloc.free(doc_value);

                    const doc_bytes = @sizeOf(mapper.MapperDoc) + doc_id.len + doc_value.len;
                    if (state.mapped_docs.items.len > 0 and state.source_bytes +| doc_bytes > state.source_target_bytes) {
                        state.manager.alloc.free(doc_id);
                        state.manager.alloc.free(doc_value);
                        doc_id_owned = false;
                        doc_value_owned = false;
                        state.stopped_early = true;
                        return .stop;
                    }

                    try state.mapped_docs.append(state.manager.alloc, .{
                        .key = doc_id,
                        .value = doc_value,
                        // Resolve the whole page with getManySorted when the
                        // projection batch is built. The identity mapping is
                        // stable for the lifetime of a document ordinal.
                        .doc_ordinal = null,
                    });
                    doc_id_owned = false;
                    doc_value_owned = false;
                    state.source_bytes +|= doc_bytes;
                    try state.rememberKey(key);

                    if (state.batch_last_doc_key.*) |old| state.manager.alloc.free(old);
                    state.batch_last_doc_key.* = try state.manager.alloc.dupe(u8, key);

                    if (state.mapped_docs.items.len >= state.doc_limit or
                        state.source_bytes >= state.source_target_bytes or
                        state.scanned >= state.scan_budget)
                    {
                        state.stopped_early = true;
                        return .stop;
                    }
                    return .@"continue";
                }
            };

            var scan_state = ScanState{
                .manager = self,
                .text_entry = entry,
                .lower_exclusive = scan_lower_buf,
                .mapped_docs = &mapped_docs,
                .batch_last_doc_key = &batch_last_doc_key,
                .page_last_seen_key = &page_last_seen_key,
                .saw_visible_doc = &saw_visible_doc,
                .scan_budget = scan_budget_per_page,
                .doc_limit = backfill_doc_limit,
                .source_target_bytes = backfill_source_target_bytes,
            };
            try store.scanReadTxnWithContext(read_txn, if (scan_lower_buf) |buf| buf else lower, if (upper) |buf| buf else "", .{}, &scan_state, ScanState.scanEntry);
            reached_end = !scan_state.stopped_early or page_last_seen_key == null;

            if (page_last_seen_key) |seen| {
                if (scan_lower_buf) |old| self.alloc.free(old);
                scan_lower_buf = try self.alloc.dupe(u8, seen);
            }

            if (mapped_docs.items.len > 0) {
                try flush_batch(
                    self,
                    store,
                    entry,
                    rebuild_state,
                    &mapped_docs,
                    batch_last_doc_key.?,
                    &flushed_batches,
                    read_txn,
                    cancel_check,
                    capacity_check,
                );
                if (batch_last_doc_key) |old| self.alloc.free(old);
                batch_last_doc_key = null;
            }
        }

        if (flushed_batches > 0) try self.compactTextIndex(&entry.persistent, activeTextMergePolicy());
        if (!saw_visible_doc or flushed_batches > 0) try rebuild_state.clearWithIo(self.checkpointIo());
        if (flushed_batches > 0) try entry.persistent.checkpointLsmWalAfterDurableBoundary();
    }

    fn indexPath(self: *const IndexManager, name: []const u8) ![]u8 {
        return std.fmt.allocPrint(self.alloc, "{s}/indexes/{s}", .{ self.base_path, name });
    }

    fn provisionConfiguredIndexDirDurable(self: *IndexManager, cfg: types.IndexConfig) !void {
        const storage = switch (cfg.kind) {
            .full_text => self.text_lsm_storage,
            .dense_vector => self.dense_lsm_storage,
            .sparse_vector => self.sparse_lsm_storage,
            .graph => self.graph_lsm_storage,
            .algebraic => return,
        };
        const path = try self.indexPath(cfg.name);
        defer self.alloc.free(path);

        if (storage) |lsm_storage| {
            const parent_path = try std.fmt.allocPrint(self.alloc, "{s}/indexes", .{self.base_path});
            defer self.alloc.free(parent_path);

            // A catalog row must not become durable before the namespace that
            // will hold its generation. Descendant file syncs cannot make an
            // unsynced ancestor durable, so publish each structural boundary.
            try lsm_storage.createDirPath(self.base_path);
            try lsm_storage.syncParentAbsolute(self.base_path);
            try lsm_storage.createDirPath(parent_path);
            try lsm_storage.syncParentAbsolute(parent_path);
            try lsm_storage.createDirPath(path);
            try lsm_storage.syncParentAbsolute(path);
            return;
        }

        try ensureIndexDirDurable(self.alloc, self.io, self.base_path, path);
    }

    fn prepareStorageForFreshCatalogEntry(self: *IndexManager, store: anytype, cfg: types.IndexConfig) !void {
        // Artifact records use public names, so a delayed retire operation and
        // a replacement generation cannot safely mutate them concurrently.
        if (try self.pendingGeneratedArtifactCleanupIndexForConfigAlloc(store, cfg)) |retired_name| {
            self.alloc.free(retired_name);
            return error.IndexArtifactCleanupPending;
        }
        const canonical_path = try self.indexPath(cfg.name);
        defer self.alloc.free(canonical_path);
        const active_path = try self.activeIndexPath(cfg.name);
        defer self.alloc.free(active_path);
        if (!std.mem.eql(u8, active_path, canonical_path)) {
            self.invalidateIndexPathCaches(active_path);
            try self.deleteIndexDirUsingIoIfPresentFallible(active_path);
        }
        self.invalidateIndexPathCaches(canonical_path);
        try self.deleteIndexDirUsingIoIfPresentFallible(canonical_path);
        if (cfg.kind == .dense_vector) try self.deleteDenseIndexMetadata(store, cfg.name);
        try apply_state.clearAppliedSequenceWithCheckpoint(self.alloc, self.checkpointIo(), store, self.applied_sequence_checkpoint_path, cfg.name);
    }

    fn invalidateIndexPathCaches(self: *const IndexManager, path: []const u8) void {
        if (self.lsm_cache) |cache| cache.invalidatePrefix(path);
        if (self.hbc_cache) |cache| cache.invalidatePath(path);
    }

    fn deleteIndexDirUsingIoIfPresent(self: *const IndexManager, path: []const u8) void {
        self.deleteIndexDirUsingIoIfPresentFallible(path) catch {};
    }

    fn deleteIndexDirUsingIoIfPresentFallible(self: *const IndexManager, path: []const u8) !void {
        if (builtin.os.tag == .freestanding) return;
        if (self.io) |io| {
            try std.Io.Dir.cwd().deleteTree(io, path);
            return;
        }
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        try std.Io.Dir.cwd().deleteTree(io_impl.io(), path);
    }

    fn activeIndexRootPointerPath(self: *const IndexManager, canonical_path: []const u8) ![]u8 {
        return std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ canonical_path, active_index_root_pointer_file });
    }

    pub fn writeRepairShadowInProgressMarker(alloc: Allocator, shadow_root_path: []const u8) !void {
        if (builtin.os.tag == .freestanding) return;
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        try fs_paths.createDirPathPortable(io, shadow_root_path);
        const marker_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ shadow_root_path, repair_shadow_in_progress_file });
        defer alloc.free(marker_path);
        const payload = if (platform.process.currentId()) |pid|
            try std.fmt.allocPrint(alloc, "{s}pid={d}\n", .{ repair_shadow_in_progress_magic, pid })
        else
            try std.fmt.allocPrint(alloc, "{s}pid=unknown\n", .{repair_shadow_in_progress_magic});
        defer alloc.free(payload);
        try writeFileAtomicallyDurable(alloc, io, marker_path, payload);
    }

    pub fn clearRepairShadowInProgressMarker(alloc: Allocator, shadow_root_path: []const u8) !void {
        if (builtin.os.tag == .freestanding) return;
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        const marker_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ shadow_root_path, repair_shadow_in_progress_file });
        defer alloc.free(marker_path);
        std.Io.Dir.cwd().deleteFile(io, marker_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        };
        try fs_paths.syncDirPortable(io, shadow_root_path);
    }

    fn readActiveIndexRootPointer(self: *const IndexManager, canonical_path: []const u8, name: []const u8) !?[]u8 {
        if (builtin.os.tag == .freestanding) return null;
        const marker_path = try self.activeIndexRootPointerPath(canonical_path);
        defer self.alloc.free(marker_path);

        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const raw = std.Io.Dir.cwd().readFileAlloc(io_impl.io(), marker_path, self.alloc, .limited(4096)) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => return err,
        };
        defer self.alloc.free(raw);
        if (!std.mem.startsWith(u8, raw, active_index_root_pointer_magic)) return error.InvalidIndexRootPointer;
        const trimmed = std.mem.trim(u8, raw[active_index_root_pointer_magic.len..], "\r\n");
        if (trimmed.len == 0) return error.InvalidIndexRootPointer;
        if (!validRelativeRepairIndexRoot(name, trimmed)) return error.InvalidIndexRootPointer;
        return try self.alloc.dupe(u8, trimmed);
    }

    /// Algebraic data lives in the primary store, so its physical namespace
    /// must follow the same active-root pointer as filesystem-backed indexes.
    /// New indexes always use an explicit generation; there is intentionally
    /// no logical-name/legacy fallback.
    fn algebraicStorageNamespaceAlloc(self: *const IndexManager, name: []const u8) ![]u8 {
        const canonical_path = try self.indexPath(name);
        defer self.alloc.free(canonical_path);
        if (try self.readActiveIndexRootPointer(canonical_path, name)) |relative| {
            defer self.alloc.free(relative);
            const separator = std.mem.indexOfScalar(u8, relative, '/') orelse return error.InvalidIndexRootPointer;
            return try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ relative[0..separator], name });
        }

        const base_name = std.fs.path.basename(self.base_path);
        const generation = if (std.mem.startsWith(u8, base_name, repair_shadow_root_prefix))
            base_name
        else
            canonical_algebraic_generation;
        return try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ generation, name });
    }

    fn writeActiveIndexRootPointer(self: *const IndexManager, canonical_path: []const u8, relative_active_path: []const u8) !void {
        if (builtin.os.tag == .freestanding) return;
        if (!validRelativeRepairIndexRoot(std.fs.path.basename(canonical_path), relative_active_path)) return error.InvalidIndexRootPointer;
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        try fs_paths.createDirPathPortable(io, canonical_path);
        const marker_path = try self.activeIndexRootPointerPath(canonical_path);
        defer self.alloc.free(marker_path);
        const payload = try std.fmt.allocPrint(self.alloc, "{s}{s}\n", .{ active_index_root_pointer_magic, relative_active_path });
        defer self.alloc.free(payload);
        try writeFileAtomicallyDurable(self.alloc, io, marker_path, payload);
    }

    fn clearActiveIndexRootPointer(self: *const IndexManager, canonical_path: []const u8) !void {
        if (builtin.os.tag == .freestanding) return;
        const marker_path = try self.activeIndexRootPointerPath(canonical_path);
        defer self.alloc.free(marker_path);

        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        std.Io.Dir.cwd().deleteFile(io, marker_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        };
        const parent = std.fs.path.dirname(marker_path) orelse ".";
        try fs_paths.syncDirPortable(io, parent);
    }

    fn activeIndexPath(self: *const IndexManager, name: []const u8) ![]u8 {
        const canonical_path = try self.indexPath(name);
        errdefer self.alloc.free(canonical_path);
        if (try self.readActiveIndexRootPointer(canonical_path, name)) |relative_active_path| {
            defer self.alloc.free(relative_active_path);
            const active_path = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ self.base_path, relative_active_path });
            self.alloc.free(canonical_path);
            return active_path;
        }
        return canonical_path;
    }

    /// Storage-sized estimate for rebuilding one index. This intentionally
    /// measures the selected index generation rather than the entire table DB;
    /// node admission adds separate replay and cleanup headroom.
    pub fn activeIndexStorageBytes(self: *const IndexManager, name: []const u8) !u64 {
        for (self.algebraic_indexes.items) |*entry| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            const store = self.primary_store orelse return error.PrimaryStoreUnavailable;
            return try entry.index.storageBytes(store);
        }
        for (self.status_only_index_configs) |cfg| {
            if (cfg.kind != .algebraic or !std.mem.eql(u8, cfg.name, name)) continue;
            const storage_namespace = try self.algebraicStorageNamespaceAlloc(name);
            defer self.alloc.free(storage_namespace);
            return try self.algebraicStorageNamespaceBytes(storage_namespace);
        }
        const path = try self.activeIndexPath(name);
        defer self.alloc.free(path);
        if (builtin.os.tag == .freestanding) return 0;
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        var dir = std.Io.Dir.cwd().openDir(io, path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return 0,
            else => return err,
        };
        defer dir.close(io);
        var walker = try dir.walk(self.alloc);
        defer walker.deinit();
        var total: u64 = 0;
        while (try walker.next(io)) |entry| {
            if (entry.kind != .file) continue;
            const stat = try dir.statFile(io, entry.path, .{});
            total +|= stat.size;
        }
        return total;
    }

    pub fn algebraicStorageNamespaceBytes(self: *const IndexManager, storage_namespace: []const u8) !u64 {
        const store = self.primary_store orelse return error.PrimaryStoreUnavailable;
        const key = try algebraic_mod.index.storageBytesKeyAlloc(self.alloc, storage_namespace);
        defer self.alloc.free(key);
        const raw = store.get(self.alloc, key) catch |err| switch (err) {
            error.NotFound => return 0,
            else => return err,
        };
        defer self.alloc.free(raw);
        if (raw.len != @sizeOf(u64)) return error.InvalidAlgebraicStorageByteCounter;
        return std.mem.readInt(u64, raw[0..@sizeOf(u64)], .little);
    }

    /// A pointer-selected generation is publication state, not an empty index
    /// location. Validate its durable ready manifest before any backend open
    /// can create missing files or accept a stale/corrupt candidate.
    fn activeIndexPathForConfig(self: *const IndexManager, cfg: types.IndexConfig) ![]u8 {
        const canonical_path = try self.indexPath(cfg.name);
        errdefer self.alloc.free(canonical_path);
        const relative_active_path = (try self.readActiveIndexRootPointer(canonical_path, cfg.name)) orelse return canonical_path;
        defer self.alloc.free(relative_active_path);
        const active_path = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ self.base_path, relative_active_path });
        errdefer self.alloc.free(active_path);
        _ = try index_generation_manifest.validateReady(
            self.alloc,
            active_path,
            null,
            cfg.name,
            types.indexConfigHash(cfg),
        );
        self.alloc.free(canonical_path);
        return active_path;
    }

    fn relativeRepairIndexRootForActivePath(self: *const IndexManager, name: []const u8, active_path: []const u8) ![]u8 {
        if (!std.mem.startsWith(u8, active_path, self.base_path)) return error.InvalidIndexRootPointer;
        if (active_path.len <= self.base_path.len or active_path[self.base_path.len] != '/') return error.InvalidIndexRootPointer;
        const relative = active_path[self.base_path.len + 1 ..];
        if (!validRelativeRepairIndexRoot(name, relative)) return error.InvalidIndexRootPointer;
        return try self.alloc.dupe(u8, relative);
    }

    fn collectActiveRepairShadowRoots(self: *IndexManager, active_roots: *std.StringHashMapUnmanaged(void)) !void {
        for (self.text_indexes.items) |entry| try self.collectActiveRepairShadowRoot(active_roots, entry.config.name);
        for (self.dense_indexes.items) |entry| try self.collectActiveRepairShadowRoot(active_roots, entry.config.name);
        for (self.sparse_indexes.items) |entry| try self.collectActiveRepairShadowRoot(active_roots, entry.config.name);
        for (self.graph_indexes.items) |entry| try self.collectActiveRepairShadowRoot(active_roots, entry.config.name);
        for (self.algebraic_indexes.items) |entry| try self.collectActiveRepairShadowRoot(active_roots, entry.config.name);
        for (self.status_only_index_configs) |cfg| try self.collectActiveRepairShadowRoot(active_roots, cfg.name);
    }

    fn collectActiveRepairShadowRoot(
        self: *IndexManager,
        active_roots: *std.StringHashMapUnmanaged(void),
        index_name: []const u8,
    ) !void {
        const canonical_path = try self.indexPath(index_name);
        defer self.alloc.free(canonical_path);
        const relative = (try self.readActiveIndexRootPointer(canonical_path, index_name)) orelse return;
        defer self.alloc.free(relative);
        var iter = std.mem.splitScalar(u8, relative, '/');
        const root = iter.next() orelse return;
        if (active_roots.contains(root)) return;
        try active_roots.put(self.alloc, try self.alloc.dupe(u8, root), {});
    }

    fn deleteIndexRootForName(self: *const IndexManager, name: []const u8, canonical_path: []const u8) void {
        self.invalidateIndexRootForName(name, canonical_path);
        const active_path = self.activeIndexPath(name) catch null;
        defer if (active_path) |path| self.alloc.free(path);
        if (active_path) |path| {
            if (!std.mem.eql(u8, path, canonical_path)) self.deleteIndexDirUsingIoIfPresent(path);
        }
        self.deleteIndexDirUsingIoIfPresent(canonical_path);
    }

    fn invalidateIndexRootForName(self: *const IndexManager, name: []const u8, canonical_path: []const u8) void {
        const active_path = self.activeIndexPath(name) catch null;
        defer if (active_path) |path| self.alloc.free(path);
        if (active_path) |path| {
            self.invalidateIndexPathCaches(path);
        }
        self.invalidateIndexPathCaches(canonical_path);
    }

    fn pruneCanonicalIndexRootAfterPointerInstall(canonical_path: []const u8) !void {
        if (builtin.os.tag == .freestanding) return;
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        const io = io_impl.io();
        var dir = std.Io.Dir.cwd().openDir(io, canonical_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return,
            else => return err,
        };
        defer dir.close(io);

        var iter = dir.iterate();
        while (try iter.next(io)) |entry| {
            if (std.mem.eql(u8, entry.name, active_index_root_pointer_file)) continue;
            switch (entry.kind) {
                .directory => try dir.deleteTree(io, entry.name),
                else => try dir.deleteFile(io, entry.name),
            }
        }
        try fs_paths.syncDirPortable(io, canonical_path);
    }

    fn configRequiresEnrichmentReplay(self: *const IndexManager, cfg: types.IndexConfig) !bool {
        switch (cfg.kind) {
            .dense_vector => {
                if (try parseDenseGeneratorConfig(self.alloc, cfg.config_json)) |generator| {
                    defer generator.deinit(self.alloc);
                    return true;
                }
                const dense_cfg = try parseDenseConfig(self.alloc, cfg.config_json);
                defer dense_cfg.deinit(self.alloc);
                return dense_cfg.embedding_name != null and !dense_cfg.external and self.getEnrichment(.embedding, dense_cfg.embedding_name.?) != null;
            },
            .sparse_vector => {
                if (try parseSparseGeneratorConfig(self.alloc, cfg.config_json)) |generator| {
                    defer generator.deinit(self.alloc);
                    return true;
                }
                return false;
            },
            else => return false,
        }
    }

    fn saveBackfilledAppliedSequence(self: *IndexManager, store: anytype, cfg: types.IndexConfig) !void {
        if (try self.configRequiresEnrichmentReplay(cfg)) return;
        if (try self.configHasPendingSparseEmbeddingArtifactReplay(store, cfg)) return;
        // Backfill rebuilds the index from the full store contents, so it is
        // current through the store's durable per-kind latest replay marker
        // even when the replay records themselves have already been pruned.
        // On a fresh instance with pruned records lastReplaySequence(0) is 0;
        // saving that alone regresses the checkpoint below the marker and
        // traps startup catch-up in a permanent-debt loop that re-backfills
        // and re-regresses forever.
        var backfilled_sequence = store.lastReplaySequence(0);
        if (comptime storeSupportsLatestReplaySequenceForHint(@TypeOf(store))) {
            backfilled_sequence = try store.latestReplaySequenceForHint(replayHintForIndexKind(cfg.kind), backfilled_sequence);
        }
        try apply_state.saveAppliedSequenceUpdateWithCheckpoint(
            self.alloc,
            self.checkpointIo(),
            store,
            self.applied_sequence_checkpoint_path,
            .{
                .index_name = cfg.name,
                .sequence = backfilled_sequence,
                .config_hash = types.indexConfigHash(cfg),
            },
        );
    }

    fn storeSupportsLatestReplaySequenceForHint(comptime T: type) bool {
        return switch (@typeInfo(T)) {
            .pointer => |ptr| @hasDecl(ptr.child, "latestReplaySequenceForHint"),
            .@"struct" => @hasDecl(T, "latestReplaySequenceForHint"),
            else => false,
        };
    }

    fn replayHintForIndexKind(kind: types.IndexKind) change_journal_mod.TargetHint {
        return switch (kind) {
            .full_text => .full_text,
            .dense_vector => .dense_vector,
            .sparse_vector => .sparse_vector,
            .graph => .graph,
            .algebraic => .algebraic,
        };
    }

    fn configHasPendingSparseEmbeddingArtifactReplay(self: *IndexManager, store: anytype, cfg: types.IndexConfig) !bool {
        if (cfg.kind != .sparse_vector) return false;
        const expected_embedding_name = try self.sparseConfigEmbeddingNameAlloc(cfg);
        defer self.alloc.free(expected_embedding_name);

        const Context = struct {
            alloc: Allocator,
            expected_embedding_name: []const u8,
            found: bool = false,

            fn handle(ctx: *@This(), _: u64, payload: []const u8) !void {
                if (ctx.found) return;
                var decoded = try change_journal_mod.decodeRecord(ctx.alloc, payload);
                defer decoded.deinit();
                for (decoded.record.changed_artifact_keys) |artifact_key| {
                    if (internal_keys.isEmbeddingArtifactKey(artifact_key) and internal_keys.matchesEmbeddingArtifactName(artifact_key, ctx.expected_embedding_name)) {
                        ctx.found = true;
                        return;
                    }
                    if (internal_keys.isDerivedEmbeddingArtifactKey(artifact_key) and internal_keys.matchesDerivedEmbeddingArtifactName(artifact_key, ctx.expected_embedding_name)) {
                        ctx.found = true;
                        return;
                    }
                }
            }
        };

        var ctx = Context{
            .alloc = self.alloc,
            .expected_embedding_name = expected_embedding_name,
        };
        store.forEachReplayEntryFromHint(0, .sparse_vector, &ctx, Context.handle) catch |err| switch (err) {
            error.ReplayIndexUnavailable => return false,
            else => return err,
        };
        return ctx.found;
    }

    fn sparseConfigEmbeddingNameAlloc(self: *IndexManager, cfg: types.IndexConfig) ![]u8 {
        if (try parseSparseGeneratorConfig(self.alloc, cfg.config_json)) |generator| {
            defer generator.deinit(self.alloc);
            if (generator.embedding_name) |embedding_name| return try self.alloc.dupe(u8, embedding_name);
        }
        return try self.alloc.dupe(u8, cfg.name);
    }

    fn appendOpenedIndex(self: *IndexManager, opened: OpenedIndex) !void {
        switch (opened) {
            .full_text => |entry| {
                try self.text_indexes.append(self.alloc, entry);
                if (entry.compaction_pending.load(.acquire)) {
                    TextMergeScheduler.schedule(&self.text_indexes.items[self.text_indexes.items.len - 1]);
                }
            },
            .dense_vector => |entry| try self.dense_indexes.append(self.alloc, entry),
            .sparse_vector => |entry| try self.sparse_indexes.append(self.alloc, entry),
            .graph => |entry| try self.graph_indexes.append(self.alloc, entry),
            .algebraic => |entry| try self.algebraic_indexes.append(self.alloc, entry),
        }
    }

    fn ensureConfiguredIndexDir(self: *IndexManager, cfg: types.IndexConfig) !void {
        const path = try self.indexPath(cfg.name);
        defer self.alloc.free(path);

        switch (cfg.kind) {
            .full_text => {
                if (self.text_lsm_storage == null) {
                    try ensureIndexDir(self.alloc, self.base_path, path);
                }
            },
            .dense_vector => {
                if (self.dense_lsm_storage == null) {
                    try ensureIndexDir(self.alloc, self.base_path, path);
                }
            },
            .sparse_vector => {
                if (self.sparse_lsm_storage == null) {
                    try ensureIndexDir(self.alloc, self.base_path, path);
                }
            },
            .graph => {
                if (self.graph_lsm_storage == null) {
                    try ensureIndexDir(self.alloc, self.base_path, path);
                }
            },
            .algebraic => {},
        }
    }

    fn openConfiguredIndex(self: *IndexManager, store: anytype, cfg: types.IndexConfig, allow_backfill: bool, read_only: bool) !void {
        try self.beginIndexLoadNoLock(cfg.name);
        defer self.completeIndexLoadNoLock(cfg.name);
        try self.ensureConfiguredIndexDir(cfg);
        var opened = try self.openConfiguredIndexDetached(store, cfg, allow_backfill, read_only);
        errdefer opened.deinit(self);
        try self.appendOpenedIndex(opened);
        if (cfg.kind == .algebraic) {
            if (comptime @TypeOf(store) == *docstore_mod.DocStore) {
                if (self.algebraicIndex(cfg.name)) |entry| {
                    entry.index.loadAdaptiveHllCardinalities(store) catch |err| {
                        std.log.warn("adaptive HLL registry recovery failed index={s} err={s}", .{ cfg.name, @errorName(err) });
                    };
                    entry.index.resumeHllMaintenance(store);
                }
            }
        }
    }

    fn openConfiguredIndexDetached(self: *IndexManager, store: anytype, cfg_input: types.IndexConfig, allow_backfill: bool, read_only: bool) !OpenedIndex {
        if (test_inject_index_open_error) |err| return err;
        var cfg = cfg_input;
        try populateCoverageConfigFingerprint(self.alloc, &cfg);
        try self.ensureConfiguredIndexDir(cfg);
        switch (cfg.kind) {
            .full_text => {
                const managed_admission_pending = self.managedAdmissionPending(cfg.name);
                const allow_full_text_backfill = allow_backfill and !managed_admission_pending;
                const started_ns = nowNs();
                var backfill_ns: u64 = 0;
                const text_cfg = try parseTextConfig(self.alloc, cfg.config_json);
                defer text_cfg.deinit(self.alloc);

                const path = try self.activeIndexPathForConfig(cfg);
                defer self.alloc.free(path);

                const zpath = try self.alloc.dupeZ(u8, path);
                defer self.alloc.free(zpath);

                const persistent_opts = persistent_mod.PersistentIndexOptions{
                    .path = zpath,
                    .main_backend = self.text_main_backend,
                    .main_lsm_storage = self.text_lsm_storage,
                    .wal_storage = self.text_lsm_storage,
                    .main_lsm_options = self.text_main_lsm_options,
                    .wal_lsm_options = self.text_wal_lsm_options,
                    .lsm_cache = self.lsm_cache,
                    .lsm_root_generation = self.lsm_root_generation,
                    .read_only = read_only,
                    .main_no_sync = self.relaxed_split_durability,
                    .main_no_meta_sync = self.relaxed_split_durability,
                    .wal_no_sync = self.relaxed_split_durability,
                };
                var persistent = openTextPersistentIndexWithRetry(self.alloc, persistent_opts) catch |err| {
                    std.log.warn("full_text open failed step=persistent_open name={s} err={s}", .{
                        cfg.name,
                        @errorName(err),
                    });
                    return err;
                };
                if (self.resource_manager) |manager| persistent.attachResourceManager(manager);
                var persistent_moved = false;
                errdefer if (!persistent_moved) persistent.close();
                const runtime_schema = loadRuntimeSchemaForTextIndex(self.alloc, store, cfg.name) catch |err| {
                    std.log.warn("full_text open failed step=runtime_schema name={s} err={s}", .{
                        cfg.name,
                        @errorName(err),
                    });
                    return err;
                };
                var runtime_schema_moved = false;
                errdefer if (!runtime_schema_moved) {
                    if (runtime_schema) |schema| schema_mod.freeSchema(self.alloc, schema);
                };
                const projection_provenance = try TextProjectionProvenance.fromRuntimeSchema(
                    self.alloc,
                    cfg,
                    runtime_schema,
                );
                ensureTextProjectionProvenance(self.alloc, &persistent, projection_provenance, read_only) catch |err| {
                    std.log.warn("full_text open failed step=projection_provenance name={s} err={s}", .{
                        cfg.name,
                        @errorName(err),
                    });
                    return err;
                };
                var text_analysis = parseTextAnalysisForIndexConfig(self.alloc, cfg.config_json, runtime_schema) catch |err| {
                    std.log.warn("full_text open failed step=text_analysis name={s} err={s}", .{
                        cfg.name,
                        @errorName(err),
                    });
                    return err;
                };
                var text_analysis_moved = false;
                errdefer if (!text_analysis_moved) introducer_mod.freeTextAnalysisConfig(self.alloc, text_analysis);
                const observed_field_analyzers = loadObservedTextFieldAnalyzers(self.alloc, store, cfg.name) catch |err| {
                    std.log.warn("full_text open failed step=observed_field_analyzers name={s} err={s}", .{
                        cfg.name,
                        @errorName(err),
                    });
                    return err;
                };
                var observed_field_analyzers_moved = false;
                errdefer if (!observed_field_analyzers_moved) freeObservedTextFieldAnalyzers(self.alloc, observed_field_analyzers);
                try appendObservedFieldAnalyzers(self.alloc, &text_analysis, observed_field_analyzers);
                if (!read_only) try publishFullTextDictionaryRegistry(store, self.alloc, cfg.name, text_analysis);
                const apply_mutex = try self.allocIndexApplyMutex();
                var apply_mutex_owned = true;
                errdefer if (apply_mutex_owned) self.destroyIndexApplyMutex(apply_mutex);

                var entry = TextIndex{
                    .instance_id = self.allocateTextIndexInstanceId(),
                    .apply_mutex = apply_mutex,
                    .config = try types.IndexConfig.clone(self.alloc, cfg),
                    .chunk_name = if (text_cfg.source_artifact_name) |name| try self.alloc.dupe(u8, name) else null,
                    .text_analysis = text_analysis,
                    .observed_field_analyzers = observed_field_analyzers,
                    .runtime_schema = runtime_schema,
                    .rebuild_root_path = try self.alloc.dupe(u8, path),
                    .persistent = persistent,
                };
                apply_mutex_owned = false;
                persistent_moved = true;
                runtime_schema_moved = true;
                text_analysis_moved = true;
                observed_field_analyzers_moved = true;
                errdefer {
                    self.freeTextIndexEntry(&entry);
                }

                const persisted_ranges = entry.persistent.activeSegmentRanges(self.alloc) catch |err| {
                    std.log.warn("full_text open failed step=active_segment_ranges name={s} err={s}", .{
                        cfg.name,
                        @errorName(err),
                    });
                    return err;
                };
                defer {
                    for (persisted_ranges) |*range| range.deinit(self.alloc);
                    self.alloc.free(persisted_ranges);
                }

                const rebuild_state = self.rebuildState(.full_text, entry.rebuild_root_path, entry.config);
                var resume_from = rebuild_state.checkWithIo(self.alloc, self.checkpointIo()) catch |err| {
                    std.log.warn("full_text open failed step=rebuild_state_check name={s} err={s}", .{
                        cfg.name,
                        @errorName(err),
                    });
                    return err;
                };
                defer if (resume_from) |buf| self.alloc.free(buf);

                var rebuild_from_scratch_after_interruption = false;
                if (allow_full_text_backfill and resume_from != null) {
                    try entry.persistent.resetAllForRebuild();
                    self.alloc.free(resume_from.?);
                    resume_from = null;
                    rebuild_from_scratch_after_interruption = true;
                }

                if (allow_full_text_backfill and (rebuild_from_scratch_after_interruption or resume_from != null or (entry.persistent.snapshot().liveDocCount() == 0 and persisted_ranges.len == 0))) {
                    const backfill_started_ns = nowNs();
                    try rebuild_state.updateWithIo(self.checkpointIo(), if (resume_from) |buf| buf else "");
                    try self.backfillTextIndex(store, &entry, resume_from);
                    try self.saveBackfilledAppliedSequence(store, cfg);
                    backfill_ns += elapsedSince(backfill_started_ns);
                }

                entry.compaction_pending.store(
                    try self.textIndexNeedsMerge(&entry.persistent, activeTextMergePolicy()),
                    .release,
                );
                if (openProfileEnabled()) {
                    logOpenIndexProfile(.{
                        .kind = cfg.kind,
                        .name = cfg.name,
                        .open_ns = elapsedSince(started_ns) -| backfill_ns,
                        .backfill_ns = backfill_ns,
                    });
                }
                return .{ .full_text = entry };
            },
            .dense_vector => {
                const started_ns = nowNs();
                var backfill_ns: u64 = 0;
                const dense_cfg = try parseDenseConfig(self.alloc, cfg.config_json);
                defer dense_cfg.deinit(self.alloc);
                const cache_limits = self.resource_manager.?.hbcCacheLimits(dense_cfg.dims, self.hbc_cache != null);
                const dense_generator = try parseDenseGeneratorConfig(self.alloc, cfg.config_json);
                defer if (dense_generator) |generator| generator.deinit(self.alloc);
                const referenced_embedding = if (dense_generator == null and dense_cfg.embedding_name != null and !dense_cfg.external)
                    self.getEnrichment(.embedding, dense_cfg.embedding_name.?)
                else
                    null;
                if (dense_generator == null and dense_cfg.embedding_name != null and !dense_cfg.external and referenced_embedding == null) {
                    return error.InvalidIndexConfig;
                }
                if (referenced_embedding) |embedding_cfg| {
                    if (embedding_cfg.expected_dims > 0 and embedding_cfg.expected_dims != dense_cfg.dims) {
                        return error.InvalidIndexConfig;
                    }
                }

                const path = try self.activeIndexPathForConfig(cfg);
                defer self.alloc.free(path);

                const zpath = try self.alloc.dupeZ(u8, path);
                defer self.alloc.free(zpath);

                var index = try hbc_mod.HBCIndex.openWithLsmOptions(self.alloc, zpath, .{
                    .storage_backend = self.dense_storage_backend,
                    .dims = dense_cfg.dims,
                    .metric = dense_cfg.metric,
                    .split_algo = dense_cfg.split_algo,
                    .search_width = dense_cfg.search_width,
                    .epsilon = dense_cfg.epsilon,
                    .branching_factor = dense_cfg.branching_factor,
                    .leaf_size = dense_cfg.leaf_size,
                    .bulk_build_algo = dense_cfg.bulk_build_algo,
                    .kmeans_backend = dense_cfg.kmeans_backend,
                    .kmeans_update_strategy = dense_cfg.kmeans_update_strategy,
                    .use_quantization = dense_cfg.use_quantization,
                    .rerank_policy = dense_cfg.rerank_policy,
                    .quantizer_seed = dense_cfg.quantizer_seed,
                    .use_random_ortho_trans = dense_cfg.use_random_ortho_trans,
                    .max_cached_nodes = cache_limits.max_cached_nodes,
                    .max_cached_vectors = cache_limits.max_cached_vectors,
                    .max_cached_metadata = cache_limits.max_cached_metadata,
                    .lazy_posting_maintenance = dense_cfg.lazy_posting_maintenance,
                    .auto_posting_maintenance_max_postings = dense_cfg.auto_posting_maintenance_max_postings,
                    .centroid_directory_mode = dense_cfg.centroid_directory_mode,
                    .flat_centroid_block_size = dense_cfg.flat_centroid_block_size,
                    .flat_centroid_probe_count = dense_cfg.flat_centroid_probe_count,
                    .no_sync = self.relaxed_split_durability,
                    .no_meta_sync = self.relaxed_split_durability,
                }, .{
                    .backend_options = self.dense_lsm_options,
                    .storage = self.dense_lsm_storage,
                    .cache = self.lsm_cache,
                    .root_generation = self.lsm_root_generation,
                });
                if (self.hbc_cache) |cache| index.attachSharedCache(cache);
                if (self.resource_manager) |manager| {
                    index.attachResourceManagerWithSharedCacheBinding(manager, self.bind_cache_resource_manager);
                }
                var index_moved = false;
                errdefer if (!index_moved) index.close();
                const vector_loader_context = try self.alloc.create(DenseVectorLoadContext);
                var vector_loader_context_initialized = false;
                errdefer if (!index_moved) {
                    if (vector_loader_context_initialized) {
                        vector_loader_context.deinit(self.alloc);
                    } else {
                        self.alloc.destroy(vector_loader_context);
                    }
                };
                vector_loader_context.* = .{
                    .manager = self,
                    .index_name = try self.alloc.dupe(u8, cfg.name),
                };
                vector_loader_context_initialized = true;
                index.setExternalVectorLoader(vector_loader_context, loadDenseVectorForHbc);
                index.setExternalVectorScratchLoader(vector_loader_context, loadDenseVectorForHbcIntoScratch);
                index.setExternalVectorBatchScratchLoader(vector_loader_context, loadDenseVectorsForHbcBatch);
                index.setExternalVectorBatchTransformedMatrixLoader(vector_loader_context, loadDenseVectorsForHbcBatchIntoTransformedMatrix);
                index.setExternalVectorBatchDistanceLoader(vector_loader_context, scoreDenseVectorsForHbcBatch);
                const apply_mutex = try self.allocIndexApplyMutex();
                var apply_mutex_owned = true;
                errdefer if (apply_mutex_owned) self.destroyIndexApplyMutex(apply_mutex);

                var entry = DenseIndex{
                    .apply_mutex = apply_mutex,
                    .config = try types.IndexConfig.clone(self.alloc, cfg),
                    .field_name = try self.alloc.dupe(u8, dense_cfg.field_name),
                    .dims = dense_cfg.dims,
                    .metric = dense_cfg.metric,
                    .external = dense_cfg.external,
                    .managed_direct_field = !dense_cfg.external and dense_generator == null and referenced_embedding == null,
                    .chunk_name = if (dense_generator) |generator|
                        if (generatorHasChunking(generator)) try self.alloc.dupe(u8, generator.artifact_name) else null
                    else if (referenced_embedding) |embedding_cfg|
                        if (embedding_cfg.source_artifact_name.len > 0) try self.alloc.dupe(u8, embedding_cfg.source_artifact_name) else null
                    else
                        null,
                    .embedding_name = if (dense_generator) |generator|
                        if (generator.embedding_name) |embedding_name| try self.alloc.dupe(u8, embedding_name) else try self.alloc.dupe(u8, cfg.name)
                    else if (dense_cfg.embedding_name) |embedding_name|
                        try self.alloc.dupe(u8, embedding_name)
                    else
                        null,
                    .index = index,
                    .vector_loader_context = vector_loader_context,
                };
                apply_mutex_owned = false;
                index_moved = true;
                errdefer self.freeDenseIndexEntry(&entry);

                if (allow_backfill and entry.index.metadata.active_count == 0) {
                    const backfill_started_ns = nowNs();
                    try self.backfillDenseIndex(store, &entry);
                    backfill_ns += elapsedSince(backfill_started_ns);
                }

                if (openProfileEnabled()) {
                    logOpenIndexProfile(.{
                        .kind = cfg.kind,
                        .name = cfg.name,
                        .open_ns = elapsedSince(started_ns) -| backfill_ns,
                        .backfill_ns = backfill_ns,
                    });
                }
                return .{ .dense_vector = entry };
            },
            .sparse_vector => {
                const started_ns = nowNs();
                var backfill_ns: u64 = 0;
                const sparse_cfg = try parseSparseConfig(self.alloc, cfg.config_json);
                defer sparse_cfg.deinit(self.alloc);
                const sparse_generator = try parseSparseGeneratorConfig(self.alloc, cfg.config_json);
                defer if (sparse_generator) |generator| generator.deinit(self.alloc);
                const referenced_embedding = if (sparse_generator == null)
                    self.getEnrichment(.embedding, cfg.name)
                else
                    null;

                const path = try self.activeIndexPathForConfig(cfg);
                defer self.alloc.free(path);

                const zpath = try self.alloc.dupeZ(u8, path);
                defer self.alloc.free(zpath);

                var index = try sparse_mod.SparseIndex.open(self.alloc, zpath, .{
                    .no_sync = self.relaxed_split_durability,
                    .no_meta_sync = self.relaxed_split_durability,
                    .backend = self.sparse_backend,
                    .lsm_storage = self.sparse_lsm_storage,
                    .lsm_cache = self.lsm_cache,
                    .lsm_options = self.sparse_lsm_options,
                    .lsm_root_generation = self.lsm_root_generation,
                });
                var index_moved = false;
                errdefer if (!index_moved) index.close();
                const apply_mutex = try self.allocIndexApplyMutex();
                var apply_mutex_owned = true;
                errdefer if (apply_mutex_owned) self.destroyIndexApplyMutex(apply_mutex);

                var entry = SparseIndex{
                    .apply_mutex = apply_mutex,
                    .config = try types.IndexConfig.clone(self.alloc, cfg),
                    .field_name = try self.alloc.dupe(u8, sparse_cfg.field_name),
                    .external = sparse_cfg.external,
                    .managed_direct_field = !sparse_cfg.external and sparse_generator == null and referenced_embedding == null,
                    .chunk_name = if (sparse_generator) |generator| blk: {
                        const chunk_cfg = resolveChunkGenerator(self, generator);
                        break :blk if (generatorHasChunking(chunk_cfg)) try self.alloc.dupe(u8, chunk_cfg.artifact_name) else null;
                    } else if (referenced_embedding) |embedding_cfg|
                        if (embedding_cfg.source_artifact_name.len > 0) try self.alloc.dupe(u8, embedding_cfg.source_artifact_name) else null
                    else
                        null,
                    .embedding_name = if (sparse_generator) |generator| blk: {
                        break :blk if (generator.embedding_name) |embedding_name|
                            try self.alloc.dupe(u8, embedding_name)
                        else
                            try self.alloc.dupe(u8, cfg.name);
                    } else try self.alloc.dupe(u8, cfg.name),
                    .rebuild_root_path = try self.alloc.dupe(u8, path),
                    .index = index,
                };
                apply_mutex_owned = false;
                index_moved = true;
                errdefer self.freeSparseIndexEntry(&entry);

                const rebuild_state = self.rebuildState(.sparse_vector, entry.rebuild_root_path, entry.config);
                const resume_from = try rebuild_state.checkWithIo(self.alloc, self.checkpointIo());
                defer if (resume_from) |buf| self.alloc.free(buf);

                if (allow_backfill and (resume_from != null or entry.index.next_doc_num == 0)) {
                    const backfill_started_ns = nowNs();
                    try rebuild_state.updateWithIo(self.checkpointIo(), if (resume_from) |buf| buf else "");
                    try self.backfillSparseIndex(store, &entry, resume_from);
                    try self.saveBackfilledAppliedSequence(store, cfg);
                    backfill_ns += elapsedSince(backfill_started_ns);
                }

                if (openProfileEnabled()) {
                    logOpenIndexProfile(.{
                        .kind = cfg.kind,
                        .name = cfg.name,
                        .open_ns = elapsedSince(started_ns) -| backfill_ns,
                        .backfill_ns = backfill_ns,
                    });
                }
                return .{ .sparse_vector = entry };
            },
            .graph => {
                const started_ns = nowNs();
                var backfill_ns: u64 = 0;
                var graph_cfg = try parseGraphConfig(self.alloc, cfg.config_json);
                var graph_cfg_moved = false;
                errdefer if (!graph_cfg_moved) graph_cfg.deinit(self.alloc);
                if (graph_cfg.artifact_source) |source| {
                    if (self.getEnrichment(.asset, source.artifact_name) == null and
                        self.getEnrichment(.chunk, source.artifact_name) == null)
                    {
                        return error.InvalidIndexConfig;
                    }
                }
                if (graph_cfg.shorthand_asset) |*asset| {
                    asset.deinit(self.alloc);
                    graph_cfg.shorthand_asset = null;
                }

                const path = try self.activeIndexPathForConfig(cfg);
                defer self.alloc.free(path);

                const forward_path = try std.fmt.allocPrint(self.alloc, "{s}/forward", .{path});
                defer self.alloc.free(forward_path);
                const reverse_path = try std.fmt.allocPrint(self.alloc, "{s}/reverse", .{path});
                defer self.alloc.free(reverse_path);
                const reverse_store_missing = if (self.graph_lsm_storage != null) false else if (comptime builtin.os.tag == .freestanding) true else blk: {
                    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
                    defer io_impl.deinit();
                    var reverse_dir = std.Io.Dir.cwd().openDir(io_impl.io(), reverse_path, .{}) catch |err| switch (err) {
                        error.FileNotFound => break :blk true,
                        else => return err,
                    };
                    reverse_dir.close(io_impl.io());
                    break :blk false;
                };
                const zforward = try self.alloc.dupeZ(u8, forward_path);
                defer self.alloc.free(zforward);
                const zreverse = try self.alloc.dupeZ(u8, reverse_path);
                defer self.alloc.free(zreverse);

                var cloned_cfg = try types.IndexConfig.clone(self.alloc, cfg);
                var cloned_cfg_moved = false;
                errdefer if (!cloned_cfg_moved) cloned_cfg.deinit(self.alloc);

                var index = try graph_mod.GraphIndex.openWithPrivateStores(self.alloc, zforward, zreverse, cloned_cfg.name, .{
                    .no_sync = self.relaxed_split_durability,
                    .no_meta_sync = self.relaxed_split_durability,
                    .reverse_backend = self.graph_reverse_backend,
                    .reverse_lsm_storage = self.graph_lsm_storage,
                    .reverse_lsm_cache = self.lsm_cache,
                    .reverse_lsm_options = self.graph_reverse_lsm_options,
                    .reverse_lsm_root_generation = self.lsm_root_generation,
                    .edge_type_configs = graph_cfg.edge_type_configs,
                    .rebuild_root_path = path,
                    .rebuild_owner_generation = coverageGenerationForConfig(cfg),
                    .algebraic_semiring_traversal = graph_cfg.algebraic_semiring_traversal,
                });
                var index_moved = false;
                errdefer if (!index_moved) index.close();
                const apply_mutex = try self.allocIndexApplyMutex();
                var apply_mutex_owned = true;
                errdefer if (apply_mutex_owned) self.destroyIndexApplyMutex(apply_mutex);

                var entry = GraphIndex{
                    .apply_mutex = apply_mutex,
                    .config = cloned_cfg,
                    .edge_type_configs = graph_cfg.edge_type_configs,
                    .artifact_source = graph_cfg.artifact_source,
                    .rebuild_root_path = try self.alloc.dupe(u8, path),
                    .index = index,
                };
                apply_mutex_owned = false;
                cloned_cfg_moved = true;
                index_moved = true;
                graph_cfg_moved = true;
                errdefer self.freeGraphIndexEntry(&entry);

                const rebuild_state = self.rebuildState(.graph, entry.rebuild_root_path, entry.config);
                const resume_from = try rebuild_state.checkWithIo(self.alloc, self.checkpointIo());
                defer if (resume_from) |buf| self.alloc.free(buf);
                const reverse_edges = (try entry.index.stats(self.alloc)).edge_count;

                const applied_sequence = try apply_state.loadAppliedSequenceWithCheckpoint(
                    self.alloc,
                    self.checkpointIo(),
                    store,
                    self.applied_sequence_checkpoint_path,
                    cfg.name,
                );
                const latest_replay_sequence = store.nextReplaySequence(1) -| 1;
                const graph_replay_pending = applied_sequence < latest_replay_sequence;
                const has_replay_history = latest_replay_sequence != 0;
                if (allow_backfill and (resume_from != null or (has_replay_history and (reverse_store_missing or reverse_edges == 0) and !graph_replay_pending))) {
                    const backfill_started_ns = nowNs();
                    try rebuild_state.updateWithIo(self.checkpointIo(), if (resume_from) |buf| buf else "");
                    _ = try entry.index.rebuildReverseFromOwnedOutgoingEdgesResumeWithIo(
                        self.alloc,
                        self.checkpointIo(),
                        self.byte_range.start,
                        self.byte_range.end,
                        resume_from,
                    );
                    backfill_ns += elapsedSince(backfill_started_ns);
                }

                if (openProfileEnabled()) {
                    logOpenIndexProfile(.{
                        .kind = cfg.kind,
                        .name = cfg.name,
                        .open_ns = elapsedSince(started_ns) -| backfill_ns,
                        .backfill_ns = backfill_ns,
                    });
                }
                return .{ .graph = entry };
            },
            .algebraic => {
                const storage_namespace = try self.algebraicStorageNamespaceAlloc(cfg.name);
                defer self.alloc.free(storage_namespace);
                const index = try algebraic_mod.index.Index.createWithStorageNamespace(
                    self.alloc,
                    cfg.name,
                    storage_namespace,
                    cfg.config_json,
                );
                var index_moved = false;
                errdefer if (!index_moved) index.destroy();
                const ready_key = try index.projectionConfigReadyMarkerKeyAlloc();
                defer self.alloc.free(ready_key);
                var runtime_store = try initRuntimeStore(self.alloc, store);
                defer runtime_store.deinit();
                var ready_txn = try runtime_store.store.beginProbe();
                defer ready_txn.abort();
                const ready_value: ?[]const u8 = ready_txn.get(ready_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (ready_value) |value| {
                    if (value.len == @sizeOf(u64) and
                        std.mem.readInt(u64, value[0..@sizeOf(u64)], .little) == types.indexConfigHash(cfg))
                    {
                        index.markProjectionConfigReady();
                    }
                }
                if (self.resource_manager) |manager| index.attachResourceManager(manager);
                if (self.hll_maintenance_lane) |lane| {
                    index.attachHllMaintenanceLane(lane, self.hll_maintenance_owner_id);
                }
                const apply_mutex = try self.allocIndexApplyMutex();
                var apply_mutex_owned = true;
                errdefer if (apply_mutex_owned) self.destroyIndexApplyMutex(apply_mutex);

                var entry = AlgebraicIndex{
                    .apply_mutex = apply_mutex,
                    .config = try types.IndexConfig.clone(self.alloc, cfg),
                    .index = index,
                };
                apply_mutex_owned = false;
                index_moved = true;
                errdefer self.freeAlgebraicIndexEntry(&entry);
                return .{ .algebraic = entry };
            },
        }
    }

    fn persistCatalog(self: *IndexManager, store: anytype) !void {
        try self.persistCatalogWithAtomicMutation(store, null);
    }

    fn persistCatalogWithAtomicMutation(
        self: *IndexManager,
        store: anytype,
        atomic_mutation: ?AtomicCatalogMutation,
    ) !void {
        const data = try serializeCatalog(self.alloc, self);
        defer self.alloc.free(data);
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginWrite();
        errdefer txn.abort();
        try txn.put(index_catalog_key, data);
        if (atomic_mutation) |mutation| switch (mutation) {
            .put => |write| try txn.put(write.key, write.value),
            .delete => |key| txn.delete(key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            },
            .put_delete => |writes| {
                try txn.put(writes.put.key, writes.put.value);
                txn.delete(writes.delete) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
            },
        };
        try txn.commit();
    }

    fn persistCatalogExcludingWithAtomicMutation(
        self: *IndexManager,
        store: anytype,
        excluded_name: []const u8,
        atomic_mutation: ?AtomicCatalogMutation,
    ) !void {
        const data = try serializeCatalogExcluding(self.alloc, self, excluded_name);
        defer self.alloc.free(data);
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginWrite();
        errdefer txn.abort();
        try txn.put(index_catalog_key, data);
        if (atomic_mutation) |mutation| switch (mutation) {
            .put => |write| try txn.put(write.key, write.value),
            .delete => |key| txn.delete(key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            },
            .put_delete => |writes| {
                try txn.put(writes.put.key, writes.put.value);
                txn.delete(writes.delete) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
            },
        };
        try txn.commit();
    }

    fn loadEnrichmentCatalog(self: *IndexManager, store: anytype) !void {
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginProbe();
        defer txn.abort();
        const data = txn.get(enrichment_catalog_key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };

        const configs = try enrichment_catalog.deserializeCatalog(self.alloc, data);
        defer {
            for (configs) |*cfg| cfg.deinit(self.alloc);
            self.alloc.free(configs);
        }
        for (configs) |cfg| {
            try self.enrichments.append(self.alloc, try enrichment_catalog.EnrichmentConfig.clone(self.alloc, cfg));
        }
    }

    fn persistEnrichmentCatalog(self: *IndexManager, store: anytype) !void {
        const data = try enrichment_catalog.serializeCatalog(self.alloc, self.enrichments.items);
        defer self.alloc.free(data);
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginWrite();
        errdefer txn.abort();
        try txn.put(enrichment_catalog_key, data);
        try txn.commit();
    }

    fn loadResolverCatalog(self: *IndexManager, store: anytype) !void {
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginRead();
        defer txn.abort();
        const data = txn.get(resolver_catalog_key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };

        const configs = try resolver_catalog.deserializeCatalog(self.alloc, data);
        defer {
            for (configs) |*cfg| cfg.deinit(self.alloc);
            self.alloc.free(configs);
        }
        for (configs) |cfg| {
            try self.resolvers.append(self.alloc, try resolver_catalog.ResolverConfig.clone(self.alloc, cfg));
        }
    }

    const ResolverCatalogPersistMode = enum {
        catalog_only,
        mark_reresolve_dirty,
    };

    fn persistResolverCatalog(self: *IndexManager, store: anytype, mode: ResolverCatalogPersistMode) !void {
        const data = try resolver_catalog.serializeCatalog(self.alloc, self.resolvers.items);
        defer self.alloc.free(data);
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginWrite();
        errdefer txn.abort();
        try txn.put(resolver_catalog_key, data);
        if (mode == .mark_reresolve_dirty) {
            _ = txn.get(resolver_catalog.reresolve_resume_key) catch |err| switch (err) {
                error.NotFound => try txn.put(resolver_catalog.reresolve_resume_key, ""),
                else => return err,
            };
            _ = txn.get(resolver_catalog.reresolve_repair_resume_key) catch |err| switch (err) {
                error.NotFound => try txn.put(resolver_catalog.reresolve_repair_resume_key, ""),
                else => return err,
            };
        }
        try txn.commit();
    }

    fn ensureShorthandEnrichments(self: *IndexManager, cfg: types.IndexConfig) !bool {
        var changed = false;
        switch (cfg.kind) {
            .dense_vector => {
                const dense_cfg = try parseDenseConfig(self.alloc, cfg.config_json);
                defer dense_cfg.deinit(self.alloc);
                if (try parseDenseGeneratorConfig(self.alloc, cfg.config_json)) |generator| {
                    defer generator.deinit(self.alloc);
                    const chunk_cfg = resolveChunkGenerator(self, generator);
                    if (generatorHasChunking(chunk_cfg)) {
                        changed = (try self.ensureChunkEnrichment(.{
                            .name = chunk_cfg.artifact_name,
                            .kind = .chunk,
                            .source_field = chunk_cfg.source_field,
                            .source_template = if (chunk_cfg.source_template.len > 0) chunk_cfg.source_template else "",
                            .chunk_size = chunk_cfg.chunk_size,
                            .chunk_overlap = chunk_cfg.chunk_overlap,
                            .chunker_json = if (chunk_cfg.chunker_json.len > 0) chunk_cfg.chunker_json else "",
                            .execution_json = if (chunk_cfg.chunking_execution_json.len > 0) chunk_cfg.chunking_execution_json else "",
                            .full_text_index = chunk_cfg.full_text_index,
                        })) or changed;
                    }
                    changed = (try self.ensureEmbeddingEnrichment(.{
                        .name = if (chunk_cfg.embedding_name) |embedding_name| embedding_name else cfg.name,
                        .kind = .embedding,
                        .source_field = chunk_cfg.source_field,
                        .source_template = if (chunk_cfg.source_template.len > 0) chunk_cfg.source_template else "",
                        .source_artifact_name = if (generatorHasChunking(chunk_cfg)) chunk_cfg.artifact_name else "",
                        .expected_dims = dense_cfg.dims,
                        .chunk_size = chunk_cfg.chunk_size,
                        .chunk_overlap = chunk_cfg.chunk_overlap,
                        .execution_json = if (chunk_cfg.embedding_execution_json.len > 0) chunk_cfg.embedding_execution_json else "",
                    })) or changed;
                }
            },
            .sparse_vector => {
                if (try parseSparseGeneratorConfig(self.alloc, cfg.config_json)) |generator| {
                    defer generator.deinit(self.alloc);
                    const chunk_cfg = resolveChunkGenerator(self, generator);
                    if (generatorHasChunking(chunk_cfg)) {
                        changed = (try self.ensureChunkEnrichment(.{
                            .name = chunk_cfg.artifact_name,
                            .kind = .chunk,
                            .source_field = chunk_cfg.source_field,
                            .source_template = if (chunk_cfg.source_template.len > 0) chunk_cfg.source_template else "",
                            .chunk_size = chunk_cfg.chunk_size,
                            .chunk_overlap = chunk_cfg.chunk_overlap,
                            .chunker_json = if (chunk_cfg.chunker_json.len > 0) chunk_cfg.chunker_json else "",
                            .execution_json = if (chunk_cfg.chunking_execution_json.len > 0) chunk_cfg.chunking_execution_json else "",
                            .full_text_index = chunk_cfg.full_text_index,
                        })) or changed;
                    }
                }
            },
            .graph => {
                var graph_cfg = try parseGraphConfig(self.alloc, cfg.config_json);
                defer graph_cfg.deinit(self.alloc);
                if (graph_cfg.shorthand_asset) |asset| {
                    changed = (try self.ensureAssetEnrichment(asset)) or changed;
                }
                if (graph_cfg.artifact_source) |source| {
                    if (graph_cfg.shorthand_asset) |asset| {
                        if (!std.mem.eql(u8, asset.name, source.artifact_name)) return error.InvalidIndexConfig;
                    }
                    if (self.getEnrichment(.asset, source.artifact_name) == null and
                        self.getEnrichment(.chunk, source.artifact_name) == null)
                    {
                        return error.InvalidIndexConfig;
                    }
                }
            },
            else => {},
        }
        return changed;
    }

    fn ensureChunkEnrichment(self: *IndexManager, cfg: enrichment_catalog.EnrichmentConfig) !bool {
        if (self.getEnrichment(.chunk, cfg.name)) |existing| {
            if (!std.mem.eql(u8, existing.source_field, cfg.source_field) or
                !std.mem.eql(u8, existing.source_template, cfg.source_template) or
                !std.mem.eql(u8, existing.source_artifact_name, cfg.source_artifact_name) or
                existing.chunk_size != cfg.chunk_size or
                existing.chunk_overlap != cfg.chunk_overlap or
                !std.mem.eql(u8, existing.chunker_json, cfg.chunker_json) or
                !std.mem.eql(u8, existing.execution_json, cfg.execution_json) or
                existing.full_text_index != cfg.full_text_index)
            {
                return error.ConflictingEnrichmentConfig;
            }
            return false;
        }

        try self.enrichments.append(self.alloc, try enrichment_catalog.EnrichmentConfig.clone(self.alloc, cfg));
        return true;
    }

    fn ensureEmbeddingEnrichment(self: *IndexManager, cfg: enrichment_catalog.EnrichmentConfig) !bool {
        if (self.getEnrichment(.embedding, cfg.name)) |existing| {
            if (!std.mem.eql(u8, existing.source_field, cfg.source_field) or
                !std.mem.eql(u8, existing.source_template, cfg.source_template) or
                !std.mem.eql(u8, existing.source_artifact_name, cfg.source_artifact_name) or
                existing.expected_dims != cfg.expected_dims or
                !std.mem.eql(u8, existing.execution_json, cfg.execution_json))
            {
                return error.ConflictingEnrichmentConfig;
            }
            return false;
        }

        try self.enrichments.append(self.alloc, try enrichment_catalog.EnrichmentConfig.clone(self.alloc, cfg));
        return true;
    }

    fn ensureAssetEnrichment(self: *IndexManager, cfg: enrichment_catalog.EnrichmentConfig) !bool {
        if (self.getEnrichment(.asset, cfg.name)) |existing| {
            if (!std.mem.eql(u8, existing.source_field, cfg.source_field) or
                !std.mem.eql(u8, existing.source_template, cfg.source_template) or
                !std.mem.eql(u8, existing.content_type, cfg.content_type) or
                !std.mem.eql(u8, existing.producer_json, cfg.producer_json) or
                !std.mem.eql(u8, existing.execution_json, cfg.execution_json))
            {
                return error.ConflictingEnrichmentConfig;
            }
            return false;
        }

        try self.enrichments.append(self.alloc, try enrichment_catalog.EnrichmentConfig.clone(self.alloc, cfg));
        return true;
    }

    fn validateEnrichmentConfig(self: *const IndexManager, cfg: enrichment_catalog.EnrichmentConfig) !void {
        if (cfg.name.len == 0 or (cfg.source_field.len == 0 and cfg.source_template.len == 0)) return error.InvalidEnrichmentConfig;
        if (cfg.execution_json.len > 0) _ = try enrichment_types.parseExecutionPolicyJson(self.alloc, cfg.execution_json);
        if (cfg.full_text_index and cfg.kind == .embedding) return error.InvalidEnrichmentConfig;
        switch (cfg.kind) {
            .chunk => {
                if (cfg.chunk_size == 0 and cfg.chunker_json.len == 0) return error.InvalidEnrichmentConfig;
                if (cfg.source_artifact_name.len > 0 and self.getEnrichment(.asset, cfg.source_artifact_name) == null) {
                    return error.InvalidEnrichmentConfig;
                }
            },
            .embedding => {
                if (cfg.source_artifact_name.len > 0 and self.getEnrichment(.chunk, cfg.source_artifact_name) == null) {
                    return error.InvalidEnrichmentConfig;
                }
            },
            .asset => {
                try enrichment_config_validation.validateAssetProducerConfig(self.alloc, cfg.producer_json);
            },
        }
    }

    fn validateEnrichmentCatalogGraph(self: *const IndexManager) !void {
        for (self.enrichments.items, 0..) |cfg, i| {
            for (self.enrichments.items[0..i]) |prior| {
                if (std.mem.eql(u8, prior.name, cfg.name)) return error.ConflictingEnrichmentConfig;
            }
            try validateEnrichmentConfig(self, cfg);
        }
        try self.validateIndexEnrichmentReferences();
    }

    fn validateIndexEnrichmentReferences(self: *const IndexManager) !void {
        for (self.text_indexes.items) |entry| {
            if (entry.chunk_name) |chunk_name| {
                if (self.getEnrichment(.chunk, chunk_name) == null) return error.InvalidEnrichmentConfig;
            }
        }
        for (self.dense_indexes.items) |entry| {
            if (entry.chunk_name) |chunk_name| {
                if (self.getEnrichment(.chunk, chunk_name) == null) return error.InvalidEnrichmentConfig;
            }
            if (entry.embedding_name) |embedding_name| {
                if (!entry.external and self.getEnrichment(.embedding, embedding_name) == null) return error.InvalidEnrichmentConfig;
            }
        }
        for (self.sparse_indexes.items) |entry| {
            if (entry.chunk_name) |chunk_name| {
                if (self.getEnrichment(.chunk, chunk_name) == null) return error.InvalidEnrichmentConfig;
            }
        }
        for (self.graph_indexes.items) |entry| {
            var graph_cfg = try parseGraphConfig(self.alloc, entry.config.config_json);
            defer graph_cfg.deinit(self.alloc);
            if (graph_cfg.artifact_source) |source| {
                if (self.getEnrichment(.asset, source.artifact_name) == null and
                    self.getEnrichment(.chunk, source.artifact_name) == null)
                {
                    return error.InvalidEnrichmentConfig;
                }
            }
        }
    }

    fn enrichmentInUse(self: *const IndexManager, kind: enrichment_catalog.EnrichmentType, name: []const u8) bool {
        switch (kind) {
            .chunk => {
                for (self.text_indexes.items) |entry| {
                    if (entry.chunk_name) |chunk_name| {
                        if (std.mem.eql(u8, chunk_name, name)) return true;
                    }
                }
                for (self.dense_indexes.items) |entry| {
                    if (entry.chunk_name) |chunk_name| {
                        if (std.mem.eql(u8, chunk_name, name)) return true;
                    }
                }
                for (self.sparse_indexes.items) |entry| {
                    const maybe_generator = parseSparseGeneratorConfig(self.alloc, entry.config.config_json) catch continue;
                    if (maybe_generator) |generator| {
                        defer generator.deinit(self.alloc);
                        const chunk_cfg = resolveChunkGenerator(self, generator);
                        if (generatorHasChunking(chunk_cfg) and std.mem.eql(u8, chunk_cfg.artifact_name, name)) return true;
                    }
                }
                for (self.enrichments.items) |entry| {
                    if (entry.kind == .embedding and std.mem.eql(u8, entry.source_artifact_name, name)) return true;
                }
            },
            .embedding => {
                for (self.dense_indexes.items) |entry| {
                    if (entry.embedding_name) |embedding_name| {
                        if (std.mem.eql(u8, embedding_name, name)) return true;
                    }
                }
            },
            .asset => {
                for (self.graph_indexes.items) |entry| {
                    if (entry.artifact_source) |source| {
                        if (std.mem.eql(u8, source.artifact_name, name)) return true;
                    }
                }
                for (self.enrichments.items) |entry| {
                    if (entry.kind == .chunk and std.mem.eql(u8, entry.source_artifact_name, name)) return true;
                }
            },
        }
        return false;
    }

    fn compactTextIndex(self: *IndexManager, index: *persistent_mod.PersistentIndex, policy: merger_mod.MergePolicy) !void {
        while (true) {
            const snap = index.snapshot();
            const planned = (try text_index_maintenance.planPolicyMergeAlloc(self.alloc, snap, policy)) orelse return;
            defer self.alloc.free(planned);
            var reservation = try self.reserveTextMergeBuffers(index, snap, planned, .strict);
            defer if (reservation) |*active| active.release();

            if (!try text_index_maintenance.applyPlannedMerge(
                self.alloc,
                index,
                snap,
                planned,
                policy.max_segment_size,
                "compact text index merge failed",
                "compact text index apply merge failed",
            )) return;
        }
    }

    pub fn beginTextMergeTask(self: *IndexManager) !?TextMergeTask {
        if (self.text_backfill_active.load(.acquire) != 0) return null;
        const now_ns = platform_time.monotonicNs();
        self.text_merge_scheduler.pruneExpiredQuarantines(self.alloc, now_ns);
        _ = self.textMergeStats();
        if (self.shouldDeferTextMergeForResourcePressure()) {
            self.text_merge_scheduler.deferred_for_pressure += 1;
            return null;
        }
        var attempts: usize = 0;
        while (attempts < self.text_indexes.items.len) : (attempts += 1) {
            const idx = self.text_merge_scheduler.select(self.text_indexes.items) orelse return null;
            const entry = &self.text_indexes.items[idx];
            const has_in_flight = self.text_merge_scheduler.indexHasInFlight(entry.config.name);
            const maybe_task = self.beginTextMergeTaskForEntry(entry) catch |err| switch (err) {
                error.ResourceBudgetExceeded => {
                    self.text_merge_scheduler.deferred_for_pressure += 1;
                    return null;
                },
                // Replay owns this index right now. Keep its pending bit set
                // and give another index a chance in this scheduler pass.
                error.IndexApplyBusy => continue,
                else => return err,
            };
            if (maybe_task) |task| return task;
            if (!has_in_flight and !self.text_merge_scheduler.indexHasActiveQuarantine(entry.config.name, now_ns)) TextMergeScheduler.noteComplete(entry);
        }
        return null;
    }

    pub fn executeTextMergeTask(alloc: Allocator, task: *const TextMergeTask) !TextMergeResult {
        const started_ns = platform_time.monotonicNs();
        defer task.discardSourceCleanPages();
        logTextMergeTaskMemory("before", task, 0);
        var alloc_stats = PhaseAllocStats{};
        var tracking = PhaseTrackingAllocator.init(task.mergeAllocator(), &alloc_stats);
        const task_alloc = tracking.allocator();
        const deleted_docs = task_alloc.alloc(?roaring.RoaringBitmap, task.source.len) catch |err| {
            if (tracking.limit_exceeded or task.deletion_state.budget.denied()) return error.ResourceBudgetExceeded;
            return err;
        };
        defer task_alloc.free(deleted_docs);
        for (task.source, 0..) |source, i| deleted_docs[i] = source.deleted;

        if (task.persistent.prepareMergedSegmentToFileWithAllocatorsAndDeletes(
            task_alloc,
            task.mergeAllocator(),
            task.snapshot,
            task.merge_indices,
            deleted_docs,
        )) |prepared| {
            var output_bytes: u64 = 0;
            for (prepared) |*segment| output_bytes +|= @intCast(segment.data.bytes().len);
            logTextMergeTaskMemory("after_build", task, output_bytes);
            task.discardSourceCleanPages();
            logTextMergeTaskMemory("after_source_discard", task, output_bytes);
            var result = TextMergeResult{
                .prepared_segments = prepared,
                .prepared_owner = task.persistent,
                .owned_alloc = task.mergeAllocator(),
                .elapsed_ns = platform_time.monotonicNs() -| started_ns,
                .peak_task_alloc_bytes = @intCast(alloc_stats.peak_bytes),
            };
            errdefer result.deinit(alloc);
            result.buildPublicationLookup(task_alloc) catch |err| {
                if (tracking.limit_exceeded or task.deletion_state.budget.denied()) return error.ResourceBudgetExceeded;
                return err;
            };
            result.peak_task_alloc_bytes = @intCast(alloc_stats.peak_bytes);
            return result;
        } else |err| switch (err) {
            error.EmptySegment => return .{
                .segments = &.{},
                .elapsed_ns = platform_time.monotonicNs() -| started_ns,
            },
            error.Unsupported => {},
            else => {
                if (tracking.limit_exceeded or task.deletion_state.budget.denied()) return error.ResourceBudgetExceeded;
                if (builtin.os.tag != .freestanding) {
                    std.log.err("scheduled text merge file-backed build failed index={s}: {s}", .{ task.index_name, @errorName(err) });
                }
                return err;
            },
        }

        const merged = merger_mod.mergeSegmentsBounded(tracking.allocator(), task.snapshot, task.merge_indices, .{
            .target_segment_bytes = @intCast(activeTextMergePolicy().max_segment_size),
            .deleted_docs = deleted_docs,
        }) catch |err| {
            if (tracking.limit_exceeded or task.deletion_state.budget.denied()) return error.ResourceBudgetExceeded;
            if (err == error.EmptySegment) return .{
                .elapsed_ns = platform_time.monotonicNs() -| started_ns,
                .peak_task_alloc_bytes = @intCast(alloc_stats.peak_bytes),
            };
            if (builtin.os.tag != .freestanding) {
                std.log.err("scheduled text merge failed index={s}: {s}", .{ task.index_name, @errorName(err) });
            }
            return err;
        };
        var output_bytes: u64 = 0;
        for (merged) |segment| output_bytes +|= @intCast(segment.len);
        logTextMergeTaskMemory("after_heap_build", task, output_bytes);
        var result = TextMergeResult{
            .segments = merged,
            .owned_alloc = task.mergeAllocator(),
            .elapsed_ns = platform_time.monotonicNs() -| started_ns,
            .peak_task_alloc_bytes = @intCast(alloc_stats.peak_bytes),
        };
        errdefer result.deinit(alloc);
        result.buildPublicationLookup(task_alloc) catch |err| {
            if (tracking.limit_exceeded or task.deletion_state.budget.denied()) return error.ResourceBudgetExceeded;
            return err;
        };
        result.peak_task_alloc_bytes = @intCast(alloc_stats.peak_bytes);
        return result;
    }

    fn logTextMergeTaskMemory(label: []const u8, task: *const TextMergeTask, output_bytes: u64) void {
        if (!memoryAttributionEnabled()) return;
        const memory = process_memory.snapshot();
        std.log.info(
            "antfly_bench_text_merge_memory label={s} input_segments={d} input_bytes={d} output_bytes={d} rss_bytes={d} peak_rss_bytes={d} footprint_bytes={d} peak_footprint_bytes={d} malloc_available={any} malloc_allocated_bytes={d} malloc_zone_bytes={d}",
            .{
                label,
                task.merge_indices.len,
                textMergeTaskInputBytes(task),
                output_bytes,
                memory.resident_bytes,
                memory.peak_resident_bytes,
                memory.footprint_bytes,
                memory.peak_footprint_bytes,
                memory.malloc_available,
                memory.malloc_allocated_bytes,
                memory.malloc_zone_bytes,
            },
        );
    }

    pub fn finishTextMergeTask(self: *IndexManager, task: *const TextMergeTask, result: *TextMergeResult) !bool {
        defer self.completeTextMergeTaskTracking(task);

        const entry = self.textIndexEntry(task.index_name) orelse return false;
        if (!self.text_merge_scheduler.taskInFlight(task.index_name, task.source, task.deletion_state)) {
            self.text_merge_scheduler.skipped_stale_merges += 1;
            if (try self.textIndexNeedsMerge(&entry.persistent, activeTextMergePolicy())) {
                TextMergeScheduler.schedule(entry);
            } else {
                TextMergeScheduler.noteComplete(entry);
            }
            return false;
        }

        const old_ids = try textMergeSourceIds(self.alloc, task.source);
        defer self.alloc.free(old_ids);

        // Replay mutates SegmentShared.deleted while holding this same
        // per-index mutex. Reacquire it only for validation and publication;
        // executeTextMergeTask uses the task-owned clones and runs unlocked.
        lockAtomicWithBackoff(entry.apply_mutex);
        var index_apply_locked = true;
        defer if (index_apply_locked) entry.apply_mutex.unlock();
        if (!entry.lockMergeDeletionStateCurrent(task.deletion_state)) {
            entry.apply_mutex.unlock();
            index_apply_locked = false;
            self.text_merge_scheduler.skipped_stale_merges += 1;
            TextMergeScheduler.schedule(entry);
            return false;
        }
        var merge_delta_locked = true;
        defer if (merge_delta_locked) entry.merge_delta_mutex.unlock();
        const publication_external_bytes = estimateTextMergePublicationExternalBytes(entry, task, result) catch |err| {
            return task.deletion_state.allocationError(err);
        };
        const publication_external_charge = try task.deletion_state.budget.chargeExternal(publication_external_bytes);
        defer task.deletion_state.budget.releaseExternal(publication_external_charge);
        var publication_deletes = textMergePublicationDeletes(entry, task, result, task.deletion_state.deltas) catch |err| {
            return task.deletion_state.allocationError(err);
        };
        defer publication_deletes.deinit(task.mergeAllocator());
        if (!publication_deletes.source_current) {
            entry.apply_mutex.unlock();
            index_apply_locked = false;
            self.text_merge_scheduler.skipped_stale_merges += 1;
            TextMergeScheduler.schedule(entry);
            return false;
        }

        const input_bytes = textMergeTaskInputBytes(task);
        const output_stats = textMergeResultOutputStats(result);
        const applied = if (result.prepared_segments.len == 0 and result.segments.len == 0) blk: {
            break :blk try entry.persistent.removeSegmentsIfActive(old_ids);
        } else if (result.prepared_segments.len > 0) blk: {
            const prepared_segments = result.prepared_segments;
            result.prepared_segments = &.{};
            result.prepared_owner = null;
            break :blk entry.persistent.replaceSegmentsIfActiveManyPreparedWithDeletesAndScratch(
                task.mergeAllocator(),
                old_ids,
                prepared_segments,
                publication_deletes.bitmaps,
            ) catch |err| switch (err) {
                error.EmptySegment => try entry.persistent.removeSegmentsIfActive(old_ids),
                else => {
                    const mapped_err = task.deletion_state.allocationError(err);
                    if (builtin.os.tag != .freestanding and mapped_err != error.Canceled) {
                        std.log.err("scheduled text merge apply failed index={s}: {s}", .{ task.index_name, @errorName(mapped_err) });
                    }
                    return mapped_err;
                },
            };
        } else blk: {
            const segments = result.segments;
            result.segments = &.{};
            break :blk entry.persistent.replaceSegmentsIfActiveManyOwnedWithDeletesAndScratch(
                task.mergeAllocator(),
                old_ids,
                segments,
                publication_deletes.bitmaps,
            ) catch |err| switch (err) {
                error.EmptySegment => try entry.persistent.removeSegmentsIfActive(old_ids),
                else => {
                    const mapped_err = task.deletion_state.allocationError(err);
                    if (builtin.os.tag != .freestanding and mapped_err != error.Canceled) {
                        std.log.err("scheduled text merge apply failed index={s}: {s}", .{ task.index_name, @errorName(mapped_err) });
                    }
                    return mapped_err;
                },
            };
        };
        entry.merge_delta_mutex.unlock();
        merge_delta_locked = false;
        entry.apply_mutex.unlock();
        index_apply_locked = false;

        if (applied and !try self.textIndexNeedsMerge(&entry.persistent, activeTextMergePolicy())) {
            TextMergeScheduler.noteComplete(entry);
        } else {
            TextMergeScheduler.schedule(entry);
        }
        if (applied) {
            self.text_merge_scheduler.noteAppliedMerge(
                @intCast(task.merge_indices.len),
                input_bytes,
                output_stats.segments,
                output_stats.bytes,
                result.elapsed_ns,
                result.peak_task_alloc_bytes,
            );
        }
        return applied;
    }

    pub fn cancelTextMergeTask(self: *IndexManager, task: *const TextMergeTask) void {
        self.completeTextMergeTaskTracking(task);
        if (self.textIndexEntry(task.index_name)) |entry| TextMergeScheduler.schedule(entry);
    }

    pub fn noteTextMergeFailure(self: *IndexManager, task: *const TextMergeTask, err: anyerror) void {
        self.text_merge_scheduler.failed_merges += 1;
        const now_ns = platform_time.monotonicNs();
        self.completeTextMergeTaskTracking(task);
        self.text_merge_scheduler.quarantineSource(self.alloc, task.index_name, task.source, err, now_ns) catch |quarantine_err| {
            if (builtin.os.tag != .freestanding) {
                std.log.err("text merge quarantine failed index={s}: {s}", .{ task.index_name, @errorName(quarantine_err) });
            }
        };
        if (self.textIndexEntry(task.index_name)) |entry| TextMergeScheduler.schedule(entry);
    }

    fn completeTextMergeTaskTracking(self: *IndexManager, task: *const TextMergeTask) void {
        self.text_merge_scheduler.completeTask(self.alloc, task.index_name, task.deletion_state);
        if (self.textIndexEntry(task.index_name)) |entry| entry.detachMergeDeletionState(task.deletion_state);
    }

    fn beginTextMergeTaskForEntry(self: *IndexManager, entry: *TextIndex) !?TextMergeTask {
        // Full-text replay holds this mutex while changing the shared deletion
        // bitmap. Keep planning and cloning in one short critical section so a
        // task can never observe RoaringBitmap.add() between its key and
        // container insertions. The returned task owns the clones, so the
        // expensive merge itself does not retain the mutex.
        // The background runtime reaches this point while holding the DB apply
        // lock. Do not wait there behind an active replay batch: leave the
        // index scheduled and let replay's completion notification retry it.
        if (!entry.apply_mutex.tryLock()) return error.IndexApplyBusy;
        defer entry.apply_mutex.unlock();

        const snap = entry.persistent.acquireSnapshot();
        defer snap.release();
        if (snap.segments.len < 2) return null;
        const now_ns = platform_time.monotonicNs();

        var infos = std.ArrayListUnmanaged(merger_mod.SegmentInfo).empty;
        defer infos.deinit(self.alloc);
        for (snap.segments, 0..) |seg, i| {
            if (self.text_merge_scheduler.segmentInFlight(entry.config.name, seg.id)) continue;
            if (self.text_merge_scheduler.segmentQuarantined(entry.config.name, seg.id, now_ns)) continue;
            const deletion_summary = seg.deletionSummary();
            try infos.append(self.alloc, .{
                .index = i,
                .size = seg.data.bytes().len,
                .doc_count = seg.reader.doc_count,
                .deleted_count = deletion_summary.count,
                .has_deletions = deletion_summary.has_deletions,
            });
        }
        if (infos.items.len < 2) return null;

        const planned = (try activeTextMergePolicy().plan(self.alloc, infos.items)) orelse return null;
        defer self.alloc.free(planned);
        if (planned.len < 2) return null;

        // The tier policy optimizes write amplification by selecting a wider
        // group, but that group may exceed the merge-buffer slice even though
        // a smaller merge can make forward progress. Adapt admission down to
        // a pair before reporting pressure; otherwise a synchronous
        // `full_index` drain can mistake one oversized plan for no merge debt.
        var admitted_len = planned.len;
        var task = while (true) {
            break self.copyTextMergeTask(entry.config.name, &entry.persistent, snap, planned[0..admitted_len]) catch |err| switch (err) {
                error.ResourceBudgetExceeded => {
                    if (admitted_len == 2) return err;
                    // Reservation cost is monotonic for this size-sorted
                    // prefix. Walk down to the widest admissible group rather
                    // than jumping from (for example) five sources to two and
                    // paying avoidable pairwise write amplification.
                    admitted_len -= 1;
                    continue;
                },
                else => return err,
            };
        };
        errdefer task.deinit(self.alloc);
        try entry.attachMergeDeletionState(self.alloc, task.deletion_state);
        errdefer entry.detachMergeDeletionState(task.deletion_state);
        try self.text_merge_scheduler.registerSource(self.alloc, task.index_name, task.source, task.deletion_state);
        return task;
    }

    fn copyTextMergeTask(self: *IndexManager, index_name: []const u8, persistent: *persistent_mod.PersistentIndex, snap: *index_mod.IndexSnapshot, planned: []const usize) !TextMergeTask {
        const owned_index_name = try self.alloc.dupe(u8, index_name);
        errdefer self.alloc.free(owned_index_name);

        var buffer_reservation = try self.reserveTextMergeBuffers(persistent, snap, planned, .bounded_task);
        errdefer if (buffer_reservation) |*reservation| reservation.release();

        const deletion_state = try TextMergeDeletionState.create(self.alloc, &buffer_reservation, planned.len);
        errdefer deletion_state.destroy();
        const task_alloc = deletion_state.allocator();

        const source = task_alloc.alloc(TextMergeSourceSegment, planned.len) catch |err| return deletion_state.allocationError(err);
        var source_initialized: usize = 0;
        errdefer {
            for (source[0..source_initialized]) |*item| item.deinit(task_alloc);
            task_alloc.free(source);
        }

        const merge_indices = task_alloc.alloc(usize, planned.len) catch |err| return deletion_state.allocationError(err);
        errdefer task_alloc.free(merge_indices);

        for (planned, 0..) |seg_idx, i| {
            const source_seg = &snap.segments[seg_idx];
            const deleted_state = source_seg.cloneDeletedState(deletion_state.allocator()) catch |err| {
                if (deletion_state.budget.denied()) return error.ResourceBudgetExceeded;
                return err;
            };
            source[i] = .{
                .id = source_seg.id,
                .deleted = deleted_state.bitmap,
                .deleted_count = deleted_state.count,
            };
            source_initialized += 1;
            merge_indices[i] = seg_idx;
            deletion_state.segment_ids[i] = source_seg.id;
        }

        return .{
            .index_name = owned_index_name,
            .persistent = persistent,
            .source = source,
            .merge_indices = merge_indices,
            .snapshot = snap.retain(),
            .deletion_state = deletion_state,
        };
    }

    fn reserveTextMergeBuffers(
        self: *IndexManager,
        persistent: *const persistent_mod.PersistentIndex,
        snap: *const index_mod.IndexSnapshot,
        planned: []const usize,
        mode: enum { strict, bounded_task },
    ) !?resource_manager_mod.Reservation {
        const manager = self.resource_manager orelse return null;

        var source_bytes: u64 = 0;
        var deletion_tracking_bytes: u64 = 0;
        var merge_working_set_bytes: u64 = 8 * 1024 * 1024;
        const file_backed_merge = persistent.supportsFileBackedSegmentArtifacts();
        for (planned) |seg_idx| {
            const seg = &snap.segments[seg_idx];
            source_bytes = std.math.add(u64, source_bytes, @as(u64, @intCast(seg.data.bytes().len))) catch return error.ResourceBudgetExceeded;
            deletion_tracking_bytes = std.math.add(
                u64,
                deletion_tracking_bytes,
                estimateTextMergeDeletionTrackingBytes(seg) catch return error.ResourceBudgetExceeded,
            ) catch return error.ResourceBudgetExceeded;
            merge_working_set_bytes = std.math.add(
                u64,
                merge_working_set_bytes,
                estimateTextMergeWorkingSetBytes(seg) catch return error.ResourceBudgetExceeded,
            ) catch return error.ResourceBudgetExceeded;
        }

        const segment_overhead = std.math.mul(u64, @as(u64, @intCast(planned.len)), 1024) catch return error.ResourceBudgetExceeded;
        // File-backed output is streamed into its final artifact. Heap-backed
        // output remains resident alongside its builders and publication
        // lookup until the atomic replacement, so it needs both envelopes.
        const reservation_base = if (file_backed_merge)
            merge_working_set_bytes
        else
            std.math.add(
                u64,
                std.math.mul(u64, source_bytes, 2) catch return error.ResourceBudgetExceeded,
                merge_working_set_bytes,
            ) catch return error.ResourceBudgetExceeded;
        var reservation_bytes = std.math.add(u64, reservation_base, segment_overhead) catch return error.ResourceBudgetExceeded;
        reservation_bytes = std.math.add(u64, reservation_bytes, deletion_tracking_bytes) catch return error.ResourceBudgetExceeded;
        if (file_backed_merge) {
            const hard_limit = manager.sliceStats(.text_merge_buffers).hard_limit_bytes;
            if (hard_limit > 0) {
                const enforced_cap = std.math.mul(u64, hard_limit, 2) catch std.math.maxInt(u64);
                reservation_bytes = @min(reservation_bytes, enforced_cap);
            }
        }
        return switch (mode) {
            // Synchronous compaction executes with the manager allocator, so
            // its estimate must fit the ordinary hard limit. Granting it the
            // oversized exception would account the estimate without actually
            // bounding the live working set.
            .strict => try manager.reserve(.text_merge_buffers, reservation_bytes),
            // Scheduled tasks execute through PhaseTrackingAllocator. Permit
            // one task up to 2x the normal hard limit: ResourceManager keeps it
            // exclusive and the task allocator enforces the same live cap.
            .bounded_task => try manager.reserveBoundedOversizedSingle(.text_merge_buffers, reservation_bytes, 2),
        };
    }

    fn estimateTextMergeDeletionTrackingBytes(seg: *const index_mod.SegmentEntry) !u64 {
        // Two task-owned views (the frozen source and concurrent delta), one
        // task-owned publication bitmap, and two persistent-publication views
        // (the writer clone and serialized transaction value) can overlap.
        return try estimateTextMergeRoaringBytes(seg.reader.doc_count, 5);
    }

    fn estimateTextMergePublicationExternalBytes(
        entry: *TextIndex,
        task: *const TextMergeTask,
        result: *const TextMergeResult,
    ) !u64 {
        var bytes: u64 = 0;
        for (task.merge_indices) |seg_idx| {
            if (seg_idx >= task.snapshot.segments.len) return error.InvalidSegment;
            bytes = try addTextMergeEstimate(
                bytes,
                try estimateTextMergeRoaringBytes(task.snapshot.segments[seg_idx].reader.doc_count, 2),
            );
        }

        const output_count = if (result.prepared_segments.len > 0)
            result.prepared_segments.len
        else
            result.segments.len;
        const current = entry.persistent.snapshot();
        if (task.source.len > current.segments.len) return error.InvalidSegment;
        const new_segment_count = try addTextMergeEstimate(
            @intCast(current.segments.len - task.source.len),
            @intCast(output_count),
        );
        bytes = try addTextMergeEstimate(
            bytes,
            try mulTextMergeEstimate(new_segment_count, @sizeOf(index_mod.SegmentEntry)),
        );
        bytes = try addTextMergeEstimate(bytes, @sizeOf(index_mod.IndexSnapshot));
        bytes = try addTextMergeEstimate(
            bytes,
            try mulTextMergeEstimate(@intCast(output_count), @sizeOf(index_mod.SegmentShared)),
        );

        // Segment readers retain compact field/section tables and stored-block
        // validation cells. Parse each already-built output with the admitted
        // task allocator so the estimate is based on the actual wire layout
        // without creating another persistent reader.
        var total_fields: u64 = 0;
        for (current.segments) |*segment| {
            var is_source = false;
            for (task.source) |source| {
                if (source.id != segment.id) continue;
                is_source = true;
                break;
            }
            if (is_source) continue;
            total_fields = try addTextMergeEstimate(total_fields, @intCast(segment.reader.fields.len));
        }
        if (result.prepared_segments.len > 0) {
            for (result.prepared_segments) |*prepared| {
                bytes = try addTextMergeReaderPublicationEstimate(
                    task.mergeAllocator(),
                    prepared.data.bytes(),
                    bytes,
                    &total_fields,
                );
            }
        } else {
            for (result.segments) |segment_bytes| {
                // Heap-backed publication copies task-owned output into the
                // persistent allocator before releasing the task buffer.
                bytes = try addTextMergeEstimate(bytes, @intCast(segment_bytes.len));
                bytes = try addTextMergeReaderPublicationEstimate(
                    task.mergeAllocator(),
                    segment_bytes,
                    bytes,
                    &total_fields,
                );
            }
        }

        // StringHashMap stores borrowed field names plus values and metadata.
        // This bound deliberately exceeds the implementation's load factor and
        // control-byte overhead while remaining proportional to real schema
        // width rather than segment bytes.
        bytes = try addTextMergeEstimate(
            bytes,
            try addTextMergeEstimate(4096, try mulTextMergeEstimate(total_fields, 96)),
        );
        return bytes;
    }

    fn addTextMergeReaderPublicationEstimate(
        scratch_alloc: Allocator,
        segment_bytes: []const u8,
        bytes: u64,
        total_fields: *u64,
    ) !u64 {
        var reader = try segment_mod.SegmentReader.init(scratch_alloc, segment_bytes);
        defer reader.deinit();

        total_fields.* = try addTextMergeEstimate(total_fields.*, @intCast(reader.fields.len));
        var estimated = try mulTextMergeEstimate(@intCast(reader.fields.len), @sizeOf(segment_mod.SegmentReader.FieldInfo));
        for (reader.fields) |field| {
            estimated = try addTextMergeEstimate(
                estimated,
                try mulTextMergeEstimate(@intCast(field.sections.len), @sizeOf(segment_mod.SegmentReader.SectionInfo)),
            );
        }
        if (reader.stored_block_validations) |validations| {
            estimated = try addTextMergeEstimate(
                estimated,
                try mulTextMergeEstimate(@intCast(validations.len), @sizeOf(std.atomic.Value(u8))),
            );
        }
        return try addTextMergeEstimate(bytes, estimated);
    }

    fn addTextMergeEstimate(lhs: u64, rhs: u64) !u64 {
        return std.math.add(u64, lhs, rhs) catch error.ResourceBudgetExceeded;
    }

    fn mulTextMergeEstimate(lhs: u64, rhs: u64) !u64 {
        return std.math.mul(u64, lhs, rhs) catch error.ResourceBudgetExceeded;
    }

    fn estimateTextMergeRoaringBytes(doc_count: u32, copies: u64) !u64 {
        // One Roaring container covers 2^16 document IDs and uses at most an
        // 8 KiB bitmap (array containers promote at the same payload size).
        // Reserve container/list metadata plus array-to-bitmap promotion slack,
        // including allocator capacity rounding.
        const container_span: u64 = 1 << 16;
        const container_count = std.math.divCeil(
            u64,
            @as(u64, doc_count),
            container_span,
        ) catch return error.ResourceBudgetExceeded;
        const per_container_bytes: u64 = 12 * 1024;
        return try mulTextMergeEstimate(try mulTextMergeEstimate(container_count, per_container_bytes), copies);
    }

    fn estimateTextMergeWorkingSetBytes(seg: *const index_mod.SegmentEntry) !u64 {
        const layout = seg.layoutStats(false);

        // Merge working memory is driven by doc renumbering, the largest term
        // accumulator, compact dictionary/value builders, and the publication
        // identity table. File-backed output streams separately; heap-backed
        // output adds its serialized source-sized envelope at the caller.
        // Keep generous capacity/headroom factors here and enforce the
        // reservation with the bounded task allocator.
        // Include the fixed-capacity publication identity table. Ordinal-backed
        // documents use 32 bytes at the table's <= 50% load factor; retain more
        // headroom for the less common string-identity fallback.
        const per_doc_bytes: u64 = if (layout.index_sort_bytes > 0) 224 else 160;
        var bytes = try std.math.mul(u64, seg.reader.doc_count, per_doc_bytes);
        bytes = try std.math.add(u64, bytes, try std.math.mul(u64, layout.inverted_term_dict_bytes, 3));
        bytes = try std.math.add(u64, bytes, try std.math.mul(u64, layout.inverted_bloom_bytes, 3));
        bytes = try std.math.add(u64, bytes, layout.inverted_norm_bytes);
        bytes = try std.math.add(u64, bytes, try std.math.mul(u64, layout.typed_doc_values_bytes, 2));
        bytes = try std.math.add(u64, bytes, try std.math.mul(u64, layout.doc_ordinals_bytes, 2));
        return bytes;
    }

    fn shouldDeferTextMergeForResourcePressure(self: *IndexManager) bool {
        const manager = self.resource_manager orelse return false;
        if (sliceDefersBackgroundWork(manager.sliceStats(.full_text_build_working_set))) return true;
        return sliceDefersBackgroundWork(manager.sliceStats(.text_merge_buffers));
    }

    fn sliceDefersBackgroundWork(stats: resource_manager_mod.SliceStats) bool {
        return switch (stats.pressure) {
            .normal => false,
            .soft => stats.soft_action == .defer_background_work or stats.soft_action == .reject_work,
            .hard => stats.hard_action == .defer_background_work or stats.hard_action == .reject_work,
        };
    }

    /// Reconcile deletion-only source changes into the merge output. Segment
    /// replacement is still stale, but monotonic tombstones no longer force a
    /// completed merge to be discarded and retried under sustained mutation.
    fn textMergePublicationDeletes(
        entry: *TextIndex,
        task: *const TextMergeTask,
        result: *const TextMergeResult,
        deletion_deltas: []const TextMergeDeletionDelta,
    ) !TextMergePublicationDeletes {
        if (deletion_deltas.len != task.source.len) return error.InvalidDeletionSnapshot;
        const publication_alloc = task.mergeAllocator();
        const output_count = if (result.prepared_segments.len > 0) result.prepared_segments.len else result.segments.len;
        const output_deleted = try publication_alloc.alloc(?roaring.RoaringBitmap, output_count);
        @memset(output_deleted, null);
        errdefer {
            for (output_deleted) |*maybe_deleted| {
                if (maybe_deleted.*) |*deleted| deleted.deinit();
            }
            publication_alloc.free(output_deleted);
        }

        const snap = entry.persistent.acquireSnapshot();
        defer snap.release();
        for (task.source, task.merge_indices, deletion_deltas) |source, source_idx, delta| {
            const seg = findSegmentById(snap, source.id) orelse return .{
                .source_current = false,
                .bitmaps = output_deleted,
            };
            const frozen_seg = &task.snapshot.segments[source_idx];
            const expected_count = @as(u64, source.deleted_count) + @as(u64, @intCast(delta.count));
            if (@as(u64, seg.shared.deleted_count.load(.acquire)) != expected_count) return .{
                .source_current = false,
                .bitmaps = output_deleted,
            };

            var delta_iter = delta.bitmap.iterator();
            while (delta_iter.next()) |doc_id| {
                if (doc_id >= frozen_seg.reader.doc_count) return error.InvalidSegment;

                const location = if (try frozen_seg.reader.docOrdinal(doc_id)) |ordinal|
                    result.outputForOrdinal(ordinal)
                else if (try frozen_seg.reader.storedDoc(doc_id)) |stored|
                    result.outputForId(stored.id)
                else
                    null;
                const output = location orelse return error.MissingMergeDocumentIdentity;
                if (output.segment >= output_deleted.len) return error.InvalidSegment;
                const output_idx: usize = @intCast(output.segment);
                if (output_deleted[output_idx] == null) output_deleted[output_idx] = roaring.RoaringBitmap.init(publication_alloc);
                try output_deleted[output_idx].?.add(output.doc);
            }
        }

        return .{
            .source_current = true,
            .bitmaps = output_deleted,
        };
    }

    fn findSegmentById(snap: *const index_mod.IndexSnapshot, id: u64) ?*const index_mod.SegmentEntry {
        for (snap.segments) |*seg| {
            if (seg.id == id) return seg;
        }
        return null;
    }

    fn textMergeSourceIds(alloc: Allocator, source: []const TextMergeSourceSegment) ![]u64 {
        const ids = try alloc.alloc(u64, source.len);
        for (source, 0..) |segment, i| ids[i] = segment.id;
        return ids;
    }

    fn textMergeTaskInputBytes(task: *const TextMergeTask) u64 {
        var total: u64 = 0;
        for (task.merge_indices) |seg_idx| {
            if (seg_idx >= task.snapshot.segments.len) continue;
            total +|= @intCast(task.snapshot.segments[seg_idx].data.bytes().len);
        }
        return total;
    }

    fn textMergeResultOutputStats(result: *const TextMergeResult) TextMergeResultOutputStats {
        var stats = TextMergeResultOutputStats{};
        if (result.prepared_segments.len > 0) {
            stats.segments = @intCast(result.prepared_segments.len);
            for (result.prepared_segments) |*segment| stats.bytes +|= @intCast(segment.data.bytes().len);
            return stats;
        }
        stats.segments = @intCast(result.segments.len);
        for (result.segments) |segment| stats.bytes +|= @intCast(segment.len);
        return stats;
    }

    fn textIndexNeedsMerge(self: *IndexManager, index: *persistent_mod.PersistentIndex, policy: merger_mod.MergePolicy) !bool {
        return try text_index_maintenance.needsMerge(self.alloc, index, policy);
    }

    fn forceCompactTextIndexWithOptions(
        self: *IndexManager,
        entry: *TextIndex,
        options: ForceTextCompactOptions,
    ) !bool {
        self.text_merge_scheduler.supersedeInFlightForIndex(self.alloc, entry.config.name);
        entry.detachAllMergeDeletionStates();
        while (true) {
            const snap = entry.persistent.snapshot();
            if (snap.segments.len < 2) return true;
            if (options.mode == .best_effort and self.shouldDeferTextMergeForResourcePressure()) return false;

            const planned = try text_index_maintenance.planForceCompactAlloc(self.alloc, snap, force_merge_max_segments_at_once);
            defer self.alloc.free(planned);
            var reservation = self.reserveTextMergeBuffers(&entry.persistent, snap, planned, .strict) catch |err| switch (err) {
                error.ResourceBudgetExceeded => if (options.mode == .best_effort) return false else return err,
                else => return err,
            };
            defer if (reservation) |*active| active.release();

            const applied = text_index_maintenance.applyPlannedMerge(
                self.alloc,
                &entry.persistent,
                snap,
                planned,
                activeTextMergePolicy().max_segment_size,
                "force compact text index merge failed",
                "force compact text index apply merge failed",
            ) catch |err| switch (err) {
                error.ResourceBudgetExceeded => if (options.mode == .best_effort) return false else return err,
                else => return err,
            };
            if (!applied) return false;
        }
    }

    fn removeInMemory(self: *IndexManager, name: []const u8) void {
        for (self.text_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                self.freeTextIndexEntry(entry);
                _ = self.text_indexes.orderedRemove(i);
                self.dropIndexLoadStateNoLock(name);
                return;
            }
        }
        for (self.dense_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                self.freeDenseIndexEntry(entry);
                _ = self.dense_indexes.orderedRemove(i);
                self.dropIndexLoadStateNoLock(name);
                return;
            }
        }
        for (self.sparse_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                self.freeSparseIndexEntry(entry);
                _ = self.sparse_indexes.orderedRemove(i);
                self.dropIndexLoadStateNoLock(name);
                return;
            }
        }
        for (self.graph_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                self.freeGraphIndexEntry(entry);
                _ = self.graph_indexes.orderedRemove(i);
                self.dropIndexLoadStateNoLock(name);
                return;
            }
        }
        for (self.algebraic_indexes.items, 0..) |*entry, i| {
            if (std.mem.eql(u8, entry.config.name, name)) {
                self.freeAlgebraicIndexEntry(entry);
                _ = self.algebraic_indexes.orderedRemove(i);
                self.dropIndexLoadStateNoLock(name);
                return;
            }
        }
    }

    fn detachedIndexConfig(entry: *const DetachedIndex) *const types.IndexConfig {
        return switch (entry.*) {
            inline else => |*index| &index.config,
        };
    }

    fn ensureDetachedIndexCapacity(self: *IndexManager, entry: DetachedIndex) !void {
        switch (entry) {
            .full_text => try self.text_indexes.ensureUnusedCapacity(self.alloc, 1),
            .dense_vector => try self.dense_indexes.ensureUnusedCapacity(self.alloc, 1),
            .sparse_vector => try self.sparse_indexes.ensureUnusedCapacity(self.alloc, 1),
            .graph => try self.graph_indexes.ensureUnusedCapacity(self.alloc, 1),
            .algebraic => try self.algebraic_indexes.ensureUnusedCapacity(self.alloc, 1),
        }
    }

    fn appendDetachedIndexAssumeCapacity(self: *IndexManager, entry: *DetachedIndex) void {
        switch (entry.*) {
            .full_text => |index| {
                self.text_indexes.appendAssumeCapacity(index);
                if (index.compaction_pending.load(.acquire)) TextMergeScheduler.schedule(&self.text_indexes.items[self.text_indexes.items.len - 1]);
            },
            .dense_vector => |index_value| {
                const index = index_value;
                if (index.vector_loader_context) |ctx| ctx.manager = self;
                self.dense_indexes.appendAssumeCapacity(index);
            },
            .sparse_vector => |index| self.sparse_indexes.appendAssumeCapacity(index),
            .graph => |index| self.graph_indexes.appendAssumeCapacity(index),
            .algebraic => |index| self.algebraic_indexes.appendAssumeCapacity(index),
        }
        entry.* = undefined;
    }

    fn detachInMemoryNoLock(self: *IndexManager, name: []const u8) ?DetachedIndex {
        for (self.text_indexes.items, 0..) |entry, i| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            const detached = self.text_indexes.orderedRemove(i);
            self.dropIndexLoadStateNoLock(name);
            return .{ .full_text = detached };
        }
        for (self.dense_indexes.items, 0..) |entry, i| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            const detached = self.dense_indexes.orderedRemove(i);
            self.dropIndexLoadStateNoLock(name);
            return .{ .dense_vector = detached };
        }
        for (self.sparse_indexes.items, 0..) |entry, i| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            const detached = self.sparse_indexes.orderedRemove(i);
            self.dropIndexLoadStateNoLock(name);
            return .{ .sparse_vector = detached };
        }
        for (self.graph_indexes.items, 0..) |entry, i| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            const detached = self.graph_indexes.orderedRemove(i);
            self.dropIndexLoadStateNoLock(name);
            return .{ .graph = detached };
        }
        for (self.algebraic_indexes.items, 0..) |entry, i| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            const detached = self.algebraic_indexes.orderedRemove(i);
            self.dropIndexLoadStateNoLock(name);
            return .{ .algebraic = detached };
        }
        return null;
    }

    fn detachDenseInMemoryNoLock(self: *IndexManager, name: []const u8) ?DenseIndex {
        for (self.dense_indexes.items, 0..) |entry, i| {
            if (!std.mem.eql(u8, entry.config.name, name)) continue;
            const detached = self.dense_indexes.orderedRemove(i);
            self.dropIndexLoadStateNoLock(name);
            return detached;
        }
        return null;
    }

    fn truncateEnrichments(self: *IndexManager, len: usize) void {
        while (self.enrichments.items.len > len) {
            self.enrichments.items[self.enrichments.items.len - 1].deinit(self.alloc);
            _ = self.enrichments.pop();
        }
    }

    pub fn lookupDenseDocKey(self: *IndexManager, store: *docstore_mod.DocStore, index_name: []const u8, vector_id: u64) !?[]u8 {
        const entry = self.denseIndex(index_name) orelse return null;
        if (try entry.index.getMetadata(vector_id)) |metadata| return metadata;

        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();

        var txn = try runtime_store.store.beginRead();
        defer txn.abort();
        return try self.lookupDenseDocKeyByVectorIdTxn(&txn, index_name, vector_id);
    }

    fn backfillDenseIndex(self: *IndexManager, store: *docstore_mod.DocStore, entry: *DenseIndex) !void {
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();

        const lower = try internal_keys.documentRangeLowerAlloc(self.alloc, self.byte_range.start);
        defer self.alloc.free(lower);
        const upper = try internal_keys.documentRangeUpperAlloc(self.alloc, if (self.byte_range.end.len > 0) self.byte_range.end else "");
        defer if (upper) |buf| self.alloc.free(buf);

        const docs = try backend_scan.scanRange(self.alloc, &runtime_store.store, lower, if (upper) |buf| buf else "");
        defer backend_scan.freeResults(self.alloc, docs);

        var items = std.ArrayListUnmanaged(hbc_mod.BatchInsertItem).empty;
        defer {
            for (items.items) |item| {
                self.alloc.free(@constCast(item.vector));
                if (item.metadata.len > 0) self.alloc.free(@constCast(item.metadata));
            }
            items.deinit(self.alloc);
        }
        var pending_mappings = std.ArrayListUnmanaged(PendingDenseVectorMapping).empty;
        defer pending_mappings.deinit(self.alloc);
        var mapping_batch = try runtime_store.store.beginBatch();
        errdefer mapping_batch.abort();

        for (docs) |doc| {
            if (!internal_keys.isPrimaryDocumentKey(doc.key)) continue;
            const raw_key = (try internal_keys.decodePrimaryDocumentKeyAlloc(self.alloc, doc.key)) orelse continue;
            defer self.alloc.free(raw_key);
            if (!self.keyInRange(raw_key)) continue;
            const vector_values = (try mapper.extractDenseVectorField(self.alloc, doc.value, entry.field_name, entry.dims)) orelse continue;
            errdefer self.alloc.free(vector_values);

            const assignment = try self.ensureDenseVectorIdTxn(&mapping_batch, entry.config.name, raw_key, null);
            try items.append(self.alloc, .{
                .vector_id = assignment.vector_id,
                .vector = vector_values,
                .metadata = try self.alloc.dupe(u8, raw_key),
            });
            try pending_mappings.append(self.alloc, .{
                .doc_key = items.items[items.items.len - 1].metadata,
                .parent_doc_key = null,
                .vector_id = assignment.vector_id,
            });
        }

        try self.insertDenseItems(entry, items.items);
        try self.commitDenseVectorMappingsWithRollback(&mapping_batch, &mapping_batch, entry, entry.config.name, pending_mappings.items);
    }

    fn backfillSparseIndex(self: *IndexManager, store: *docstore_mod.DocStore, entry: *SparseIndex, resume_from: ?[]const u8) !void {
        const rebuild_state = self.rebuildState(.sparse_vector, entry.rebuild_root_path, entry.config);
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();

        const lower = try internal_keys.documentRangeLowerAlloc(self.alloc, self.byte_range.start);
        defer self.alloc.free(lower);
        const upper = try internal_keys.documentRangeUpperAlloc(self.alloc, if (self.byte_range.end.len > 0) self.byte_range.end else "");
        defer if (upper) |buf| self.alloc.free(buf);

        const docs = try backend_scan.scanRange(self.alloc, &runtime_store.store, lower, if (upper) |buf| buf else "");
        defer backend_scan.freeResults(self.alloc, docs);

        var writes = std.ArrayListUnmanaged(sparse_mod.SparseWrite).empty;
        defer {
            for (writes.items) |item| {
                self.alloc.free(@constCast(item.doc_id));
                self.alloc.free(@constCast(item.vec.indices));
                self.alloc.free(@constCast(item.vec.values));
            }
            writes.deinit(self.alloc);
        }

        var flushed_batches: usize = 0;
        var backfilled_doc_count: u64 = entry.index.doc_count;
        var saw_visible_doc = false;
        var max_flushed_key: ?[]const u8 = null;

        const flush_batch = struct {
            fn run(
                manager: *IndexManager,
                doc_store: *docstore_mod.DocStore,
                sparse_entry: *SparseIndex,
                rebuild: backfill_state_mod.RebuildState,
                writes_buf: *std.ArrayListUnmanaged(sparse_mod.SparseWrite),
                last_doc_key: []const u8,
                flush_count: *usize,
                doc_count: *u64,
            ) !void {
                if (writes_buf.items.len == 0) return;
                try manager.assignSparseWriteDocNumsFromIdentity(doc_store, sparse_entry, writes_buf.items);
                try sparse_entry.index.batchWithOptions(writes_buf.items, &.{}, .{
                    .defer_term_range_updates = true,
                });
                doc_count.* = sparse_entry.index.doc_count;
                try sparse_entry.index.persistBackfillDocCount(doc_count.*);
                for (writes_buf.items) |item| {
                    manager.alloc.free(@constCast(item.doc_id));
                    manager.alloc.free(@constCast(item.vec.indices));
                    manager.alloc.free(@constCast(item.vec.values));
                }
                writes_buf.clearRetainingCapacity();
                try rebuild.updateWithIo(manager.checkpointIo(), last_doc_key);
                flush_count.* += 1;
                if (@import("builtin").is_test) {
                    if (test_abort_sparse_backfill_after_batches) |limit| {
                        if (flush_count.* >= limit) return error.TestInjectedBackfillFailure;
                    }
                }
            }
        }.run;

        const backfill_batch_size = if (builtin.is_test) test_sparse_backfill_batch_size orelse sparse_backfill_batch_size else sparse_backfill_batch_size;
        for (docs) |doc| {
            if (!internal_keys.isPrimaryDocumentKey(doc.key)) continue;
            if (resume_from) |resume_key| {
                if (resume_key.len > 0 and std.mem.order(u8, doc.key, resume_key) != .gt) continue;
            }
            const raw_key = (try internal_keys.decodePrimaryDocumentKeyAlloc(self.alloc, doc.key)) orelse continue;
            defer self.alloc.free(raw_key);
            if (!self.keyInRange(raw_key)) continue;
            var sparse_vec = (try mapper.extractSparseVectorField(self.alloc, doc.value, entry.field_name)) orelse continue;
            var sparse_vec_owned = true;
            errdefer if (sparse_vec_owned) sparse_vec.deinit(self.alloc);
            saw_visible_doc = true;
            if (max_flushed_key == null or std.mem.order(u8, doc.key, max_flushed_key.?) == .gt) {
                max_flushed_key = doc.key;
            }
            try writes.append(self.alloc, .{
                .doc_id = try self.alloc.dupe(u8, raw_key),
                .vec = .{
                    .indices = sparse_vec.indices,
                    .values = sparse_vec.values,
                },
            });
            sparse_vec_owned = false;
            if (writes.items.len >= backfill_batch_size) {
                try flush_batch(self, store, entry, rebuild_state, &writes, max_flushed_key.?, &flushed_batches, &backfilled_doc_count);
            }
        }

        if (writes.items.len > 0) {
            try flush_batch(self, store, entry, rebuild_state, &writes, max_flushed_key.?, &flushed_batches, &backfilled_doc_count);
        }

        if (!saw_visible_doc or flushed_batches > 0) try rebuild_state.clearWithIo(self.checkpointIo());
        if (flushed_batches > 0) try entry.index.checkpointLsmWalAfterDurableBoundary();
    }

    fn denseVectorIdHasExistingMetadata(
        self: *IndexManager,
        entry: *DenseIndex,
        vector_id: u64,
        memo: ?*DenseVectorMetadataPresenceMemo,
    ) !bool {
        if (memo) |cache| {
            if (cache.get(vector_id)) |present| return present;
        }
        const existing_metadata = entry.index.getMetadata(vector_id) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const present = existing_metadata != null;
        if (memo) |cache| {
            if (existing_metadata) |metadata| {
                defer self.alloc.free(metadata);
                try cache.notePresent(self.alloc, vector_id, metadata);
            } else {
                try cache.noteAbsent(self.alloc, vector_id);
            }
        } else if (existing_metadata) |metadata| {
            self.alloc.free(metadata);
        }
        return present;
    }

    fn denseVectorIdMetadataState(
        self: *IndexManager,
        entry: *DenseIndex,
        vector_id: u64,
        doc_key: []const u8,
        memo: ?*DenseVectorMetadataPresenceMemo,
    ) !DenseVectorMetadataState {
        if (memo) |cache| {
            if (cache.getMetadata(vector_id)) |metadata| {
                return if (std.mem.eql(u8, metadata, doc_key)) .matches else .conflicts;
            }
            if (cache.get(vector_id) == false) return .absent;
        }
        const existing_metadata = entry.index.getMetadata(vector_id) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (existing_metadata) |metadata| {
            defer self.alloc.free(metadata);
            if (memo) |cache| try cache.notePresent(self.alloc, vector_id, metadata);
            return if (std.mem.eql(u8, metadata, doc_key)) .matches else .conflicts;
        }
        if (memo) |cache| try cache.noteAbsent(self.alloc, vector_id);
        return .absent;
    }

    fn legacyOrdinalDenseVectorIdAssignmentTxn(
        self: *IndexManager,
        txn: anytype,
        entry: *DenseIndex,
        doc_key: []const u8,
        parent_doc_key: ?[]const u8,
        metadata_presence_memo: ?*DenseVectorMetadataPresenceMemo,
    ) !?DenseVectorIdAssignment {
        if (parent_doc_key != null) return null;
        const ordinal = (try doc_identity.lookupOrdinalTxn(self.alloc, txn, doc_key)) orelse return null;
        const vector_id: u64 = ordinal;
        // Compatibility only: pre-DOCID dense vectors may have used the document
        // ordinal as the HBC vector ID. New assignments use deterministic IDs.
        return switch (try self.denseVectorIdMetadataState(entry, vector_id, doc_key, metadata_presence_memo)) {
            .matches => .{
                .vector_id = vector_id,
                .needs_mapping = false,
                .can_assume_absent = false,
            },
            .absent, .conflicts => null,
        };
    }

    fn prefetchDenseExistingMetadataTxn(
        self: *IndexManager,
        entry: *DenseIndex,
        index_txn: anytype,
        writes: []const mapper.DenseEmbeddingWrite,
        keep_write: []const bool,
        prefetched_ordinals: ?[]const ?doc_identity.DocOrdinal,
        memo: *DenseVectorMetadataPresenceMemo,
    ) !void {
        var candidate_count: usize = 0;
        for (writes, 0..) |write, write_index| {
            if (!keep_write[write_index]) continue;
            if (!std.mem.eql(u8, write.index_name, entry.config.name)) continue;
            if (write.vector.len == 0 and write.artifact_key == null) continue;
            candidate_count += 1;
        }
        if (candidate_count == 0) return;

        var arena_state = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        const max_candidate_ids = candidate_count * 2;
        const vector_ids_storage = try arena.alloc(u64, max_candidate_ids);
        const out_metadata = try arena.alloc(?[]const u8, max_candidate_ids);
        const lookups = try arena.alloc(hbc_mod.FixedKeyLookup, max_candidate_ids);
        const key_views = try arena.alloc([]const u8, max_candidate_ids);
        const values = try arena.alloc(?[]const u8, max_candidate_ids);

        var filled: usize = 0;
        for (writes, 0..) |write, write_index| {
            if (!keep_write[write_index]) continue;
            if (!std.mem.eql(u8, write.index_name, entry.config.name)) continue;
            if (write.vector.len == 0 and write.artifact_key == null) continue;
            vector_ids_storage[filled] = deterministicDenseVectorId(write.doc_key);
            filled += 1;
            if (write.parent_doc_key == null) {
                const ordinal = if (prefetched_ordinals) |ordinals|
                    ordinals[write_index]
                else
                    null;
                if (ordinal) |legacy_ordinal| {
                    vector_ids_storage[filled] = legacy_ordinal;
                    filled += 1;
                }
            }
        }

        const candidate_vector_ids = vector_ids_storage[0..filled];
        std.mem.sort(u64, candidate_vector_ids, {}, std.sort.asc(u64));
        var unique_count: usize = 0;
        var previous: ?u64 = null;
        for (candidate_vector_ids) |vector_id| {
            if (previous != null and previous.? == vector_id) continue;
            vector_ids_storage[unique_count] = vector_id;
            unique_count += 1;
            previous = vector_id;
        }
        const vector_ids = vector_ids_storage[0..unique_count];

        if (comptime @hasDecl(@TypeOf(index_txn.*), "getManySorted")) {
            try entry.index.getMetadataManySortedInTxnWithScratch(
                index_txn,
                vector_ids,
                out_metadata[0..unique_count],
                lookups,
                key_views,
                values,
            );
        } else {
            for (vector_ids, 0..) |vector_id, i| {
                out_metadata[i] = try entry.index.getMetadataInTxn(index_txn, vector_id);
            }
        }
        for (vector_ids, out_metadata[0..unique_count]) |vector_id, maybe_metadata| {
            if (maybe_metadata) |metadata| {
                try memo.notePresent(self.alloc, vector_id, metadata);
            } else {
                try memo.noteAbsent(self.alloc, vector_id);
            }
        }
    }

    fn ensureDenseVectorIdTxn(self: *IndexManager, txn: anytype, index_name: []const u8, doc_key: []const u8, parent_doc_key: ?[]const u8) !DenseVectorIdAssignment {
        return try self.ensureDenseVectorIdTxnWithMemo(txn, index_name, doc_key, parent_doc_key, null);
    }

    fn ensureDenseVectorIdTxnWithMemo(
        self: *IndexManager,
        txn: anytype,
        index_name: []const u8,
        doc_key: []const u8,
        parent_doc_key: ?[]const u8,
        metadata_presence_memo: ?*DenseVectorMetadataPresenceMemo,
    ) !DenseVectorIdAssignment {
        const mutable_txn = txn;
        if (try self.lookupDenseVectorIdTxn(mutable_txn, index_name, doc_key)) |existing| {
            return .{
                .vector_id = existing,
                .needs_mapping = false,
                .can_assume_absent = false,
            };
        }
        if (self.denseIndex(index_name)) |entry| {
            if (try self.legacyOrdinalDenseVectorIdAssignmentTxn(mutable_txn, entry, doc_key, parent_doc_key, metadata_presence_memo)) |assignment| {
                return assignment;
            }
            const vector_id = deterministicDenseVectorId(doc_key);
            if (try self.denseVectorIdHasExistingMetadata(entry, vector_id, metadata_presence_memo)) {
                return .{
                    .vector_id = vector_id,
                    .needs_mapping = false,
                    .can_assume_absent = false,
                };
            }
            return .{
                .vector_id = vector_id,
                .needs_mapping = false,
                .can_assume_absent = true,
            };
        }
        const vector_id = deterministicDenseVectorId(doc_key);
        return .{
            .vector_id = vector_id,
            .needs_mapping = false,
            .can_assume_absent = true,
        };
    }

    fn replaceDenseVectorIdTxn(
        self: *IndexManager,
        txn: anytype,
        entry: *DenseIndex,
        index_name: []const u8,
        doc_key: []const u8,
        parent_doc_key: ?[]const u8,
        replacement_deletes: *std.ArrayListUnmanaged(u64),
    ) !DenseVectorIdAssignment {
        return try self.replaceDenseVectorIdTxnWithMemo(
            txn,
            entry,
            index_name,
            doc_key,
            parent_doc_key,
            replacement_deletes,
            null,
        );
    }

    fn replaceDenseVectorIdTxnWithMemo(
        self: *IndexManager,
        txn: anytype,
        entry: *DenseIndex,
        index_name: []const u8,
        doc_key: []const u8,
        parent_doc_key: ?[]const u8,
        replacement_deletes: *std.ArrayListUnmanaged(u64),
        metadata_presence_memo: ?*DenseVectorMetadataPresenceMemo,
    ) !DenseVectorIdAssignment {
        _ = replacement_deletes;
        const mutable_txn = txn;
        if (try self.lookupDenseVectorIdTxn(mutable_txn, index_name, doc_key)) |mapped| {
            return .{
                .vector_id = mapped,
                .needs_mapping = false,
                .can_assume_absent = false,
            };
        }

        if (try self.legacyOrdinalDenseVectorIdAssignmentTxn(mutable_txn, entry, doc_key, parent_doc_key, metadata_presence_memo)) |assignment| {
            return assignment;
        }

        const vector_id = deterministicDenseVectorId(doc_key);
        if (try self.denseVectorIdHasExistingMetadata(entry, vector_id, metadata_presence_memo)) {
            return .{
                .vector_id = vector_id,
                .needs_mapping = false,
                .can_assume_absent = false,
            };
        }
        return .{
            .vector_id = vector_id,
            .needs_mapping = false,
            .can_assume_absent = true,
        };
    }

    fn replaceDenseVectorIdFromPrefetchedState(
        self: *IndexManager,
        entry: *DenseIndex,
        doc_key: []const u8,
        parent_doc_key: ?[]const u8,
        mapped_vector_id: ?u64,
        ordinal: ?doc_identity.DocOrdinal,
        metadata_presence_memo: *DenseVectorMetadataPresenceMemo,
    ) !DenseVectorIdAssignment {
        if (mapped_vector_id) |mapped| {
            return .{
                .vector_id = mapped,
                .needs_mapping = false,
                .can_assume_absent = false,
            };
        }
        if (parent_doc_key == null) {
            if (ordinal) |legacy_ordinal| {
                const legacy_vector_id: u64 = legacy_ordinal;
                if ((try self.denseVectorIdMetadataState(entry, legacy_vector_id, doc_key, metadata_presence_memo)) == .matches) {
                    return .{
                        .vector_id = legacy_vector_id,
                        .needs_mapping = false,
                        .can_assume_absent = false,
                    };
                }
            }
        }

        const vector_id = deterministicDenseVectorId(doc_key);
        if (try self.denseVectorIdHasExistingMetadata(entry, vector_id, metadata_presence_memo)) {
            return .{
                .vector_id = vector_id,
                .needs_mapping = false,
                .can_assume_absent = false,
            };
        }
        return .{
            .vector_id = vector_id,
            .needs_mapping = false,
            .can_assume_absent = true,
        };
    }

    fn reserveDenseVectorIdTxn(self: *IndexManager, txn: anytype, index_name: []const u8) !u64 {
        const mutable_txn = txn;
        const next_key = try denseNextIdKey(self.alloc, index_name);
        defer self.alloc.free(next_key);
        const legacy_next_key = try legacyDenseNextIdKey(self.alloc, index_name);
        defer self.alloc.free(legacy_next_key);

        var next_id: u64 = 1;
        const next_raw = mutable_txn.get(next_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (next_raw) |raw| {
            if (raw.len != 8) return error.InvalidDenseVectorMetadata;
            next_id = std.mem.readInt(u64, raw[0..8], .little);
        }
        const legacy_next_raw = mutable_txn.get(legacy_next_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (legacy_next_raw) |raw| {
            if (raw.len != 8) return error.InvalidDenseVectorMetadata;
            next_id = @max(next_id, std.mem.readInt(u64, raw[0..8], .little));
        }

        var next_buf: [8]u8 = undefined;
        std.mem.writeInt(u64, &next_buf, next_id + 1, .little);
        try mutable_txn.put(next_key, &next_buf);
        return next_id;
    }

    fn setDenseNextIdAtLeast(self: *IndexManager, store: anytype, index_name: []const u8, next_id: u64) !void {
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();

        var txn = try runtime_store.store.beginWrite();
        errdefer txn.abort();
        try self.setDenseNextIdAtLeastTxn(&txn, index_name, next_id);
        try txn.commit();
    }

    fn setDenseNextIdAtLeastTxn(self: *IndexManager, txn: anytype, index_name: []const u8, next_id: u64) !void {
        const mutable_txn = txn;
        const next_key = try denseNextIdKey(self.alloc, index_name);
        defer self.alloc.free(next_key);
        const legacy_next_key = try legacyDenseNextIdKey(self.alloc, index_name);
        defer self.alloc.free(legacy_next_key);

        const next_raw = mutable_txn.get(next_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        var current_next_id: u64 = 1;
        if (next_raw) |raw| {
            if (raw.len != 8) return error.InvalidDenseVectorMetadata;
            current_next_id = std.mem.readInt(u64, raw[0..8], .little);
        }
        const legacy_next_raw = mutable_txn.get(legacy_next_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (legacy_next_raw) |raw| {
            if (raw.len != 8) return error.InvalidDenseVectorMetadata;
            current_next_id = @max(current_next_id, std.mem.readInt(u64, raw[0..8], .little));
        }
        if (current_next_id >= next_id) return;

        var next_buf: [8]u8 = undefined;
        std.mem.writeInt(u64, &next_buf, next_id, .little);
        try mutable_txn.put(next_key, &next_buf);
    }

    pub fn lookupDenseVectorId(self: *IndexManager, store: anytype, index_name: []const u8, doc_key: []const u8) !?u64 {
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();

        var txn = try runtime_store.store.beginRead();
        defer txn.abort();
        if (try self.lookupDenseVectorIdTxn(&txn, index_name, doc_key)) |mapped| return mapped;

        const entry = self.denseIndex(index_name) orelse return null;
        if (try doc_identity.lookupOrdinalTxn(self.alloc, &txn, doc_key)) |ordinal| {
            const vector_id: u64 = ordinal;
            if ((try self.denseVectorIdMetadataState(entry, vector_id, doc_key, null)) == .matches) return vector_id;
        }
        const vector_id = deterministicDenseVectorId(doc_key);
        const metadata = (try entry.index.getMetadata(vector_id)) orelse return null;
        self.alloc.free(metadata);
        return vector_id;
    }

    fn lookupDenseVectorIdTxn(self: *IndexManager, txn: anytype, index_name: []const u8, doc_key: []const u8) !?u64 {
        var mutable_txn = txn;
        const key = try denseDocMappingKey(self.alloc, index_name, doc_key);
        defer self.alloc.free(key);
        const legacy_key = try legacyDenseDocMappingKey(self.alloc, index_name, doc_key);
        defer self.alloc.free(legacy_key);

        const raw = mutable_txn.get(key) catch |err| switch (err) {
            error.NotFound => legacy: {
                const legacy_raw = mutable_txn.get(legacy_key) catch |legacy_err| switch (legacy_err) {
                    error.NotFound => return null,
                    else => return legacy_err,
                };
                break :legacy legacy_raw;
            },
            else => return err,
        };
        if (raw.len != 8) return error.InvalidDenseVectorMetadata;
        return std.mem.readInt(u64, raw[0..8], .little);
    }

    fn lookupDenseVectorIdsTxnAlloc(
        self: *IndexManager,
        txn: anytype,
        index_name: []const u8,
        doc_keys: []const []const u8,
    ) ![]?u64 {
        const mutable_txn = txn;
        const PendingLookup = struct {
            source_index: usize,
            legacy: bool,
            key: []u8,

            fn lessThan(_: void, lhs: @This(), rhs: @This()) bool {
                return std.mem.lessThan(u8, lhs.key, rhs.key);
            }
        };

        const out = try self.alloc.alloc(?u64, doc_keys.len);
        errdefer self.alloc.free(out);
        @memset(out, null);
        if (doc_keys.len == 0) return out;

        const modern_found = try self.alloc.alloc(bool, doc_keys.len);
        defer self.alloc.free(modern_found);
        @memset(modern_found, false);
        const pending = try self.alloc.alloc(PendingLookup, doc_keys.len * 2);
        var initialized_pending: usize = 0;
        defer {
            for (pending[0..initialized_pending]) |item| self.alloc.free(item.key);
            self.alloc.free(pending);
        }
        for (doc_keys, 0..) |doc_key, i| {
            pending[i * 2] = .{
                .source_index = i,
                .legacy = false,
                .key = try denseDocMappingKey(self.alloc, index_name, doc_key),
            };
            initialized_pending += 1;
            pending[i * 2 + 1] = .{
                .source_index = i,
                .legacy = true,
                .key = try legacyDenseDocMappingKey(self.alloc, index_name, doc_key),
            };
            initialized_pending += 1;
        }
        std.sort.pdq(PendingLookup, pending, {}, PendingLookup.lessThan);

        const read_keys = try self.alloc.alloc([]const u8, pending.len);
        defer self.alloc.free(read_keys);
        const read_values = try self.alloc.alloc(?[]const u8, pending.len);
        defer self.alloc.free(read_values);
        for (pending, 0..) |item, i| read_keys[i] = item.key;
        try mutable_txn.getManySorted(read_keys, read_values);

        for (pending, read_values) |item, maybe_raw| {
            const raw = maybe_raw orelse continue;
            if (raw.len != @sizeOf(u64)) return error.InvalidDenseVectorMetadata;
            const vector_id = std.mem.readInt(u64, raw[0..8], .little);
            if (item.legacy) {
                if (!modern_found[item.source_index] and out[item.source_index] == null) {
                    out[item.source_index] = vector_id;
                }
            } else {
                out[item.source_index] = vector_id;
                modern_found[item.source_index] = true;
            }
        }
        return out;
    }

    fn resolveDenseVectorIdForDeleteTxn(self: *IndexManager, txn: anytype, index_name: []const u8, doc_key: []const u8) !?u64 {
        if (try self.lookupDenseVectorIdTxn(txn, index_name, doc_key)) |mapped| return mapped;
        const entry = self.denseIndex(index_name) orelse return null;
        if (try doc_identity.lookupOrdinalTxn(self.alloc, txn, doc_key)) |ordinal| {
            const vector_id: u64 = ordinal;
            if ((try self.denseVectorIdMetadataState(entry, vector_id, doc_key, null)) == .matches) return vector_id;
        }
        return deterministicDenseVectorId(doc_key);
    }

    fn indexTextBatchForConfig(self: *IndexManager, store: *docstore_mod.DocStore, entry: *TextIndex, writes: []const types.BatchWrite) !TextBatchMutationStats {
        if (writes.len == 0) return .{};

        var filtered = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer filtered.deinit(self.alloc);

        for (writes) |write| {
            if (!self.keyInRange(write.key)) continue;
            if (!try textIndexShouldConsumeDoc(self, entry, write.key)) continue;
            try filtered.append(self.alloc, write);
        }

        if (filtered.items.len == 0) return .{};

        var doc_ids = try self.alloc.alloc([]const u8, filtered.items.len);
        defer self.alloc.free(doc_ids);
        for (filtered.items, 0..) |write, i| doc_ids[i] = write.key;

        var identity_txn = try store.beginProbeTxn();
        defer identity_txn.abort();
        const ordinals = try doc_identity.lookupOrdinalsTxnAlloc(self.alloc, &identity_txn, doc_ids);
        defer self.alloc.free(ordinals);

        var docs = try self.alloc.alloc(mapper.MapperDoc, filtered.items.len);
        defer self.alloc.free(docs);
        for (filtered.items, 0..) |write, i| {
            docs[i] = .{
                .key = write.key,
                .value = write.value,
                .doc_ordinal = ordinals[i],
            };
        }
        return try self.indexTextProjectionDocsMaybeChunked(store, entry, docs);
    }

    fn indexTextProjectionDocs(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *TextIndex,
        docs: []const mapper.MapperDoc,
    ) !TextBatchMutationStats {
        var arena_state = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const source_batch = try mapper.buildTextProjectionSourceBatchWithOptions(
            arena,
            docs,
            try self.textProjectionOptionsForSchema(arena, entry.runtime_schema == null),
        );
        return try self.indexPreparedTextProjectionSourceDocsWithArena(arena, store, entry, source_batch.docs);
    }

    fn indexTextProjectionDocsMaybeChunked(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *TextIndex,
        docs: []const mapper.MapperDoc,
    ) !TextBatchMutationStats {
        const source_target_bytes = textProjectionSourceBuildTargetBytes();
        if (docs.len <= max_text_projection_docs_per_segment_build and estimatedMapperDocsBytes(docs) <= source_target_bytes) {
            return try self.indexTextProjectionDocs(store, entry, docs);
        }

        var stats = TextBatchMutationStats{};
        var start: usize = 0;
        while (start < docs.len) {
            const end = splitMapperDocsEnd(docs, start, source_target_bytes);
            const chunk_stats = try self.indexTextProjectionDocs(store, entry, docs[start..end]);
            stats.noteIndex(chunk_stats.indexed_any);
            stats.noteDelete(chunk_stats.deleted_any);
            start = end;
        }
        return stats;
    }

    fn indexTextProjectionSourceDocs(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *TextIndex,
        source_docs: []const mapper.TextProjectionSourceDoc,
        opts: IndexBatchOptions,
        skip: ?*const TextSplitHandoff,
    ) !void {
        var arena_state = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const stats = try self.indexFilteredTextProjectionSourceDocsWithArena(arena, store, entry, source_docs, skip);
        try self.finalizeTextBatchMutations(entry, opts, stats);
    }

    fn indexFilteredTextProjectionSourceDocsWithArena(
        self: *IndexManager,
        arena: std.mem.Allocator,
        store: *docstore_mod.DocStore,
        entry: *TextIndex,
        source_docs: []const mapper.TextProjectionSourceDoc,
        skip: ?*const TextSplitHandoff,
    ) !TextBatchMutationStats {
        var filtered = std.ArrayListUnmanaged(mapper.TextProjectionSourceDoc).empty;
        defer filtered.deinit(arena);
        for (source_docs) |doc| {
            if (!self.keyInRange(doc.key)) continue;
            if (!try textIndexShouldConsumeDoc(self, entry, doc.key)) continue;
            if (skip) |handoff| {
                if (handoff.shouldSkip(doc.key)) continue;
            }
            try filtered.append(arena, doc);
        }
        if (filtered.items.len == 0) return .{};

        return try self.indexPreparedTextProjectionSourceDocsMaybeChunked(arena, store, entry, filtered.items);
    }

    fn indexPreparedTextProjectionSourceDocsMaybeChunked(
        self: *IndexManager,
        arena: std.mem.Allocator,
        store: *docstore_mod.DocStore,
        entry: *TextIndex,
        source_docs: []const mapper.TextProjectionSourceDoc,
    ) !TextBatchMutationStats {
        const source_target_bytes = textProjectionSourceBuildTargetBytes();
        if (source_docs.len <= max_text_projection_docs_per_segment_build and estimatedTextProjectionSourceDocsBytes(source_docs) <= source_target_bytes) {
            return try self.indexPreparedTextProjectionSourceDocsWithArena(arena, store, entry, source_docs);
        }

        var stats = TextBatchMutationStats{};
        var start: usize = 0;
        while (start < source_docs.len) {
            const end = splitTextProjectionSourceDocsEnd(source_docs, start, source_target_bytes);
            var chunk_arena_state = std.heap.ArenaAllocator.init(self.alloc);
            defer chunk_arena_state.deinit();
            const chunk_stats = try self.indexPreparedTextProjectionSourceDocsWithArena(
                chunk_arena_state.allocator(),
                store,
                entry,
                source_docs[start..end],
            );
            stats.noteIndex(chunk_stats.indexed_any);
            stats.noteDelete(chunk_stats.deleted_any);
            start = end;
        }
        return stats;
    }

    fn estimatedMapperDocsBytes(docs: []const mapper.MapperDoc) usize {
        var total: usize = 0;
        for (docs) |doc| total +|= estimatedMapperDocBytes(doc);
        return total;
    }

    fn estimatedMapperDocBytes(doc: mapper.MapperDoc) usize {
        return @sizeOf(mapper.MapperDoc) + doc.key.len + doc.value.len;
    }

    fn estimateProjectedTextPublication(docs: []const introducer_mod.TextDocument) TextPublicationEstimate {
        if (docs.len == 0) return .{};
        const target_segment_bytes = @max(@as(usize, 1), textSegmentBuildTargetBytes());
        const target_build_memory_bytes = @max(@as(usize, 1), textBuildMemoryTargetBytes());
        var estimate = TextPublicationEstimate{};
        var start: usize = 0;
        while (start < docs.len) {
            const split = introducer_mod.splitTextDocumentsForBuildBudget(docs, start, .{
                .target_build_memory_bytes = target_build_memory_bytes,
                .target_segment_bytes = target_segment_bytes,
            });
            estimate.segment_count +|= 1;
            estimate.byte_count +|= @max(split.estimated_build_bytes, split.estimated_segment_bytes) +| 64 * 1024;
            start = split.end;
        }
        return estimate;
    }

    fn splitMapperDocsEnd(docs: []const mapper.MapperDoc, start: usize, target_bytes: usize) usize {
        const max_end = @min(start + max_text_projection_docs_per_segment_build, docs.len);
        var end = start;
        var bytes: usize = 0;
        while (end < max_end) : (end += 1) {
            const doc_bytes = estimatedMapperDocBytes(docs[end]);
            if (end > start and bytes +| doc_bytes > target_bytes) break;
            bytes +|= doc_bytes;
        }
        return @max(start + 1, end);
    }

    fn estimatedTextProjectionSourceDocsBytes(docs: []const mapper.TextProjectionSourceDoc) usize {
        var total: usize = 0;
        for (docs) |doc| total +|= estimatedTextProjectionSourceDocBytes(doc);
        return total;
    }

    fn estimatedTextProjectionSourceDocBytes(doc: mapper.TextProjectionSourceDoc) usize {
        var total: usize = @sizeOf(mapper.TextProjectionSourceDoc) + doc.key.len + doc.stored_data.len;
        for (doc.schema_less_text_fields) |field| {
            total +|= @sizeOf(introducer_mod.TextField) + field.field_name.len + field.text.len;
        }
        return total;
    }

    fn splitTextProjectionSourceDocsEnd(
        docs: []const mapper.TextProjectionSourceDoc,
        start: usize,
        target_bytes: usize,
    ) usize {
        const max_end = @min(start + max_text_projection_docs_per_segment_build, docs.len);
        var end = start;
        var bytes: usize = 0;
        while (end < max_end) : (end += 1) {
            const doc_bytes = estimatedTextProjectionSourceDocBytes(docs[end]);
            if (end > start and bytes +| doc_bytes > target_bytes) break;
            bytes +|= doc_bytes;
        }
        return @max(start + 1, end);
    }

    fn indexPreparedTextProjectionSourceDocsWithArena(
        self: *IndexManager,
        arena: std.mem.Allocator,
        store: *docstore_mod.DocStore,
        entry: *TextIndex,
        source_docs: []const mapper.TextProjectionSourceDoc,
    ) !TextBatchMutationStats {
        if (source_docs.len == 0) return .{};

        const detailed_profile_enabled = textBenchProfileEnabled();
        const metrics_enabled = textBenchMetricsEnabled() or detailed_profile_enabled;
        const total_start_ns = if (metrics_enabled) platform_time.monotonicNs() else 0;
        var ordinals_ns: u64 = 0;
        var projection_ns: u64 = 0;
        var analyzer_merge_ns: u64 = 0;
        var segment_build_ns: u64 = 0;
        var index_segment_ns: u64 = 0;
        const memory_start: process_memory.Stats = if (detailed_profile_enabled) process_memory.snapshot() else .{};

        var ordinals_alloc_stats = PhaseAllocStats{};
        var ordinals_tracking = PhaseTrackingAllocator.init(arena, &ordinals_alloc_stats);
        const ordinals_alloc = if (detailed_profile_enabled) ordinals_tracking.allocator() else arena;
        const ordinals_start_ns = if (metrics_enabled) platform_time.monotonicNs() else 0;
        const source_docs_with_ordinals = try self.textProjectionSourceDocsWithOrdinals(ordinals_alloc, store, source_docs);
        if (metrics_enabled) ordinals_ns = platform_time.monotonicNs() - ordinals_start_ns;
        const memory_after_ordinals: process_memory.Stats = if (detailed_profile_enabled) process_memory.snapshot() else .{};

        var projection_alloc_stats = PhaseAllocStats{};
        var text_build_profile = introducer_mod.BuildTextProfile{};
        var segment_alloc_stats = PhaseAllocStats{};
        const segment_build_start_ns = if (metrics_enabled) platform_time.monotonicNs() else 0;
        var indexed_any = false;
        var segment_bytes: usize = 0;
        var segment_count: usize = 0;
        var projection_doc_count: usize = 0;
        var observed_field_analyzer_count: usize = 0;
        const target_segment_bytes = @max(@as(usize, 1), textSegmentBuildTargetBytes());
        const target_build_memory_bytes = @max(@as(usize, 1), textBuildMemoryTargetBytes());
        const doc_scratch_retained_bytes = textDocScratchRetainedBytes();
        var flush_build_memory_count: u64 = 0;
        var flush_segment_bytes_count: u64 = 0;
        var flush_end_count: u64 = 0;
        var oversized_doc_count: u64 = 0;
        var estimated_build_bytes_peak: u64 = 0;
        var estimated_segment_bytes_peak: u64 = 0;
        var memory_after_projection: process_memory.Stats = .{};
        var memory_after_analyzer_merge: process_memory.Stats = .{};

        var source_start: usize = 0;
        while (source_start < source_docs_with_ordinals.len) {
            var next_source_start = source_start;
            {
                var projection_arena_state = std.heap.ArenaAllocator.init(self.alloc);
                defer projection_arena_state.deinit();
                var projection_tracking = PhaseTrackingAllocator.init(projection_arena_state.allocator(), &projection_alloc_stats);
                const projection_alloc = if (detailed_profile_enabled) projection_tracking.allocator() else projection_arena_state.allocator();
                var observed_field_analyzers = std.ArrayListUnmanaged(mapper.ObservedFieldAnalyzer).empty;
                defer observed_field_analyzers.deinit(projection_alloc);
                var builder = mapper.TextProjectionBatchBuilder.init(projection_alloc, entry.text_analysis, entry.runtime_schema, &observed_field_analyzers);
                defer builder.deinit();

                var source_end = source_start;
                var projection_doc_limit: usize = 0;
                var projected_build_bytes: u64 = 0;
                var projected_segment_bytes: u64 = 0;
                while (source_end < source_docs_with_ordinals.len) {
                    const projection_start_ns = if (metrics_enabled) platform_time.monotonicNs() else 0;
                    const previous_projection_docs = builder.text_docs.items.len;
                    try builder.appendSourceDoc(source_docs_with_ordinals[source_end]);
                    if (metrics_enabled) projection_ns +|= platform_time.monotonicNs() - projection_start_ns;
                    source_end += 1;

                    if (builder.text_docs.items.len == previous_projection_docs) {
                        next_source_start = source_end;
                        continue;
                    }

                    const projected_doc = builder.text_docs.items[builder.text_docs.items.len - 1];
                    const doc_build_bytes = introducer_mod.estimateTextDocumentBuildMemoryBytes(projected_doc);
                    const doc_segment_bytes = introducer_mod.estimateTextDocumentSegmentBytes(projected_doc);
                    const next_build_bytes = projected_build_bytes +| doc_build_bytes;
                    const next_segment_bytes = projected_segment_bytes +| doc_segment_bytes;
                    if (previous_projection_docs > 0 and (next_build_bytes > target_build_memory_bytes or next_segment_bytes > target_segment_bytes)) {
                        projection_doc_limit = previous_projection_docs;
                        next_source_start = source_end - 1;
                        break;
                    }

                    projected_build_bytes = next_build_bytes;
                    projected_segment_bytes = next_segment_bytes;
                    projection_doc_limit = builder.text_docs.items.len;
                    next_source_start = source_end;
                    if (projection_doc_limit >= max_text_projection_docs_per_segment_build) break;
                }

                const projection_batch = mapper.TextProjectionBatch{
                    .docs = builder.text_docs.items[0..projection_doc_limit],
                    .observed_field_analyzers = builder.batch().observed_field_analyzers,
                };
                if (projection_batch.docs.len == 0) {
                    source_start = @max(source_start + 1, next_source_start);
                    continue;
                }
                projection_doc_count += projection_batch.docs.len;
                observed_field_analyzer_count += projection_batch.observed_field_analyzers.len;
                if (detailed_profile_enabled) memory_after_projection = process_memory.snapshot();
                if (projection_batch.observed_field_analyzers.len > 0) {
                    const analyzer_merge_start_ns = if (metrics_enabled) platform_time.monotonicNs() else 0;
                    try mergeObservedTextFieldAnalyzers(self, store, entry, projection_batch.observed_field_analyzers);
                    if (metrics_enabled) analyzer_merge_ns +|= platform_time.monotonicNs() - analyzer_merge_start_ns;
                }
                if (detailed_profile_enabled) memory_after_analyzer_merge = process_memory.snapshot();

                var start: usize = 0;
                while (start < projection_batch.docs.len) {
                    const split = introducer_mod.splitTextDocumentsForBuildBudget(projection_batch.docs, start, .{
                        .target_build_memory_bytes = target_build_memory_bytes,
                        .target_segment_bytes = target_segment_bytes,
                    });
                    const end = split.end;
                    switch (split.reason) {
                        .build_memory => flush_build_memory_count +|= 1,
                        .segment_bytes => flush_segment_bytes_count +|= 1,
                        .end => flush_end_count +|= 1,
                    }
                    if (split.oversized_doc) oversized_doc_count +|= 1;
                    estimated_build_bytes_peak = @max(estimated_build_bytes_peak, split.estimated_build_bytes);
                    estimated_segment_bytes_peak = @max(estimated_segment_bytes_peak, split.estimated_segment_bytes);
                    const chunk: mapper.TextProjectionBatch = .{
                        .docs = projection_batch.docs[start..end],
                        .observed_field_analyzers = &.{},
                    };
                    const build_options = introducer_mod.BuildTextOptions{
                        .profile = if (metrics_enabled) &text_build_profile else null,
                        .resource_manager = self.resource_manager,
                        .build_memory_target_bytes = target_build_memory_bytes,
                        .doc_scratch_retained_bytes = doc_scratch_retained_bytes,
                        .profile_timings = metrics_enabled,
                        .profile_working_set = detailed_profile_enabled,
                        .store_document_source = false,
                    };
                    var segment_arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
                    defer segment_arena_state.deinit();
                    var segment_tracking = PhaseTrackingAllocator.init(segment_arena_state.allocator(), &segment_alloc_stats);
                    const segment_alloc = if (detailed_profile_enabled) segment_tracking.allocator() else segment_arena_state.allocator();
                    const runtime_index_sort = if (entry.runtime_schema) |schema| schema.index_sort else &.{};
                    const index_sort = try textIndexSortFieldsForSegmentAlloc(segment_alloc, runtime_index_sort);
                    var build_ctx = TextSegmentSinkBuildContext{
                        .alloc = segment_alloc,
                        .projection_batch = chunk,
                        .text_analysis = entry.text_analysis,
                        .build_options = withTextIndexSort(build_options, index_sort),
                    };
                    const built_len = try entry.persistent.indexSegmentFromSinkBuilder(&build_ctx, buildTextSegmentIntoSink);
                    segment_bytes += built_len;
                    segment_count += 1;
                    indexed_any = true;
                    start = end;
                }
            }
            source_start = next_source_start;
        }
        text_build_profile.build_memory_target_bytes = @intCast(target_build_memory_bytes);
        text_build_profile.flush_build_memory_count = flush_build_memory_count;
        text_build_profile.flush_segment_bytes_count = flush_segment_bytes_count;
        text_build_profile.flush_end_count = flush_end_count;
        text_build_profile.oversized_doc_count = oversized_doc_count;
        text_build_profile.estimated_build_bytes = estimated_build_bytes_peak;
        text_build_profile.estimated_segment_bytes = estimated_segment_bytes_peak;
        if (metrics_enabled) segment_build_ns = platform_time.monotonicNs() - segment_build_start_ns;
        const memory_after_segment_build: process_memory.Stats = if (detailed_profile_enabled) process_memory.snapshot() else .{};

        const index_segment_start_ns = if (metrics_enabled) platform_time.monotonicNs() else 0;
        if (metrics_enabled) {
            index_segment_ns = platform_time.monotonicNs() - index_segment_start_ns;
            std.log.info(
                "antfly_bench_text_index index={s} source_docs={d} projection_docs={d} observed_analyzers={d} segments={d} segment_bytes={d} build_memory_target_bytes={d} doc_scratch_retained_bytes={d} estimated_build_peak_bytes={d} estimated_segment_peak_bytes={d} flush_build_memory={d} flush_segment_bytes={d} flush_end={d} oversized_docs={d} text_docs={d} text_fields={d} tokens={d} term_hits={d} typed_values={d}",
                .{
                    entry.config.name,
                    source_docs.len,
                    projection_doc_count,
                    observed_field_analyzer_count,
                    segment_count,
                    segment_bytes,
                    target_build_memory_bytes,
                    doc_scratch_retained_bytes,
                    estimated_build_bytes_peak,
                    estimated_segment_bytes_peak,
                    flush_build_memory_count,
                    flush_segment_bytes_count,
                    flush_end_count,
                    oversized_doc_count,
                    text_build_profile.doc_count,
                    text_build_profile.text_field_count,
                    text_build_profile.token_count,
                    text_build_profile.term_hit_count,
                    text_build_profile.typed_value_count,
                },
            );
            std.log.info(
                "antfly_bench_text_index_timing index={s} source_docs={d} projection_docs={d} total_ms={d} ordinals_ms={d} projection_ms={d} analyzer_merge_ms={d} segment_build_ms={d} index_segment_ms={d} analyzer_ms={d} term_accum_ms={d} hit_materialize_ms={d} typed_collect_ms={d} typed_build_ms={d} stored_attach_ms={d} inverted_build_ms={d} inverted_sort_ms={d} inverted_postings_serialize_ms={d} inverted_term_dict_ms={d} inverted_norms_ms={d} inverted_bloom_finish_ms={d} inverted_final_assembly_ms={d} section_attach_ms={d} stored_compress_ms={d} segment_assembly_ms={d} segment_encode_ms={d}",
                .{
                    entry.config.name,
                    source_docs.len,
                    projection_doc_count,
                    nsToMs(platform_time.monotonicNs() - total_start_ns),
                    nsToMs(ordinals_ns),
                    nsToMs(projection_ns),
                    nsToMs(analyzer_merge_ns),
                    nsToMs(segment_build_ns),
                    nsToMs(index_segment_ns),
                    nsToMs(text_build_profile.analyzer_ns),
                    nsToMs(text_build_profile.term_accum_ns),
                    nsToMs(text_build_profile.hit_materialize_ns),
                    nsToMs(text_build_profile.typed_collect_ns),
                    nsToMs(text_build_profile.typed_build_ns),
                    nsToMs(text_build_profile.stored_doc_attach_ns),
                    nsToMs(text_build_profile.inverted_build_ns),
                    nsToMs(text_build_profile.inverted_sort_ns),
                    nsToMs(text_build_profile.inverted_postings_serialize_ns),
                    nsToMs(text_build_profile.inverted_term_dict_ns),
                    nsToMs(text_build_profile.inverted_norms_ns),
                    nsToMs(text_build_profile.inverted_bloom_finish_ns),
                    nsToMs(text_build_profile.inverted_final_assembly_ns),
                    nsToMs(text_build_profile.section_attach_ns),
                    nsToMs(text_build_profile.stored_compress_ns),
                    nsToMs(text_build_profile.segment_assembly_ns),
                    nsToMs(text_build_profile.segment_encode_ns),
                },
            );
            if (self.resource_manager) |manager| {
                const resource_stats = manager.snapshot();
                const ft_pending = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.full_text_pending_segments)];
                const ft_build = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.full_text_build_working_set)];
                const lsm_cache = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_block_table_cache)];
                const lsm_compaction = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_compaction_work)];
                const lsm_table_builder = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_table_builder_working_set)];
                const lsm_state = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_in_memory_state)];
                const lsm_wal_write = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_wal_write_working_set)];
                const lsm_wal_retention = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_wal_retention)];
                const lsm_recovery = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_recovery_working_set)];
                const derived_backlog = resource_stats.slices[@intFromEnum(resource_manager_mod.Slice.derived_backlog)];
                const lsm_stats = self.snapshotLsmMaintenanceStats();
                const lsm_cache_stats: lsm_backend_mod.cache.Stats = if (self.lsm_cache) |cache| cache.snapshotStats() else .{};
                const lsm_resource_used = lsm_cache.used_bytes +| lsm_compaction.used_bytes +| lsm_table_builder.used_bytes +| lsm_state.used_bytes +| lsm_wal_write.used_bytes +| lsm_recovery.used_bytes;
                const lsm_resource_peak = lsm_cache.peak_bytes +| lsm_compaction.peak_bytes +| lsm_table_builder.peak_bytes +| lsm_state.peak_bytes +| lsm_wal_write.peak_bytes +| lsm_recovery.peak_bytes;
                std.log.info(
                    "antfly_bench_text_resources index={s} source_docs={d} projection_docs={d} segments={d} full_text_pending_used_bytes={d} full_text_pending_peak_bytes={d} full_text_build_used_bytes={d} full_text_build_peak_bytes={d} derived_backlog_used_bytes={d} derived_backlog_peak_bytes={d} lsm_cache_used_bytes={d} lsm_cache_peak_bytes={d} lsm_compaction_used_bytes={d} lsm_compaction_peak_bytes={d} lsm_table_builder_used_bytes={d} lsm_table_builder_peak_bytes={d} lsm_state_used_bytes={d} lsm_state_peak_bytes={d} lsm_wal_write_used_bytes={d} lsm_wal_write_peak_bytes={d} lsm_wal_retention_disk_bytes={d} lsm_wal_retention_peak_disk_bytes={d} lsm_recovery_used_bytes={d} lsm_recovery_peak_bytes={d} lsm_resource_used_bytes={d} lsm_resource_peak_bytes={d} cache_reclaim_requests={d} cache_reclaimed_bytes={d}",
                    .{
                        entry.config.name,
                        source_docs.len,
                        projection_doc_count,
                        segment_count,
                        ft_pending.used_bytes,
                        ft_pending.peak_bytes,
                        ft_build.used_bytes,
                        ft_build.peak_bytes,
                        derived_backlog.used_bytes,
                        derived_backlog.peak_bytes,
                        lsm_cache.used_bytes,
                        lsm_cache.peak_bytes,
                        lsm_compaction.used_bytes,
                        lsm_compaction.peak_bytes,
                        lsm_table_builder.used_bytes,
                        lsm_table_builder.peak_bytes,
                        lsm_state.used_bytes,
                        lsm_state.peak_bytes,
                        lsm_wal_write.used_bytes,
                        lsm_wal_write.peak_bytes,
                        lsm_wal_retention.used_bytes,
                        lsm_wal_retention.peak_bytes,
                        lsm_recovery.used_bytes,
                        lsm_recovery.peak_bytes,
                        lsm_resource_used,
                        lsm_resource_peak,
                        resource_stats.reclaim_requests,
                        resource_stats.reclaimed_bytes,
                    },
                );
                std.log.info(
                    "antfly_bench_text_lsm_tables index={s} source_docs={d} projection_docs={d} segments={d} lsm_mutable_bytes={d} lsm_immutable_bytes={d} lsm_immutable_memtables={d} lsm_total_run_bytes={d} lsm_total_runs={d} lsm_cache_entries={d} lsm_cache_transient_serves={d} lsm_cache_state_bytes={d} lsm_cache_raw_table_bytes={d} lsm_cache_table_index_bytes={d} lsm_cache_block_bytes={d} lsm_cache_block_inserts={d} lsm_cache_block_evictions={d} lsm_cache_physical_block_bytes={d} lsm_cache_physical_block_inserts={d} lsm_cache_physical_block_evictions={d}",
                    .{
                        entry.config.name,
                        source_docs.len,
                        projection_doc_count,
                        segment_count,
                        lsm_stats.mutable_bytes,
                        lsm_stats.immutable_bytes,
                        lsm_stats.immutable_memtables,
                        lsm_stats.total_run_bytes,
                        lsm_stats.total_runs,
                        lsm_cache_stats.entry_count,
                        lsm_cache_stats.run_state.transient_serves +|
                            lsm_cache_stats.run_table_raw.transient_serves +|
                            lsm_cache_stats.run_table_index.transient_serves +|
                            lsm_cache_stats.run_table_block.transient_serves +|
                            lsm_cache_stats.run_table_physical_block.transient_serves,
                        lsm_cache_stats.run_state.used_bytes,
                        lsm_cache_stats.run_table_raw.used_bytes,
                        lsm_cache_stats.run_table_index.used_bytes,
                        lsm_cache_stats.run_table_block.used_bytes,
                        lsm_cache_stats.run_table_block.inserts,
                        lsm_cache_stats.run_table_block.evictions,
                        lsm_cache_stats.run_table_physical_block.used_bytes,
                        lsm_cache_stats.run_table_physical_block.inserts,
                        lsm_cache_stats.run_table_physical_block.evictions,
                    },
                );
            }
        }
        if (detailed_profile_enabled) {
            const memory_after_index_segment = process_memory.snapshot();
            std.log.info(
                "antfly_bench_text_alloc index={s} source_docs={d} projection_docs={d} segments={d} ord_alloc_bytes={d} ord_free_bytes={d} ord_peak_bytes={d} ord_outstanding_bytes={d} ord_alloc_count={d} ord_free_count={d} projection_alloc_bytes={d} projection_free_bytes={d} projection_peak_bytes={d} projection_outstanding_bytes={d} projection_alloc_count={d} projection_free_count={d} segment_alloc_bytes={d} segment_free_bytes={d} segment_peak_bytes={d} segment_outstanding_bytes={d} segment_alloc_count={d} segment_free_count={d}",
                .{
                    entry.config.name,
                    source_docs.len,
                    projection_doc_count,
                    segment_count,
                    ordinals_alloc_stats.total_alloc_bytes,
                    ordinals_alloc_stats.total_free_bytes,
                    ordinals_alloc_stats.peak_bytes,
                    ordinals_alloc_stats.current_bytes,
                    ordinals_alloc_stats.alloc_count,
                    ordinals_alloc_stats.free_count,
                    projection_alloc_stats.total_alloc_bytes,
                    projection_alloc_stats.total_free_bytes,
                    projection_alloc_stats.peak_bytes,
                    projection_alloc_stats.current_bytes,
                    projection_alloc_stats.alloc_count,
                    projection_alloc_stats.free_count,
                    segment_alloc_stats.total_alloc_bytes,
                    segment_alloc_stats.total_free_bytes,
                    segment_alloc_stats.peak_bytes,
                    segment_alloc_stats.current_bytes,
                    segment_alloc_stats.alloc_count,
                    segment_alloc_stats.free_count,
                },
            );
            std.log.info(
                "antfly_bench_text_memory index={s} source_docs={d} projection_docs={d} segments={d} rss_start_bytes={d} rss_after_ordinals_bytes={d} rss_after_projection_bytes={d} rss_after_analyzer_merge_bytes={d} rss_after_segment_build_bytes={d} rss_after_index_segment_bytes={d} footprint_start_bytes={d} footprint_after_ordinals_bytes={d} footprint_after_projection_bytes={d} footprint_after_analyzer_merge_bytes={d} footprint_after_segment_build_bytes={d} footprint_after_index_segment_bytes={d}",
                .{
                    entry.config.name,
                    source_docs.len,
                    projection_doc_count,
                    segment_count,
                    memory_start.resident_bytes,
                    memory_after_ordinals.resident_bytes,
                    memory_after_projection.resident_bytes,
                    memory_after_analyzer_merge.resident_bytes,
                    memory_after_segment_build.resident_bytes,
                    memory_after_index_segment.resident_bytes,
                    memory_start.footprint_bytes,
                    memory_after_ordinals.footprint_bytes,
                    memory_after_projection.footprint_bytes,
                    memory_after_analyzer_merge.footprint_bytes,
                    memory_after_segment_build.footprint_bytes,
                    memory_after_index_segment.footprint_bytes,
                },
            );
            std.log.info(
                "antfly_bench_text_working_set index={s} source_docs={d} projection_docs={d} segments={d} build_memory_target_bytes={d} doc_scratch_retained_bytes={d} estimated_build_peak_bytes={d} estimated_segment_peak_bytes={d} flush_build_memory={d} flush_segment_bytes={d} flush_end={d} oversized_docs={d} doc_arena_peak_bytes={d} peak_doc_scratch_bytes={d} builder_scratch_peak_bytes={d} field_postings_estimated_bytes={d} typed_doc_values_estimated_bytes={d} stored_docs_estimated_bytes={d} postings_live_bytes={d} typed_live_bytes={d} section_live_bytes={d} sink_live_bytes={d} section_bytes={d} fst_and_term_metadata_bytes={d} segment_sink_bytes={d} resource_peak_bytes={d} builder_rss_before_bytes={d} builder_rss_after_analyze_bytes={d} builder_rss_after_postings_build_bytes={d} builder_rss_after_sections_bytes={d} builder_rss_after_publish_bytes={d}",
                .{
                    entry.config.name,
                    source_docs.len,
                    projection_doc_count,
                    segment_count,
                    text_build_profile.build_memory_target_bytes,
                    text_build_profile.doc_scratch_retained_bytes,
                    text_build_profile.estimated_build_bytes,
                    text_build_profile.estimated_segment_bytes,
                    text_build_profile.flush_build_memory_count,
                    text_build_profile.flush_segment_bytes_count,
                    text_build_profile.flush_end_count,
                    text_build_profile.oversized_doc_count,
                    text_build_profile.doc_arena_peak_bytes,
                    text_build_profile.peak_doc_scratch_bytes,
                    text_build_profile.builder_scratch_peak_bytes,
                    text_build_profile.field_postings_estimated_bytes,
                    text_build_profile.typed_doc_values_estimated_bytes,
                    text_build_profile.stored_docs_estimated_bytes,
                    text_build_profile.postings_live_bytes,
                    text_build_profile.typed_live_bytes,
                    text_build_profile.section_live_bytes,
                    text_build_profile.sink_live_bytes,
                    text_build_profile.section_bytes,
                    text_build_profile.fst_and_term_metadata_bytes,
                    text_build_profile.segment_sink_bytes,
                    text_build_profile.resource_peak_bytes,
                    text_build_profile.rss_before,
                    text_build_profile.rss_after_analyze,
                    text_build_profile.rss_after_postings_build,
                    text_build_profile.rss_after_sections,
                    text_build_profile.rss_after_publish,
                },
            );
        }
        self.logMemoryAttribution("text_index_batch", source_docs.len, projection_doc_count, segment_count);
        return .{ .indexed_any = indexed_any };
    }

    fn textProjectionSourceDocsWithOrdinals(
        _: *IndexManager,
        arena: std.mem.Allocator,
        store: *docstore_mod.DocStore,
        source_docs: []const mapper.TextProjectionSourceDoc,
    ) ![]mapper.TextProjectionSourceDoc {
        var docs = try arena.dupe(mapper.TextProjectionSourceDoc, source_docs);

        const PendingOrdinalLookup = struct {
            source_index: usize,
            store_key: []u8,
        };
        var pending = std.ArrayListUnmanaged(PendingOrdinalLookup).empty;
        defer pending.deinit(arena);

        for (docs, 0..) |doc, i| {
            if (doc.doc_ordinal != null) continue;
            try pending.append(arena, .{
                .source_index = i,
                .store_key = try internal_keys.identityDocToOrdinalKeyAlloc(arena, doc.key),
            });
        }
        if (pending.items.len == 0) return docs;

        std.mem.sort(PendingOrdinalLookup, pending.items, {}, struct {
            fn lessThan(_: void, lhs: PendingOrdinalLookup, rhs: PendingOrdinalLookup) bool {
                return std.mem.order(u8, lhs.store_key, rhs.store_key) == .lt;
            }
        }.lessThan);

        const read_keys = try arena.alloc([]const u8, pending.items.len);
        const read_values = try arena.alloc(?[]const u8, pending.items.len);
        for (pending.items, 0..) |item, i| {
            read_keys[i] = item.store_key;
            read_values[i] = null;
        }

        var identity_txn = try store.beginProbeTxn();
        defer identity_txn.abort();
        try identity_txn.getManySorted(read_keys, read_values);

        for (pending.items, 0..) |item, i| {
            const raw = read_values[i] orelse continue;
            if (raw.len != @sizeOf(doc_identity.DocOrdinal)) return error.InvalidDocIdentity;
            docs[item.source_index].doc_ordinal = std.mem.readInt(doc_identity.DocOrdinal, raw[0..4], .big);
        }

        return docs;
    }

    fn textCompactionDue(index: *persistent_mod.PersistentIndex, opts: IndexBatchOptions) bool {
        if (opts.compact_text) return true;
        const threshold = opts.compact_text_segment_threshold orelse return false;
        return index.snapshot().segments.len >= threshold;
    }

    fn deleteTextBatchEntry(_: *IndexManager, entry: *TextIndex, keys: []const []const u8) !TextBatchMutationStats {
        const delete_infos = try entry.persistent.deleteByIdsTracked(keys);
        defer entry.persistent.freeDeleteInfos(delete_infos);
        entry.recordCommittedDeletes(delete_infos);
        return .{ .deleted_any = delete_infos.len != 0 };
    }

    fn finalizeTextBatchMutations(
        self: *IndexManager,
        entry: *TextIndex,
        opts: IndexBatchOptions,
        stats: TextBatchMutationStats,
    ) !void {
        if (!stats.touched()) return;
        const compaction_due = stats.deleted_any or textCompactionDue(&entry.persistent, opts) or opts.defer_text_compaction;
        if (!compaction_due) return;
        if (opts.defer_text_compaction and entry.compaction_pending.load(.acquire)) return;
        if (!try self.textIndexNeedsMerge(&entry.persistent, activeTextMergePolicy())) {
            TextMergeScheduler.noteComplete(entry);
            return;
        }
        if (opts.defer_text_compaction) {
            TextMergeScheduler.schedule(entry);
            return;
        }
        try self.compactTextIndex(&entry.persistent, activeTextMergePolicy());
        TextMergeScheduler.noteComplete(entry);
    }

    fn indexDenseBatchEntry(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *DenseIndex,
        writes: []const types.BatchWrite,
        batch_options: StoreBatchOptions,
    ) !void {
        return self.indexDenseBatchEntryWithSkip(store, entry, writes, null, batch_options);
    }

    fn indexDenseBatchEntryWithSkip(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *DenseIndex,
        writes: []const types.BatchWrite,
        skip: ?*const DenseSplitHandoff,
        batch_options: StoreBatchOptions,
    ) !void {
        var store_batch = try store.beginWriteBatchWithOptions(batch_options);
        errdefer store_batch.abort();
        const store_txn = store_batch.asTxn();

        var items = std.ArrayListUnmanaged(hbc_mod.BatchInsertItem).empty;
        defer {
            for (items.items) |item| self.alloc.free(@constCast(item.vector));
            items.deinit(self.alloc);
        }
        var pending_mappings = std.ArrayListUnmanaged(PendingDenseVectorMapping).empty;
        defer pending_mappings.deinit(self.alloc);
        var replacement_deletes = std.ArrayListUnmanaged(u64).empty;
        defer replacement_deletes.deinit(self.alloc);
        var metadata_presence_memo: DenseVectorMetadataPresenceMemo = .{};
        defer metadata_presence_memo.deinit(self.alloc);
        var all_vector_ids_new = true;

        for (writes) |write| {
            if (!self.keyInRange(write.key)) continue;
            if (!isPrimaryDocumentCandidate(write.key)) continue;
            if (skip) |handoff| {
                if (handoff.shouldSkip(write.key)) continue;
            }
            const vector_values = (try mapper.extractDenseVectorField(self.alloc, write.value, entry.field_name, entry.dims)) orelse continue;

            const assignment = try self.replaceDenseVectorIdTxnWithMemo(
                store_txn,
                entry,
                entry.config.name,
                write.key,
                null,
                &replacement_deletes,
                &metadata_presence_memo,
            );
            all_vector_ids_new = all_vector_ids_new and assignment.can_assume_absent;
            try items.append(self.alloc, .{
                .vector_id = assignment.vector_id,
                .vector = vector_values,
                .metadata = write.key,
            });
            try pending_mappings.append(self.alloc, .{
                .doc_key = write.key,
                .parent_doc_key = null,
                .vector_id = assignment.vector_id,
            });
        }

        try self.applyDenseItemsWithOptions(entry, items.items, replacement_deletes.items, batch_options, all_vector_ids_new, store_txn);
        try self.commitDenseVectorMappingsWithRollback(&store_batch, store_txn, entry, entry.config.name, pending_mappings.items);
    }

    fn deleteDenseBatchEntry(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *DenseIndex,
        keys: []const []const u8,
        batch_options: StoreBatchOptions,
    ) !void {
        var pending_deletes = std.ArrayListUnmanaged(PendingDenseVectorDelete).empty;
        defer pending_deletes.deinit(self.alloc);
        {
            var read_txn = try store.beginReadTxn();
            defer read_txn.abort();
            for (keys) |key| {
                const vector_id = (try self.resolveDenseVectorIdForDeleteTxn(&read_txn, entry.config.name, key)) orelse continue;
                const ordinal = if (entry.chunk_name == null)
                    (try doc_identity.lookupOrdinalTxn(self.alloc, &read_txn, key)) orelse
                        try self.lookupDenseVectorOrdinalTxn(&read_txn, entry.config.name, vector_id)
                else
                    null;
                try pending_deletes.append(self.alloc, .{
                    .doc_key = key,
                    .vector_id = vector_id,
                    .ordinal = ordinal,
                });
            }
        }
        if (pending_deletes.items.len == 0) return;

        var store_batch = try store.beginWriteBatchWithOptions(batch_options);
        errdefer store_batch.abort();
        const store_txn = store_batch.asTxn();
        var vector_ids = std.ArrayListUnmanaged(u64).empty;
        defer vector_ids.deinit(self.alloc);

        for (pending_deletes.items) |pending| {
            try vector_ids.append(self.alloc, pending.vector_id);
            try self.clearDenseVectorMappingTxnWithOrdinal(store_txn, entry.config.name, pending.doc_key, pending.vector_id, pending.ordinal);
        }

        entry.index.batchApply(&.{}, vector_ids.items) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        try store_batch.commit();
        for (pending_deletes.items) |pending| {
            if (pending.ordinal) |ordinal| {
                _ = entry.ordinal_vector_ids.remove(ordinal);
                _ = entry.vector_ordinals.remove(pending.vector_id);
            }
        }
    }

    fn indexSparseBatchEntry(self: *IndexManager, store: ?*docstore_mod.DocStore, entry: *SparseIndex, writes: []const types.BatchWrite) !void {
        return self.indexSparseBatchEntryWithOptions(store, entry, writes, .{});
    }

    fn indexSparseBatchEntryWithOptions(self: *IndexManager, store: ?*docstore_mod.DocStore, entry: *SparseIndex, writes: []const types.BatchWrite, batch_options: StoreBatchOptions) !void {
        return self.indexSparseBatchEntryWithSkipAndOptions(store, entry, writes, null, batch_options);
    }

    fn indexSparseBatchEntryWithSkip(
        self: *IndexManager,
        store: ?*docstore_mod.DocStore,
        entry: *SparseIndex,
        writes: []const types.BatchWrite,
        skip: ?*const SparseSplitHandoff,
    ) !void {
        return self.indexSparseBatchEntryWithSkipAndOptions(store, entry, writes, skip, .{});
    }

    fn indexSparseBatchEntryWithSkipAndOptions(
        self: *IndexManager,
        store: ?*docstore_mod.DocStore,
        entry: *SparseIndex,
        writes: []const types.BatchWrite,
        skip: ?*const SparseSplitHandoff,
        batch_options: StoreBatchOptions,
    ) !void {
        const ReplayProfile = struct {
            scan_ns: u64 = 0,
            extract_ns: u64 = 0,
            append_ns: u64 = 0,
            batch_ns: u64 = 0,
            in_range: usize = 0,
            primary_candidates: usize = 0,
            skipped_by_handoff: usize = 0,
            extracted: usize = 0,
        };
        const profile_enabled = sparseReplayProfileEnabled();
        const total_start_ns = if (profile_enabled) platform_time.monotonicNs() else 0;
        var profile: ReplayProfile = .{};
        var sparse_writes = std.ArrayListUnmanaged(sparse_mod.SparseWrite).empty;
        defer {
            for (sparse_writes.items) |item| {
                self.alloc.free(@constCast(item.vec.indices));
                self.alloc.free(@constCast(item.vec.values));
            }
            sparse_writes.deinit(self.alloc);
        }

        const scan_start_ns = if (profile_enabled) platform_time.monotonicNs() else 0;
        for (writes) |write| {
            if (!self.keyInRange(write.key)) continue;
            if (profile_enabled) profile.in_range += 1;
            if (!isPrimaryDocumentCandidate(write.key)) continue;
            if (profile_enabled) profile.primary_candidates += 1;
            if (skip) |handoff| {
                if (handoff.shouldSkip(write.key)) {
                    if (profile_enabled) profile.skipped_by_handoff += 1;
                    continue;
                }
            }
            const extract_start_ns = if (profile_enabled) platform_time.monotonicNs() else 0;
            var sparse_vec = (try mapper.extractSparseVectorField(self.alloc, write.value, entry.field_name)) orelse continue;
            var sparse_vec_owned = true;
            errdefer if (sparse_vec_owned) sparse_vec.deinit(self.alloc);
            if (profile_enabled) {
                profile.extract_ns += platform_time.monotonicNs() - extract_start_ns;
                profile.extracted += 1;
            }

            const append_start_ns = if (profile_enabled) platform_time.monotonicNs() else 0;
            try sparse_writes.append(self.alloc, .{
                .doc_id = write.key,
                .vec = .{
                    .indices = sparse_vec.indices,
                    .values = sparse_vec.values,
                },
            });
            sparse_vec_owned = false;
            if (profile_enabled) profile.append_ns += platform_time.monotonicNs() - append_start_ns;
        }
        if (profile_enabled) profile.scan_ns = platform_time.monotonicNs() - scan_start_ns -| profile.extract_ns -| profile.append_ns;

        const sparse_batch_options: sparse_mod.BatchOptions = .{
            .defer_term_range_updates = true,
            .backend_batch_options = batch_options,
            .prefer_bulk_build = batch_options.mode == .bulk_ingest,
            .assume_new_doc_ids = batch_options.mode == .bulk_ingest,
        };
        if (store) |doc_store| {
            try self.assignSparseWriteDocNumsFromIdentity(doc_store, entry, sparse_writes.items);
        }
        const max_sparse_writes_per_txn: usize = if (batch_options.mode == .bulk_ingest) 16 * 1024 else 256;
        var start: usize = 0;
        while (start < sparse_writes.items.len) {
            const end = @min(start + max_sparse_writes_per_txn, sparse_writes.items.len);
            const batch_start_ns = if (profile_enabled) platform_time.monotonicNs() else 0;
            try entry.index.batchWithOptions(sparse_writes.items[start..end], &.{}, sparse_batch_options);
            if (profile_enabled) profile.batch_ns += platform_time.monotonicNs() - batch_start_ns;
            start = end;
        }
        if (profile_enabled and (writes.len > 0 or sparse_writes.items.len > 0)) {
            std.log.info(
                "antfly_bench_sparse_doc_index index={s} mode={s} input_writes={d} in_range={d} primary_candidates={d} skipped_by_handoff={d} extracted={d} sparse_writes={d} total_ms={d} scan_filter_ms={d} extract_ms={d} append_ms={d} sparse_batch_ms={d}",
                .{
                    entry.config.name,
                    @tagName(batch_options.mode),
                    writes.len,
                    profile.in_range,
                    profile.primary_candidates,
                    profile.skipped_by_handoff,
                    profile.extracted,
                    sparse_writes.items.len,
                    nsToMs(platform_time.monotonicNs() - total_start_ns),
                    nsToMs(profile.scan_ns),
                    nsToMs(profile.extract_ns),
                    nsToMs(profile.append_ns),
                    nsToMs(profile.batch_ns),
                },
            );
        }
    }

    fn assignSparseWriteDocNumsFromIdentity(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *SparseIndex,
        writes: []sparse_mod.SparseWrite,
    ) !void {
        if (entry.chunk_name != null or writes.len == 0) return;

        var txn = try store.beginProbeTxn();
        defer txn.abort();

        const doc_ids = try self.alloc.alloc([]const u8, writes.len);
        defer self.alloc.free(doc_ids);
        for (writes, 0..) |write, i| doc_ids[i] = write.doc_id;

        const ordinals = try doc_identity.lookupOrdinalsTxnAlloc(self.alloc, &txn, doc_ids);
        defer self.alloc.free(ordinals);
        for (ordinals, 0..) |maybe_ordinal, i| {
            const ordinal = maybe_ordinal orelse continue;
            writes[i].doc_num = ordinal;
        }
    }

    fn indexSparsePreparedWritesEntryWithOptions(
        self: *IndexManager,
        entry: *SparseIndex,
        writes: []const sparse_mod.SparseWrite,
        batch_options: StoreBatchOptions,
    ) !void {
        _ = self;
        const profile_enabled = sparseReplayProfileEnabled();
        const total_start_ns = if (profile_enabled) platform_time.monotonicNs() else 0;
        var batch_ns: u64 = 0;
        const sparse_batch_options: sparse_mod.BatchOptions = .{
            .defer_term_range_updates = true,
            .backend_batch_options = batch_options,
            .prefer_bulk_build = batch_options.mode == .bulk_ingest,
            .assume_new_doc_ids = batch_options.mode == .bulk_ingest,
        };
        const max_sparse_writes_per_txn: usize = if (batch_options.mode == .bulk_ingest) 16 * 1024 else 256;
        var start: usize = 0;
        while (start < writes.len) {
            const end = @min(start + max_sparse_writes_per_txn, writes.len);
            const batch_start_ns = if (profile_enabled) platform_time.monotonicNs() else 0;
            try entry.index.batchWithOptions(writes[start..end], &.{}, sparse_batch_options);
            if (profile_enabled) batch_ns += platform_time.monotonicNs() - batch_start_ns;
            start = end;
        }
        if (profile_enabled) {
            std.log.info(
                "antfly_bench_sparse_prepared_index index={s} mode={s} sparse_writes={d} total_ms={d} sparse_batch_ms={d}",
                .{
                    entry.config.name,
                    @tagName(batch_options.mode),
                    writes.len,
                    nsToMs(platform_time.monotonicNs() - total_start_ns),
                    nsToMs(batch_ns),
                },
            );
        }
    }

    fn deleteSparseBatchEntry(self: *IndexManager, entry: *SparseIndex, keys: []const []const u8) !void {
        return self.deleteSparseBatchEntryWithOptions(entry, keys, .{});
    }

    fn deleteSparseBatchEntryWithOptions(self: *IndexManager, entry: *SparseIndex, keys: []const []const u8, batch_options: StoreBatchOptions) !void {
        var filtered = std.ArrayListUnmanaged([]const u8).empty;
        defer filtered.deinit(self.alloc);
        for (keys) |key| {
            try filtered.append(self.alloc, key);
        }
        try entry.index.batchWithOptions(&.{}, filtered.items, .{
            .defer_term_range_updates = true,
            .backend_batch_options = batch_options,
        });
    }

    pub fn lookupSparseDocNumsForOrdinalsAlloc(
        self: *IndexManager,
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        index_name: []const u8,
        ordinals: []const doc_identity.DocOrdinal,
    ) ![]const u32 {
        const bench_profile = getenv("ANTFLY_BENCH_QUERY_PROFILE") != null;
        const total_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        var runtime_store_ns: u64 = 0;
        var primary_txn_ns: u64 = 0;
        var sparse_txn_ns: u64 = 0;
        var doc_id_ns: u64 = 0;
        var doc_num_ns: u64 = 0;
        const entry = self.findSparseIndexEntry(index_name) orelse return error.IndexNotFound;

        const sparse_txn_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        var sparse_txn = try entry.index.beginReadTxn();
        defer sparse_txn.abort();
        if (bench_profile) sparse_txn_ns = platform_time.monotonicNs() - sparse_txn_start_ns;

        if (entry.chunk_name == null) {
            var fast_lookup = try entry.index.docNumsForOrdinalDocNumsAlloc(alloc, &sparse_txn, ordinals);
            defer fast_lookup.deinit(alloc);
            if (fast_lookup.missing_ordinals.len == 0) {
                const out = try alloc.dupe(u32, fast_lookup.doc_nums);
                if (bench_profile) {
                    std.log.info(
                        "antfly_bench_sparse_ordinal_projection total_us={d} runtime_store_us={d} primary_txn_us={d} sparse_txn_us={d} doc_id_us={d} doc_num_us={d} ordinals={d} doc_nums={d}",
                        .{
                            (platform_time.monotonicNs() - total_start_ns) / 1000,
                            runtime_store_ns / 1000,
                            primary_txn_ns / 1000,
                            sparse_txn_ns / 1000,
                            doc_id_ns / 1000,
                            doc_num_ns / 1000,
                            ordinals.len,
                            out.len,
                        },
                    );
                }
                return out;
            }

            const primary_txn_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            var txn = try store.beginProbeTxn();
            defer txn.abort();
            if (bench_profile) primary_txn_ns = platform_time.monotonicNs() - primary_txn_start_ns;
            const doc_id_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            const parent_doc_ids = try lookupSparseProjectionDocIdsForOrdinalsAlloc(alloc, &txn, fast_lookup.missing_ordinals);
            defer alloc.free(parent_doc_ids);
            if (bench_profile) doc_id_ns = platform_time.monotonicNs() - doc_id_start_ns;
            const doc_num_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            const fallback_doc_nums = try entry.index.docNumsForDocIdsAlloc(alloc, &sparse_txn, parent_doc_ids);
            defer alloc.free(fallback_doc_nums);
            var out = std.ArrayListUnmanaged(u32).empty;
            errdefer out.deinit(alloc);
            try out.appendSlice(alloc, fast_lookup.doc_nums);
            try out.appendSlice(alloc, fallback_doc_nums);
            const out_slice = try out.toOwnedSlice(alloc);
            if (bench_profile) {
                doc_num_ns = platform_time.monotonicNs() - doc_num_start_ns;
                std.log.info(
                    "antfly_bench_sparse_ordinal_projection total_us={d} runtime_store_us={d} primary_txn_us={d} sparse_txn_us={d} doc_id_us={d} doc_num_us={d} ordinals={d} doc_nums={d}",
                    .{
                        (platform_time.monotonicNs() - total_start_ns) / 1000,
                        runtime_store_ns / 1000,
                        primary_txn_ns / 1000,
                        sparse_txn_ns / 1000,
                        doc_id_ns / 1000,
                        doc_num_ns / 1000,
                        ordinals.len,
                        out_slice.len,
                    },
                );
            }
            return out_slice;
        }

        const primary_txn_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        var txn = try store.beginProbeTxn();
        defer txn.abort();
        if (bench_profile) primary_txn_ns = platform_time.monotonicNs() - primary_txn_start_ns;

        const runtime_store_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        if (bench_profile) runtime_store_ns = platform_time.monotonicNs() - runtime_store_start_ns;

        var out = std.ArrayListUnmanaged(u32).empty;
        errdefer out.deinit(alloc);
        var seen = std.AutoHashMapUnmanaged(u32, void).empty;
        defer seen.deinit(alloc);
        for (ordinals) |ordinal| {
            const parent_doc_id = (try doc_identity.lookupDocIdTxn(self.alloc, &txn, ordinal)) orelse continue;
            defer self.alloc.free(parent_doc_id);
            const prefix = try internal_keys.artifactNamedPrefixAlloc(self.alloc, parent_doc_id, "chunk", entry.chunk_name.?);
            defer self.alloc.free(prefix);
            const upper = try internal_keys.nextPrefixAlloc(self.alloc, prefix);
            defer if (upper) |buf| self.alloc.free(buf);
            const chunk_rows = try backend_scan.scanRange(alloc, &runtime_store.store, prefix, if (upper) |buf| buf else "");
            defer backend_scan.freeResults(alloc, chunk_rows);
            for (chunk_rows) |row| {
                if (!internal_keys.isChunkArtifactRecordKey(row.key)) continue;
                const doc_num = (entry.index.debugDocNumForDocId(row.key) catch |err| switch (err) {
                    error.DocNumOverflow => continue,
                    else => return err,
                }) orelse continue;
                const gop = try seen.getOrPut(alloc, doc_num);
                if (!gop.found_existing) try out.append(alloc, doc_num);
            }
        }
        return try out.toOwnedSlice(alloc);
    }

    fn lookupSparseProjectionDocIdsForOrdinalsAlloc(alloc: Allocator, txn: anytype, ordinals: []const doc_identity.DocOrdinal) ![]const []const u8 {
        if (ordinals.len == 0) return try alloc.alloc([]const u8, 0);

        const sorted_ordinals = try alloc.dupe(doc_identity.DocOrdinal, ordinals);
        defer alloc.free(sorted_ordinals);
        std.mem.sort(doc_identity.DocOrdinal, sorted_ordinals, {}, docOrdinalLessThan);

        const IdentityOrdinalKey = @TypeOf(internal_keys.identityOrdinalToDocKey(0));
        var key_storage = try alloc.alloc(IdentityOrdinalKey, sorted_ordinals.len);
        defer alloc.free(key_storage);
        var keys = try alloc.alloc([]const u8, sorted_ordinals.len);
        defer alloc.free(keys);
        var values = try alloc.alloc(?[]const u8, sorted_ordinals.len);
        defer alloc.free(values);

        var key_count: usize = 0;
        var previous: ?doc_identity.DocOrdinal = null;
        for (sorted_ordinals) |ordinal| {
            if (previous != null and previous.? == ordinal) continue;
            key_storage[key_count] = internal_keys.identityOrdinalToDocKey(ordinal);
            keys[key_count] = key_storage[key_count][0..];
            values[key_count] = null;
            key_count += 1;
            previous = ordinal;
        }

        try txn.getManySorted(keys[0..key_count], values[0..key_count]);

        var doc_ids = std.ArrayListUnmanaged([]const u8).empty;
        errdefer doc_ids.deinit(alloc);
        try doc_ids.ensureTotalCapacity(alloc, key_count);
        for (values[0..key_count]) |maybe_raw| {
            if (maybe_raw) |raw| doc_ids.appendAssumeCapacity(raw);
        }
        return try doc_ids.toOwnedSlice(alloc);
    }

    fn deleteGraphDocsEntry(self: *IndexManager, entry: *GraphIndex, keys: []const []const u8) !void {
        var deletes = std.ArrayListUnmanaged(graph_mod.BatchDelete).empty;
        defer {
            for (deletes.items) |delete| {
                self.alloc.free(@constCast(delete.source));
                self.alloc.free(@constCast(delete.target));
                self.alloc.free(@constCast(delete.edge_type));
            }
            deletes.deinit(self.alloc);
        }

        for (keys) |key| {
            const edges = try entry.index.getEdges(self.alloc, key, "", .both);
            defer graph_mod.GraphIndex.freeEdges(self.alloc, edges);

            for (edges) |edge| {
                try deletes.append(self.alloc, .{
                    .source = try self.alloc.dupe(u8, edge.source),
                    .target = try self.alloc.dupe(u8, edge.target),
                    .edge_type = try self.alloc.dupe(u8, edge.edge_type),
                });
            }
        }

        try entry.index.batchApply(&.{}, deletes.items);
    }

    fn applyGraphWritesEntry(self: *IndexManager, entry: *GraphIndex, writes: []const types.GraphEdgeWrite) !void {
        try self.applyGraphMutationsEntry(entry, writes, &.{});
    }

    fn applyGraphDeletesEntry(self: *IndexManager, entry: *GraphIndex, deletes: []const types.GraphEdgeDelete) !void {
        try self.applyGraphMutationsEntry(entry, &.{}, deletes);
    }

    fn applyGraphMutationsEntry(
        self: *IndexManager,
        entry: *GraphIndex,
        writes: []const types.GraphEdgeWrite,
        deletes: []const types.GraphEdgeDelete,
    ) !void {
        var batch_writes = std.ArrayListUnmanaged(graph_mod.BatchWrite).empty;
        defer batch_writes.deinit(self.alloc);
        var batch_deletes = std.ArrayListUnmanaged(graph_mod.BatchDelete).empty;
        defer batch_deletes.deinit(self.alloc);

        for (writes) |write| {
            if (!self.keyInRange(write.source)) continue;
            if (!std.mem.eql(u8, write.index_name, entry.config.name)) continue;
            try batch_writes.append(self.alloc, .{
                .source = write.source,
                .target = write.target,
                .edge_type = write.edge_type,
                .weight = write.weight,
                .created_at = write.created_at,
                .updated_at = write.updated_at,
                .metadata_json = write.metadata_json,
            });
        }

        for (deletes) |delete| {
            if (!self.keyInRange(delete.source)) continue;
            if (!std.mem.eql(u8, delete.index_name, entry.config.name)) continue;
            try batch_deletes.append(self.alloc, .{
                .source = delete.source,
                .target = delete.target,
                .edge_type = delete.edge_type,
            });
        }

        try entry.index.batchApply(batch_writes.items, batch_deletes.items);
    }

    fn applyDenseEmbeddingWritesEntry(
        self: *IndexManager,
        store: *docstore_mod.DocStore,
        entry: *DenseIndex,
        writes: []const mapper.DenseEmbeddingWrite,
        batch_options: StoreBatchOptions,
    ) !void {
        const keep_write = try self.alloc.alloc(bool, writes.len);
        defer self.alloc.free(keep_write);
        try computeDenseReplayKeepMask(self.alloc, writes, keep_write);

        var dense_apply_working_bytes: u64 = 0;
        defer self.observeDenseApplyWorkingBytes(&dense_apply_working_bytes, 0);
        var store_batch = try store.beginWriteBatchWithOptions(batch_options);
        errdefer store_batch.abort();
        const store_txn = store_batch.asTxn();
        const previous_load_session = active_dense_vector_load_session;
        var vector_load_session: ?DenseVectorLoadSession = null;
        defer {
            active_dense_vector_load_session = previous_load_session;
            if (vector_load_session != null) entry.index.setBypassExternalVectorCache(false);
            if (vector_load_session) |*session| session.deinit();
        }
        if (self.primary_store != null and entry.vector_loader_context != null) {
            const existing_session = active_dense_vector_load_session;
            const reuse_existing_session = existing_session != null and existing_session.?.context == entry.vector_loader_context.?;
            if (!reuse_existing_session) {
                vector_load_session = .{
                    .context = entry.vector_loader_context.?,
                    .txn_override = store_txn,
                };
                active_dense_vector_load_session = &vector_load_session.?;
                entry.index.setBypassExternalVectorCache(true);
            }
        }
        const existing_vector_scratch = try self.alloc.alloc(f32, entry.dims);
        defer self.alloc.free(existing_vector_scratch);
        const preloaded_artifact_vectors = try self.alloc.alloc(?[]const f32, writes.len);
        defer {
            self.alloc.free(preloaded_artifact_vectors);
        }
        for (preloaded_artifact_vectors) |*slot| slot.* = null;
        var preloaded_artifact_vector_scratch = std.ArrayListUnmanaged(f32).empty;
        defer preloaded_artifact_vector_scratch.deinit(self.alloc);
        var unreadable_artifact_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer unreadable_artifact_keys.deinit(self.alloc);

        var items: OwnedDenseInsertItems = .{};
        defer items.deinit(self.alloc);
        _ = try items.ensureArena(self.alloc);
        var new_items = std.ArrayListUnmanaged(hbc_mod.BatchInsertItem).empty;
        defer new_items.deinit(self.alloc);
        var existing_items = std.ArrayListUnmanaged(hbc_mod.BatchInsertItem).empty;
        defer existing_items.deinit(self.alloc);
        var pending_mappings = std.ArrayListUnmanaged(PendingDenseVectorMapping).empty;
        defer pending_mappings.deinit(self.alloc);
        var replacement_deletes = std.ArrayListUnmanaged(u64).empty;
        defer replacement_deletes.deinit(self.alloc);
        var metadata_presence_memo: DenseVectorMetadataPresenceMemo = .{};
        defer metadata_presence_memo.deinit(self.alloc);
        var all_vector_ids_new = true;
        var preloaded_vector_bytes: u64 = 0;
        var item_vector_bytes: u64 = 0;
        var item_metadata_bytes: u64 = 0;

        if (try self.preloadDenseEmbeddingArtifactVectorsTxn(
            entry.config.name,
            entry.dims,
            writes,
            keep_write,
            &store_txn,
            preloaded_artifact_vectors,
            &preloaded_artifact_vector_scratch,
            &unreadable_artifact_keys,
        )) {
            if (unreadable_artifact_keys.items.len > 0) return error.ArtifactRepairRequired;
        }
        for (preloaded_artifact_vectors) |maybe_vector| {
            if (maybe_vector) |vector| preloaded_vector_bytes += @as(u64, @intCast(vector.len * @sizeOf(f32)));
        }
        self.observeDenseApplyWorkingBytes(&dense_apply_working_bytes, preloaded_vector_bytes);

        const mapping_doc_keys = try self.alloc.alloc([]const u8, writes.len);
        defer self.alloc.free(mapping_doc_keys);
        const ordinal_doc_keys = try self.alloc.alloc([]const u8, writes.len);
        defer self.alloc.free(ordinal_doc_keys);
        for (writes, 0..) |write, write_index| {
            mapping_doc_keys[write_index] = write.doc_key;
            ordinal_doc_keys[write_index] = write.parent_doc_key orelse write.doc_key;
        }
        const prefetched_ordinals = try doc_identity.lookupOrdinalsTxnAlloc(self.alloc, store_txn, ordinal_doc_keys);
        defer self.alloc.free(prefetched_ordinals);
        const prefetched_mapped_vector_ids = try self.lookupDenseVectorIdsTxnAlloc(store_txn, entry.config.name, mapping_doc_keys);
        defer self.alloc.free(prefetched_mapped_vector_ids);
        {
            var existing_index_write_txn = try entry.index.beginRuntimeWriteTxn();
            defer existing_index_write_txn.abort();
            try self.prefetchDenseExistingMetadataTxn(entry, &existing_index_write_txn, writes, keep_write, prefetched_ordinals, &metadata_presence_memo);

            for (writes, 0..) |write, write_index| {
                if (!keep_write[write_index]) continue;
                if (!std.mem.eql(u8, write.index_name, entry.config.name)) continue;

                if (write.vector.len > 0) {
                    if (entry.dims != write.vector.len) return error.InvalidVectorDimensions;
                    const assignment = try self.replaceDenseVectorIdFromPrefetchedState(
                        entry,
                        write.doc_key,
                        write.parent_doc_key,
                        prefetched_mapped_vector_ids[write_index],
                        prefetched_ordinals[write_index],
                        &metadata_presence_memo,
                    );
                    const artifact_name = entry.embedding_name orelse entry.config.name;
                    try self.writeDenseEmbeddingArtifactTxn(store_txn, write.doc_key, write.doc_key, artifact_name, "_embeddings", null, write.vector);
                    if (try self.denseVectorWriteIsNoOp(entry, &existing_index_write_txn, assignment.vector_id, write.doc_key, write.vector, existing_vector_scratch, &metadata_presence_memo)) continue;
                    all_vector_ids_new = all_vector_ids_new and assignment.can_assume_absent;
                    try items.appendBorrowed(self.alloc, assignment.vector_id, write.vector, write.doc_key);
                    if (assignment.can_assume_absent) {
                        try new_items.append(self.alloc, items.items.items[items.items.items.len - 1]);
                    } else {
                        try existing_items.append(self.alloc, items.items.items[items.items.items.len - 1]);
                    }
                    item_vector_bytes += @as(u64, @intCast(write.vector.len * @sizeOf(f32)));
                    item_metadata_bytes += @intCast(write.doc_key.len);
                    self.observeDenseApplyWorkingBytes(&dense_apply_working_bytes, preloaded_vector_bytes + item_vector_bytes + item_metadata_bytes);
                    try pending_mappings.append(self.alloc, .{
                        .doc_key = items.items.items[items.items.items.len - 1].metadata,
                        .parent_doc_key = write.parent_doc_key,
                        .vector_id = assignment.vector_id,
                        .ordinal = prefetched_ordinals[write_index],
                    });
                } else if (write.artifact_key != null) {
                    const vector = preloaded_artifact_vectors[write_index] orelse continue;
                    const assignment = try self.replaceDenseVectorIdFromPrefetchedState(
                        entry,
                        write.doc_key,
                        write.parent_doc_key,
                        prefetched_mapped_vector_ids[write_index],
                        prefetched_ordinals[write_index],
                        &metadata_presence_memo,
                    );
                    if (try self.denseVectorWriteIsNoOp(entry, &existing_index_write_txn, assignment.vector_id, write.doc_key, vector, existing_vector_scratch, &metadata_presence_memo)) continue;
                    all_vector_ids_new = all_vector_ids_new and assignment.can_assume_absent;
                    try items.appendBorrowedVectorOwnedMetadata(self.alloc, assignment.vector_id, vector, write.doc_key);
                    if (assignment.can_assume_absent) {
                        try new_items.append(self.alloc, items.items.items[items.items.items.len - 1]);
                    } else {
                        try existing_items.append(self.alloc, items.items.items[items.items.items.len - 1]);
                    }
                    item_metadata_bytes += @intCast(write.doc_key.len);
                    self.observeDenseApplyWorkingBytes(&dense_apply_working_bytes, preloaded_vector_bytes + item_vector_bytes + item_metadata_bytes);
                    try pending_mappings.append(self.alloc, .{
                        .doc_key = items.items.items[items.items.items.len - 1].metadata,
                        .parent_doc_key = write.parent_doc_key,
                        .vector_id = assignment.vector_id,
                        .ordinal = prefetched_ordinals[write_index],
                    });
                } else {
                    continue;
                }
            }
        }

        if (items.items.items.len == 0) {
            if (replacement_deletes.items.len > 0) {
                try entry.index.batchApplyOptions(
                    &.{},
                    replacement_deletes.items,
                    denseHbcBatchOptions(batch_options, true, entry.index.hasExternalVectorLoader()),
                );
            }
            try store_batch.commit();
            return;
        }

        // Explicit embedding writes can be the first population path for an
        // otherwise empty external dense index. Use the direct HBC insert path
        // there for default live writes; replay/bulk-ingest can take the HBC
        // bulk builder because the input is already a derived batch.
        if (entry.index.stats().active_count == 0 and batch_options.mode == .default) {
            const before_stats = entry.index.stats();
            const before_profile = entry.index.getWriteProfile();
            const before_lsm_stats = entry.index.snapshotLsmWriteStats();
            const started = platform_time.monotonicNs();
            const skip_vector_store = entry.index.hasExternalVectorLoader();
            if (skip_vector_store) entry.index.setBypassExternalVectorCache(true);
            defer if (skip_vector_store) entry.index.setBypassExternalVectorCache(false);
            try entry.index.batchInsertWithMetadataOptions(
                items.items.items,
                denseHbcBatchOptions(batch_options, all_vector_ids_new, skip_vector_store),
            );
            logBenchHbcWrite(self.alloc, "explicit_empty_batch_insert", entry, items.items.items.len, batch_options, all_vector_ids_new, before_stats, before_profile, before_lsm_stats, started);
        } else {
            if (new_items.items.len > 0) {
                try self.applyDenseItemsWithOptions(entry, new_items.items, &.{}, batch_options, true, store_txn);
            }
            if (existing_items.items.len > 0 or replacement_deletes.items.len > 0) {
                try self.applyDenseItemsWithOptions(entry, existing_items.items, replacement_deletes.items, batch_options, false, store_txn);
            }
        }
        try self.commitDenseVectorMappingsWithRollback(&store_batch, store_txn, entry, entry.config.name, pending_mappings.items);
    }

    const PendingDenseArtifactLoad = struct {
        write_index: usize,
        artifact_key: []const u8,
    };

    fn preloadDenseEmbeddingArtifactVectorsTxn(
        self: *IndexManager,
        index_name: []const u8,
        dims: u32,
        writes: []const mapper.DenseEmbeddingWrite,
        keep_write: []const bool,
        store_txn: anytype,
        out_vectors: []?[]const f32,
        fallback_scratch: *std.ArrayListUnmanaged(f32),
        unreadable_artifact_keys: *std.ArrayListUnmanaged([]const u8),
    ) !bool {
        return try self.preloadDenseEmbeddingArtifactVectorsFromTxn(
            index_name,
            dims,
            writes,
            keep_write,
            store_txn,
            out_vectors,
            fallback_scratch,
            unreadable_artifact_keys,
        );
    }

    fn preloadDenseEmbeddingArtifactVectorsFromSession(
        self: *IndexManager,
        index_name: []const u8,
        dims: u32,
        writes: []const mapper.DenseEmbeddingWrite,
        keep_write: []const bool,
        store: *docstore_mod.DocStore,
        session: *DenseVectorLoadSession,
        out_vectors: []?[]const f32,
        fallback_scratch: *std.ArrayListUnmanaged(f32),
        unreadable_artifact_keys: *std.ArrayListUnmanaged([]const u8),
    ) !bool {
        const dims_usize: usize = @intCast(dims);
        var pending = std.ArrayListUnmanaged(PendingDenseArtifactLoad).empty;
        defer pending.deinit(self.alloc);

        for (writes, 0..) |write, write_index| {
            if (!keep_write[write_index]) continue;
            if (!std.mem.eql(u8, write.index_name, index_name)) continue;
            if (write.vector.len > 0) continue;
            const artifact_key = write.artifact_key orelse continue;
            try pending.append(self.alloc, .{
                .write_index = write_index,
                .artifact_key = artifact_key,
            });
        }
        if (pending.items.len == 0) return false;

        std.mem.sort(PendingDenseArtifactLoad, pending.items, {}, struct {
            fn lessThan(_: void, a: PendingDenseArtifactLoad, b: PendingDenseArtifactLoad) bool {
                return std.mem.order(u8, a.artifact_key, b.artifact_key) == .lt;
            }
        }.lessThan);

        const read_keys = try self.alloc.alloc([]const u8, pending.items.len);
        defer self.alloc.free(read_keys);
        const read_values = try self.alloc.alloc(?[]const u8, pending.items.len);
        defer self.alloc.free(read_values);

        for (pending.items, 0..) |item, i| read_keys[i] = item.artifact_key;
        try session.getManySorted(store, read_keys, read_values);

        var fallback_count: usize = 0;
        for (pending.items, 0..) |item, i| {
            const raw = read_values[i] orelse {
                try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                continue;
            };
            if (enrichment_artifact_codec.denseEmbeddingVectorView(raw)) |maybe_view| {
                if (maybe_view) |view| {
                    if (view.len != dims_usize) {
                        try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                        continue;
                    }
                    continue;
                }
                fallback_count += 1;
            } else |err| {
                if (isRecoverableEmbeddingArtifactError(err)) {
                    try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                    continue;
                }
                return err;
            }
        }

        const fallback_start = fallback_scratch.items.len;
        if (fallback_count > 0) try fallback_scratch.resize(self.alloc, fallback_start + fallback_count * dims_usize);
        var fallback_index: usize = 0;
        for (pending.items, 0..) |item, i| {
            const raw = read_values[i] orelse {
                try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                continue;
            };
            if (enrichment_artifact_codec.denseEmbeddingVectorView(raw)) |maybe_view| {
                if (maybe_view) |view| {
                    if (view.len != dims_usize) {
                        try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                        continue;
                    }
                    out_vectors[item.write_index] = view;
                    continue;
                }
            } else |err| {
                if (isRecoverableEmbeddingArtifactError(err)) {
                    try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                    continue;
                }
                return err;
            }
            const vector = fallback_scratch.items[fallback_start + fallback_index * dims_usize ..][0..dims_usize];
            fallback_index += 1;
            _ = enrichment_artifact_codec.decodeDenseEmbeddingInto(raw, vector) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) {
                    try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                    continue;
                }
                return err;
            };
            if (vector.len != dims_usize) {
                try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                continue;
            }
            out_vectors[item.write_index] = vector;
        }
        return true;
    }

    fn preloadDenseEmbeddingArtifactVectorsFromTxn(
        self: *IndexManager,
        index_name: []const u8,
        dims: u32,
        writes: []const mapper.DenseEmbeddingWrite,
        keep_write: []const bool,
        txn: anytype,
        out_vectors: []?[]const f32,
        fallback_scratch: *std.ArrayListUnmanaged(f32),
        unreadable_artifact_keys: *std.ArrayListUnmanaged([]const u8),
    ) !bool {
        const dims_usize: usize = @intCast(dims);
        var pending = std.ArrayListUnmanaged(PendingDenseArtifactLoad).empty;
        defer pending.deinit(self.alloc);

        for (writes, 0..) |write, write_index| {
            if (!keep_write[write_index]) continue;
            if (!std.mem.eql(u8, write.index_name, index_name)) continue;
            if (write.vector.len > 0) continue;
            const artifact_key = write.artifact_key orelse continue;
            try pending.append(self.alloc, .{
                .write_index = write_index,
                .artifact_key = artifact_key,
            });
        }
        if (pending.items.len == 0) return false;

        std.mem.sort(PendingDenseArtifactLoad, pending.items, {}, struct {
            fn lessThan(_: void, a: PendingDenseArtifactLoad, b: PendingDenseArtifactLoad) bool {
                return std.mem.order(u8, a.artifact_key, b.artifact_key) == .lt;
            }
        }.lessThan);

        const read_keys = try self.alloc.alloc([]const u8, pending.items.len);
        defer self.alloc.free(read_keys);
        const read_values = try self.alloc.alloc(?[]const u8, pending.items.len);
        defer self.alloc.free(read_values);

        for (pending.items, 0..) |item, i| read_keys[i] = item.artifact_key;
        try txn.getManySorted(read_keys, read_values);

        var fallback_count: usize = 0;
        for (pending.items, 0..) |item, i| {
            const raw = read_values[i] orelse {
                try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                continue;
            };
            if (enrichment_artifact_codec.denseEmbeddingVectorView(raw)) |maybe_view| {
                if (maybe_view) |view| {
                    if (view.len != dims_usize) {
                        try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                        continue;
                    }
                    continue;
                }
                fallback_count += 1;
            } else |err| {
                if (isRecoverableEmbeddingArtifactError(err)) {
                    try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                    continue;
                }
                return err;
            }
        }

        const fallback_start = fallback_scratch.items.len;
        if (fallback_count > 0) try fallback_scratch.resize(self.alloc, fallback_start + fallback_count * dims_usize);
        var fallback_index: usize = 0;
        for (pending.items, 0..) |item, i| {
            const raw = read_values[i] orelse {
                try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                continue;
            };
            if (enrichment_artifact_codec.denseEmbeddingVectorView(raw)) |maybe_view| {
                if (maybe_view) |view| {
                    if (view.len != dims_usize) {
                        try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                        continue;
                    }
                    out_vectors[item.write_index] = view;
                    continue;
                }
            } else |err| {
                if (isRecoverableEmbeddingArtifactError(err)) {
                    try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                    continue;
                }
                return err;
            }
            const vector = fallback_scratch.items[fallback_start + fallback_index * dims_usize ..][0..dims_usize];
            fallback_index += 1;
            _ = enrichment_artifact_codec.decodeDenseEmbeddingInto(raw, vector) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) {
                    try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                    continue;
                }
                return err;
            };
            if (vector.len != dims_usize) {
                try unreadable_artifact_keys.append(self.alloc, item.artifact_key);
                continue;
            }
            out_vectors[item.write_index] = vector;
        }
        return true;
    }

    fn persistDenseVectorMappings(self: *IndexManager, store: anytype, index_name: []const u8, pending: []const PendingDenseVectorMapping) !void {
        if (pending.len == 0) return;

        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();

        var batch = try runtime_store.store.beginBatch();
        errdefer batch.abort();
        for (pending) |mapping| {
            try self.writeDenseVectorMappingTxn(&batch, index_name, mapping.doc_key, mapping.parent_doc_key, mapping.vector_id);
        }
        try batch.commit();
    }

    fn commitDenseVectorMappingsTxn(self: *IndexManager, txn: anytype, index_name: []const u8, pending: []const PendingDenseVectorMapping) !void {
        for (pending) |mapping| {
            if (mapping.ordinal) |ordinal| {
                try self.writeDenseVectorMappingTxnWithOrdinal(txn, index_name, mapping.doc_key, mapping.vector_id, ordinal);
            } else {
                try self.writeDenseVectorMappingTxn(txn, index_name, mapping.doc_key, mapping.parent_doc_key, mapping.vector_id);
            }
        }
    }

    const DenseReplayKey = struct {
        index_name: []const u8,
        doc_key: []const u8,
    };

    const DenseReplayKeyContext = struct {
        pub fn hash(_: @This(), key: DenseReplayKey) u64 {
            var hasher = std.hash.Wyhash.init(0);
            const index_name_len: u64 = @intCast(key.index_name.len);
            const doc_key_len: u64 = @intCast(key.doc_key.len);
            hasher.update(std.mem.asBytes(&index_name_len));
            hasher.update(key.index_name);
            hasher.update(std.mem.asBytes(&doc_key_len));
            hasher.update(key.doc_key);
            return hasher.final();
        }

        pub fn eql(_: @This(), a: DenseReplayKey, b: DenseReplayKey) bool {
            return std.mem.eql(u8, a.index_name, b.index_name) and
                std.mem.eql(u8, a.doc_key, b.doc_key);
        }
    };

    fn computeDenseReplayKeepMask(alloc: Allocator, writes: []const mapper.DenseEmbeddingWrite, keep_write: []bool) !void {
        @memset(keep_write, true);
        if (writes.len <= 1) return;

        var seen = std.HashMapUnmanaged(DenseReplayKey, void, DenseReplayKeyContext, 80).empty;
        defer seen.deinit(alloc);

        var i: usize = writes.len;
        while (i > 0) {
            i -= 1;
            const key: DenseReplayKey = .{
                .index_name = writes[i].index_name,
                .doc_key = writes[i].doc_key,
            };
            if (seen.contains(key)) {
                keep_write[i] = false;
                continue;
            }
            try seen.put(alloc, key, {});
        }
    }

    fn denseVectorWriteIsNoOp(
        self: *IndexManager,
        entry: *DenseIndex,
        txn: anytype,
        vector_id: u64,
        doc_key: []const u8,
        vector: []const f32,
        scratch: []f32,
        metadata_memo: ?*DenseVectorMetadataPresenceMemo,
    ) !bool {
        _ = self;
        const existing_metadata = blk: {
            if (metadata_memo) |memo| {
                if (memo.get(vector_id)) |present| {
                    if (!present) return false;
                    if (memo.getMetadata(vector_id)) |metadata| break :blk metadata;
                }
            }
            break :blk (try entry.index.getMetadataInTxn(txn, vector_id)) orelse return false;
        };
        if (!std.mem.eql(u8, existing_metadata, doc_key)) return false;
        const existing_vector = entry.index.getVectorScratch(txn, vector_id, scratch) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        if (existing_vector.len != vector.len) return false;
        return std.mem.eql(u8, std.mem.sliceAsBytes(existing_vector), std.mem.sliceAsBytes(vector));
    }

    fn rollbackPendingDenseVectors(self: *IndexManager, entry: *DenseIndex, pending: []const PendingDenseVectorMapping) void {
        if (pending.len == 0) return;
        const vector_ids = self.alloc.alloc(u64, pending.len) catch return;
        defer self.alloc.free(vector_ids);
        for (pending, 0..) |mapping, i| vector_ids[i] = mapping.vector_id;
        entry.index.batchDelete(vector_ids) catch {};
        entry.index.clearMetadataCache();
    }

    fn commitDenseVectorMappingsWithRollback(
        self: *IndexManager,
        batch: anytype,
        txn: anytype,
        entry: *DenseIndex,
        index_name: []const u8,
        pending: []const PendingDenseVectorMapping,
    ) !void {
        const cache_updates = try self.collectDenseOrdinalVectorCacheUpdatesTxn(self.alloc, txn, pending);
        defer self.alloc.free(cache_updates);
        self.commitDenseVectorMappingsTxn(txn, index_name, pending) catch |err| {
            self.rollbackPendingDenseVectors(entry, pending);
            return err;
        };
        batch.commit() catch |err| {
            self.rollbackPendingDenseVectors(entry, pending);
            return err;
        };
        try self.applyDenseOrdinalVectorCacheUpdates(entry, cache_updates);
    }

    fn persistDenseVectorMappingsWithRollback(
        self: *IndexManager,
        store: anytype,
        entry: *DenseIndex,
        index_name: []const u8,
        pending: []const PendingDenseVectorMapping,
    ) !void {
        self.persistDenseVectorMappings(store, index_name, pending) catch |err| {
            if (pending.len > 0) {
                const vector_ids = self.alloc.alloc(u64, pending.len) catch return err;
                defer self.alloc.free(vector_ids);
                for (pending, 0..) |mapping, i| vector_ids[i] = mapping.vector_id;
                entry.index.batchDelete(vector_ids) catch {};
                entry.index.clearMetadataCache();
            }
            return err;
        };
        try self.refreshDenseOrdinalVectorCacheFromStoreAlloc(store, entry, index_name, pending);
    }

    fn collectDenseOrdinalVectorCacheUpdatesTxn(
        self: *IndexManager,
        alloc: Allocator,
        txn: anytype,
        pending: []const PendingDenseVectorMapping,
    ) ![]DenseOrdinalVectorCacheUpdate {
        const mutable_txn = txn;
        var updates = std.ArrayListUnmanaged(DenseOrdinalVectorCacheUpdate).empty;
        errdefer updates.deinit(alloc);
        for (pending) |mapping| {
            const ordinal = mapping.ordinal orelse blk: {
                const ordinal_doc_key = mapping.parent_doc_key orelse mapping.doc_key;
                break :blk (try doc_identity.lookupOrdinalTxn(self.alloc, mutable_txn, ordinal_doc_key)) orelse continue;
            };
            try updates.append(alloc, .{
                .ordinal = ordinal,
                .vector_id = mapping.vector_id,
            });
        }
        return try updates.toOwnedSlice(alloc);
    }

    fn applyDenseOrdinalVectorCacheUpdates(
        self: *IndexManager,
        entry: *DenseIndex,
        updates: []const DenseOrdinalVectorCacheUpdate,
    ) !void {
        if (entry.chunk_name != null) return;
        for (updates) |update| {
            try entry.ordinal_vector_ids.put(self.alloc, update.ordinal, update.vector_id);
            try entry.vector_ordinals.put(self.alloc, update.vector_id, update.ordinal);
        }
        if (benchMetricsEnabled()) {
            std.log.info(
                "antfly_bench_dense_ordinal_cache index={s} updates={d} ordinal_cache={d} vector_cache={d}",
                .{ entry.config.name, updates.len, entry.ordinal_vector_ids.count(), entry.vector_ordinals.count() },
            );
        }
    }

    fn refreshDenseOrdinalVectorCacheFromStoreAlloc(
        self: *IndexManager,
        store: anytype,
        entry: *DenseIndex,
        index_name: []const u8,
        pending: []const PendingDenseVectorMapping,
    ) !void {
        _ = index_name;
        if (entry.chunk_name != null or pending.len == 0) return;
        var runtime_store = try initRuntimeStore(self.alloc, store);
        defer runtime_store.deinit();
        var txn = try runtime_store.store.beginRead();
        defer txn.abort();
        const updates = try self.collectDenseOrdinalVectorCacheUpdatesTxn(self.alloc, &txn, pending);
        defer self.alloc.free(updates);
        try self.applyDenseOrdinalVectorCacheUpdates(entry, updates);
    }

    fn insertDenseItems(self: *IndexManager, entry: *DenseIndex, items: []const hbc_mod.BatchInsertItem) !void {
        try self.insertDenseItemsWithOptions(entry, items, .{}, false);
    }

    fn insertDenseItemsWithOptions(
        self: *IndexManager,
        entry: *DenseIndex,
        items: []const hbc_mod.BatchInsertItem,
        batch_options: StoreBatchOptions,
        all_vector_ids_new: bool,
    ) !void {
        try self.applyDenseItemsWithOptions(entry, items, &.{}, batch_options, all_vector_ids_new, null);
    }

    fn applyDenseItemsWithOptions(
        self: *IndexManager,
        entry: *DenseIndex,
        items: []const hbc_mod.BatchInsertItem,
        deletes: []const u64,
        batch_options: StoreBatchOptions,
        all_vector_ids_new: bool,
        primary_store_txn: ?docstore_mod.DocStore.Batch.BatchTxn,
    ) !void {
        if (items.len == 0 and deletes.len == 0) return;
        const before_stats = entry.index.stats();
        const before_profile = entry.index.getWriteProfile();
        const before_lsm_stats = entry.index.snapshotLsmWriteStats();
        const started = platform_time.monotonicNs();
        const previous_load_session = active_dense_vector_load_session;
        var vector_load_session: ?DenseVectorLoadSession = null;
        const reuse_existing_session = blk: {
            if (active_dense_vector_load_session == null) break :blk false;
            if (entry.vector_loader_context == null) break :blk false;
            break :blk active_dense_vector_load_session.?.context == entry.vector_loader_context.?;
        };
        defer {
            if (vector_load_session != null) {
                active_dense_vector_load_session = previous_load_session;
                entry.index.setBypassExternalVectorCache(false);
            }
            if (vector_load_session) |*session| session.deinit();
        }
        if (!reuse_existing_session and self.primary_store != null and entry.vector_loader_context != null) {
            vector_load_session = .{
                .context = entry.vector_loader_context.?,
                .txn_override = primary_store_txn,
            };
            active_dense_vector_load_session = &vector_load_session.?;
            entry.index.setBypassExternalVectorCache(true);
        }
        if (deletes.len == 0 and entry.index.stats().active_count == 0 and shouldBulkBuildEmptyDenseIndex(batch_options, items.len)) {
            const skip_vector_store = entry.index.hasExternalVectorLoader();
            const bulk_options: hbc_mod.BulkBuildOptions = .{
                .skip_vector_store = skip_vector_store,
                .algo = if (batch_options.mode == .bulk_ingest) .recursive else null,
            };
            entry.index.bulkBuildWithMetadataOptions(items, bulk_options) catch |err| switch (err) {
                error.IndexNotEmpty => {
                    try entry.index.batchApplyOptions(items, deletes, denseHbcBatchOptions(batch_options, false, skip_vector_store));
                    logBenchHbcWrite(self.alloc, "bulk_build_fallback_batch_apply", entry, items.len, batch_options, false, before_stats, before_profile, before_lsm_stats, started);
                    return;
                },
                else => return err,
            };
            logBenchHbcWrite(self.alloc, "bulk_build", entry, items.len, batch_options, all_vector_ids_new, before_stats, before_profile, before_lsm_stats, started);
            return;
        }
        try entry.index.batchApplyOptions(
            items,
            deletes,
            denseHbcBatchOptions(batch_options, all_vector_ids_new, entry.index.hasExternalVectorLoader()),
        );
        logBenchHbcWrite(self.alloc, "batch_apply", entry, items.len, batch_options, all_vector_ids_new, before_stats, before_profile, before_lsm_stats, started);
    }

    fn denseHbcBatchOptions(batch_options: StoreBatchOptions, all_vector_ids_new: bool, skip_vector_store: bool) hbc_mod.BatchInsertOptions {
        const bulk_ingest = batch_options.mode == .bulk_ingest;
        const bulk_new_vectors = bulk_ingest and all_vector_ids_new;
        return .{
            .assume_absent_ids = bulk_new_vectors,
            .centroid_only_routing = bulk_ingest,
            .allow_quantized_routing = bulk_ingest,
            .coalesce_leaf_writes = bulk_ingest and hbcCoalesceBulkWritesEnabled(),
            .defer_quantized_rebuild = bulk_ingest,
            .defer_quantized_rebuild_to_bulk_finish = bulk_ingest and hbcDeferBulkQuantizedRebuildEnabled(),
            .skip_vector_store = skip_vector_store,
            .bulk_ingest = bulk_ingest,
            .defer_leaf_splits_to_batch_finish = bulk_ingest and hbcDeferBulkLeafSplitsEnabled(),
            .defer_leaf_splits_to_bulk_finish = false,
            .bulk_rebuild_leaf_min_members = if (bulk_ingest) hbcBulkRebuildLeafMinMembers() else 0,
        };
    }

    fn shouldBulkBuildEmptyDenseIndex(batch_options: StoreBatchOptions, item_count: usize) bool {
        return switch (batch_options.mode) {
            .default => true,
            .bulk_ingest => item_count >= hbcBulkIngestBulkBuildMinItems(),
        };
    }

    fn hbcBulkIngestBulkBuildMinItems() usize {
        const cached = hbc_bulk_ingest_bulk_build_min_items_cache.load(.monotonic);
        if (cached != 0) return cached - 1;
        const value = stressEnvUsize("ANTFLY_HBC_BULK_INGEST_BULK_BUILD_MIN_ITEMS", 1024);
        hbc_bulk_ingest_bulk_build_min_items_cache.store(value +% 1, .monotonic);
