fn parseMetric(raw: []const u8) !vector_mod.DistanceMetric {
    if (std.mem.eql(u8, raw, "l2_squared")) return .l2_squared;
    if (std.mem.eql(u8, raw, "cosine")) return .cosine;
    if (std.mem.eql(u8, raw, "inner_product")) return .inner_product;
    return error.InvalidIndexConfig;
}

fn parseClustAlgorithm(raw: []const u8) !vector_mod.ClustAlgorithm {
    if (std.mem.eql(u8, raw, "kmeans")) return .kmeans;
    if (std.mem.eql(u8, raw, "hilbert")) return .hilbert;
    return error.InvalidIndexConfig;
}

fn parseBulkBuildAlgo(raw: []const u8) !hbc_mod.BulkBuildAlgo {
    if (std.mem.eql(u8, raw, "recursive")) return .recursive;
    if (std.mem.eql(u8, raw, "hilbert_seeded")) return .hilbert_seeded;
    if (std.mem.eql(u8, raw, "doc_key_seeded")) return .doc_key_seeded;
    if (std.mem.eql(u8, raw, "kmeans")) return .kmeans;
    return error.InvalidIndexConfig;
}

fn parseKmeansBackend(raw: []const u8) !hbc_mod.HBCConfig.KmeansBackend {
    if (std.mem.eql(u8, raw, "auto")) return .auto;
    if (std.mem.eql(u8, raw, "cpu")) return .cpu;
    if (std.mem.eql(u8, raw, "metal")) return .metal;
    return error.InvalidIndexConfig;
}

fn parseKmeansUpdateStrategy(raw: []const u8) !hbc_mod.HBCConfig.KmeansUpdateStrategy {
    if (std.mem.eql(u8, raw, "auto")) return .auto;
    if (std.mem.eql(u8, raw, "scatter")) return .scatter;
    if (std.mem.eql(u8, raw, "segmented")) return .segmented;
    if (std.mem.eql(u8, raw, "metal")) return .metal;
    return error.InvalidIndexConfig;
}

fn parseDenseRerankPolicy(raw: []const u8) !hbc_mod.HBCConfig.RerankPolicy {
    if (std.mem.eql(u8, raw, "always")) return .always;
    if (std.mem.eql(u8, raw, "boundary")) return .boundary;
    if (std.mem.eql(u8, raw, "never")) return .never;
    return error.InvalidIndexConfig;
}

fn parseCentroidDirectoryMode(raw: []const u8) !hbc_mod.HBCConfig.CentroidDirectoryMode {
    if (std.mem.eql(u8, raw, "hbc")) return .hbc;
    if (std.mem.eql(u8, raw, "flat_rabitq")) return .flat_rabitq;
    return error.InvalidIndexConfig;
}

fn ensureIndexDir(alloc: Allocator, base_path: []const u8, path: []const u8) !void {
    const parent_path = try std.fmt.allocPrint(alloc, "{s}/indexes", .{base_path});
    defer alloc.free(parent_path);

    if (builtin.os.tag != .freestanding) {
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        try fs_paths.createDirPathPortable(io_impl.io(), parent_path);
        try fs_paths.createDirPathPortable(io_impl.io(), path);
        const wal_path = try std.fmt.allocPrint(alloc, "{s}/wal", .{path});
        defer alloc.free(wal_path);
        try fs_paths.createDirPathPortable(io_impl.io(), wal_path);
    }
}

fn ensureIndexDirDurable(
    alloc: Allocator,
    shared_io: ?std.Io,
    base_path: []const u8,
    path: []const u8,
) !void {
    if (builtin.os.tag == .freestanding) return;

    if (shared_io) |io| {
        return ensureIndexDirDurableWithIo(alloc, io, base_path, path);
    }
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    try ensureIndexDirDurableWithIo(alloc, io_impl.io(), base_path, path);
}

fn ensureIndexDirDurableWithIo(
    alloc: Allocator,
    io: std.Io,
    base_path: []const u8,
    path: []const u8,
) !void {
    const parent_path = try std.fmt.allocPrint(alloc, "{s}/indexes", .{base_path});
    defer alloc.free(parent_path);

    try fs_paths.createDirPathPortable(io, base_path);
    try fs_paths.syncDirPortable(io, std.fs.path.dirname(base_path) orelse ".");
    try fs_paths.createDirPathPortable(io, parent_path);
    try fs_paths.syncDirPortable(io, base_path);
    try fs_paths.createDirPathPortable(io, path);
    try fs_paths.syncDirPortable(io, parent_path);
}

fn deleteIndexDirIfPresent(path: []const u8) void {
    if (builtin.os.tag == .freestanding) return;

    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
}

fn repairShadowRootInProgress(path: []const u8) bool {
    if (builtin.os.tag == .freestanding) return false;

    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    const io = io_impl.io();
    const marker_path = std.fmt.allocPrint(std.heap.page_allocator, "{s}/{s}", .{ path, repair_shadow_in_progress_file }) catch return true;
    defer std.heap.page_allocator.free(marker_path);
    const raw = std.Io.Dir.cwd().readFileAlloc(io, marker_path, std.heap.page_allocator, .limited(4096)) catch |err| switch (err) {
        error.FileNotFound => return false,
        else => return true,
    };
    defer std.heap.page_allocator.free(raw);
    if (!std.mem.startsWith(u8, raw, repair_shadow_in_progress_magic)) return true;
    const body = raw[repair_shadow_in_progress_magic.len..];
    if (!std.mem.startsWith(u8, body, "pid=")) return true;
    const end = std.mem.indexOfAny(u8, body["pid=".len..], "\r\n") orelse body["pid=".len..].len;
    const pid_text = body["pid=".len..][0..end];
    const pid = std.fmt.parseUnsigned(u32, pid_text, 10) catch return true;
    if (platform.process.alive(pid)) return true;
    std.log.warn("discarding stale repair shadow root for dead owner path={s} pid={d}", .{ path, pid });
    return false;
}

fn writeFileAtomicallyDurable(alloc: Allocator, io: std.Io, path: []const u8, contents: []const u8) !void {
    const tmp_path = try std.fmt.allocPrint(alloc, "{s}.tmp-{d}", .{ path, platform_time.monotonicNs() });
    defer alloc.free(tmp_path);

    if (std.fs.path.dirname(path)) |parent| try fs_paths.createDirPathPortable(io, parent);

    {
        var file = try fs_paths.createFilePortable(io, tmp_path, .{ .truncate = true });
        defer file.close(io);
        var buf: [1024]u8 = undefined;
        var writer = file.writer(io, &buf);
        try writer.interface.writeAll(contents);
        try writer.end();
        try file.sync(io);
    }

    std.Io.Dir.rename(std.Io.Dir.cwd(), tmp_path, std.Io.Dir.cwd(), path, io) catch |err| {
        std.Io.Dir.cwd().deleteFile(io, tmp_path) catch {};
        return err;
    };
    if (std.fs.path.dirname(path)) |parent| try fs_paths.syncDirPortable(io, parent);
}

fn validRelativeRepairIndexRoot(index_name: []const u8, relative_path: []const u8) bool {
    if (relative_path.len == 0) return false;
    if (std.fs.path.isAbsolute(relative_path)) return false;

    var iter = std.mem.splitScalar(u8, relative_path, '/');
    const root = iter.next() orelse return false;
    if (root.len == 0 or !std.mem.startsWith(u8, root, repair_shadow_root_prefix)) return false;
    if (std.mem.eql(u8, root, repair_shadow_root_prefix)) return false;
    if (iter.next()) |component| {
        if (!std.mem.eql(u8, component, "indexes")) return false;
    } else return false;
    if (iter.next()) |component| {
        if (!std.mem.eql(u8, component, index_name)) return false;
        if (std.mem.eql(u8, component, ".") or std.mem.eql(u8, component, "..")) return false;
    } else return false;
    return iter.next() == null;
}

test "active repair shadow root validation rejects escapes" {
    try std.testing.expect(validRelativeRepairIndexRoot("ft_v1", ".repair-shadow-1/indexes/ft_v1"));
    try std.testing.expect(!validRelativeRepairIndexRoot("ft_v1", ""));
    try std.testing.expect(!validRelativeRepairIndexRoot("ft_v1", "."));
    try std.testing.expect(!validRelativeRepairIndexRoot("ft_v1", ".."));
    try std.testing.expect(!validRelativeRepairIndexRoot("ft_v1", "/tmp/table/.repair-shadow-1/indexes/ft_v1"));
    try std.testing.expect(!validRelativeRepairIndexRoot("ft_v1", ".repair-shadow-1/../indexes/ft_v1"));
    try std.testing.expect(!validRelativeRepairIndexRoot("ft_v1", ".repair-shadow-1/indexes/other"));
    try std.testing.expect(!validRelativeRepairIndexRoot("ft_v1", ".shadow-1/indexes/ft_v1"));
}

