    defer plan.deinit();
    try std.testing.expectEqual(@as(usize, 1), plan.chunks.len);
    try std.testing.expectEqual(@as(usize, 1), plan.chunks[0].end);
    try std.testing.expectEqual(@as(u64, 1), plan.chunks[0].estimate.segment_count);
}

